/**
 * In Redshift, DATE is a function. It requires special treatment in the
 * parser because it is a reserved keyword.
 * (Curiously, TIMESTAMP and TIME are not functions.)
 */
@Test
void testDateFunction() {
    final String expected = "SELECT `DATE`(`X`)\n" + "FROM `T`";
    sql("select date(x) from t").ok(expected);
}

/**
 * In Redshift, PostgreSQL the DATEADD, DATEDIFF and DATE_PART functions have
 * ordinary function syntax except that its first argument is a time unit
 * (e.g. DAY). We must not parse that first argument as an identifier.
 */
@Test
void testRedshiftFunctionsWithDateParts() {
    final String sql = "SELECT DATEADD(day, 1, t),\n" + " DATEDIFF(week, 2, t),\n" + " DATE_PART(year, t) FROM mytable";
    final String expected = "SELECT DATEADD(DAY, 1, `T`)," + " DATEDIFF(WEEK, 2, `T`), DATE_PART(YEAR, `T`)\n" + "FROM `MYTABLE`";
    sql(sql).ok(expected);
}

/**
 * Overrides, adding tests for DATEADD, DATEDIFF, DATE_PART functions
 * in addition to EXTRACT.
 */
@Test
protected void testTimeUnitCodes() {
    super.testTimeUnitCodes();
    // As for FLOOR in the base class, so for DATEADD, DATEDIFF, DATE_PART.
    // Extensions such as 'y' remain as identifiers; they are resolved in the
    // validator.
    final String ts = "'2022-06-03 12:00:00.000'";
    final String ts2 = "'2022-06-03 15:30:00.000'";
    expr("DATEADD(year, 1, " + ts + ")").ok("DATEADD(YEAR, 1, " + ts + ")");
    expr("DATEADD(y, 1, " + ts + ")").ok("DATEADD(`Y`, 1, " + ts + ")");
    expr("DATEDIFF(year, 1, " + ts + ", " + ts2 + ")").ok("DATEDIFF(YEAR, 1, '2022-06-03 12:00:00.000', " + "'2022-06-03 15:30:00.000')");
    expr("DATEDIFF(y, 1, " + ts + ", " + ts2 + ")").ok("DATEDIFF(`Y`, 1, '2022-06-03 12:00:00.000', " + "'2022-06-03 15:30:00.000')");
    expr("DATE_PART(year, " + ts + ")").ok("DATE_PART(YEAR, '2022-06-03 12:00:00.000')");
    expr("DATE_PART(y, " + ts + ")").ok("DATE_PART(`Y`, '2022-06-03 12:00:00.000')");
}

/**
 * PostgreSQL and Redshift allow TIMESTAMP literals that contain only a
 * date part.
 */
@Test
void testShortTimestampLiteral() {
    // Parser doesn't actually check the contents of the string. The validator
    // will convert it to '1969-07-20 00:00:00', when it has decided that
    // TIMESTAMP maps to the TIMESTAMP type.
    sql("select timestamp '1969-07-20'").ok("SELECT TIMESTAMP '1969-07-20'");
    // PostgreSQL allows the following. We should too.
    sql("select ^timestamp '1969-07-20 1:2'^").ok("SELECT TIMESTAMP '1969-07-20 1:2'");
    sql("select ^timestamp '1969-07-20:23:'^").ok("SELECT TIMESTAMP '1969-07-20:23:'");
}

