@Test
void testArrayLiteralFromString() {
    sql("select array '{1,2,3}'").ok("SELECT (ARRAY[1, 2, 3])");
    sql("select array '{{1,2,5}, {3,4,7}}'").ok("SELECT (ARRAY[(ARRAY[1, 2, 5]), (ARRAY[3, 4, 7])])");
    sql("select array '{}'").ok("SELECT (ARRAY[])");
    sql("select array '{\"1\", \"2\", \"3\"}'").ok("SELECT (ARRAY['1', '2', '3'])");
    sql("select array '{null, 1, null, 2}'").ok("SELECT (ARRAY[NULL, 1, NULL, 2])");
    sql("select array ^'null, 1, null, 2'^").fails("Illegal array expression 'null, 1, null, 2'");
}

