    f.sql("SET search_path = public,public,\"$user\"").ok("SET \"search_path\" = \"public\", \"public\", \"$user\"");
    f.sql("SET SCHEMA public,public,\"$user\"").ok("SET \"search_path\" = \"public\", \"public\", \"$user\"");
