/**
 * Tests that you can run tests via {@link Fixtures}.
 */
@Test
void testFixtures() {
    final SqlValidatorFixture v = Fixtures.forValidator();
    v.withSql("select ^1 + date '2002-03-04'^").fails("(?s).*Cannot apply '\\+' to arguments of" + " type '<INTEGER> \\+ <DATE>'.*");
    v.withSql("select 1 + 2 as three").type("RecordType(INTEGER NOT NULL THREE) NOT NULL");
    // 'as' as identifier is invalid with Core parser
    final SqlParserFixture p = Fixtures.forParser();
    p.sql("select ^as^ from t").fails("(?s)Encountered \"as\".*");
    // 'as' as identifier is invalid if you use Babel's tester and Core parser
    p.sql("select ^as^ from t").withTester(new BabelParserTest.BabelTesterImpl()).fails("(?s)Encountered \"as\".*");
    // 'as' as identifier is valid with Babel parser
    p.withConfig(c -> c.withParserFactory(SqlBabelParserImpl.FACTORY)).sql("select as from t").ok("SELECT `AS`\n" + "FROM `T`");
    // Postgres cast is invalid with core parser
    p.sql("select 1 ^:^: integer as x").fails("(?s).*Encountered \":\" at .*");
}

/**
 * Tests that DATEADD, DATEDIFF, DATEPART, DATE_PART allow custom time
 * frames.
 */
@Test
void testTimeFrames() {
    final SqlValidatorFixture f = Fixtures.forValidator().withParserConfig(p -> p.withParserFactory(SqlBabelParserImpl.FACTORY)).withOperatorTable(operatorTableFor(SqlLibrary.MSSQL)).withFactory(tf -> tf.withTypeSystem(typeSystem -> new DelegatingTypeSystem(typeSystem) {

        @Override
        public TimeFrameSet deriveTimeFrameSet(TimeFrameSet frameSet) {
            return TimeFrameSet.builder().addAll(frameSet).addDivision("minute15", 4, "HOUR").build();
        }
    }));
    final String ts = "timestamp '2020-06-27 12:34:56'";
    final String ts2 = "timestamp '2020-06-27 13:45:56'";
    f.withSql("SELECT DATEADD(YEAR, 3, " + ts + ")").ok();
    f.withSql("SELECT DATEADD(HOUR^.^A, 3, " + ts + ")").fails("(?s).*Encountered \".\" at .*");
    f.withSql("SELECT DATEADD(^A^, 3, " + ts + ")").fails("'A' is not a valid time frame");
    f.withSql("SELECT DATEADD(minute15, 3, " + ts + ")").ok();
    f.withSql("SELECT DATEDIFF(^A^, " + ts + ", " + ts2 + ")").fails("'A' is not a valid time frame");
    f.withSql("SELECT DATEDIFF(minute15, " + ts + ", " + ts2 + ")").ok();
    f.withSql("SELECT DATEPART(^A^, " + ts + ")").fails("'A' is not a valid time frame");
    f.withSql("SELECT DATEPART(minute15, " + ts + ")").ok();
    // Where DATEPART is MSSQL, DATE_PART is Postgres
    f.withSql("SELECT ^DATE_PART(A, " + ts + ")^").fails("No match found for function signature " + "DATE_PART\\(<INTERVAL_DAY_TIME>, <TIMESTAMP>\\)");
    final SqlValidatorFixture f2 = f.withOperatorTable(operatorTableFor(SqlLibrary.POSTGRESQL));
    f2.withSql("SELECT ^DATEPART(A, " + ts + ")^").fails("No match found for function signature " + "DATEPART\\(<INTERVAL_DAY_TIME>, <TIMESTAMP>\\)");
    f2.withSql("SELECT DATE_PART(^A^, " + ts + ")").fails("'A' is not a valid time frame");
    f2.withSql("SELECT DATE_PART(minute15, " + ts + ")").ok();
}

@Test
void testNullSafeEqual() {
    // x <=> y
    checkSqlResult("mysql", "SELECT 1 <=> NULL", "EXPR$0=false\n");
    checkSqlResult("mysql", "SELECT NULL <=> NULL", "EXPR$0=true\n");
    // (a, b) <=> (x, y)
    checkSqlResult("mysql", "SELECT (CAST(NULL AS Integer), 1) <=> (1, CAST(NULL AS Integer))", "EXPR$0=false\n");
    checkSqlResult("mysql", "SELECT (CAST(NULL AS Integer), CAST(NULL AS Integer))\n" + "<=> (CAST(NULL AS Integer), CAST(NULL AS Integer))", "EXPR$0=true\n");
    // the higher precedence
    checkSqlResult("mysql", "SELECT x <=> 1 + 3 FROM (VALUES (1, 2)) as tbl(x,y)", "EXPR$0=false\n");
    // the lower precedence
    checkSqlResult("mysql", "SELECT NOT x <=> 1 FROM (VALUES (1, 2)) as tbl(x,y)", "EXPR$0=false\n");
}

