    assertEquals(0xa3b, ArrayTable.BitSlicedPrimitiveArray.getLong(12, values, 10));
    Arrays.fill(values, 0);
    for (int i = 0; i < 10; i++) {
        ArrayTable.BitSlicedPrimitiveArray.orLong(10, values, i, i);
    }
    for (int i = 0; i < 10; i++) {
        assertEquals(i, ArrayTable.BitSlicedPrimitiveArray.getLong(10, values, i));
    }
}

