@Test
void testCushionLikeOperatorRecognitionRule() {
    final RelBuilder relBuilder = RelBuilder.create(config().build());
    final RelNode query = relBuilder.scan("EMP").filter(relBuilder.call(SqlStdOperatorTable.LIKE, relBuilder.field(1), relBuilder.literal("ABCD%"))).build();
    final RelNode target = relBuilder.scan("EMP").filter(relBuilder.call(SqlStdOperatorTable.LIKE, relBuilder.field(1), relBuilder.literal("ABC%"))).build();
    final RelNode replacement = relBuilder.scan("mv0").build();
    final RelOptMaterialization relOptMaterialization = new RelOptMaterialization(replacement, target, null, Lists.newArrayList("mv0"));
    final List<UnifyRule> rules = new ArrayList<>();
    rules.addAll(SubstitutionVisitor.DEFAULT_RULES);
    rules.add(CustomizedMaterializationRule.INSTANCE);
    final List<Pair<RelNode, List<RelOptMaterialization>>> relOptimized = RelOptMaterializations.useMaterializedViews(query, ImmutableList.of(relOptMaterialization), rules);
    final String optimized = "" + "LogicalCalc(expr#0..7=[{inputs}], expr#8=['ABCD%'], expr#9=[LIKE($t1, $t8)], proj#0." + ".7=[{exprs}], $condition=[$t9])\n" + "  LogicalProject(empno=[CAST($0):SMALLINT NOT NULL], ename=[CAST($1):VARCHAR(10)], " + "job=[CAST($2):VARCHAR(9)], mgr=[CAST($3):SMALLINT], hiredate=[CAST($4):DATE], " + "sal=[CAST($5):DECIMAL(7, 2)], comm=[CAST($6):DECIMAL(7, 2)], deptno=[CAST($7)" + ":TINYINT])\n" + "    LogicalTableScan(table=[[mv0]])\n";
    final String relOptimizedStr = RelOptUtil.toString(relOptimized.get(0).getKey());
    assertThat(relOptimizedStr, isLinux(optimized));
}

/**
 * Some basic query patterns on the Scott schema with "EMP" and "DEPT"
 * tables.
 */
@Test
void testEmpDept() throws Exception {
    final Tester t = new Tester();
    final String q0 = "select dept.dname, count(*), sum(sal)\n" + "from emp\n" + "join dept using (deptno)\n" + "group by dept.dname";
    assertThat(t.addQuery(q0), isGraphs("EMP (DEPT:DEPTNO)", "[COUNT(), SUM(EMP.SAL)]"));
    // Same as above, but using WHERE rather than JOIN
    final String q1 = "select dept.dname, count(*), sum(sal)\n" + "from emp, dept\n" + "where emp.deptno = dept.deptno\n" + "group by dept.dname";
    assertThat(t.addQuery(q1), isGraphs("EMP (DEPT:DEPTNO)", "[COUNT(), SUM(EMP.SAL)]"));
    // With HAVING
    final String q2 = "select dept.dname\n" + "from emp, dept\n" + "where emp.deptno = dept.deptno\n" + "group by dept.dname\n" + "having count(*) > 10";
    assertThat(t.addQuery(q2), isGraphs("EMP (DEPT:DEPTNO)", "[COUNT()]"));
    // No joins, therefore graph has a single node and no edges
    final String q3 = "select distinct dname\n" + "from dept";
    assertThat(t.addQuery(q3), isGraphs("DEPT", "[]"));
    // Graph is empty because there are no tables
    final String q4 = "select distinct t.c\n" + "from (values 1, 2) as t(c)" + "join (values 2, 3) as u(c) using (c)\n";
    assertThat(t.addQuery(q4), isGraphs());
    // Self-join
    final String q5 = "select *\n" + "from emp as e\n" + "join emp as m on e.mgr = m.empno";
    assertThat(t.addQuery(q5), isGraphs("EMP (EMP:MGR)", "[]"));
    // Self-join, twice
    final String q6 = "select *\n" + "from emp as e join emp as m on e.mgr = m.empno\n" + "join emp as m2 on m.mgr = m2.empno";
    assertThat(t.addQuery(q6), isGraphs("EMP (EMP:MGR (EMP:MGR))", "[]"));
    // No graphs, because cyclic: e -> m, m -> m2, m2 -> e
    final String q7 = "select *\n" + "from emp as e\n" + "join emp as m on e.mgr = m.empno\n" + "join emp as m2 on m.mgr = m2.empno\n" + "where m2.mgr = e.empno";
    assertThat(t.addQuery(q7), isGraphs());
    // The graph of all tables and hops
    final String expected = "graph(" + "vertices: [[scott, DEPT]," + " [scott, EMP]], " + "edges: [Step([scott, EMP], [scott, DEPT], DEPTNO:DEPTNO)," + " Step([scott, EMP], [scott, EMP], MGR:EMPNO)])";
    assertThat(t.s.space.g, hasToString(expected));
}

