@Test
void testMVTrimUnusedFiled() {
    final RelBuilder relBuilder = RelBuilder.create(config().build());
    final LogicalProject project = (LogicalProject) relBuilder.scan("EMP").project(relBuilder.field("EMPNO"), relBuilder.field("ENAME"), relBuilder.field("JOB"), relBuilder.field("SAL"), relBuilder.field("DEPTNO")).build();
    final LogicalAggregate aggregate = (LogicalAggregate) relBuilder.push(project).aggregate(relBuilder.groupKey(relBuilder.field(1, 0, "DEPTNO")), relBuilder.count(relBuilder.field(1, 0, "SAL"))).build();
    final ImmutableBitSet groupSet = ImmutableBitSet.of(4);
    final AggregateCall count = aggregate.getAggCallList().get(0);
    final AggregateCall call = AggregateCall.create(count.getAggregation(), count.isDistinct(), count.isApproximate(), count.ignoreNulls(), count.rexList, ImmutableList.of(3), count.filterArg, null, count.collation, count.getType(), count.getName());
    final RelNode query = LogicalAggregate.create(project, aggregate.getHints(), groupSet, ImmutableList.of(groupSet), ImmutableList.of(call));
    final RelNode target = aggregate;
    final RelNode replacement = relBuilder.scan("mv0").build();
    final RelOptMaterialization relOptMaterialization = new RelOptMaterialization(replacement, target, null, Lists.newArrayList("mv0"));
    final List<Pair<RelNode, List<RelOptMaterialization>>> relOptimized = RelOptMaterializations.useMaterializedViews(query, ImmutableList.of(relOptMaterialization));
    final String optimized = "" + "LogicalProject(deptno=[CAST($0):TINYINT], count_sal=[$1])\n" + "  LogicalTableScan(table=[[mv0]])\n";
    final String relOptimizedStr = RelOptUtil.toString(relOptimized.get(0).getKey());
    assertThat(relOptimizedStr, isLinux(optimized));
}

@Test
void testTypeToClass() {
    RelJson relJson = RelJson.create();
    // in org.apache.calcite.rel package
    assertThat(relJson.classToTypeName(LogicalProject.class), is("LogicalProject"));
    assertThat(relJson.typeNameToClass("LogicalProject"), sameInstance((Class) LogicalProject.class));
    // in org.apache.calcite.adapter.jdbc.JdbcRules outer class
    assertThat(relJson.classToTypeName(JdbcRules.JdbcProject.class), is("JdbcProject"));
    assertThat(relJson.typeNameToClass("JdbcProject"), equalTo((Class) JdbcRules.JdbcProject.class));
    try {
        Class clazz = relJson.typeNameToClass("NonExistentRel");
        fail("expected exception, got " + clazz);
    } catch (RuntimeException e) {
        assertThat(e.getMessage(), is("unknown type NonExistentRel"));
    }
    try {
        Class clazz = relJson.typeNameToClass("org.apache.calcite.rel.NonExistentRel");
        fail("expected exception, got " + clazz);
    } catch (RuntimeException e) {
        assertThat(e.getMessage(), is("unknown type org.apache.calcite.rel.NonExistentRel"));
    }
    // In this class; no special treatment. Note: '$MyRel' not '.MyRel'.
    assertThat(relJson.classToTypeName(MyRel.class), is("org.apache.calcite.plan.RelOptPlanReaderTest$MyRel"));
    assertThat(relJson.typeNameToClass(MyRel.class.getName()), equalTo((Class) MyRel.class));
    // Using canonical name (with '$'), not found
    try {
        Class clazz = relJson.typeNameToClass(MyRel.class.getCanonicalName());
        fail("expected exception, got " + clazz);
    } catch (RuntimeException e) {
        assertThat(e.getMessage(), is("unknown type org.apache.calcite.plan.RelOptPlanReaderTest.MyRel"));
    }
}

