/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3136">[CALCITE-3136]
 * Fix the default rule description of ConverterRule</a>.
 */
@Test
void testConvertRuleDefaultRuleDescription() {
    final RelCollation collation1 = RelCollations.of(new RelFieldCollation(4, RelFieldCollation.Direction.DESCENDING));
    final RelCollation collation2 = RelCollations.of(new RelFieldCollation(0, RelFieldCollation.Direction.DESCENDING));
    final RelDistribution distribution1 = RelDistributions.hash(ImmutableList.of(0, 1));
    final RelDistribution distribution2 = RelDistributions.range(ImmutableList.of());
    final RelOptRule collationConvertRule = MyConverterRule.create(collation1, collation2);
    final RelOptRule distributionConvertRule = MyConverterRule.create(distribution1, distribution2);
    final RelOptRule compositeConvertRule = MyConverterRule.create(RelCompositeTrait.of(RelCollationTraitDef.INSTANCE, ImmutableList.of(collation2, collation1)), RelCompositeTrait.of(RelCollationTraitDef.INSTANCE, ImmutableList.of(collation1)));
    final RelOptRule compositeConvertRule0 = MyConverterRule.create(RelCompositeTrait.of(RelDistributionTraitDef.INSTANCE, ImmutableList.of(distribution1, distribution2)), RelCompositeTrait.of(RelDistributionTraitDef.INSTANCE, ImmutableList.of(distribution1)));
    assertThat(collationConvertRule, hasToString("ConverterRule(in:[4 DESC],out:[0 DESC])"));
    assertThat(distributionConvertRule, hasToString("ConverterRule(in:hash[0, 1],out:range)"));
    assertThat(compositeConvertRule, hasToString("ConverterRule(in:[[0 DESC], [4 DESC]],out:[4 DESC])"));
    assertThat(compositeConvertRule0, hasToString("ConverterRule(in:[hash[0, 1], range],out:hash[0, 1])"));
    try {
        Util.discard(MyConverterRule.create(new Convention.Impl("{sourceConvention}", RelNode.class), new Convention.Impl("<targetConvention>", RelNode.class)));
        fail("expected exception");
    } catch (RuntimeException e) {
        assertThat(e.getMessage(), is("Rule description 'ConverterRule(in:{sourceConvention}," + "out:<targetConvention>)' is not valid"));
    }
}

