    }
    RexNode between = rexBuilder.makeBetween(b.literal(45), b.literal(20), b.literal(30));
    consumer.accept(between);
    RexNode inNode = rexBuilder.makeIn(b.literal(12), ImmutableList.of(b.literal(20), b.literal(14)));
    consumer.accept(inNode);
    // Test Calcite DateString class works in a Range
    final DateString d1 = DateString.fromCalendarFields(new TimestampString(1970, 2, 1, 1, 1, 0).toCalendar());
    final DateString d2 = DateString.fromDaysSinceEpoch(100);
    final DateString d3 = DateString.fromDaysSinceEpoch(1000);
    RexNode dateNode = rexBuilder.makeBetween(rexBuilder.makeDateLiteral(d2), rexBuilder.makeDateLiteral(d1), rexBuilder.makeDateLiteral(d3));
    consumer.accept(dateNode);
    // Test Calcite TimeString
    final RexLiteral t1 = rexBuilder.makeTimeLiteral(new TimeString(1, 0, 0), 0);
