/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4321">[CALCITE-4321]
 * JDBC adapter omits FILTER (WHERE ...) expressions when generating SQL</a>
 * and
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5270">[CALCITE-5270]
 * JDBC adapter should not generate FILTER (WHERE) in Firebolt dialect</a>.
 */
@Test
void testAggregateFilterWhere() {
    String query = "select\n" + "  sum(\"shelf_width\") filter (where \"net_weight\" > 0),\n" + "  sum(\"shelf_width\")\n" + "from \"foodmart\".\"product\"\n" + "where \"product_id\" > 0\n" + "group by \"product_id\"";
    final String expectedDefault = "SELECT" + " SUM(\"shelf_width\") FILTER (WHERE \"net_weight\" > 0 IS TRUE)," + " SUM(\"shelf_width\")\n" + "FROM \"foodmart\".\"product\"\n" + "WHERE \"product_id\" > 0\n" + "GROUP BY \"product_id\"";
    final String expectedBigQuery = "SELECT" + " SUM(CASE WHEN net_weight > 0 IS TRUE" + " THEN shelf_width ELSE NULL END), " + "SUM(shelf_width)\n" + "FROM foodmart.product\n" + "WHERE product_id > 0\n" + "GROUP BY product_id";
    final String expectedFirebolt = "SELECT" + " SUM(CASE WHEN \"net_weight\" > 0 IS TRUE" + " THEN \"shelf_width\" ELSE NULL END), " + "SUM(\"shelf_width\")\n" + "FROM \"foodmart\".\"product\"\n" + "WHERE \"product_id\" > 0\n" + "GROUP BY \"product_id\"";
    sql(query).ok(expectedDefault).withBigQuery().ok(expectedBigQuery).withFirebolt().ok(expectedFirebolt);
}

@Test
void testPivotToSqlFromProductTable() {
    String query = "select * from (\n" + "  select \"shelf_width\", \"net_weight\", \"product_id\"\n" + "  from \"foodmart\".\"product\")\n" + "  pivot (sum(\"shelf_width\") as w, count(*) as c\n" + "    for (\"product_id\") in (10, 20))";
    final String expected = "SELECT \"net_weight\"," + " SUM(\"shelf_width\") FILTER (WHERE \"product_id\" = 10) AS \"10_W\"," + " COUNT(*) FILTER (WHERE \"product_id\" = 10) AS \"10_C\"," + " SUM(\"shelf_width\") FILTER (WHERE \"product_id\" = 20) AS \"20_W\"," + " COUNT(*) FILTER (WHERE \"product_id\" = 20) AS \"20_C\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY \"net_weight\"";
    // BigQuery does not support FILTER, so we generate CASE around the
    // arguments to the aggregate functions.
    final String expectedBigQuery = "SELECT net_weight," + " SUM(CASE WHEN product_id = 10 " + "THEN shelf_width ELSE NULL END) AS `10_W`," + " COUNT(CASE WHEN product_id = 10 THEN 1 ELSE NULL END) AS `10_C`," + " SUM(CASE WHEN product_id = 20 " + "THEN shelf_width ELSE NULL END) AS `20_W`," + " COUNT(CASE WHEN product_id = 20 THEN 1 ELSE NULL END) AS `20_C`\n" + "FROM foodmart.product\n" + "GROUP BY net_weight";
    sql(query).ok(expected).withBigQuery().ok(expectedBigQuery);
}

