    final String query = "SELECT TIMESTAMP_SECONDS(CAST(CEIL(CAST(3 AS BIGINT)) AS BIGINT)) " + "as created_thing\n FROM `foodmart`.`product`";
    final SqlParser.Config parserConfig = BigQuerySqlDialect.DEFAULT.configureParser(SqlParser.config());
    final Sql sql = fixture().withBigQuery().withLibrary(SqlLibrary.BIG_QUERY).parserConfig(parserConfig);
    sql.withSql(query).ok("SELECT TIMESTAMP_SECONDS(CAST(CEIL(3) AS INT64)) AS " + "created_thing\nFROM foodmart.product");
}

