 * <a href="https://issues.apache.org/jira/browse/CALCITE-4665">[CALCITE-4665]
 * Allow Aggregate.groupSet to contain columns not in any of the
 * groupSets</a>. Generate a redundant grouping set and a HAVING clause to
 * filter it out.
 */
@Test
void testGroupSuperset() {
    final Function<RelBuilder, RelNode> relFn = b -> b.scan("EMP").aggregate(b.groupKey(ImmutableBitSet.of(0, 1, 2), ImmutableList.of(ImmutableBitSet.of(0, 1), ImmutableBitSet.of(0))), b.count(false, "C"), b.sum(false, "S", b.field("SAL"))).filter(b.equals(b.field("JOB"), b.literal("DEVELOP"))).project(b.field("JOB")).build();
    final String expectedSql = "SELECT \"JOB\"\n" + "FROM (SELECT \"EMPNO\", \"ENAME\", \"JOB\", COUNT(*) AS \"C\"," + " SUM(\"SAL\") AS \"S\"\n" + "FROM \"scott\".\"EMP\"\n" + "GROUP BY GROUPING SETS((\"EMPNO\", \"ENAME\", \"JOB\")," + " (\"EMPNO\", \"ENAME\"), \"EMPNO\")\n" + "HAVING GROUPING(\"EMPNO\", \"ENAME\", \"JOB\") <> 0" + " AND \"JOB\" = 'DEVELOP') AS \"t\"";
    relFn(relFn).ok(expectedSql);
}

