void testGroupSuperset6() {
    final Function<RelBuilder, RelNode> relFn = b -> b.scan("EMP").aggregate(b.groupKey(ImmutableBitSet.of(0, 1, 2), ImmutableList.of(ImmutableBitSet.of(0, 1), ImmutableBitSet.of(0), ImmutableBitSet.of())), b.count(false, "C"), b.sum(false, "S", b.field("SAL"))).filter(b.lessThan(b.call(SqlStdOperatorTable.GROUP_ID, b.field("EMPNO")), b.literal(1))).filter(b.equals(b.field("JOB"), b.literal("DEVELOP"))).project(b.field("JOB")).build();
    final String expectedSql = "SELECT \"JOB\"\n" + "FROM (SELECT *\n" + "FROM (SELECT \"EMPNO\", \"ENAME\", \"JOB\", COUNT(*) AS \"C\", SUM(\"SAL\") AS \"S\"\n" + "FROM \"scott\".\"EMP\"\n" + "GROUP BY GROUPING SETS((\"EMPNO\", \"ENAME\", \"JOB\")," + " (\"EMPNO\", \"ENAME\"), \"EMPNO\", ())\n" + "HAVING GROUPING(\"EMPNO\", \"ENAME\", \"JOB\") <> 0" + " AND GROUP_ID(\"EMPNO\") < 1) AS \"t\") " + "AS \"t0\"\n" + "WHERE \"JOB\" = 'DEVELOP'";
    relFn(relFn).ok(expectedSql);
}

