    final Function<RelBuilder, RelNode> relFn = b -> b.scan("EMP").project(b.field("SAL")).project(b.aggregateCall(SqlStdOperatorTable.RANK).over().orderBy(b.field("SAL")).rowsUnbounded().allowPartial(true).nullWhenCountZero(false).as("rank")).as("t").aggregate(b.groupKey(), b.count(b.field("t", "rank")).distinct().as("c")).filter(b.call(SqlStdOperatorTable.GREATER_THAN_OR_EQUAL, b.field("c"), b.literal(10))).build();
    // PostgreSQL does not not support nested aggregations
    final String expectedPostgresql = "SELECT COUNT(DISTINCT \"rank\") AS \"c\"\n" + "FROM (SELECT RANK() OVER (ORDER BY \"SAL\") AS \"rank\"\n" + "FROM \"scott\".\"EMP\") AS \"t\"\n" + "HAVING COUNT(DISTINCT \"rank\") >= 10";
    relFn(relFn).withPostgresql().ok(expectedPostgresql);
    // Oracle does support nested aggregations
    final String expectedOracle = "SELECT COUNT(DISTINCT RANK() OVER (ORDER BY \"SAL\")) \"c\"\n" + "FROM \"scott\".\"EMP\"\n" + "HAVING COUNT(DISTINCT RANK() OVER (ORDER BY \"SAL\")) >= 10";
    relFn(relFn).withOracle().ok(expectedOracle);
}

