/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3811">[CALCITE-3811]
 * JDBC adapter generates SQL with invalid field names if Filter's row type
 * is different from its input</a>.
 */
@Test
void testHavingAlias() {
    final RelBuilder builder = relBuilder();
    builder.scan("EMP").project(builder.alias(builder.field("DEPTNO"), "D")).aggregate(builder.groupKey(builder.field("D")), builder.countStar("emps.count")).filter(builder.lessThan(builder.field("emps.count"), builder.literal(2)));
    final LogicalFilter filter = (LogicalFilter) builder.build();
    assertThat(filter.getRowType().getFieldNames(), hasToString("[D, emps.count]"));
    // Create a LogicalAggregate similar to the input of filter, but with different
    // field names.
    final LogicalAggregate newAggregate = (LogicalAggregate) builder.scan("EMP").project(builder.alias(builder.field("DEPTNO"), "D2")).aggregate(builder.groupKey(builder.field("D2")), builder.countStar("emps.count")).build();
    assertThat(newAggregate.getRowType().getFieldNames(), hasToString("[D2, emps.count]"));
    // Change filter's input. Its row type does not change.
    filter.replaceInput(0, newAggregate);
    assertThat(filter.getRowType().getFieldNames(), hasToString("[D, emps.count]"));
    final RelNode root = builder.push(filter).project(builder.alias(builder.field("D"), "emps.deptno")).build();
    final String expectedMysql = "SELECT `D2` AS `emps.deptno`\n" + "FROM (SELECT `DEPTNO` AS `D2`, COUNT(*) AS `emps.count`\n" + "FROM `scott`.`EMP`\n" + "GROUP BY `DEPTNO`\n" + "HAVING `emps.count` < 2) AS `t1`";
    final String expectedPostgresql = "SELECT \"DEPTNO\" AS \"emps.deptno\"\n" + "FROM \"scott\".\"EMP\"\n" + "GROUP BY \"DEPTNO\"\n" + "HAVING COUNT(*) < 2";
    final String expectedBigQuery = "SELECT D2 AS `emps.deptno`\n" + "FROM (SELECT DEPTNO AS D2, COUNT(*) AS `emps.count`\n" + "FROM scott.EMP\n" + "GROUP BY DEPTNO\n" + "HAVING `emps.count` < 2) AS t1";
    relFn(b -> root).withBigQuery().ok(expectedBigQuery).withMysql().ok(expectedMysql).withPostgresql().ok(expectedPostgresql);
}

