/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5044">[CALCITE-5044]
 * JDBC adapter generates integer literal in ORDER BY, which some dialects
 * wrongly interpret as a reference to a field</a>.
 */
@Test
void testRewriteOrderByWithNumericConstants() {
    final Function<RelBuilder, RelNode> relFn = b -> b.scan("EMP").project(b.literal(1), b.field(1), b.field(2), b.literal("23"), b.alias(b.literal(12), "col1"), b.literal(34)).sort(RelCollations.of(ImmutableList.of(new RelFieldCollation(0), new RelFieldCollation(3), new RelFieldCollation(4), new RelFieldCollation(1), new RelFieldCollation(5, Direction.DESCENDING, NullDirection.LAST)))).project(b.field(2), b.field(1)).build();
    // Default dialect rewrite numeric constant keys to string literal in the order-by.
    // case1: numeric constant - rewrite it.
    // case2: string constant - no need rewrite it.
    // case3: wrap alias to numeric constant - rewrite it.
    // case4: wrap collation's info to numeric constant - rewrite it.
    relFn(relFn).ok("SELECT \"JOB\", \"ENAME\"\n" + "FROM \"scott\".\"EMP\"\n" + "ORDER BY '1', '23', '12', \"ENAME\", '34' DESC NULLS LAST").dialect(nonOrdinalDialect()).ok("SELECT JOB, ENAME\n" + "FROM scott.EMP\n" + "ORDER BY 1, '23', 12, ENAME, 34 DESC NULLS LAST");
}

