@Test
void testIdentifier() {
    // Note that IGNORE is reserved in BigQuery but not in standard SQL
    final String query = "select *
" + "from (
" + "  select 1 as "one", 2 as "tWo", 3 as "THREE",
" + "    4 as "fo$ur", 5 as "ignore", 6 as "si`x"
" + "  from "foodmart"."days") as "my$table"
" + "where "one" < "tWo" and "THREE" < "fo$ur"";
    final String expectedBigQuery = "SELECT *
" + "FROM (SELECT 1 AS one, 2 AS tWo, 3 AS THREE," + " 4 AS `fo$ur`, 5 AS `ignore`, 6 AS `si\`x`
" + "FROM foodmart.days) AS t
" + "WHERE one < tWo AND THREE < `fo$ur`";
    final String expectedMysql = "SELECT *
" + "FROM (SELECT 1 AS `one`, 2 AS `tWo`, 3 AS `THREE`," + " 4 AS `fo$ur`, 5 AS `ignore`, 6 AS `si``x`
" + "FROM `foodmart`.`days`) AS `t`
" + "WHERE `one` < `tWo` AND `THREE` < `fo$ur`";
    final String expectedPostgresql = "SELECT *
" + "FROM (SELECT 1 AS "one", 2 AS "tWo", 3 AS "THREE"," + " 4 AS "fo$ur", 5 AS "ignore", 6 AS "si`x"
" + "FROM "foodmart"."days") AS "t"
" + "WHERE "one" < "tWo" AND "THREE" < "fo$ur"";
    final String expectedOracle = expectedPostgresql.replace(" AS ", " ");
    final String expectedExasol = "SELECT *
" + "FROM (SELECT 1 AS one, 2 AS tWo, 3 AS THREE," + " 4 AS "fo$ur", 5 AS "ignore", 6 AS "si`x"
" + "FROM foodmart.days) AS t
" + "WHERE one < tWo AND THREE < "fo$ur"";
    sql(query).withBigQuery().ok(expectedBigQuery).withMysql().ok(expectedMysql).withOracle().ok(expectedOracle).withPostgresql().ok(expectedPostgresql).withExasol().ok(expectedExasol);
}

