@Test
void testSelectOrderByDescNullsFirst() {
    final String query = "select \"product_id\" from \"product\"\n" + "order by \"product_id\" desc nulls first";
    // Hive and MSSQL do not support NULLS FIRST, so need to emulate
    final String expected = "SELECT product_id\n" + "FROM foodmart.product\n" + "ORDER BY product_id IS NULL DESC, product_id DESC";
    final String mssqlExpected = "SELECT [product_id]\n" + "FROM [foodmart].[product]\n" + "ORDER BY CASE WHEN [product_id] IS NULL THEN 0 ELSE 1 END, [product_id] DESC";
    sql(query).dialect(HiveSqlDialect.DEFAULT).ok(expected).dialect(MssqlSqlDialect.DEFAULT).ok(mssqlExpected);
}

