@Test
void testMySqlUnparseListAggCall() {
    final String query = "select
" + "listagg(distinct "product_name", ',') within group(order by "cases_per_pallet"),
" + "listagg("product_name", ',') within group(order by "cases_per_pallet"),
" + "listagg(distinct "product_name") within group(order by "cases_per_pallet" desc),
" + "listagg(distinct "product_name", ',') within group(order by "cases_per_pallet"),
" + "listagg("product_name"),
" + "listagg("product_name", ',')
" + "from "product"
" + "group by "product_id"
";
    final String expected = "SELECT GROUP_CONCAT(DISTINCT `product_name` " + "ORDER BY `cases_per_pallet` IS NULL, `cases_per_pallet` SEPARATOR ','), " + "GROUP_CONCAT(`product_name` " + "ORDER BY `cases_per_pallet` IS NULL, `cases_per_pallet` SEPARATOR ','), " + "GROUP_CONCAT(DISTINCT `product_name` " + "ORDER BY `cases_per_pallet` IS NULL DESC, `cases_per_pallet` DESC), " + "GROUP_CONCAT(DISTINCT `product_name` " + "ORDER BY `cases_per_pallet` IS NULL, `cases_per_pallet` SEPARATOR ','), " + "GROUP_CONCAT(`product_name`), GROUP_CONCAT(`product_name` SEPARATOR ',')
" + "FROM `foodmart`.`product`
" + "GROUP BY `product_id`";
    sql(query).withMysql().ok(expected);
}

