    String expected = "SELECT *\n" + "FROM \"foodmart\".\"sales_fact_1997\"\n" + "INNER JOIN \"foodmart\".\"customer\" " + "ON \"sales_fact_1997\".\"customer_id\" = \"customer\".\"customer_id\"" + " OR \"sales_fact_1997\".\"customer_id\" IS NULL" + " AND \"customer\".\"customer_id\" IS NULL" + " OR \"customer\".\"occupation\" IS NULL\n" + "INNER JOIN \"foodmart\".\"product\" " + "ON \"sales_fact_1997\".\"product_id\" = \"product\".\"product_id\"" + " OR \"sales_fact_1997\".\"product_id\" IS NOT NULL" + " OR \"product\".\"product_id\" IS NOT NULL";
