/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3112">[CALCITE-3112]
 * Support Window in RelToSqlConverter</a>.
 */
@Test
void testConvertWindowToSql() {
    String query0 = "SELECT row_number() over (order by \"hire_date\") FROM \"employee\"";
    String expected0 = "SELECT ROW_NUMBER() OVER (ORDER BY \"hire_date\") AS \"$0\"\n" + "FROM \"foodmart\".\"employee\"";
    String query1 = "SELECT rank() over (order by \"hire_date\") FROM \"employee\"";
    String expected1 = "SELECT RANK() OVER (ORDER BY \"hire_date\") AS \"$0\"\n" + "FROM \"foodmart\".\"employee\"";
    String query2 = "SELECT lead(\"employee_id\",1,'NA') over " + "(partition by \"hire_date\" order by \"employee_id\")\n" + "FROM \"employee\"";
    String expected2 = "SELECT LEAD(\"employee_id\", 1, 'NA') OVER " + "(PARTITION BY \"hire_date\" " + "ORDER BY \"employee_id\") AS \"$0\"\n" + "FROM \"foodmart\".\"employee\"";
    String query3 = "SELECT lag(\"employee_id\",1,'NA') over " + "(partition by \"hire_date\" order by \"employee_id\")\n" + "FROM \"employee\"";
    String expected3 = "SELECT LAG(\"employee_id\", 1, 'NA') OVER " + "(PARTITION BY \"hire_date\" ORDER BY \"employee_id\") AS \"$0\"\n" + "FROM \"foodmart\".\"employee\"";
    String query4 = "SELECT lag(\"employee_id\",1,'NA') " + "over (partition by \"hire_date\" order by \"employee_id\") as lag1, " + "lag(\"employee_id\",1,'NA') " + "over (partition by \"birth_date\" order by \"employee_id\") as lag2, " + "count(*) over (partition by \"hire_date\" order by \"employee_id\") as count1, " + "count(*) over (partition by \"birth_date\" order by \"employee_id\") as count2\n" + "FROM \"employee\"";
    String expected4 = "SELECT LAG(\"employee_id\", 1, 'NA') OVER " + "(PARTITION BY \"hire_date\" ORDER BY \"employee_id\") AS \"$0\", " + "LAG(\"employee_id\", 1, 'NA') OVER " + "(PARTITION BY \"birth_date\" ORDER BY \"employee_id\") AS \"$1\", " + "COUNT(*) OVER (PARTITION BY \"hire_date\" ORDER BY \"employee_id\" " + "RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS \"$2\", " + "COUNT(*) OVER (PARTITION BY \"birth_date\" ORDER BY \"employee_id\" " + "RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS \"$3\"\n" + "FROM \"foodmart\".\"employee\"";
    String query5 = "SELECT lag(\"employee_id\",1,'NA') " + "over (partition by \"hire_date\" order by \"employee_id\") as lag1, " + "lag(\"employee_id\",1,'NA') " + "over (partition by \"birth_date\" order by \"employee_id\") as lag2, " + "max(sum(\"employee_id\")) over (partition by \"hire_date\" order by \"employee_id\") as count1, " + "max(sum(\"employee_id\")) over (partition by \"birth_date\" order by \"employee_id\") as count2\n" + "FROM \"employee\" group by \"employee_id\", \"hire_date\", \"birth_date\"";
    String expected5 = "SELECT LAG(\"employee_id\", 1, 'NA') OVER " + "(PARTITION BY \"hire_date\" ORDER BY \"employee_id\") AS \"$0\", " + "LAG(\"employee_id\", 1, 'NA') OVER " + "(PARTITION BY \"birth_date\" ORDER BY \"employee_id\") AS \"$1\", " + "MAX(SUM(\"employee_id\")) OVER (PARTITION BY \"hire_date\" ORDER BY \"employee_id\" " + "RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS \"$2\", " + "MAX(SUM(\"employee_id\")) OVER (PARTITION BY \"birth_date\" ORDER BY \"employee_id\" " + "RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS \"$3\"\n" + "FROM \"foodmart\".\"employee\"\n" + "GROUP BY \"employee_id\", \"hire_date\", \"birth_date\"";
    String query6 = "SELECT lag(\"employee_id\",1,'NA') over " + "(partition by \"hire_date\" order by \"employee_id\"), \"hire_date\"\n" + "FROM \"employee\"\n" + "group by \"hire_date\", \"employee_id\"";
    String expected6 = "SELECT LAG(\"employee_id\", 1, 'NA') " + "OVER (PARTITION BY \"hire_date\" ORDER BY \"employee_id\"), \"hire_date\"\n" + "FROM \"foodmart\".\"employee\"\n" + "GROUP BY \"hire_date\", \"employee_id\"";
    String query7 = "SELECT " + "count(distinct \"employee_id\") over (order by \"hire_date\") FROM \"employee\"";
    String expected7 = "SELECT " + "COUNT(DISTINCT \"employee_id\") OVER (ORDER BY \"hire_date\"" + " RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS \"$0\"\n" + "FROM \"foodmart\".\"employee\"";
    String query8 = "SELECT " + "sum(distinct \"position_id\") over (order by \"hire_date\") FROM \"employee\"";
    String expected8 = "SELECT CASE WHEN (COUNT(DISTINCT \"position_id\") OVER (ORDER BY \"hire_date\" " + "RANGE" + " BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) > 0 THEN COALESCE(SUM(DISTINCT " + "\"position_id\") OVER (ORDER BY \"hire_date\" RANGE BETWEEN UNBOUNDED " + "PRECEDING AND CURRENT ROW), 0) ELSE NULL END\n" + "FROM \"foodmart\".\"employee\"";
    HepProgramBuilder builder = new HepProgramBuilder();
    builder.addRuleClass(ProjectToWindowRule.class);
    HepPlanner hepPlanner = new HepPlanner(builder.build());
    RuleSet rules = RuleSets.ofList(CoreRules.PROJECT_TO_LOGICAL_PROJECT_AND_WINDOW);
    sql(query0).optimize(rules, hepPlanner).ok(expected0);
    sql(query1).optimize(rules, hepPlanner).ok(expected1);
    sql(query2).optimize(rules, hepPlanner).ok(expected2);
    sql(query3).optimize(rules, hepPlanner).ok(expected3);
    sql(query4).optimize(rules, hepPlanner).ok(expected4);
    sql(query5).optimize(rules, hepPlanner).ok(expected5);
    sql(query6).optimize(rules, hepPlanner).ok(expected6);
    sql(query7).optimize(rules, hepPlanner).ok(expected7);
    sql(query8).optimize(rules, hepPlanner).ok(expected8);
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3866">[CALCITE-3866]
 * "numeric field overflow" when running the generated SQL in PostgreSQL </a>.
 */
@Test
void testSumReturnType() {
    String query = "select sum(e1.\"store_sales\"), sum(e2.\"store_sales\") from \"sales_fact_dec_1998\" as " + "e1 , \"sales_fact_dec_1998\" as e2 where e1.\"product_id\" = e2.\"product_id\"";
    String expect = "SELECT SUM(CAST(\"t\".\"EXPR$0\" * \"t0\".\"$f1\" AS DECIMAL" + "(19, 4))), SUM(CAST(\"t\".\"$f2\" * \"t0\".\"EXPR$1\" AS DECIMAL(19, 4)))\n" + "FROM (SELECT \"product_id\", SUM(\"store_sales\") AS \"EXPR$0\", COUNT(*) AS \"$f2\"\n" + "FROM \"foodmart\".\"sales_fact_dec_1998\"\n" + "GROUP BY \"product_id\") AS \"t\"\n" + "INNER JOIN " + "(SELECT \"product_id\", COUNT(*) AS \"$f1\", SUM(\"store_sales\") AS \"EXPR$1\"\n" + "FROM \"foodmart\".\"sales_fact_dec_1998\"\n" + "GROUP BY \"product_id\") AS \"t0\" ON \"t\".\"product_id\" = \"t0\".\"product_id\"";
    HepProgramBuilder builder = new HepProgramBuilder();
    builder.addRuleClass(FilterJoinRule.class);
    builder.addRuleClass(AggregateProjectMergeRule.class);
    builder.addRuleClass(AggregateJoinTransposeRule.class);
    HepPlanner hepPlanner = new HepPlanner(builder.build());
    RuleSet rules = RuleSets.ofList(CoreRules.FILTER_INTO_JOIN, CoreRules.JOIN_CONDITION_PUSH, CoreRules.AGGREGATE_PROJECT_MERGE, CoreRules.AGGREGATE_JOIN_TRANSPOSE_EXTENDED);
    sql(query).withPostgresql().optimize(rules, hepPlanner).ok(expect);
}

