/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5711">[CALCITE-5711]
 * Implement the SINGLE_VALUE aggregation in PostgreSQL Dialect</a>.
 */
@Test
void testSubQueryWithSingleValue() {
    final String query = "select "product_class_id" as c
" + "from "product" where  "net_weight" > (select "product_class_id" from "product")";
    final String expectedMysql = "SELECT `product`.`product_class_id` AS `C`
" + "FROM `foodmart`.`product`
" + "LEFT JOIN (SELECT CASE COUNT(`product_class_id`) " + "WHEN 0 THEN NULL WHEN 1 THEN `product_class_id` ELSE (SELECT NULL
" + "UNION ALL
" + "SELECT NULL) END AS `$f0`
" + "FROM `foodmart`.`product`) AS `t0` ON TRUE
" + "WHERE `product`.`net_weight` > `t0`.`$f0`";
    final String expectedPostgresql = "SELECT "product"."product_class_id" AS "C"
" + "FROM "foodmart"."product"
" + "LEFT JOIN (SELECT CASE COUNT("product_class_id") WHEN 0 THEN NULL WHEN 1 THEN MIN("product_class_id") ELSE (SELECT CAST(NULL AS INTEGER)
" + "UNION ALL
" + "SELECT CAST(NULL AS INTEGER)) END AS "$f0"
" + "FROM "foodmart"."product") AS "t0" ON TRUE
" + "WHERE "product"."net_weight" > "t0"."$f0"";
    sql(query).withConfig(c -> c.withExpand(true)).withMysql().ok(expectedMysql).withPostgresql().ok(expectedPostgresql);
}

