/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3840">[CALCITE-3840]
 * Re-aliasing of VALUES that has column aliases produces wrong SQL in the
 * JDBC adapter</a>.
 */
@Test
void testValuesReAlias() {
    final RelBuilder builder = relBuilder();
    final RelNode root = builder.values(new String[] { "a", "b" }, 1, "x ", 2, "yy").values(new String[] { "a", "b" }, 1, "x ", 2, "yy").join(JoinRelType.FULL).project(builder.field("a")).build();
    final String expectedSql = "SELECT \"t\".\"a\"\n" + "FROM (VALUES (1, 'x '),\n" + "(2, 'yy')) AS \"t\" (\"a\", \"b\")\n" + "FULL JOIN (VALUES (1, 'x '),\n" + "(2, 'yy')) AS \"t0\" (\"a\", \"b\") ON TRUE";
    assertThat(toSql(root), isLinux(expectedSql));
    // Now with indentation.
    final String expectedSql2 = "SELECT \"t\".\"a\"\n" + "FROM (VALUES (1, 'x '),\n" + "        (2, 'yy')) AS \"t\" (\"a\", \"b\")\n" + "  FULL JOIN (VALUES (1, 'x '),\n" + "        (2, 'yy')) AS \"t0\" (\"a\", \"b\") ON TRUE";
    assertThat(toSql(root, DatabaseProduct.CALCITE.getDialect(), c -> c.withIndentation(2)), isLinux(expectedSql2));
}

@Test
void testTableScanHints() {
    final RelBuilder builder = relBuilder();
    builder.getCluster().setHintStrategies(HintStrategyTable.builder().hintStrategy("PLACEHOLDERS", HintPredicates.TABLE_SCAN).build());
    final RelNode root = builder.scan("orders").hints(RelHint.builder("PLACEHOLDERS").hintOption("a", "b").build()).project(builder.field("PRODUCT")).build();
    final String expectedSql = "SELECT \"PRODUCT\"\n" + "FROM \"scott\".\"orders\"";
    assertThat(toSql(root, DatabaseProduct.CALCITE.getDialect()), isLinux(expectedSql));
    final String expectedSql2 = "SELECT PRODUCT\n" + "FROM scott.orders\n" + "/*+ PLACEHOLDERS(a = 'b') */";
    assertThat(toSql(root, new AnsiSqlDialect(SqlDialect.EMPTY_CONTEXT)), isLinux(expectedSql2));
}

