/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4485">[CALCITE-4485]
 * JDBC adapter generates invalid SQL when one of the joins is {@code INNER
 * JOIN ... ON TRUE}</a>.
 */
@Test
void testCommaCrossJoin() {
    final Function<RelBuilder, RelNode> relFn = b -> b.scan("tpch", "customer").aggregate(b.groupKey(b.field("nation_name")), b.count().as("cnt1")).project(b.field("nation_name"), b.field("cnt1")).as("cust").scan("tpch", "lineitem").aggregate(b.groupKey(), b.count().as("cnt2")).project(b.field("cnt2")).as("lineitem").join(JoinRelType.INNER).scan("tpch", "part").join(JoinRelType.LEFT, b.equals(b.field(2, "cust", "nation_name"), b.field(2, "part", "p_brand"))).project(b.field("cust", "nation_name"), b.alias(b.call(SqlStdOperatorTable.MINUS, b.field("cnt1"), b.field("cnt2")), "f1")).build();
    // For documentation purposes, here is the query that was generated before
    // [CALCITE-4485] was fixed.
    final String previousPostgresql = "" + "SELECT \"t\".\"nation_name\", \"t\".\"cnt1\" - \"t0\".\"cnt2\" AS \"f1\"\n" + "FROM (SELECT \"nation_name\", COUNT(*) AS \"cnt1\"\n" + "FROM \"tpch\".\"customer\"\n" + "GROUP BY \"nation_name\") AS \"t\",\n" + "(SELECT COUNT(*) AS \"cnt2\"\n" + "FROM \"tpch\".\"lineitem\") AS \"t0\"\n" + "LEFT JOIN \"tpch\".\"part\" ON \"t\".\"nation_name\" = \"part\".\"p_brand\"";
    final String expectedPostgresql = "" + "SELECT \"t\".\"nation_name\", \"t\".\"cnt1\" - \"t0\".\"cnt2\" AS \"f1\"\n" + "FROM (SELECT \"nation_name\", COUNT(*) AS \"cnt1\"\n" + "FROM \"tpch\".\"customer\"\n" + "GROUP BY \"nation_name\") AS \"t\"\n" + "CROSS JOIN (SELECT COUNT(*) AS \"cnt2\"\n" + "FROM \"tpch\".\"lineitem\") AS \"t0\"\n" + "LEFT JOIN \"tpch\".\"part\" ON \"t\".\"nation_name\" = \"part\".\"p_brand\"";
    relFn(relFn).schema(CalciteAssert.SchemaSpec.TPCH).withPostgresql().ok(expectedPostgresql);
}

/**
 * A cartesian product is unparsed as a CROSS JOIN on Spark,
 * comma join on other DBs.
 *
 * @see SqlDialect#emulateJoinTypeForCrossJoin()
 */
@Test
void testCrossJoinEmulation() {
    final String expectedSpark = "SELECT *\n" + "FROM foodmart.employee\n" + "CROSS JOIN foodmart.department";
    final String expectedMysql = "SELECT *\n" + "FROM `foodmart`.`employee`,\n" + "`foodmart`.`department`";
    Consumer<String> fn = sql -> sql(sql).withSpark().ok(expectedSpark).withMysql().ok(expectedMysql);
    fn.accept("select * from \"employee\", \"department\"");
    fn.accept("select * from \"employee\" cross join \"department\"");
    fn.accept("select * from \"employee\" join \"department\" on true");
}

/**
 * Similar to {@link #testCommaCrossJoin()} (but uses SQL)
 * and {@link #testCrossJoinEmulation()} (but is 3 way). We generate a comma
 * join if the only joins are {@code CROSS JOIN} or
 * {@code INNER JOIN ... ON TRUE}, and if we're not on Spark.
 */
@Test
void testCommaCrossJoin3way() {
    String sql = "select *\n" + "from \"store\" as s\n" + "inner join \"employee\" as e on true\n" + "cross join \"department\" as d";
    final String expectedMysql = "SELECT *\n" + "FROM `foodmart`.`store`,\n" + "`foodmart`.`employee`,\n" + "`foodmart`.`department`";
    final String expectedSpark = "SELECT *\n" + "FROM foodmart.store\n" + "CROSS JOIN foodmart.employee\n" + "CROSS JOIN foodmart.department";
    sql(sql).withMysql().ok(expectedMysql).withSpark().ok(expectedSpark);
}

