    dialects().forEach((dialect, databaseProduct) -> {
        assertThat(dialect.quoteStringLiteral(""), is("''"));
        assertThat(dialect.quoteStringLiteral("can't run"), databaseProduct == DatabaseProduct.BIG_QUERY ? is("'can\\'t run'") : is("'can''t run'"));
        assertThat(dialect.unquoteStringLiteral("''"), is(""));
        if (databaseProduct == DatabaseProduct.BIG_QUERY) {
            assertThat(dialect.unquoteStringLiteral("'can\\'t run'"), is("can't run"));
        } else {
            assertThat(dialect.unquoteStringLiteral("'can't run'"), is("can't run"));
        }
    });
}

