/**
 * Test string literal encoding.
 */
@Test
void testStringLiteral() {
    final RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    final RelDataType varchar = typeFactory.createSqlType(SqlTypeName.VARCHAR);
    final RexBuilder builder = new RexBuilder(typeFactory);
    final NlsString latin1 = new NlsString("foobar", "LATIN1", SqlCollation.IMPLICIT);
    final NlsString utf8 = new NlsString("foobar", "UTF8", SqlCollation.IMPLICIT);
    RexLiteral literal = builder.makePreciseStringLiteral("foobar");
    assertEquals("'foobar'", literal.toString());
    literal = builder.makePreciseStringLiteral(new ByteString(new byte[] { 'f', 'o', 'o', 'b', 'a', 'r' }), "UTF8", SqlCollation.IMPLICIT);
    assertEquals("_UTF8'foobar'", literal.toString());
    assertEquals("_UTF8'foobar':CHAR(6) CHARACTER SET \"UTF-8\"", literal.computeDigest(RexDigestIncludeType.ALWAYS));
    literal = builder.makePreciseStringLiteral(new ByteString("\u82f1\u56fd".getBytes(StandardCharsets.UTF_8)), "UTF8", SqlCollation.IMPLICIT);
    assertEquals("_UTF8'\u82f1\u56fd'", literal.toString());
    // Test again to check decode cache.
    literal = builder.makePreciseStringLiteral(new ByteString("\u82f1".getBytes(StandardCharsets.UTF_8)), "UTF8", SqlCollation.IMPLICIT);
    assertEquals("_UTF8'\u82f1'", literal.toString());
    try {
        literal = builder.makePreciseStringLiteral(new ByteString("\u82f1\u56fd".getBytes(StandardCharsets.UTF_8)), "GB2312", SqlCollation.IMPLICIT);
        fail("expected exception, got " + literal);
    } catch (RuntimeException e) {
        assertThat(e.getMessage(), containsString("Failed to encode"));
    }
    literal = builder.makeLiteral(latin1, varchar);
    assertEquals("_LATIN1'foobar'", literal.toString());
    literal = builder.makeLiteral(utf8, varchar);
    assertEquals("_UTF8'foobar'", literal.toString());
}

