 * <a href="https://issues.apache.org/jira/browse/CALCITE-3198">[CALCITE-3198]
 * Enhance RexSimplify to handle (x&lt;&gt;a or x&lt;&gt;b)</a>.
 */
@Test
void testSimplifyOrNotEqualsNullable2() {
    checkSimplify3(or(ne(vInt(0), literal(1)), eq(vInt(1), literal(10)), ne(vInt(0), literal(2))), "OR(IS NOT NULL(?0.int0), null, =(?0.int1, 10))", "OR(IS NOT NULL(?0.int0), =(?0.int1, 10))", "true");
}

@Test
void testSimplifyOrNotEqualsNull() {
    checkSimplify3(or(ne(vInt(0), literal(1)), eq(vInt(1), nullInt), ne(vInt(0), literal(2))), "OR(IS NOT NULL(?0.int0), null)", "IS NOT NULL(?0.int0)", "true");
}

@Test
void testSimplifyAndPush() {
    final RelDataType intType = typeFactory.createSqlType(SqlTypeName.INTEGER);
    final RelDataType rowType = typeFactory.builder().add("a", intType).add("b", intType).build();
    final RexDynamicParam range = rexBuilder.makeDynamicParam(rowType, 0);
    final RexNode aRef = rexBuilder.makeFieldAccess(range, 0);
    final RexNode bRef = rexBuilder.makeFieldAccess(range, 1);
    checkSimplifyFilter(or(or(eq(aRef, literal(1)), eq(aRef, literal(1))), eq(aRef, literal(1))), "=(?0.a, 1)");
    checkSimplifyFilter(or(and(eq(aRef, literal(1)), eq(aRef, literal(1))), and(eq(aRef, literal(10)), eq(aRef, literal(1)))), "=(?0.a, 1)");
    checkSimplifyFilter(and(eq(aRef, literal(1)), or(eq(aRef, literal(1)), eq(aRef, literal(10)))), "=(?0.a, 1)");
    checkSimplifyFilter(and(or(eq(aRef, literal(1)), eq(aRef, literal(10))), eq(aRef, literal(1))), "=(?0.a, 1)");
    checkSimplifyFilter(and(gt(aRef, literal(10)), gt(aRef, literal(1))), ">(?0.a, 10)");
    checkSimplifyFilter(and(gt(aRef, literal(1)), gt(aRef, literal(10))), ">(?0.a, 10)");
    // "null AND NOT(null OR x)" => "null AND NOT(x)"
    checkSimplify3(and(nullBool, not(or(nullBool, vBool()))), "AND(null, NOT(?0.bool0))", "false", "NOT(?0.bool0)");
    // "x1 AND x2 AND x3 AND NOT(x1) AND NOT(x2) AND NOT(x0)" =>
    // "x3 AND null AND x1 IS NULL AND x2 IS NULL AND NOT(x0)"
    checkSimplify2(and(vBool(1), vBool(2), vBool(3), not(vBool(1)), not(vBool(2)), not(vBool())), "AND(?0.bool3, null, IS NULL(?0.bool1)," + " IS NULL(?0.bool2), NOT(?0.bool0))", "false");
}

@SuppressWarnings("UnstableApiUsage")
@Test
void testRangeSetMinus() {
    final RangeSet<Integer> setNone = ImmutableRangeSet.of();
    final RangeSet<Integer> setAll = setNone.complement();
    final RangeSet<Integer> setGt2 = ImmutableRangeSet.of(Range.greaterThan(2));
    final RangeSet<Integer> setGt1 = ImmutableRangeSet.of(Range.greaterThan(1));
    final RangeSet<Integer> setGe1 = ImmutableRangeSet.of(Range.atLeast(1));
    final RangeSet<Integer> setGt0 = ImmutableRangeSet.of(Range.greaterThan(0));
    final RangeSet<Integer> setComplex = ImmutableRangeSet.<Integer>builder().add(Range.closed(0, 2)).add(Range.singleton(3)).add(Range.greaterThan(5)).build();
    assertThat(setComplex, isRangeSet("[[0..2], [3..3], (5..+\u221e)]"));
    assertThat(RangeSets.minus(setAll, Range.singleton(1)), isRangeSet("[(-\u221e..1), (1..+\u221e)]"));
    assertThat(RangeSets.minus(setNone, Range.singleton(1)), is(setNone));
    assertThat(RangeSets.minus(setGt2, Range.singleton(1)), is(setGt2));
    assertThat(RangeSets.minus(setGt1, Range.singleton(1)), is(setGt1));
    assertThat(RangeSets.minus(setGe1, Range.singleton(1)), is(setGt1));
    assertThat(RangeSets.minus(setGt0, Range.singleton(1)), isRangeSet("[(0..1), (1..+\u221e)]"));
    assertThat(RangeSets.minus(setComplex, Range.singleton(1)), isRangeSet("[[0..1), (1..2], [3..3], (5..+\u221e)]"));
    assertThat(RangeSets.minus(setComplex, Range.singleton(2)), isRangeSet("[[0..2), [3..3], (5..+\u221e)]"));
    assertThat(RangeSets.minus(setComplex, Range.singleton(3)), isRangeSet("[[0..2], (5..+\u221e)]"));
    assertThat(RangeSets.minus(setComplex, Range.open(2, 3)), isRangeSet("[[0..2], [3..3], (5..+\u221e)]"));
    assertThat(RangeSets.minus(setComplex, Range.closed(2, 3)), isRangeSet("[[0..2), (5..+\u221e)]"));
    assertThat(RangeSets.minus(setComplex, Range.closed(2, 7)), isRangeSet("[[0..2), (7..+\u221e)]"));
}

@Test
void testSimplifyOrTerms() {
    final RelDataType intType = typeFactory.createSqlType(SqlTypeName.INTEGER);
    final RelDataType boolType = typeFactory.createSqlType(SqlTypeName.BOOLEAN);
    final RelDataType rowType = typeFactory.builder().add("a", intType).nullable(false).add("b", intType).nullable(true).add("c", intType).nullable(true).add("d", boolType).nullable(true).build();
    final RexDynamicParam range = rexBuilder.makeDynamicParam(rowType, 0);
    final RexNode aRef = rexBuilder.makeFieldAccess(range, 0);
    final RexNode bRef = rexBuilder.makeFieldAccess(range, 1);
    final RexNode cRef = rexBuilder.makeFieldAccess(range, 2);
    final RexNode dRef = rexBuilder.makeFieldAccess(range, 3);
    final RexLiteral literal1 = rexBuilder.makeExactLiteral(BigDecimal.ONE);
    final RexLiteral literal2 = rexBuilder.makeExactLiteral(BigDecimal.valueOf(2));
    final RexLiteral literal3 = rexBuilder.makeExactLiteral(BigDecimal.valueOf(3));
    final RexLiteral literal4 = rexBuilder.makeExactLiteral(BigDecimal.valueOf(4));
    final RexLiteral literal5 = rexBuilder.makeExactLiteral(BigDecimal.valueOf(5));
    // "a <> 1 or a = 1" ==> "true"
    checkSimplifyFilter(or(ne(aRef, literal1), eq(aRef, literal1)), "true");
    // "a = 1 or a <> 1" ==> "true"
    checkSimplifyFilter(or(eq(aRef, literal1), ne(aRef, literal1)), "true");
    // "a = 1 or a <> 2" could (and should) be simplified to "a <> 2"
    checkSimplifyFilter(or(eq(aRef, literal1), ne(aRef, literal2)), "<>(?0.a, 2)");
    // "a < 1 or a > 1" ==> "a <> 1"
    checkSimplifyFilter(or(lt(aRef, literal1), gt(aRef, literal1)), "<>(?0.a, 1)");
    // "(a >= 1 and a <= 3) or a <> 2", or equivalently
    // "a between 1 and 3 or a <> 2" ==> "true"
    checkSimplifyFilter(or(and(ge(aRef, literal1), le(aRef, literal3)), ne(aRef, literal2)), "true");
    // "(a >= 1 and a <= 3) or a < 4" ==> "a < 4"
    checkSimplifyFilter(or(and(ge(aRef, literal1), le(aRef, literal3)), lt(aRef, literal4)), "<(?0.a, 4)");
    // "(a >= 1 and a <= 2) or (a >= 4 and a <= 5) or a <> 3" ==> "a <> 3"
    checkSimplifyFilter(or(and(ge(aRef, literal1), le(aRef, literal2)), and(ge(aRef, literal4), le(aRef, literal5)), ne(aRef, literal3)), "<>(?0.a, 3)");
    // "(a >= 1 and a <= 2) or (a >= 4 and a <= 5) or a <> 4" ==> "true"
    checkSimplifyFilter(or(and(ge(aRef, literal1), le(aRef, literal2)), and(ge(aRef, literal4), le(aRef, literal5)), ne(aRef, literal4)), "true");
    // "(a >= 1 and a <= 2) or (a > 4 and a <= 5) or a <> 4" ==> "a <> 4"
    checkSimplifyFilter(or(and(ge(aRef, literal1), le(aRef, literal2)), and(gt(aRef, literal4), le(aRef, literal5)), ne(aRef, literal4)), "<>(?0.a, 4)");
    // "b <> 1 or b = 1" ==> "b is not null" with unknown as false
    final RexNode neOrEq = or(ne(bRef, literal(1)), eq(bRef, literal(1)));
    checkSimplifyFilter(neOrEq, "IS NOT NULL(?0.b)");
    // Careful of the excluded middle!
    // We cannot simplify "b <> 1 or b = 1" to "true" because if b is null, the
    // result is unknown.
    // TODO: "b = b" would be the best simplification.
    final RexNode simplified = this.simplify.simplifyUnknownAs(neOrEq, RexUnknownAs.UNKNOWN);
    assertThat(simplified, hasToString("OR(IS NOT NULL(?0.b), null)"));
    // "a is null or a is not null" ==> "true"
    checkSimplifyFilter(or(isNull(aRef), isNotNull(aRef)), "true");
    // "a is not null or a is null" ==> "true"
    checkSimplifyFilter(or(isNotNull(aRef), isNull(aRef)), "true");
    // "b is not null or b is null" ==> "true" (valid even though b nullable)
    checkSimplifyFilter(or(isNotNull(bRef), isNull(bRef)), "true");
    // "b is null b > 1 or b <= 1" ==> "true"
    checkSimplifyFilter(or(isNull(bRef), gt(bRef, literal(1)), le(bRef, literal(1))), "true");
    // "b > 1 or b <= 1 or b is null" ==> "true"
    checkSimplifyFilter(or(gt(bRef, literal(1)), le(bRef, literal(1)), isNull(bRef)), "true");
    // "b <= 1 or b > 1 or b is null" ==> "true"
    checkSimplifyFilter(or(le(bRef, literal(1)), gt(bRef, literal(1)), isNull(bRef)), "true");
    // "b < 2 or b > 0 or b is null" ==> "true"
    checkSimplifyFilter(or(lt(bRef, literal(2)), gt(bRef, literal(0)), isNull(bRef)), "true");
    // "b is not null or c is null" unchanged,
    // but "c is null" is moved to front
    checkSimplifyFilter(or(isNotNull(bRef), isNull(cRef)), "OR(IS NULL(?0.c), IS NOT NULL(?0.b))");
    // "d is null or d is not false" => "d is null or d"
    // (because after the first term we know that d cannot be null)
    checkSimplifyFilter(or(isNull(dRef), isNotFalse(dRef)), "OR(IS NULL(?0.d), ?0.d)");
    // multiple predicates are handled correctly
    checkSimplifyFilter(and(or(eq(bRef, literal(1)), eq(bRef, literal(2))), eq(bRef, literal(2)), eq(aRef, literal(3)), or(eq(aRef, literal(3)), eq(aRef, literal(4)))), "AND(=(?0.b, 2), =(?0.a, 3))");
    checkSimplify3(or(lt(vInt(), nullInt), ne(literal(0), vInt())), "OR(null, <>(0, ?0.int0))", "<>(0, ?0.int0)", "true");
}

/**
 * Unit test for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5780">[CALCITE-5780]
 * Simplify '1 > x OR 1 <= x OR x IS NULL' to TRUE</a>.
 */
@Test
void testSimplifyOrTermsWithReverseOrderComparison() {
    final RelDataType intType = typeFactory.createSqlType(SqlTypeName.INTEGER);
    final RelDataType rowType = typeFactory.builder().add("a", intType).nullable(true).build();
    final RexDynamicParam range = rexBuilder.makeDynamicParam(rowType, 0);
    final RexNode aRef = rexBuilder.makeFieldAccess(range, 0);
    // "1 > a or 1 <= a or a is null" ==> "true"
    checkSimplifyFilter(or(gt(literal(1), aRef), le(literal(1), aRef), isNull(aRef)), "true");
    // "1 <= a or 1 > a or a is null" ==> "true"
    checkSimplifyFilter(or(le(literal(1), aRef), gt(literal(1), aRef), isNull(aRef)), "true");
    // "a is null or 1 > a or 1 <= a" ==> "true"
    checkSimplifyFilter(or(isNull(aRef), gt(literal(1), aRef), le(literal(1), aRef)), "true");
    // "2 > a or 0 < a or a is null" ==> "true"
    checkSimplifyFilter(or(gt(literal(2), aRef), lt(literal(0), aRef), isNull(aRef)), "true");
    // "1 > a or a >= 1 or a is null" ==> "true"
    checkSimplifyFilter(or(gt(literal(1), aRef), ge(aRef, literal(1)), isNull(aRef)), "true");
    // "1 <= a or a < 1 or a is null" ==> "true"
    checkSimplifyFilter(or(le(literal(1), aRef), lt(aRef, literal(1)), isNull(aRef)), "true");
    // "a >= 1 or 1 > a or a is null" ==> "true"
    checkSimplifyFilter(or(ge(aRef, literal(1)), gt(literal(1), aRef), isNull(aRef)), "true");
}

@Test
void testSimplifyRange() {
    final RexNode aRef = input(tInt(), 0);
    // ((0 < a and a <= 10) or a >= 15) and a <> 6 and a <> 12
    RexNode expr = and(or(and(lt(literal(0), aRef), le(aRef, literal(10))), ge(aRef, literal(15))), ne(aRef, literal(6)), ne(aRef, literal(12)));
    final String simplified = "SEARCH($0, Sarg[(0..6), (6..10], [15..+\u221e)])";
    final String expanded = "OR(AND(>($0, 0), <($0, 6)), AND(>($0, 6)," + " <=($0, 10)), >=($0, 15))";
    checkSimplify(expr, simplified).expandedSearch(expanded);
}

