@Test
void testSimplifyRange3() {
    final RexNode aRef = input(tInt(true), 0);
    // (0 < a and a <= 10) or a is null or (8 < a and a < 12) or a >= 15
    RexNode expr = or(and(lt(literal(0), aRef), le(aRef, literal(10))), isNull(aRef), and(lt(literal(8), aRef), lt(aRef, literal(12))), ge(aRef, literal(15)));
    // [CALCITE-4190] causes "or a >= 15" to disappear from the simplified form.
    final String simplified = "SEARCH($0, Sarg[(0..12), [15..+\u221e); NULL AS TRUE])";
    final String expanded = "OR(IS NULL($0), AND(>($0, 0), <($0, 12)), >=($0, 15))";
    checkSimplify(expr, simplified).expandedSearch(expanded);
}

