@Test
void testSimplifyRange8() {
    final RexNode aRef = input(tInt(true), 0);
    // a not in (1.0, 2.0)
    RexNode expr = not(in(aRef, literal(new BigDecimal("1.0")), literal(new BigDecimal("2.0"))));
    final String simplified = "SEARCH($0, " + "Sarg[(-\u221e..1.0:DECIMAL(2, 1))," + " (1.0:DECIMAL(2, 1)..2.0:DECIMAL(2, 1))," + " (2.0:DECIMAL(2, 1)..+\u221e)]:DECIMAL(2, 1))";
    checkSimplify(expr, simplified);
    // The following identical to previous, and simplifies to the same:
    //   a < 1.0 or (1.0 < a and a < 2.0) or 2.0 < a
    RexNode expr2 = or(lt(aRef, literal(new BigDecimal("1.0"))), and(lt(literal(new BigDecimal("1.0")), aRef), lt(aRef, literal(new BigDecimal("2.0")))), lt(literal(new BigDecimal("2.0")), aRef));
    checkSimplify(expr2, simplified);
    // Identical to previous, except one "2.0" is "2":
    //   a < 1.0 or (1.0 < a and a < 2.0) or 2.00 < a
    RexNode expr3 = or(lt(aRef, literal(new BigDecimal("1.0"))), and(lt(literal(new BigDecimal("1.0")), aRef), lt(aRef, literal(new BigDecimal("2.0")))), lt(literal(new BigDecimal("2")), aRef));
    final String simplified3 = "SEARCH($0, " + "Sarg[(-\u221e..1.0:DECIMAL(11, 1))," + " (1.0:DECIMAL(11, 1)..2.0:DECIMAL(11, 1))," + " (2:DECIMAL(11, 1)..+\u221e)]:DECIMAL(11, 1))";
    checkSimplify(expr3, simplified3);
}

@Test
void testSimplifyRange9() {
    // Contiguous ranges can be merged:
    //   a > 1 and <= 2 or a > 2.0 and a < 3
    // becomes
    //   a > 1 and a < 3
    final RexNode aRef = input(tInt(true), 0);
    RexNode expr = or(and(gt(aRef, literal(1)), le(aRef, literal(2))), and(gt(aRef, literal(new BigDecimal("2.0"))), lt(aRef, literal(3))));
    final String simplified = "SEARCH($0, " + "Sarg[(1:DECIMAL(11, 1)..3:DECIMAL(11, 1))]:DECIMAL(11, 1))";
    checkSimplify(expr, simplified);
}

