void testSimplifyAndIsNotNullWithEquality() {
    // "AND(IS NOT NULL(x), =(x, y)) => AND(IS NOT NULL(x), =(x, y)) (unknownAsFalse=false),
    // "=(x, y)" (unknownAsFalse=true)
    checkSimplify2(and(isNotNull(vInt(0)), eq(vInt(0), vInt(1))), "AND(IS NOT NULL(?0.int0), =(?0.int0, ?0.int1))", "=(?0.int0, ?0.int1)");
    // "AND(IS NOT NULL(x), =(x, y)) => "=(x, y)"
    checkSimplify(and(isNotNull(vIntNotNull(0)), eq(vIntNotNull(0), vInt(1))), "=(?0.notNullInt0, ?0.int1)");
