@Test
void testConstantMap() {
    final RelDataType intType = typeFactory.createSqlType(SqlTypeName.INTEGER);
    final RelDataType bigintType = typeFactory.createSqlType(SqlTypeName.BIGINT);
    final RelDataType decimalType = typeFactory.createSqlType(SqlTypeName.DECIMAL, 4, 2);
    final RelDataType charType = typeFactory.createSqlType(SqlTypeName.CHAR, 5);
    final RelDataType rowType = typeFactory.builder().add("a", intType).add("b", intType).add("c", intType).add("d", intType).add("e", bigintType).add("f", decimalType).add("g", charType).build();
    final RexDynamicParam range = rexBuilder.makeDynamicParam(rowType, 0);
    final RexNode aRef = rexBuilder.makeFieldAccess(range, 0);
    final RexNode bRef = rexBuilder.makeFieldAccess(range, 1);
    final RexNode cRef = rexBuilder.makeFieldAccess(range, 2);
    final RexNode dRef = rexBuilder.makeFieldAccess(range, 3);
    final RexNode eRef = rexBuilder.makeFieldAccess(range, 4);
    final RexNode fRef = rexBuilder.makeFieldAccess(range, 5);
    final RexNode gRef = rexBuilder.makeFieldAccess(range, 6);
    final ImmutableMap<RexNode, RexNode> map = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(aRef, bRef), eq(cRef, literal(1)), eq(cRef, aRef), eq(dRef, eRef)));
    assertThat(getString(map), is("{1=?0.c, ?0.a=?0.b, ?0.b=?0.a, ?0.c=1, ?0.d=?0.e, ?0.e=?0.d}"));
    // Contradictory constraints yield no constants
    final RexNode ref0 = rexBuilder.makeInputRef(rowType, 0);
    final ImmutableMap<RexNode, RexNode> map2 = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(ref0, literal(1)), eq(ref0, literal(2))));
    assertThat(getString(map2), is("{}"));
    // Contradictory constraints on field accesses SHOULD yield no constants
    // but currently there's a bug
    final ImmutableMap<RexNode, RexNode> map3 = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(aRef, literal(1)), eq(aRef, literal(2))));
    assertThat(getString(map3), is("{1=?0.a, 2=?0.a}"));
    // Different precision and scale in decimal
    final ImmutableMap<RexNode, RexNode> map4 = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(cast(fRef, typeFactory.createSqlType(SqlTypeName.DECIMAL, 3, 1)), rexBuilder.makeExactLiteral(BigDecimal.valueOf(21.2)))));
    assertThat(getString(map4), is("{21.2:DECIMAL(3, 1)=CAST(?0.f):DECIMAL(3, 1) NOT NULL," + " CAST(?0.f):DECIMAL(3, 1) NOT NULL=21.2:DECIMAL(3, 1)}"));
    // Different precision in char
    final ImmutableMap<RexNode, RexNode> map5 = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(cast(gRef, typeFactory.createSqlType(SqlTypeName.CHAR, 3)), rexBuilder.makeLiteral("abc"))));
    assertThat(getString(map5), is("{'abc'=CAST(?0.g):CHAR(3) NOT NULL," + " CAST(?0.g):CHAR(3) NOT NULL='abc'}"));
    // Cast bigint to int
    final ImmutableMap<RexNode, RexNode> map6 = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(cast(eRef, typeFactory.createSqlType(SqlTypeName.INTEGER)), literal(1))));
    assertThat(getString(map6), is("{1=CAST(?0.e):INTEGER NOT NULL, CAST(?0.e):INTEGER NOT NULL=1}"));
    // Cast int to bigint
    final ImmutableMap<RexNode, RexNode> map7 = RexUtil.predicateConstants(RexNode.class, rexBuilder, ImmutableList.of(eq(cast(aRef, typeFactory.createSqlType(SqlTypeName.BIGINT)), literal(1))));
    assertThat(getString(map7), is("{1=CAST(?0.a):BIGINT NOT NULL, ?0.a=1}"));
}

