    checkSimplify(coalesce(vIntNotNull(), vIntNotNull()), "?0.notNullInt0");
    checkSimplify(coalesce(vIntNotNull(), literal(1)), "?0.notNullInt0");
    checkSimplifyUnchanged(coalesce(vInt(), literal(1)));
    checkSimplify(coalesce(vInt(), plus(vInt(), vIntNotNull()), literal(1), vIntNotNull()), "COALESCE(?0.int0, +(?0.int0, ?0.notNullInt0), 1)");
    checkSimplify(coalesce(gt(nullInt, nullInt), trueLiteral), "true");
    checkSimplify(coalesce(unaryPlus(nullInt), unaryPlus(vInt())), "?0.int0");
    checkSimplifyUnchanged(coalesce(vInt(1), vInt()));
    checkSimplify(coalesce(nullInt, vInt()), "?0.int0");
    checkSimplify(coalesce(vInt(), nullInt, vInt(1)), "COALESCE(?0.int0, ?0.int1)");
    // first arg not null
    checkSimplify(coalesce(vDecimalNotNull(), vDecimal()), "?0.notNullDecimal0");
    checkSimplifyUnchanged(coalesce(vDecimal(), vDecimalNotNull()));
    // repeated arg
    checkSimplify(coalesce(vDecimal(), vDecimal()), "?0.decimal0");
    // repeated arg
    checkSimplify(coalesce(vDecimalNotNull(), vDecimalNotNull()), "?0.notNullDecimal0");
    checkSimplify(coalesce(vDecimalNotNull(), literal(1)), "?0.notNullDecimal0");
    checkSimplifyUnchanged(coalesce(vDecimal(), literal(1)));
    checkSimplify(coalesce(vDecimal(), plus(vDecimal(), vDecimalNotNull()), literal(1), vDecimalNotNull()), "COALESCE(?0.decimal0, +(?0.decimal0, ?0.notNullDecimal0), 1)");
    checkSimplify(coalesce(gt(nullDecimal, nullDecimal), trueLiteral), "true");
    checkSimplify(coalesce(unaryPlus(nullDecimal), unaryPlus(vDecimal())), "?0.decimal0");
    checkSimplifyUnchanged(coalesce(vDecimal(1), vDecimal()));
    checkSimplify(coalesce(nullDecimal, vDecimal()), "?0.decimal0");
    checkSimplify(coalesce(vDecimal(), nullInt, vDecimal(1)), "COALESCE(?0.decimal0, ?0.decimal1)");
