    checkSimplify3(or(eq(vInt(1), vInt(1)), not(ge(vInt(2), vInt(2)))), "OR(null, IS NOT NULL(?0.int1), AND(null, IS NULL(?0.int2)))", "IS NOT NULL(?0.int1)", "true");
