    checkSimplify3(not(or(eq(vInt(1), vInt(1)), not(ge(vInt(2), vInt(2))))), "AND(null, IS NULL(?0.int1), OR(null, IS NOT NULL(?0.int2)))", "false", "IS NULL(?0.int1)");
