@SuppressWarnings("UnstableApiUsage")
@Test
void testSargComplexity() {
    checkSarg("complexity of 'x is not null'", Sarg.of(RexUnknownAs.FALSE, RangeSets.<Integer>rangeSetAll()), is(1), is("Sarg[IS NOT NULL]"));
    checkSarg("complexity of 'x is null'", Sarg.of(RexUnknownAs.TRUE, ImmutableRangeSet.<Integer>of()), is(1), is("Sarg[IS NULL]"));
    checkSarg("complexity of 'false'", Sarg.of(RexUnknownAs.FALSE, ImmutableRangeSet.<Integer>of()), is(0), is("Sarg[FALSE]"));
    checkSarg("complexity of 'true'", Sarg.of(RexUnknownAs.TRUE, RangeSets.<Integer>rangeSetAll()), is(2), is("Sarg[TRUE]"));
    checkSarg("complexity of 'x = 1'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.of(Range.singleton(1))), is(1), is("Sarg[1]"));
    checkSarg("complexity of 'x > 1'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.of(Range.greaterThan(1))), is(1), is("Sarg[(1..+\u221E)]"));
    checkSarg("complexity of 'x >= 1'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.of(Range.atLeast(1))), is(1), is("Sarg[[1..+\u221E)]"));
    checkSarg("complexity of 'x > 1 or x is null'", Sarg.of(RexUnknownAs.TRUE, ImmutableRangeSet.of(Range.greaterThan(1))), is(2), is("Sarg[(1..+\u221E); NULL AS TRUE]"));
    checkSarg("complexity of 'x <> 1'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.of(Range.singleton(1)).complement()), is(1), is("Sarg[(-\u221E..1), (1..+\u221E)]"));
    checkSarg("complexity of 'x <> 1 or x is null'", Sarg.of(RexUnknownAs.TRUE, ImmutableRangeSet.of(Range.singleton(1)).complement()), is(2), is("Sarg[(-\u221E..1), (1..+\u221E); NULL AS TRUE]"));
    checkSarg("complexity of 'x < 10 or x >= 20'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.<Integer>builder().add(Range.lessThan(10)).add(Range.atLeast(20)).build()), is(2), is("Sarg[(-\u221E..10), [20..+\u221E)]"));
    checkSarg("complexity of 'x in (2, 4, 6) or x > 20'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.<Integer>builder().add(Range.singleton(2)).add(Range.singleton(4)).add(Range.singleton(6)).add(Range.greaterThan(20)).build()), is(4), is("Sarg[2, 4, 6, (20..+\u221E)]"));
    checkSarg("complexity of 'x between 3 and 8 or x between 10 and 20'", Sarg.of(RexUnknownAs.UNKNOWN, ImmutableRangeSet.<Integer>builder().add(Range.closed(3, 8)).add(Range.closed(10, 20)).build()), is(2), is("Sarg[[3..8], [10..20]]"));
}

