/**
 * Tests
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4094">[CALCITE-4094]
 * RexSimplify should simplify more always true OR expressions</a>.
 */
@Test
void testSimplifyLike() {
    final RexNode ref = input(tVarchar(true, 10), 0);
    checkSimplify3(like(ref, literal("%")), "OR(null, IS NOT NULL($0))", "IS NOT NULL($0)", "true");
    checkSimplify3(like(ref, literal("%"), literal("#")), "OR(null, IS NOT NULL($0))", "IS NOT NULL($0)", "true");
    checkSimplify3(or(like(ref, literal("%")), like(ref, literal("% %"))), "OR(null, IS NOT NULL($0), LIKE($0, '% %'))", "OR(IS NOT NULL($0), LIKE($0, '% %'))", "true");
    checkSimplify(or(isNull(ref), like(ref, literal("%"))), "true");
    checkSimplify(or(isNull(ref), like(ref, literal("%"), literal("#"))), "true");
    checkSimplifyUnchanged(like(ref, literal("%A")));
    checkSimplifyUnchanged(like(ref, literal("%A"), literal("#")));
    // As above, but ref is NOT NULL
    final RexNode refMandatory = vVarcharNotNull(0);
    checkSimplify(like(refMandatory, literal("%")), "true");
    checkSimplify(or(like(refMandatory, literal("%")), like(refMandatory, literal("% %"))), "true");
    // NOT LIKE and NOT SIMILAR TO are not allowed in Rex land
    try {
        rexBuilder.makeCall(SqlStdOperatorTable.NOT_LIKE, ref, literal("%"));
    } catch (AssertionError e) {
        assertThat(e.getMessage(), is("unsupported negated operator NOT LIKE"));
    }
    try {
        rexBuilder.makeCall(SqlStdOperatorTable.NOT_SIMILAR_TO, ref, literal("%"));
    } catch (AssertionError e) {
        assertThat(e.getMessage(), is("unsupported negated operator NOT SIMILAR TO"));
    }
    // NOT(LIKE)
    checkSimplify3(not(like(ref, literal("%"))), "NOT(OR(null, IS NOT NULL($0)))", "false", "NOT(IS NOT NULL($0))");
    // SIMILAR TO is not optimized
    checkSimplifyUnchanged(rexBuilder.makeCall(SqlStdOperatorTable.SIMILAR_TO, ref, literal("%")));
    // NOT(SIMILAR TO) is not optimized
    checkSimplifyUnchanged(not(rexBuilder.makeCall(SqlStdOperatorTable.SIMILAR_TO, ref, literal("%"))));
}

@Test
void testSimplifyNullCheckInFilter() {
    final RexNode iRef = input(tInt(true), 0);
    final RexNode vRef = input(tVarchar(true, 10), 1);
    final RexNode iRef2 = input(tInt(true), 2);
    final RexNode vRef2 = input(tVarchar(true, 10), 3);
    final RexNode fieldRef = vVarchar();
    // CAST(x) > 1 AND x IS NOT NULL
    RelDataType longType = typeFactory.createTypeWithNullability(typeFactory.createSqlType(SqlTypeName.BIGINT), false);
    checkSimplifyFilter(and(isNotNull(iRef), gt(cast(iRef, longType), literal(BigDecimal.ONE))), ">(CAST($0):BIGINT NOT NULL, 1)");
    // LIKE
    checkSimplifyFilter(and(isNotNull(vRef), like(vRef, literal("%hello%"))), "LIKE($1, '%hello%')");
    // LIKE on field ref
    checkSimplifyFilter(and(isNotNull(fieldRef), like(fieldRef, literal("%hello%"))), "LIKE(?0.varchar0, '%hello%')");
    // NOT LIKE
    checkSimplifyFilter(and(isNotNull(vRef), not(like(vRef, literal("%hello%")))), "NOT(LIKE($1, '%hello%'))");
    // OR(LIKE, LIKE)
    checkSimplifyFilter(and(isNotNull(vRef), or(like(vRef, literal("%hello%")), like(vRef, literal("%bye%")))), "OR(LIKE($1, '%hello%'), LIKE($1, '%bye%'))");
    // SIMILAR TO
    checkSimplifyFilter(and(isNotNull(vRef), similar(vRef, literal("%hello%"))), "SIMILAR TO($1, '%hello%')");
    // Arithmetic expression compared to value and checked for not null
    checkSimplifyFilter(and(isNotNull(mul(iRef, iRef2)), gt(mul(iRef, iRef2), literal(10))), ">(*($0, $2), 10)");
    // COALESCE: not simplified because expression is not strong
    checkSimplifyFilter(and(isNotNull(vRef2), coalesce(vRef, vRef2)), "AND(COALESCE($1, $3), IS NOT NULL($3))");
    // Not simplified because expression is not strong
    checkSimplifyFilter(and(isNotNull(vRef), or(like(vRef, literal("%hello%")), like(vRef2, literal("%bye%")))), "AND(OR(LIKE($1, '%hello%'), LIKE($3, '%bye%')), IS NOT NULL($1))");
}

