@Test
void testSimple() {
    // pattern(a)
    final Pattern p = Pattern.builder().symbol("a").build();
    assertThat(p, hasToString("a"));
    final String[] rows = { "", "a", "", "a" };
    final Matcher<String> matcher = Matcher.<String>builder(p.toAutomaton()).add("a", s -> s.get().contains("a")).build();
    final String expected = "[[a], [a]]";
    assertThat(matcher.match(rows), isMatchList(expected));
}

@Test
void testSequence() {
    // pattern(a b)
    final Pattern p = Pattern.builder().symbol("a").symbol("b").seq().build();
    assertThat(p, hasToString("a b"));
    final String[] rows = { "", "a", "", "ab", "a", "ab", "b", "b" };
    final Matcher<String> matcher = Matcher.<String>builder(p.toAutomaton()).add("a", s -> s.get().contains("a")).add("b", s -> s.get().contains("b")).build();
    final String expected = "[[a, ab], [ab, b]]";
    assertThat(matcher.match(rows), isMatchList(expected));
}

@Test
void testStar() {
    // pattern(a* b)
    final Pattern p = Pattern.builder().symbol("a").star().symbol("b").seq().build();
    assertThat(p, hasToString("(a)* b"));
    final String[] rows = { "", "a", "", "b", "", "ab", "a", "ab", "b", "b" };
    final Matcher<String> matcher = Matcher.<String>builder(p.toAutomaton()).add("a", s -> s.get().contains("a")).add("b", s -> s.get().contains("b")).build();
    final String expected = "[[b], [ab], [ab], [ab, a, ab], [a, ab], [b], [ab, b], [ab, a, ab, b], " + "[a, ab, b], [b]]";
    assertThat(matcher.match(rows), isMatchList(expected));
}

