@Test
void testOptional() {
    // pattern(a+ b)
    final Pattern p = Pattern.builder().symbol("a").symbol("b").optional().seq().symbol("c").seq().build();
    assertThat(p, hasToString("a b? c"));
    final String rows = "acabcabbc";
    final Matcher<Character> matcher = Matcher.<Character>builder(p.toAutomaton()).add("a", s -> s.get() == 'a').add("b", s -> s.get() == 'b').add("c", s -> s.get() == 'c').build();
    final String expected = "[[a, c], [a, b, c]]";
    assertThat(matcher.match(chars(rows)), isMatchList(expected));
}

@Test
void testRepeat() {
    // pattern(a b{0, 2} c)
    checkRepeat(0, 2, "a (b){0, 2} c", "[[a, c], [a, b, c], [a, b, b, c]]");
    // pattern(a b{0, 1} c)
    checkRepeat(0, 1, "a (b){0, 1} c", "[[a, c], [a, b, c]]");
    // pattern(a b{1, 1} c)
    checkRepeat(1, 1, "a (b){1} c", "[[a, b, c]]");
    // pattern(a b{1,3} c)
    checkRepeat(1, 3, "a (b){1, 3} c", "[[a, b, c], [a, b, b, c], [a, b, b, b, c]]");
    // pattern(a b{1,2} c)
    checkRepeat(1, 2, "a (b){1, 2} c", "[[a, b, c], [a, b, b, c]]");
    // pattern(a b{2,3} c)
    checkRepeat(2, 3, "a (b){2, 3} c", "[[a, b, b, c], [a, b, b, b, c]]");
}

@Test
void testRepeatComposite() {
    // pattern(a (b a){1, 2} c)
    final Pattern p = Pattern.builder().symbol("a").symbol("b").symbol("a").seq().repeat(1, 2).seq().symbol("c").seq().build();
    assertThat(p, hasToString("a (b a){1, 2} c"));
    final String rows = "acabcabbcabbbcabbbbcabdbcabacababcababac";
    final Matcher<Character> matcher = Matcher.<Character>builder(p.toAutomaton()).add("a", s -> s.get() == 'a').add("b", s -> s.get() == 'b').add("c", s -> s.get() == 'c').build();
    assertThat(matcher.match(chars(rows)), isMatchList("[[a, b, a, c], [a, b, a, c], [a, b, a, b, a, c]]"));
}

@Test
void testResultWithLabels() {
    // pattern(a)
    final Pattern p = Pattern.builder().symbol("A").symbol("B").seq().build();
    assertThat(p, hasToString("A B"));
    final String[] rows = { "", "a", "ab", "a", "b" };
    final Matcher<String> matcher = Matcher.<String>builder(p.toAutomaton()).add("A", s -> s.get().contains("a")).add("B", s -> s.get().contains("b")).build();
    final Matcher.PartitionState<String> partitionState = matcher.createPartitionState(0, 0);
    final ImmutableList.Builder<Matcher.PartialMatch<String>> builder = ImmutableList.builder();
    MemoryFactory<String> memoryFactory = new MemoryFactory<>(0, 0);
    for (String row : rows) {
        memoryFactory.add(row);
        builder.addAll(matcher.matchOneWithSymbols(memoryFactory.create(), partitionState));
    }
    assertThat(builder.build(), hasToString("[[(A, a), (B, ab)], [(A, a), (B, b)]]"));
}

