@Test
void convertAutomaton() {
    final Pattern.PatternBuilder builder = Pattern.builder();
    final Pattern pattern = builder.symbol("A").repeat(1, 2).build();
    final Automaton automaton = pattern.toAutomaton();
    final DeterministicAutomaton da = new DeterministicAutomaton(automaton);
    assertThat(da.startState, is(new DeterministicAutomaton.MultiState(new Automaton.State(0), new Automaton.State(2))));
    // Result should have three states
    // 0 -A-> 1 -A-> 2
    // 1 and 2 should be final
    assertThat(da.getTransitions(), hasSize(2));
    assertThat(da.getEndStates(), hasSize(2));
}

@Test
void convertAutomaton2() {
    final Pattern.PatternBuilder builder = Pattern.builder();
    final Pattern pattern = builder.symbol("A").symbol("B").or().build();
    final Automaton automaton = pattern.toAutomaton();
    final DeterministicAutomaton da = new DeterministicAutomaton(automaton);
    // Result should have two transitions
    // 0 -A-> 1
    //   -B->
    // 1 should be final
    assertThat(da.getTransitions(), hasSize(2));
    assertThat(da.getEndStates(), hasSize(1));
}

@Test
void convertAutomaton3() {
    final Pattern.PatternBuilder builder = Pattern.builder();
    final Pattern pattern = builder.symbol("A").symbol("B").star().seq().build();
    final Automaton automaton = pattern.toAutomaton();
    final DeterministicAutomaton da = new DeterministicAutomaton(automaton);
    // Result should have two transitions
    // 0 -A-> 1 -B-> 2 (which again goes to 2 on a "B")
    // 1 should be final
    assertThat(da.getTransitions(), hasSize(3));
    assertThat(da.getEndStates(), hasSize(2));
}

@Test
void convertAutomaton4() {
    final Pattern.PatternBuilder builder = Pattern.builder();
    final Pattern pattern = builder.symbol("A").symbol("B").optional().seq().symbol("A").seq().build();
    final Automaton automaton = pattern.toAutomaton();
    final DeterministicAutomaton da = new DeterministicAutomaton(automaton);
    // Result should have four transitions and one end state
    assertThat(da.getTransitions(), hasSize(4));
    assertThat(da.getEndStates(), hasSize(1));
}

