@Test
void testMergeJoin2() {
    final JoinType[] joinTypes = { JoinType.INNER, JoinType.SEMI };
    for (JoinType joinType : joinTypes) {
        // Matching keys at start
        testIntersect(newArrayList(1, 3, 4), newArrayList(1, 4), equalTo("[1, 4]"), joinType);
        // Matching key at start and end of right, not of left
        testIntersect(newArrayList(0, 1, 3, 4, 5), newArrayList(1, 4), equalTo("[1, 4]"), joinType);
        // Matching key at start and end of left, not right
        testIntersect(newArrayList(1, 3, 4), newArrayList(0, 1, 4, 5), equalTo("[1, 4]"), joinType);
        // Matching key not at start or end of left or right
        testIntersect(newArrayList(0, 2, 3, 4, 5), newArrayList(1, 3, 4, 6), equalTo("[3, 4]"), joinType);
        // Matching duplicated keys
        testIntersect(newArrayList(1, 3, 4), newArrayList(1, 1, 4, 4), equalTo(joinType == JoinType.INNER ? "[1, 1, 4, 4]" : "[1, 4]"), joinType);
    }
    // ANTI join tests:
    // Matching keys at start
    testIntersect(newArrayList(1, 3, 4), newArrayList(1, 4), equalTo("[3]"), JoinType.ANTI);
    // Matching key at start and end of right, not of left
    testIntersect(newArrayList(0, 1, 3, 4, 5), newArrayList(1, 4), equalTo("[0, 3, 5]"), JoinType.ANTI);
    // Matching key at start and end of left, not right
    testIntersect(newArrayList(1, 3, 4), newArrayList(0, 1, 4, 5), equalTo("[3]"), JoinType.ANTI);
    // Matching key not at start or end of left or right
    testIntersect(newArrayList(0, 2, 3, 4, 5), newArrayList(1, 3, 4, 6), equalTo("[0, 2, 5]"), JoinType.ANTI);
    // Matching duplicated keys
    testIntersect(newArrayList(1, 3, 4), newArrayList(1, 1, 4, 4), equalTo("[3]"), JoinType.ANTI);
    // LEFT join tests:
    // Matching keys at start
    testIntersect(newArrayList(1, 3, 4), newArrayList(1, 4), equalTo("[1-1, 3-null, 4-4]"), equalTo("[1-1, 3-null, 4-4, null-null]"), JoinType.LEFT);
    // Matching key at start and end of right, not of left
    testIntersect(newArrayList(0, 1, 3, 4, 5), newArrayList(1, 4), equalTo("[0-null, 1-1, 3-null, 4-4, 5-null]"), equalTo("[0-null, 1-1, 3-null, 4-4, 5-null, null-null]"), JoinType.LEFT);
    // Matching key at start and end of left, not right
    testIntersect(newArrayList(1, 3, 4), newArrayList(0, 1, 4, 5), equalTo("[1-1, 3-null, 4-4]"), equalTo("[1-1, 3-null, 4-4, null-null]"), JoinType.LEFT);
    // Matching key not at start or end of left or right
    testIntersect(newArrayList(0, 2, 3, 4, 5), newArrayList(1, 3, 4, 6), equalTo("[0-null, 2-null, 3-3, 4-4, 5-null]"), equalTo("[0-null, 2-null, 3-3, 4-4, 5-null, null-null]"), JoinType.LEFT);
    // Matching duplicated keys
    testIntersect(newArrayList(1, 3, 4), newArrayList(1, 1, 4, 4), equalTo("[1-1, 1-1, 3-null, 4-4, 4-4]"), equalTo("[1-1, 1-1, 3-null, 4-4, 4-4, null-null]"), JoinType.LEFT);
}

@Test
void testMergeJoin3() {
    final JoinType[] joinTypes = { JoinType.INNER, JoinType.SEMI };
    for (JoinType joinType : joinTypes) {
        // No overlap
        testIntersect(Lists.newArrayList(0, 2, 4), Lists.newArrayList(1, 3, 5), equalTo("[]"), joinType);
        // Left empty
        testIntersect(new ArrayList<>(), newArrayList(1, 3, 4, 6), equalTo("[]"), joinType);
        // Right empty
        testIntersect(newArrayList(3, 7), new ArrayList<>(), equalTo("[]"), joinType);
        // Both empty
        testIntersect(new ArrayList<Integer>(), new ArrayList<>(), equalTo("[]"), joinType);
    }
    // ANTI join tests:
    // No overlap
    testIntersect(newArrayList(0, 2, 4), newArrayList(1, 3, 5), equalTo("[0, 2, 4]"), JoinType.ANTI);
    // Left empty
    testIntersect(new ArrayList<>(), newArrayList(1, 3, 4, 6), equalTo("[]"), JoinType.ANTI);
    // Right empty
    testIntersect(newArrayList(3, 7), new ArrayList<>(), equalTo("[3, 7]"), JoinType.ANTI);
    // Both empty
    testIntersect(new ArrayList<Integer>(), new ArrayList<>(), equalTo("[]"), JoinType.ANTI);
    // LEFT join tests:
    // No overlap
    testIntersect(newArrayList(0, 2, 4), newArrayList(1, 3, 5), equalTo("[0-null, 2-null, 4-null]"), equalTo("[0-null, 2-null, 4-null, null-null]"), JoinType.LEFT);
    // Left empty
    testIntersect(new ArrayList<>(), newArrayList(1, 3, 4, 6), equalTo("[]"), equalTo("[null-null]"), JoinType.LEFT);
    // Right empty
    testIntersect(newArrayList(3, 7), new ArrayList<>(), equalTo("[3-null, 7-null]"), equalTo("[3-null, 7-null, null-null]"), JoinType.LEFT);
    // Both empty
    testIntersect(new ArrayList<Integer>(), new ArrayList<>(), equalTo("[]"), equalTo("[null-null]"), JoinType.LEFT);
}

@Test
void testMergeJoinWithPredicate() {
    final List<Emp> listEmp1 = Arrays.asList(new Emp(1, "Fred"), new Emp(2, "Fred"), new Emp(3, "Joe"), new Emp(4, "Joe"), new Emp(5, "Peter"));
    final List<Emp> listEmp2 = Arrays.asList(new Emp(2, "Fred"), new Emp(3, "Fred"), new Emp(3, "Joe"), new Emp(5, "Joe"), new Emp(6, "Peter"));
    assertThat(EnumerableDefaults.mergeJoin(Linq4j.asEnumerable(listEmp1), Linq4j.asEnumerable(listEmp2), e1 -> e1.name, e2 -> e2.name, (e1, e2) -> e1.deptno < e2.deptno, (v0, v1) -> v0 + "-" + v1, JoinType.INNER, null, null).toList(), hasToString("[" + "Emp(1, Fred)-Emp(2, Fred), " + "Emp(1, Fred)-Emp(3, Fred), " + "Emp(2, Fred)-Emp(3, Fred), " + "Emp(3, Joe)-Emp(5, Joe), " + "Emp(4, Joe)-Emp(5, Joe), " + "Emp(5, Peter)-Emp(6, Peter)]"));
    assertThat(EnumerableDefaults.mergeJoin(Linq4j.asEnumerable(listEmp2), Linq4j.asEnumerable(listEmp1), e2 -> e2.name, e1 -> e1.name, (e2, e1) -> e2.deptno > e1.deptno, (v0, v1) -> v0 + "-" + v1, JoinType.INNER, null, null).toList(), hasToString("[" + "Emp(2, Fred)-Emp(1, Fred), " + "Emp(3, Fred)-Emp(1, Fred), " + "Emp(3, Fred)-Emp(2, Fred), " + "Emp(5, Joe)-Emp(3, Joe), " + "Emp(5, Joe)-Emp(4, Joe), " + "Emp(6, Peter)-Emp(5, Peter)]"));
    assertThat(EnumerableDefaults.mergeJoin(Linq4j.asEnumerable(listEmp1), Linq4j.asEnumerable(listEmp2), e1 -> e1.name, e2 -> e2.name, (e1, e2) -> e1.deptno == e2.deptno * 2, (v0, v1) -> v0 + "-" + v1, JoinType.INNER, null, null).toList(), hasToString("[]"));
    assertThat(EnumerableDefaults.mergeJoin(Linq4j.asEnumerable(listEmp2), Linq4j.asEnumerable(listEmp1), e2 -> e2.name, e1 -> e1.name, (e2, e1) -> e2.deptno == e1.deptno * 2, (v0, v1) -> v0 + "-" + v1, JoinType.INNER, null, null).toList(), hasToString("[Emp(2, Fred)-Emp(1, Fred)]"));
    assertThat(EnumerableDefaults.mergeJoin(Linq4j.asEnumerable(listEmp2), Linq4j.asEnumerable(listEmp1), e2 -> e2.name, e1 -> e1.name, (e2, e1) -> e2.deptno == e1.deptno + 2, (v0, v1) -> v0 + "-" + v1, JoinType.INNER, null, null).toList(), hasToString("[Emp(3, Fred)-Emp(1, Fred), Emp(5, Joe)-Emp(3, Joe)]"));
}

