public void testMatch() {
    final Enumerable<Emp> emps = Linq4j.asEnumerable(Arrays.asList(new Emp(20, "Theodore"), new Emp(10, "Fred"), new Emp(20, "Sebastian"), new Emp(30, "Joe")));
    final Pattern p = Pattern.builder().symbol("A").symbol("B").seq().build();
    final Matcher<Emp> matcher = Matcher.<Emp>builder(p.toAutomaton()).add("A", s -> s.get().deptno == 20).add("B", s -> s.get().deptno != 20).build();
    final Enumerables.Emitter<Emp, String> emitter = (rows, rowStates, rowSymbols, match, consumer) -> {
        for (int i = 0; i < rows.size(); i++) {
            if (rowSymbols == null) {
                continue;
            }
            if ("A".equals(rowSymbols.get(i))) {
                consumer.accept(String.format(Locale.ENGLISH, "%s %s %d", rows, rowStates, match));
            }
        }
    };
    final Enumerable<String> matches = Enumerables.match(emps, emp -> 0L, matcher, emitter, 1, 1);
    assertThat(matches.toList(), hasToString("[[Emp(20, Theodore), Emp(10, Fred)] null 1, " + "[Emp(20, Sebastian), Emp(30, Joe)] null 2]"));
}

