/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5952">[CALCITE-5952]
 * SemiJoinJoinTransposeRule should check if JoinType supports pushing predicates
 * into its inputs</a>.
 */
@Test
void semiJoinLeftJoinTransposeTest() {
    tester(true, new HrSchema()).withRel(builder -> builder.scan("s", "depts").scan("s", "emps").join(JoinRelType.LEFT, builder.equals(builder.field(2, 0, "deptno"), builder.field(2, 1, "deptno"))).scan("s", "dependents").semiJoin(builder.equals(builder.field(2, 0, "empid"), builder.field(2, 1, "empid"))).build()).withHook(Hook.PLANNER, (Consumer<RelOptPlanner>) planner -> planner.addRule(CoreRules.SEMI_JOIN_JOIN_TRANSPOSE)).returnsUnordered();
}

