/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4401">[CALCITE-4401]
 * SqlJoin toString throws RuntimeException</a>.
 */
@Test
void testJoinClauseToString() {
    final String sql = "SELECT t.region_name, t0.o_totalprice\n" + "FROM (SELECT c_custkey, region_name\n" + "FROM tpch.out_tpch_vw__customer) AS t\n" + "INNER JOIN (SELECT o_custkey, o_totalprice\n" + "FROM tpch.out_tpch_vw__orders) AS t0 ON t.c_custkey = t0.o_custkey";
    final String expectedJoinString = "SELECT *\n" + "FROM (SELECT `C_CUSTKEY`, `REGION_NAME`\n" + "FROM `TPCH`.`OUT_TPCH_VW__CUSTOMER`) AS `T`\n" + "INNER JOIN (SELECT `O_CUSTKEY`, `O_TOTALPRICE`\n" + "FROM `TPCH`.`OUT_TPCH_VW__ORDERS`) AS `T0`" + " ON `T`.`C_CUSTKEY` = `T0`.`O_CUSTKEY`";
    sql(sql).checkTransformedNode(root -> {
        assertThat(root, instanceOf(SqlSelect.class));
        SqlNode from = ((SqlSelect) root).getFrom();
        assertThat(from, notNullValue());
        assertThat(from, hasToString(isLinux(expectedJoinString)));
        return from;
    });
}

