@Test
void testSequenceOfFamily() throws Exception {
    // Test for https://issues.apache.org/jira/browse/CALCITE-5479. The original checker that
    // inspired this test was doing "and(family(STRING), LITERAL)". We tweak this a bit here because
    // the test fixture does not preserve literals.
    final SqlOperandTypeChecker fChecker = OperandTypes.sequence("F(<STRING>, <TIMESTAMP or DATE>)", OperandTypes.STRING, OperandTypes.or(OperandTypes.TIMESTAMP, OperandTypes.DATE));
    final SqlOperator fOperator = new SqlFunction("F", SqlKind.OTHER_FUNCTION, ReturnTypes.BIGINT, null, fChecker, SqlFunctionCategory.USER_DEFINED_FUNCTION);
    final SqlOperatorTable operatorTable = SqlOperatorTables.of(fOperator, SqlStdOperatorTable.ROW);
    try (SqlOperatorFixture f = Fixtures.forOperators(false).withOperatorTable(operatorTable)) {
        f.setFor(fOperator);
        f.checkType("F('foo', TIMESTAMP '2000-01-01 00:00:00')", "BIGINT NOT NULL");
        f.checkFails("^F('foo', 1)^", "Cannot apply 'F' to arguments of type 'F\\(<CHAR\\(3\\)>, <INTEGER>\\)'\\. Supported " + "form\\(s\\): F\\(<STRING>, <TIMESTAMP or DATE>\\)", false);
    }
}

