    RelDataTypeField field0 = new RelDataTypeFieldImpl("i", 0, typeFactory.createSqlType(SqlTypeName.INTEGER));
    RelDataTypeField field1 = new RelDataTypeFieldImpl("s", 1, typeFactory.createSqlType(SqlTypeName.VARCHAR));
    fields.add(field0);
    fields.add(field1);
    // nullable false by default
    final RelDataType recordType = new RelRecordType(fields);
    final RelDataType copyRecordType = typeFactory.createTypeWithNullability(recordType, true);
    assertFalse(recordType.isNullable());
    assertTrue(copyRecordType.isNullable());
}

