void testNameMatcher() {
    final ImmutableList<String> beatles = ImmutableList.of("john", "paul", "ringo", "rinGo");
    final SqlNameMatcher insensitiveMatcher = SqlNameMatchers.withCaseSensitive(false);
    assertThat(insensitiveMatcher.frequency(beatles, "ringo"), is(2));
    assertThat(insensitiveMatcher.frequency(beatles, "rinGo"), is(2));
    assertThat(insensitiveMatcher.indexOf(beatles, "rinGo"), is(2));
    assertThat(insensitiveMatcher.indexOf(beatles, "stuart"), is(-1));
    final SqlNameMatcher sensitiveMatcher = SqlNameMatchers.withCaseSensitive(true);
    assertThat(sensitiveMatcher.frequency(beatles, "ringo"), is(1));
    assertThat(sensitiveMatcher.frequency(beatles, "rinGo"), is(1));
    assertThat(sensitiveMatcher.frequency(beatles, "Ringo"), is(0));
    assertThat(sensitiveMatcher.indexOf(beatles, "ringo"), is(2));
    assertThat(sensitiveMatcher.indexOf(beatles, "rinGo"), is(3));
    assertThat(sensitiveMatcher.indexOf(beatles, "Ringo"), is(-1));
}

@Test
void testSingleCorrelationCallOverVariableInFilter() {
    final RelBuilder builder = RelBuilder.create(config().build());
    final Holder<@Nullable RexCorrelVariable> v = Holder.empty();
    RelNode before = builder.scan("EMP").variable(v::set).scan("DEPT").filter(builder.equals(builder.field(0), builder.call(SqlStdOperatorTable.PLUS, builder.literal(10), builder.field(v.get(), "DEPTNO")))).correlate(JoinRelType.LEFT, v.get().id, builder.field(2, 0, "DEPTNO")).build();
    final String planBefore = "" + "LogicalCorrelate(correlation=[$cor0], joinType=[left], requiredColumns=[{7}])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n" + "  LogicalFilter(condition=[=($0, +(10, $cor0.DEPTNO))])\n" + "    LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(before, hasTree(planBefore));
    RelNode after = before.accept(new CorrelateProjectExtractor(RelFactories.LOGICAL_BUILDER));
    final String planAfter = "" + "LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], HIREDATE=[$4], SAL=[$5], COMM=[$6], DEPTNO=[$7], DEPTNO0=[$9], DNAME=[$10], LOC=[$11])\n" + "  LogicalCorrelate(correlation=[$cor0], joinType=[left], requiredColumns=[{8}])\n" + "    LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], HIREDATE=[$4], SAL=[$5], COMM=[$6], DEPTNO=[$7], $f8=[+(10, $7)])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n" + "    LogicalFilter(condition=[=($0, $cor0.$f8)])\n" + "      LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(after, hasTree(planAfter));
}

@Test
void testDoubleCorrelationCallOverVariableInFilters() {
    final RelBuilder builder = RelBuilder.create(config().build());
    final Holder<@Nullable RexCorrelVariable> v = Holder.empty();
    RelNode before = builder.scan("EMP").variable(v::set).scan("DEPT").filter(builder.equals(builder.field("DEPTNO"), builder.call(SqlStdOperatorTable.PLUS, builder.literal(10), builder.field(v.get(), "DEPTNO")))).correlate(JoinRelType.LEFT, v.get().id, builder.field(2, 0, "DEPTNO")).variable(v::set).scan("DEPT").filter(builder.equals(builder.field("DEPTNO"), builder.call(SqlStdOperatorTable.MINUS, builder.literal(50), builder.field(v.get(), "DEPTNO")))).correlate(JoinRelType.LEFT, v.get().id, builder.field(2, 0, "DEPTNO")).build();
    final String planBefore = "" + "LogicalCorrelate(correlation=[$cor1], joinType=[left], requiredColumns=[{7}])
" + "  LogicalCorrelate(correlation=[$cor0], joinType=[left], requiredColumns=[{7}])
" + "    LogicalTableScan(table=[[scott, EMP]])
" + "    LogicalFilter(condition=[=($0, +(10, $cor0.DEPTNO))])
