" + "      LogicalCorrelate(correlation=[$cor0], joinType=[left], requiredColumns=[{8}])
" + "        LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], HIREDATE=[$4], SAL=[$5], COMM=[$6], DEPTNO=[$7], $f8=[+(10, $7)])
" + "          LogicalTableScan(table=[[scott, EMP]])
