@Test
void testJoinWithHints() {
    final RelHint noHashJoinHint = RelHint.builder("no_hash_join").build();
    final RelBuilder builder = RelBuilder.create(config().build());
    builder.getCluster().setHintStrategies(HintStrategyTable.builder().hintStrategy("no_hash_join", HintPredicates.JOIN).build());
    final RelNode original = builder.scan("EMP").scan("DEPT").join(JoinRelType.INNER, builder.equals(builder.field(2, 0, "DEPTNO"), builder.field(2, 1, "DEPTNO"))).hints(noHashJoinHint).project(builder.field("ENAME"), builder.field("DNAME")).build();
    final RelFieldTrimmer fieldTrimmer = new RelFieldTrimmer(null, builder);
    final RelNode trimmed = fieldTrimmer.trim(original);
    final String expected = "" + "LogicalProject(ENAME=[$1], DNAME=[$4])\n" + "  LogicalJoin(condition=[=($2, $3)], joinType=[inner])\n" + "    LogicalProject(EMPNO=[$0], ENAME=[$1], DEPTNO=[$7])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n" + "    LogicalProject(DEPTNO=[$0], DNAME=[$1])\n" + "      LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(trimmed, hasTree(expected));
    assertTrue(original.getInput(0) instanceof Join);
    final Join originalJoin = (Join) original.getInput(0);
    assertTrue(originalJoin.getHints().contains(noHashJoinHint));
    assertTrue(trimmed.getInput(0) instanceof Join);
    final Join join = (Join) trimmed.getInput(0);
    assertTrue(join.getHints().contains(noHashJoinHint));
}

