    // Note: explicit sort is used so EnumerableMergeJoin could actually work
    scan("s", "emps").sort(builder.field("deptno")).scan("s", "depts").sort(builder.field("deptno")).join(JoinRelType.INNER, builder.and(builder.equals(builder.field(2, 0, "deptno"), builder.field(2, 1, "deptno")), builder.getRexBuilder().makeCall(SqlStdOperatorTable.GREATER_THAN, builder.field(2, 0, "empid"), builder.getRexBuilder().makeCall(SqlStdOperatorTable.MULTIPLY, builder.literal(10), builder.field(2, 1, "deptno"))))).project(builder.field(1, "emps", "empid"), builder.field(1, "emps", "name"), builder.alias(builder.field(1, "depts", "name"), "dept_name"), builder.alias(builder.field(1, "emps", "deptno"), "e_deptno"), builder.alias(builder.field(1, "depts", "deptno"), "d_deptno")).build()).explainHookMatches(// It is important that we have MergeJoin in the plan
