 * EnumerableDefaults#orderBy should be lazily computed + support enumerator
 * re-initialization</a>.
 */
@Test
void testRepeatUnionWithMergeJoin() {
    tester(false, new HierarchySchema()).withHook(Hook.PLANNER, (Consumer<RelOptPlanner>) planner -> {
        planner.addRule(Bindables.BINDABLE_TABLE_SCAN_RULE);
        planner.addRule(EnumerableRules.ENUMERABLE_MERGE_JOIN_RULE);
        planner.removeRule(EnumerableRules.ENUMERABLE_JOIN_RULE);
    }).// Note: explicit sort is used so EnumerableMergeJoin can actually work
    withRel(builder -> builder.//   WITH RECURSIVE delta(empid, name) as (
    //     SELECT empid, name FROM emps WHERE empid = 2
    //     UNION ALL
    //     SELECT e.empid, e.name FROM delta d
    //                            JOIN hierarchies h ON d.empid = h.managerid
    //                            JOIN emps e        ON h.subordinateid = e.empid
    //   )
    //   SELECT empid, name FROM delta
    scan("s", "emps").filter(builder.equals(builder.field("empid"), builder.literal(2))).project(builder.field("emps", "empid"), builder.field("emps", "name")).transientScan("#DELTA#").sort(builder.field("empid")).scan("s", "hierarchies").sort(builder.field("managerid")).join(JoinRelType.INNER, builder.equals(builder.field(2, "#DELTA#", "empid"), builder.field(2, "hierarchies", "managerid"))).sort(builder.field("subordinateid")).scan("s", "emps").sort(builder.field("empid")).join(JoinRelType.INNER, builder.equals(builder.field(2, "hierarchies", "subordinateid"), builder.field(2, "emps", "empid"))).project(builder.field("emps", "empid"), builder.field("emps", "name")).repeatUnion("#DELTA#", true).build()).explainHookMatches(// It is important to have MergeJoin + EnumerableSort in the plan
    "" + "EnumerableRepeatUnion(all=[true])\n" + "  EnumerableTableSpool(readType=[LAZY], writeType=[LAZY], table=[[#DELTA#]])\n" + "    EnumerableCalc(expr#0..4=[{inputs}], expr#5=[2], expr#6=[=($t0, $t5)], empid=[$t0], name=[$t2], $condition=[$t6])\n" + "      EnumerableTableScan(table=[[s, emps]])\n" + "  EnumerableTableSpool(readType=[LAZY], writeType=[LAZY], table=[[#DELTA#]])\n" + "    EnumerableCalc(expr#0..4=[{inputs}], empid=[$t3], name=[$t4])\n" + "      EnumerableMergeJoin(condition=[=($2, $3)], joinType=[inner])\n" + "        EnumerableSort(sort0=[$2], dir0=[ASC])\n" + "          EnumerableMergeJoin(condition=[=($0, $1)], joinType=[inner])\n" + "            EnumerableSort(sort0=[$0], dir0=[ASC])\n" + "              EnumerableCalc(expr#0..1=[{inputs}], empid=[$t0])\n" + "                EnumerableInterpreter\n" + "                  BindableTableScan(table=[[#DELTA#]])\n" + "            EnumerableSort(sort0=[$0], dir0=[ASC])\n" + "              EnumerableTableScan(table=[[s, hierarchies]])\n" + "        EnumerableSort(sort0=[$0], dir0=[ASC])\n" + "          EnumerableCalc(expr#0..4=[{inputs}], empid=[$t0], name=[$t2])\n" + "            EnumerableTableScan(table=[[s, emps]])\n").returnsUnordered("empid=2; name=Emp2", "empid=3; name=Emp3", "empid=5; name=Emp5");
}

