@ParameterizedTest(name = "{index} : hierarchy(startIds:{2}, ascendant:{3}, " + "maxDepth:{4}, all:{0})")
@MethodSource("data")
public void testHierarchy(boolean all, int[] startIds, String startIdsStr, boolean ascendant, int maxDepth, String[] expected) {
    final String fromField;
    final String toField;
    if (ascendant) {
        fromField = "subordinateid";
        toField = "managerid";
    } else {
        fromField = "managerid";
        toField = "subordinateid";
    }
    final Schema schema = new ReflectiveSchema(new HierarchySchema());
    CalciteAssert.that().withSchema("s", schema).withRel(buildHierarchy(all, startIds, fromField, toField, maxDepth)).returnsOrdered(expected);
}

@Test
void testGenerateNumbers() {
    CalciteAssert.that().withRel(//   WITH RECURSIVE delta(n) AS (
    //     VALUES (1)
    //     UNION ALL
    //     SELECT n+1 FROM delta WHERE n < 10
    //   )
    //   SELECT * FROM delta
    builder -> builder.values(new String[] { "i" }, 1).transientScan("DELTA").filter(builder.call(SqlStdOperatorTable.LESS_THAN, builder.field(0), builder.literal(10))).project(builder.call(SqlStdOperatorTable.PLUS, builder.field(0), builder.literal(1))).repeatUnion("DELTA", true).build()).returnsOrdered("i=1", "i=2", "i=3", "i=4", "i=5", "i=6", "i=7", "i=8", "i=9", "i=10");
}

