    builder -> builder.values(new String[] { "i" }, 0).transientScan("AUX").filter(builder.call(SqlStdOperatorTable.LESS_THAN, builder.field(0), builder.literal(10))).project(builder.call(SqlStdOperatorTable.MOD, builder.call(SqlStdOperatorTable.PLUS, builder.field(0), builder.literal(1)), builder.literal(10))).repeatUnion("AUX", false).build()).returnsOrdered("i=0", "i=1", "i=2", "i=3", "i=4", "i=5", "i=6", "i=7", "i=8", "i=9");
