@Test
void testFactorial() {
    CalciteAssert.that().withRel(//   WITH RECURSIVE d(n, fact) AS (
    //     VALUES (0, 1)
    //     UNION ALL
    //     SELECT n+1, (n+1)*fact FROM d WHERE n < 7
    //   )
    //   SELECT * FROM delta
    builder -> builder.values(new String[] { "n", "fact" }, 0, 1).transientScan("D").filter(builder.call(SqlStdOperatorTable.LESS_THAN, builder.field("n"), builder.literal(7))).project(Arrays.asList(builder.call(SqlStdOperatorTable.PLUS, builder.field("n"), builder.literal(1)), builder.call(SqlStdOperatorTable.MULTIPLY, builder.call(SqlStdOperatorTable.PLUS, builder.field("n"), builder.literal(1)), builder.field("fact"))), Arrays.asList("n", "fact")).repeatUnion("D", true).build()).returnsOrdered("n=0; fact=1", "n=1; fact=1", "n=2; fact=2", "n=3; fact=6", "n=4; fact=24", "n=5; fact=120", "n=6; fact=720", "n=7; fact=5040");
}

