/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4054">[CALCITE-4054]
 * RepeatUnion containing a Correlate with a transientScan on its RHS causes NPE</a>.
 */
@Test
void testRepeatUnionWithCorrelateWithTransientScanOnItsRight() {
    CalciteAssert.that().with(CalciteConnectionProperty.LEX, Lex.JAVA).with(CalciteConnectionProperty.FORCE_DECORRELATE, false).withSchema("s", new ReflectiveSchema(new HierarchySchema())).withHook(Hook.PLANNER, (Consumer<RelOptPlanner>) planner -> {
        planner.addRule(JoinToCorrelateRule.Config.DEFAULT.toRule());
        planner.removeRule(JoinCommuteRule.Config.DEFAULT.toRule());
        planner.removeRule(EnumerableRules.ENUMERABLE_MERGE_JOIN_RULE);
        planner.removeRule(EnumerableRules.ENUMERABLE_JOIN_RULE);
    }).withRel(builder -> {
        builder.//   WITH RECURSIVE delta(empid, name) as (
        //     SELECT empid, name FROM emps WHERE empid = 2
        //     UNION ALL
        //     SELECT e.empid, e.name FROM delta d
        //                            JOIN hierarchies h ON d.empid = h.managerid
        //                            JOIN emps e        ON h.subordinateid = e.empid
        //   )
        //   SELECT empid, name FROM delta
        scan("s", "emps").filter(builder.equals(builder.field("empid"), builder.literal(2))).project(builder.field("emps", "empid"), builder.field("emps", "name")).transientScan("#DELTA#");
        // pop the transientScan to use it later
        RelNode transientScan = builder.build();
        builder.scan("s", "hierarchies").push(// use the transientScan as right input of the join
        transientScan).join(JoinRelType.INNER, builder.equals(builder.field(2, "#DELTA#", "empid"), builder.field(2, "hierarchies", "managerid"))).scan("s", "emps").join(JoinRelType.INNER, builder.equals(builder.field(2, "hierarchies", "subordinateid"), builder.field(2, "emps", "empid"))).project(builder.field("emps", "empid"), builder.field("emps", "name")).repeatUnion("#DELTA#", true);
        return builder.build();
    }).explainHookMatches("" + "EnumerableRepeatUnion(all=[true])\n" + "  EnumerableTableSpool(readType=[LAZY], writeType=[LAZY], table=[[#DELTA#]])\n" + "    EnumerableCalc(expr#0..4=[{inputs}], expr#5=[2], expr#6=[=($t0, $t5)], empid=[$t0], name=[$t2], $condition=[$t6])\n" + "      EnumerableTableScan(table=[[s, emps]])\n" + "  EnumerableTableSpool(readType=[LAZY], writeType=[LAZY], table=[[#DELTA#]])\n" + "    EnumerableCalc(expr#0..4=[{inputs}], empid=[$t3], name=[$t4])\n" + "      EnumerableCorrelate(correlation=[$cor1], joinType=[inner], requiredColumns=[{1}])\n" + // It is important to have EnumerableCorrelate + #DELTA# table scan on its right
    // to reproduce the issue CALCITE-4054
    "        EnumerableCorrelate(correlation=[$cor0], joinType=[inner], requiredColumns=[{0}])\n" + "          EnumerableTableScan(table=[[s, hierarchies]])\n" + "          EnumerableCalc(expr#0..1=[{inputs}], expr#2=[$cor0], expr#3=[$t2.managerid], expr#4=[=($t0, $t3)], empid=[$t0], $condition=[$t4])\n" + "            EnumerableInterpreter\n" + "              BindableTableScan(table=[[#DELTA#]])\n" + "        EnumerableCalc(expr#0..4=[{inputs}], expr#5=[$cor1], expr#6=[$t5.subordinateid], expr#7=[=($t6, $t0)], empid=[$t0], name=[$t2], $condition=[$t7])\n" + "          EnumerableTableScan(table=[[s, emps]])\n").returnsUnordered("empid=2; name=Emp2", "empid=3; name=Emp3", "empid=5; name=Emp5");
}

