@Test
void testInterpretUnnest() {
    sql("select * from unnest(array[1, 2])").returnsRows("[1]", "[2]");
    reset();
    sql("select * from unnest(multiset[1, 2])").returnsRowsUnordered("[1]", "[2]");
    reset();
    sql("select * from unnest(map['a', 12])").returnsRows("[a, 12]");
    reset();
    sql("select * from unnest(\n" + "select * from (values array[10, 20], array[30, 40]))\n" + "with ordinality as t(i, o)").returnsRows("[10, 1]", "[20, 2]", "[30, 1]", "[40, 2]");
    reset();
    sql("select * from unnest(map['a', 12, 'b', 13]) with ordinality as t(a, b, o)").returnsRows("[a, 12, 1]", "[b, 13, 2]");
    reset();
    sql("select * from unnest(\n" + "select * from (values multiset[10, 20], multiset[30, 40]))\n" + "with ordinality as t(i, o)").returnsRows("[10, 1]", "[20, 2]", "[30, 1]", "[40, 2]");
    reset();
    sql("select * from unnest(array[cast(null as integer), 10])").returnsRows("[null]", "[10]");
    reset();
    sql("select * from unnest(map[cast(null as integer), 10, 10, cast(null as integer)])").returnsRowsUnordered("[null, 10]", "[10, null]");
    reset();
    sql("select * from unnest(multiset[cast(null as integer), 10])").returnsRowsUnordered("[null]", "[10]");
    try {
        reset();
        sql("select * from unnest(cast(null as int array))").returnsRows("");
    } catch (NullPointerException e) {
        assertThat(e.getMessage(), equalTo("NULL value for unnest."));
    }
}

/**
 * Tests a user-defined scalar function that is non-static.
 */
@Test
void testInterpretFunction() {
    SchemaPlus schema = rootSchema.add("s", new AbstractSchema());
    final ScalarFunction f = ScalarFunctionImpl.create(Smalls.MY_PLUS_EVAL_METHOD);
    schema.add("myPlus", f);
    final String sql = "select x, \"s\".\"myPlus\"(x, 1)\n" + "from (values (2), (4), (7)) as t (x)";
    String[] rows = { "[2, 3]", "[4, 5]", "[7, 8]" };
    final int n = Smalls.MyPlusFunction.INSTANCE_COUNT.get().get();
    sql(sql).returnsRows(rows);
    final int n2 = Smalls.MyPlusFunction.INSTANCE_COUNT.get().get();
    // instantiated once per run, not once per row
    assertThat(n2, is(n + 1));
}

/**
 * Tests a user-defined scalar function that is non-static and has a
 * constructor that uses
 * {@link org.apache.calcite.schema.FunctionContext}.
 */
@Test
void testInterpretFunctionWithInitializer() {
    SchemaPlus schema = rootSchema.add("s", new AbstractSchema());
    final ScalarFunction f = ScalarFunctionImpl.create(Smalls.MY_PLUS_INIT_EVAL_METHOD);
    schema.add("myPlusInit", f);
    final String sql = "select x, \"s\".\"myPlusInit\"(x, 1)\n" + "from (values (2), (4), (7)) as t (x)";
    String[] rows = { "[2, 3]", "[4, 5]", "[7, 8]" };
    final int n = Smalls.MyPlusInitFunction.INSTANCE_COUNT.get().get();
    sql(sql).returnsRows(rows);
    final int n2 = Smalls.MyPlusInitFunction.INSTANCE_COUNT.get().get();
    // instantiated once per run, not once per row
    assertThat(n2, is(n + 1));
    final String digest = Smalls.MyPlusInitFunction.THREAD_DIGEST.get();
    String expectedDigest = "parameterCount=2; " + "argument 0 is not constant; " + "argument 1 is constant and has value 1";
    assertThat(digest, is(expectedDigest));
    // Similar, but replace '1' with the expression '3 - 2'
    final String sql2 = "select x, \"s\".\"myPlusInit\"(x, 3 - 2)\n" + "from (values (2), (4), (7)) as t (x)";
    String[] rows2 = { "[2, 102]", "[4, 104]", "[7, 107]" };
    sql(sql2).returnsRows(rows2);
    final int n3 = Smalls.MyPlusInitFunction.INSTANCE_COUNT.get().get();
    // instantiated once per run, not once per row
    assertThat(n3, is(n2 + 1));
    final String digest2 = Smalls.MyPlusInitFunction.THREAD_DIGEST.get();
    String expectedDigest2 = "parameterCount=2; " + "argument 0 is not constant; " + "argument 1 is not constant";
    assertThat(digest2, is(expectedDigest2));
}

