    final String model = FoodmartSchema.FOODMART_MODEL.replace("jdbcUser: 'FOODMART'", "jdbcUser: 'sa'").replace("jdbcPassword: 'FOODMART'", "jdbcPassword: ''").replace("jdbcCatalog: 'foodmart'", "jdbcCatalog: null").replace("jdbcSchema: 'foodmart'", "jdbcSchema: null");
