    enable(CalciteAssert.DB == DatabaseInstance.POSTGRESQL).query("select \"store_id\", \"account_id\", \"exp_date\"," + " \"time_id\", \"category_id\", \"currency_id\", \"amount\"," + " last_value(\"time_id\") over ()" + " as \"last_version\" from \"expense_fact\"").runs();
