/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3423">[CALCITE-3423]
 * Support using CAST operation and BOOLEAN type value in table macro</a>.
 */
@Test
void testTableMacroWithCastOrBoolean() throws SQLException {
    Connection connection = DriverManager.getConnection("jdbc:calcite:");
    addTableMacro(connection, Smalls.STR_METHOD);
    // check for cast
    ResultSet resultSet = connection.createStatement().executeQuery("select *\n" + "from table(\"s\".\"str\"(MAP['a', 1, 'baz', 2], cast(1 as bigint))) as t(n)");
    assertThat(CalciteAssert.toString(resultSet), is("N={'a'=1, 'baz'=2}\n" + "N=1               \n"));
    // check for Boolean type
    resultSet = connection.createStatement().executeQuery("select *\n" + "from table(\"s\".\"str\"(MAP['a', 1, 'baz', 2], true)) as t(n)");
    assertThat(CalciteAssert.toString(resultSet), is("N={'a'=1, 'baz'=2}\n" + "N=true            \n"));
    // check for nested cast
    resultSet = connection.createStatement().executeQuery("select *\n" + "from table(\"s\".\"str\"(MAP['a', 1, 'baz', 2]," + "cast(cast(1 as int) as varchar(1)))) as t(n)");
    assertThat(CalciteAssert.toString(resultSet), is("N={'a'=1, 'baz'=2}\n" + "N=1               \n"));
    resultSet = connection.createStatement().executeQuery("select *\n" + "from table(\"s\".\"str\"(MAP['a', 1, 'baz', 2]," + "cast(cast(cast('2019-10-18 10:35:23' as TIMESTAMP) as BIGINT) as VARCHAR))) as t(n)");
    assertThat(CalciteAssert.toString(resultSet), is("N={'a'=1, 'baz'=2}     \n" + "N='2019-10-18 10:35:23'\n"));
    // check for implicit type coercion
    addTableMacro(connection, Smalls.VIEW_METHOD);
    resultSet = connection.createStatement().executeQuery("select *\n" + "from table(\"s\".\"view\"(5)) as t(n)");
    assertThat(CalciteAssert.toString(resultSet), is("N=1\n" + "N=3\n" + "N=5\n"));
    connection.close();
}

/**
 * Tests a table macro with named and optional parameters.
 */
@Test
void testTableMacroWithNamedParameters() throws Exception {
    // View(String r optional, String s, int t optional)
    final CalciteAssert.AssertThat with = assertWithMacro(Smalls.TableMacroFunctionWithNamedParameters.class, Smalls.AnotherTableMacroFunctionWithNamedParameters.class);
    with.query("select * from table(\"adhoc\".\"View\"('(5)'))").throws_("No match found for function signature View(<CHARACTER>)");
    final String expected1 = "c=1\n" + "c=3\n" + "c=5\n" + "c=6\n";
    with.query("select * from table(\"adhoc\".\"View\"('5', '6'))").returns(expected1);
    final String expected2 = "c=1\n" + "c=3\n" + "c=5\n" + "c=6\n";
    with.query("select * from table(\"adhoc\".\"View\"(r=>'5', s=>'6'))").returns(expected2);
    with.query("select * from table(\"adhoc\".\"View\"(t=>'5', t=>'6'))").throws_("Duplicate argument name 'T'");
    final String expected3 = "c=1\n" + "c=3\n" + "c=6\n" + "c=5\n";
    // implicit type coercion
    with.query("select * from table(\"adhoc\".\"View\"(t=>'5', s=>'6'))").returns(expected3);
    with.query("select * from table(\"adhoc\".\"View\"(t=>5, s=>'6'))").returns(expected3);
    with.query("select * from table(\"adhoc\".\"View\"(s=>'6', t=>5))").returns(expected3);
}

