@ParameterizedTest
@MethodSource("explainFormats")
void testUnionWithSameColumnNames(String format) {
    String expected = null;
    String extra = null;
    switch(format) {
        case "dot":
            expected = "PLAN=digraph {\n" + "\"EnumerableCalc\\nexpr#0..3 = {inputs}\\ndeptno = $t0\\ndeptno0 = $t0\\n\" -> " + "\"EnumerableUnion\\nall = false\\n\" [label=\"0\"]\n" + "\"EnumerableCalc\\nexpr#0..4 = {inputs}\\ndeptno = $t1\\nempid = $t0\\n\" -> " + "\"EnumerableUnion\\nall = false\\n\" [label=\"1\"]\n" + "\"EnumerableTableScan\\ntable = [hr, depts]\\n\" -> \"EnumerableCalc\\nexpr#0..3 = " + "{inputs}\\ndeptno = $t0\\ndeptno0 = $t0\\n\" [label=\"0\"]\n" + "\"EnumerableTableScan\\ntable = [hr, emps]\\n\" -> \"EnumerableCalc\\nexpr#0..4 = " + "{inputs}\\ndeptno = $t1\\nempid = $t0\\n\" [label=\"0\"]\n" + "}\n" + "\n";
            extra = " as dot ";
            break;
        case "text":
            expected = "" + "PLAN=EnumerableUnion(all=[false])\n" + "  EnumerableCalc(expr#0..3=[{inputs}], deptno=[$t0], deptno0=[$t0])\n" + "    EnumerableTableScan(table=[[hr, depts]])\n" + "  EnumerableCalc(expr#0..4=[{inputs}], deptno=[$t1], empid=[$t0])\n" + "    EnumerableTableScan(table=[[hr, emps]])\n";
            extra = "";
            break;
    }
    CalciteAssert.hr().query("select \"deptno\", \"deptno\" from \"hr\".\"depts\" union select \"deptno\", \"empid\" from \"hr\".\"emps\"").explainMatches(extra, CalciteAssert.checkResultContains(expected)).returnsUnordered("deptno=10; deptno=110", "deptno=10; deptno=10", "deptno=20; deptno=200", "deptno=10; deptno=100", "deptno=10; deptno=150", "deptno=30; deptno=30", "deptno=40; deptno=40");
}

