    switch(format) {
        case "text":
            expected = "EnumerableAggregate(group=[{0, 3}])\n" + "  EnumerableNestedLoopJoin(condition=[=(CAST($1):INTEGER NOT NULL, $2)], joinType=[inner])\n" + "    EnumerableTableScan(table=[[SALES, EMPS]])\n" + "    EnumerableCalc(expr#0..1=[{inputs}], expr#2=['SameName'], expr#3=[=($t1, $t2)], proj#0..1=[{exprs}], $condition=[$t3])\n" + "      EnumerableValues(tuples=[[{ 10, 'SameName' }]])\n";
