        case "dot":
            expected = "PLAN=digraph {\n" + "\"EnumerableNestedLoop\\nJoin\\ncondition = =(CAST($\\n1):INTEGER NOT NULL,\\n $2)" + "\\njoinType = inner\\n\" -> \"EnumerableAggregate\\ngroup = {0, 3}\\n\" " + "[label=\"0\"]\n" + "\"EnumerableTableScan\\ntable = [SALES, EMPS\\n]\\n\" -> " + "\"EnumerableNestedLoop\\nJoin\\ncondition = =(CAST($\\n1):INTEGER NOT NULL,\\n $2)" + "\\njoinType = inner\\n\" [label=\"0\"]\n" + "\"EnumerableCalc\\nexpr#0..1 = {inputs}\\nexpr#2 = 'SameName'\\nexpr#3 = =($t1, $t2)" + "\\nproj#0..1 = {exprs}\\n$condition = $t3\" -> " + "\"EnumerableNestedLoop\\nJoin\\ncondition = =(CAST($\\n1):INTEGER NOT NULL,\\n $2)" + "\\njoinType = inner\\n\" [label=\"1\"]\n" + "\"EnumerableValues\\ntuples = [{ 10, 'Sam\\neName' }]\\n\" -> " + "\"EnumerableCalc\\nexpr#0..1 = {inputs}\\nexpr#2 = 'SameName'\\nexpr#3 = =($t1, $t2)" + "\\nproj#0..1 = {exprs}\\n$condition = $t3\" [label=\"0\"]\n" + "}\n" + "\n";
            extra = " as dot ";
