@ParameterizedTest
@MethodSource("explainFormats")
void testOrderByOnSortedTable2(String format) {
    String expected = null;
    String extra = null;
    switch(format) {
        case "text":
            expected = "" + "PLAN=EnumerableCalc(expr#0..9=[{inputs}], expr#10=[370], expr#11=[<($t0, $t10)], proj#0..1=[{exprs}], $condition=[$t11])\n" + "  EnumerableTableScan(table=[[foodmart2, time_by_day]])\n\n";
            extra = "";
            break;
        case "dot":
            expected = "PLAN=digraph {\n" + "\"EnumerableTableScan\\ntable = [foodmart2, \\ntime_by_day]\\n\" -> " + "\"EnumerableCalc\\nexpr#0..9 = {inputs}\\nexpr#10 = 370\\nexpr#11 = <($t0, $t1\\n0)" + "\\nproj#0..1 = {exprs}\\n$condition = $t11\" [label=\"0\"]\n" + "}\n" + "\n";
            extra = " as dot ";
            break;
    }
    CalciteAssert.that().with(CalciteAssert.Config.FOODMART_CLONE).query("select \"time_id\", \"the_date\" from \"time_by_day\"\n" + "where \"time_id\" < 370\n" + "order by \"time_id\"").returns("time_id=367; the_date=1997-01-01 00:00:00\n" + "time_id=368; the_date=1997-01-02 00:00:00\n" + "time_id=369; the_date=1997-01-03 00:00:00\n").explainMatches(extra, CalciteAssert.checkResultContains(expected));
}

