@Test
void testVarcharEquals() {
    CalciteAssert.model(FoodmartSchema.FOODMART_MODEL).query("select \"lname\" from \"customer\" where \"lname\" = 'Nowmer'").returns("lname=Nowmer\n");
    // lname is declared as VARCHAR(30), comparing it with a string longer
    // than 30 characters would introduce a cast to the least restrictive
    // type, thus lname would be cast to a varchar(40) in this case.
    // These sorts of casts are removed though when constructing the jdbc
    // sql, since e.g. HSQLDB does not support them.
    CalciteAssert.model(FoodmartSchema.FOODMART_MODEL).query("select count(*) as c from \"customer\" " + "where \"lname\" = 'this string is longer than 30 characters'").returns("C=0\n");
    CalciteAssert.model(FoodmartSchema.FOODMART_MODEL).query("select count(*) as c from \"customer\" " + "where cast(\"customer_id\" as char(20)) = 'this string is longer than 30 characters'").returns("C=0\n");
}

