/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4323">[CALCITE-4323]
 * View with ORDER BY throws AssertionError during view expansion</a>.
 */
@Test
void testSortedView() {
    final String viewSql = "select * from "EMPLOYEES" order by "deptno"";
    final CalciteAssert.AssertThat with = modelWithView(viewSql, null);
    // Keep sort, because view is top node
    with.query("select * from "adhoc".V").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalProject(empid=[$0], deptno=[$1], name=[$2], " + "salary=[$3], commission=[$4])
" + "  LogicalSort(sort0=[$1], dir0=[ASC])
" + "    LogicalProject(empid=[$0], deptno=[$1], name=[$2], salary=[$3], " + "commission=[$4])
" + "      LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    // Remove sort, because view not is top node
    with.query("select * from "adhoc".V union all select * from  "adhoc"."EMPLOYEES"").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalUnion(all=[true])
" + "  LogicalProject(empid=[$0], deptno=[$1], name=[$2], salary=[$3], " + "commission=[$4])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])
" + "  LogicalProject(empid=[$0], deptno=[$1], name=[$2], salary=[$3], " + "commission=[$4])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    with.query("select * from " + "(select "empid", "deptno" from  "adhoc".V) where "deptno" > 10").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalProject(empid=[$0], deptno=[$1])
" + "  LogicalFilter(condition=[>($1, 10)])
" + "    LogicalProject(empid=[$0], deptno=[$1])
" + "      LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    with.query("select * from "adhoc"."EMPLOYEES" where exists (select * from "adhoc".V)").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalProject(empid=[$0], deptno=[$1], name=[$2], " + "salary=[$3], commission=[$4])
" + "  LogicalFilter(condition=[EXISTS({
" + "LogicalTableScan(table=[[adhoc, EMPLOYEES]])
" + "})])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    // View is used in a query at top level，but it's not the top plan
    // Still remove sort
    with.query("select * from "adhoc".V order by "empid"").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalSort(sort0=[$0], dir0=[ASC])
" + "  LogicalProject(empid=[$0], deptno=[$1], name=[$2], salary=[$3], " + "commission=[$4])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    with.query("select * from "adhoc".V, "adhoc"."EMPLOYEES"").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalProject(empid=[$0], deptno=[$1], name=[$2], " + "salary=[$3], commission=[$4], empid0=[$5], deptno0=[$6], name0=[$7], salary0=[$8]," + " commission0=[$9])
" + "  LogicalJoin(condition=[true], joinType=[inner])
" + "    LogicalProject(empid=[$0], deptno=[$1], name=[$2], salary=[$3], " + "commission=[$4])
" + "      LogicalTableScan(table=[[adhoc, EMPLOYEES]])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    with.query("select "empid", count(*) from "adhoc".V group by "empid"").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalAggregate(group=[{0}], EXPR$1=[COUNT()])
" + "  LogicalProject(empid=[$0])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
    with.query("select distinct * from "adhoc".V").explainMatches(" without implementation ", checkResult("PLAN=" + "LogicalAggregate(group=[{0, 1, 2, 3, 4}])
" + "  LogicalProject(empid=[$0], deptno=[$1], name=[$2], salary=[$3], " + "commission=[$4])
" + "    LogicalTableScan(table=[[adhoc, EMPLOYEES]])

"));
}

/**
 * Tests a view with ORDER BY and LIMIT clauses.
 */
@Test
void testOrderByView() throws Exception {
    final CalciteAssert.AssertThat with = modelWithView("select * from \"EMPLOYEES\" where \"deptno\" = 10 " + "order by \"empid\" limit 2", null);
    with.query("select \"name\" from \"adhoc\".V order by \"name\"").returns("name=Bill\n" + "name=Theodore\n");
    // Now a sub-query with ORDER BY and LIMIT clauses. (Same net effect, but
    // ORDER BY and LIMIT in sub-query were not standard SQL until SQL:2008.)
    with.query("select \"name\" from (\n" + "select * from \"adhoc\".\"EMPLOYEES\" where \"deptno\" = 10\n" + "order by \"empid\" limit 2)\n" + "order by \"name\"").returns("name=Bill\n" + "name=Theodore\n");
}

