/**
 * Test for MONTHNAME, DAYNAME and DAYOFWEEK functions in two locales.
 */
@Test
void testMonthName() {
    final String sql = "SELECT * FROM (VALUES(\n" + " monthname(TIMESTAMP '1969-01-01 00:00:00'),\n" + " monthname(DATE '1969-01-01'),\n" + " monthname(DATE '2019-02-10'),\n" + " monthname(TIMESTAMP '2019-02-10 02:10:12'),\n" + " dayname(TIMESTAMP '1969-01-01 00:00:00'),\n" + " dayname(DATE '1969-01-01'),\n" + " dayname(DATE '2019-02-10'),\n" + " dayname(TIMESTAMP '2019-02-10 02:10:12'),\n" + // sat=7
    " dayofweek(DATE '2019-02-09'),\n" + // sun=1
    " dayofweek(DATE '2019-02-10'),\n" + // sat=7
    " extract(DOW FROM DATE '2019-02-09'),\n" + // sun=1
    " extract(DOW FROM DATE '2019-02-10'),\n" + // sat=6
    " extract(ISODOW FROM DATE '2019-02-09'),\n" + // sun=7
    " extract(ISODOW FROM DATE '2019-02-10')\n" + ")) AS t(t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13)";
    Stream.of(TestLocale.values()).forEach(t -> {
        try {
            CalciteAssert.that().with(CalciteConnectionProperty.LOCALE, t.localeName).with(CalciteConnectionProperty.FUN, "mysql").doWithConnection(connection -> {
                try (Statement statement = connection.createStatement()) {
                    try (ResultSet rs = statement.executeQuery(sql)) {
                        assertThat(rs.next(), is(true));
                        assertThat(rs.getString(1), is(t.january));
                        assertThat(rs.getString(2), is(t.january));
                        assertThat(rs.getString(3), is(t.february));
                        assertThat(rs.getString(4), is(t.february));
                        assertThat(rs.getString(5), is(t.wednesday));
                        assertThat(rs.getString(6), is(t.wednesday));
                        assertThat(rs.getString(7), is(t.sunday));
                        assertThat(rs.getString(8), is(t.sunday));
                        assertThat(rs.getInt(9), is(7));
                        assertThat(rs.getInt(10), is(1));
                        assertThat(rs.getInt(11), is(7));
                        assertThat(rs.getInt(12), is(1));
                        assertThat(rs.getInt(13), is(6));
                        assertThat(rs.getInt(14), is(7));
                        assertThat(rs.next(), is(false));
                    }
                } catch (SQLException e) {
                    throw TestUtil.rethrow(e);
                }
            });
        } catch (Exception e) {
            System.out.println(t.localeName + ":" + Locale.getDefault().toString());
            throw TestUtil.rethrow(e);
        }
    });
}

