@Test
void testLogMatcher() {
    final BiFunction<String, String, List<String>> f = (subject, body) -> {
        final List<String> warnings = new ArrayList<>();
        checkMessage(subject, body, warnings::add);
        return warnings;
    };
    assertThat(f.apply(" [CALCITE-1234] abc", ""), hasItem("starts with space"));
    assertThat(f.apply("[CALCITE-1234]  abc", ""), hasItem("starts with space"));
    assertThat(f.apply("[CALCITE-12b]  abc", ""), hasItem("malformed [CALCITE-nnnn] reference"));
    assertThat(f.apply("[CALCITE-12345]  abc", ""), hasItem("malformed [CALCITE-nnnn] reference"));
    assertThat(f.apply("[CALCITE-1234]: abc", ""), hasItem("malformed [CALCITE-nnnn] reference"));
    assertThat(f.apply("CALCITE-1234: abc", ""), hasItem("malformed [CALCITE-nnnn] reference"));
    assertThat(f.apply("[CALCITE-12] Abc", ""), empty());
    assertThat(f.apply("[CALCITE-123] Abc", ""), empty());
    assertThat(f.apply("[CALCITE-1234] Fix problem with foo", ""), hasItem("contains 'fix' or 'fixes'; you should describe the " + "problem, not what you did"));
    assertThat(f.apply("[CALCITE-1234] Baz doesn't buzz", ""), empty());
    assertThat(f.apply("[CALCITE-1234] Baz doesn't buzz.", ""), hasItem("ends with period"));
    assertThat(f.apply("[CALCITE-1234]  Two problems.", ""), hasSize(2));
    assertThat(f.apply("[CALCITE-1234]  Two problems.", ""), hasItem("ends with period"));
    assertThat(f.apply("[CALCITE-1234]  Two problems.", ""), hasItem("starts with space"));
    assertThat(f.apply("Cosmetic: Move everything one character to left", ""), empty());
    assertThat(f.apply("Finishing up [CALCITE-4937], remove workarounds for " + "[CALCITE-4877]", ""), empty());
    assertThat(f.apply("Fix typo in filterable-model.yaml", ""), empty());
    assertThat(f.apply("Revert \"[CALCITE-4817] Expand SubstitutionVisitor\"", ""), empty());
    assertThat(f.apply("[CALCITE-4817] cannot start with lower-case", ""), hasSize(1));
    assertThat(f.apply("[CALCITE-4817] cannot start with lower-case", ""), hasItem("Message must start with upper-case letter"));
    // If 'Lint:skip' occurs in the body, no checks are performed
    assertThat(f.apply("[CALCITE-4817] cannot start with lower-case", "Body line 1\n" + "\n" + "Lint:skip"), empty());
}

/**
 * Planner does not compare.
 */
@Test
void fieldNamesDoNotInfluenceDigest() {
    final RelBuilder rb = RelBuilder.create(Frameworks.newConfigBuilder().build());
    final RelNode xAsEmpid = rb.values(new String[] { "x", "y", "z" }, 1, 2, 3).project(rb.alias(rb.field("x"), "renamed_x"), rb.alias(rb.field("y"), "renamed_y"), rb.alias(rb.literal("u"), "extra_field")).build();
    assertThat("project column name should not be included to the project digest", RelOptUtil.toString(xAsEmpid, SqlExplainLevel.DIGEST_ATTRIBUTES), isLinux("" + "LogicalProject(inputs=[0..1], exprs=[['u']])\n" + "  LogicalValues(type=[RecordType(INTEGER x, INTEGER y, INTEGER z)], tuples=[[{ 1, 2, 3 }]])\n"));
    assertThat("project column names should be present in EXPPLAN_ATTRIBUTES", RelOptUtil.toString(xAsEmpid, SqlExplainLevel.EXPPLAN_ATTRIBUTES), isLinux("" + "LogicalProject(renamed_x=[$0], renamed_y=[$1], extra_field=['u'])\n" + "  LogicalValues(tuples=[[{ 1, 2, 3 }]])\n"));
    assertThat("project column names should be present with default RelOptUtil.toString(...)", RelOptUtil.toString(xAsEmpid), isLinux("" + "LogicalProject(renamed_x=[$0], renamed_y=[$1], extra_field=['u'])\n" + "  LogicalValues(tuples=[[{ 1, 2, 3 }]])\n"));
}

@Test
void testProjectDigestWithOneTrivialField() {
    final FrameworkConfig config = RelBuilderTest.config().build();
    final RelBuilder builder = RelBuilder.create(config);
    final RelNode rel = builder.scan("EMP").project(builder.field("EMPNO")).build();
    String digest = RelOptUtil.toString(rel, SqlExplainLevel.DIGEST_ATTRIBUTES);
    final String expected = "" + "LogicalProject(inputs=[0])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(digest, isLinux(expected));
}

