/**
 * Unit test for logic functions
 * {@link org.apache.calcite.plan.SubstitutionVisitor#mayBeSatisfiable} and
 * {@link RexUtil#simplify}.
 */
@Test
void testSatisfiable() {
    final SatisfiabilityFixture f = new SatisfiabilityFixture();
    final RexBuilder rexBuilder = f.rexBuilder;
    // TRUE may be satisfiable
    f.checkSatisfiable(rexBuilder.makeLiteral(true), "true");
    // FALSE is not satisfiable
    f.checkNotSatisfiable(rexBuilder.makeLiteral(false));
    // The expression "$0 = 1".
    final RexNode i0_eq_0 = rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, rexBuilder.makeInputRef(f.typeFactory.createType(int.class), 0), rexBuilder.makeExactLiteral(BigDecimal.ZERO));
    // "$0 = 1" may be satisfiable
    f.checkSatisfiable(i0_eq_0, "=($0, 0)");
    // "$0 = 1 AND TRUE" may be satisfiable
    final RexNode e0 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeLiteral(true));
    f.checkSatisfiable(e0, "=($0, 0)");
    // "$0 = 1 AND FALSE" is not satisfiable
    final RexNode e1 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeLiteral(false));
    f.checkNotSatisfiable(e1);
    // "$0 = 0 AND NOT $0 = 0" is not satisfiable
    final RexNode e2 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeCall(SqlStdOperatorTable.NOT, i0_eq_0));
    f.checkNotSatisfiable(e2);
    // "TRUE AND NOT $0 = 0" may be satisfiable. Can simplify.
    final RexNode e3 = rexBuilder.makeCall(SqlStdOperatorTable.AND, rexBuilder.makeLiteral(true), rexBuilder.makeCall(SqlStdOperatorTable.NOT, i0_eq_0));
    f.checkSatisfiable(e3, "<>($0, 0)");
    // The expression "$1 = 1".
    final RexNode i1_eq_1 = rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, rexBuilder.makeInputRef(f.typeFactory.createType(int.class), 1), rexBuilder.makeExactLiteral(BigDecimal.ONE));
    // "$0 = 0 AND $1 = 1 AND NOT $0 = 0" is not satisfiable
    final RexNode e4 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeCall(SqlStdOperatorTable.AND, i1_eq_1, rexBuilder.makeCall(SqlStdOperatorTable.NOT, i0_eq_0)));
    f.checkNotSatisfiable(e4);
    // "$0 = 0 AND NOT $1 = 1" may be satisfiable. Can't simplify.
    final RexNode e5 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeCall(SqlStdOperatorTable.NOT, i1_eq_1));
    f.checkSatisfiable(e5, "AND(=($0, 0), <>($1, 1))");
    // "$0 = 0 AND NOT ($0 = 0 AND $1 = 1)" may be satisfiable. Can simplify.
    final RexNode e6 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeCall(SqlStdOperatorTable.NOT, rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, i1_eq_1)));
    f.checkSatisfiable(e6, "AND(=($0, 0), <>($1, 1))");
    // "$0 = 0 AND ($1 = 1 AND NOT ($0 = 0))" is not satisfiable.
    final RexNode e7 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeCall(SqlStdOperatorTable.AND, i1_eq_1, rexBuilder.makeCall(SqlStdOperatorTable.NOT, i0_eq_0)));
    f.checkNotSatisfiable(e7);
    // The expression "$2".
    final RexInputRef i2 = rexBuilder.makeInputRef(f.typeFactory.createType(boolean.class), 2);
    // The expression "$3".
    final RexInputRef i3 = rexBuilder.makeInputRef(f.typeFactory.createType(boolean.class), 3);
    // The expression "$4".
    final RexInputRef i4 = rexBuilder.makeInputRef(f.typeFactory.createType(boolean.class), 4);
    // "$0 = 0 AND $2 AND $3 AND NOT ($2 AND $3 AND $4) AND NOT ($2 AND $4)" may
    // be satisfiable. Can't simplify.
    final RexNode e8 = rexBuilder.makeCall(SqlStdOperatorTable.AND, i0_eq_0, rexBuilder.makeCall(SqlStdOperatorTable.AND, i2, rexBuilder.makeCall(SqlStdOperatorTable.AND, i3, rexBuilder.makeCall(SqlStdOperatorTable.NOT, rexBuilder.makeCall(SqlStdOperatorTable.AND, i2, i3, i4)), rexBuilder.makeCall(SqlStdOperatorTable.NOT, i4))));
    f.checkSatisfiable(e8, "AND(=($0, 0), $2, $3, OR(NOT($2), NOT($3), NOT($4)), NOT($4))");
}

@Test
void testSplitFilter() {
    final SatisfiabilityFixture f = new SatisfiabilityFixture();
    final RexBuilder rexBuilder = f.rexBuilder;
    final RexSimplify simplify = f.simplify;
    final RexLiteral i1 = rexBuilder.makeExactLiteral(BigDecimal.ONE);
    final RexLiteral i2 = rexBuilder.makeExactLiteral(BigDecimal.valueOf(2));
    final RexLiteral i3 = rexBuilder.makeExactLiteral(BigDecimal.valueOf(3));
    final RelDataType intType = f.typeFactory.createType(int.class);
    // $0
    final RexInputRef x = rexBuilder.makeInputRef(intType, 0);
    // $1
    final RexInputRef y = rexBuilder.makeInputRef(intType, 1);
    // $2
    final RexInputRef z = rexBuilder.makeInputRef(intType, 2);
    final RexNode x_eq_1 = // $0 = 1
    rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, x, i1);
    final RexNode x_eq_1_b = // 1 = $0
    rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, i1, x);
    final RexNode x_eq_2 = // $0 = 2
    rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, x, i2);
    final RexNode y_eq_2 = // $1 = 2
    rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, y, i2);
    final RexNode z_eq_3 = // $2 = 3
    rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, z, i3);
    final // x + y > 2
    RexNode // x + y > 2
    x_plus_y_gt = rexBuilder.makeCall(SqlStdOperatorTable.GREATER_THAN, rexBuilder.makeCall(SqlStdOperatorTable.PLUS, x, y), i2);
    final // y + x > 2
    RexNode // y + x > 2
    y_plus_x_gt = rexBuilder.makeCall(SqlStdOperatorTable.GREATER_THAN, rexBuilder.makeCall(SqlStdOperatorTable.PLUS, y, x), i2);
    final // x*y > 2
    RexNode // x*y > 2
    x_times_y_gt = rexBuilder.makeCall(SqlStdOperatorTable.GREATER_THAN, rexBuilder.makeCall(SqlStdOperatorTable.MULTIPLY, x, y), i2);
    final // 2 < y*x
    RexNode // 2 < y*x
    y_times_x_gt = rexBuilder.makeCall(SqlStdOperatorTable.LESS_THAN, i2, rexBuilder.makeCall(SqlStdOperatorTable.MULTIPLY, y, x));
    final // x + x > 2
    RexNode // x + x > 2
    x_plus_x_gt = rexBuilder.makeCall(SqlStdOperatorTable.GREATER_THAN, rexBuilder.makeCall(SqlStdOperatorTable.PLUS, x, y), i2);
    RexNode newFilter;
    // Example 1.
    //   condition: x = 1 or y = 2
    //   target:    y = 2 or 1 = x
    // yields
    //   residue:   true
    newFilter = SubstitutionVisitor.splitFilter(simplify, rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, y_eq_2), rexBuilder.makeCall(SqlStdOperatorTable.OR, y_eq_2, x_eq_1_b));
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
    // Example 2.
    //   condition: x = 1,
    //   target:    x = 1 or z = 3
    // yields
    //   residue:   x = 1
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_eq_1, rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, z_eq_3));
    assertThat(newFilter, notNullValue());
    assertThat(newFilter, hasToString("=($0, 1)"));
    // 2b.
    //   condition: x = 1 or y = 2
    //   target:    x = 1 or y = 2 or z = 3
    // yields
    //   residue:   x = 1 or y = 2
    newFilter = SubstitutionVisitor.splitFilter(simplify, rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, y_eq_2), rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, y_eq_2, z_eq_3));
    assertThat(newFilter, notNullValue());
    assertThat(newFilter, hasToString("OR(=($0, 1), =($1, 2))"));
    // 2c.
    //   condition: x = 1
    //   target:    x = 1 or y = 2 or z = 3
    // yields
    //   residue:   x = 1
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_eq_1, rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, y_eq_2, z_eq_3));
    assertThat(newFilter, notNullValue());
    assertThat(newFilter, hasToString("=($0, 1)"));
    // 2d.
    //   condition: x = 1 or y = 2
    //   target:    y = 2 or x = 1
    // yields
    //   residue:   true
    newFilter = SubstitutionVisitor.splitFilter(simplify, rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, y_eq_2), rexBuilder.makeCall(SqlStdOperatorTable.OR, y_eq_2, x_eq_1));
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
    // 2e.
    //   condition: x = 1
    //   target:    x = 1 (different object)
    // yields
    //   residue:   true
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_eq_1, x_eq_1_b);
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
    // 2f.
    //   condition: x = 1 or y = 2
    //   target:    x = 1
    // yields
    //   residue:   null
    newFilter = SubstitutionVisitor.splitFilter(simplify, rexBuilder.makeCall(SqlStdOperatorTable.OR, x_eq_1, y_eq_2), x_eq_1);
    assertNull(newFilter);
    // Example 3.
    // Condition [x = 1 and y = 2],
    // target [y = 2 and x = 1] yields
    // residue [true].
    newFilter = SubstitutionVisitor.splitFilter(simplify, rexBuilder.makeCall(SqlStdOperatorTable.AND, x_eq_1, y_eq_2), rexBuilder.makeCall(SqlStdOperatorTable.AND, y_eq_2, x_eq_1));
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
    // Example 4.
    //   condition: x = 1 and y = 2
    //   target:    y = 2
    // yields
    //   residue:   x = 1
    newFilter = SubstitutionVisitor.splitFilter(simplify, rexBuilder.makeCall(SqlStdOperatorTable.AND, x_eq_1, y_eq_2), y_eq_2);
    assertThat(newFilter, notNullValue());
    assertThat(newFilter, hasToString("=($0, 1)"));
    // Example 5.
    //   condition: x = 1
    //   target:    x = 1 and y = 2
    // yields
    //   residue:   null
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_eq_1, rexBuilder.makeCall(SqlStdOperatorTable.AND, x_eq_1, y_eq_2));
    assertNull(newFilter);
    // Example 6.
    //   condition: x = 1
    //   target:    y = 2
    // yields
    //   residue:   null
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_eq_1, y_eq_2);
    assertNull(newFilter);
    // Example 7.
    //   condition: x = 1
    //   target:    x = 2
    // yields
    //   residue:   null
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_eq_1, x_eq_2);
    assertNull(newFilter);
    // Example 8.
    //   condition: x + y > 2
    //   target:    y + x > 2
    // yields
    //   residue:  true
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_plus_y_gt, y_plus_x_gt);
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
    // Example 9.
    //   condition: x + x > 2
    //   target:    x + x > 2
    // yields
    //   residue:  true
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_plus_x_gt, x_plus_x_gt);
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
    // Example 10.
    //   condition: x * y > 2
    //   target:    2 < y * x
    // yields
    //   residue:  true
    newFilter = SubstitutionVisitor.splitFilter(simplify, x_times_y_gt, y_times_x_gt);
    assertThat(newFilter, notNullValue());
    assertThat(newFilter.isAlwaysTrue(), equalTo(true));
}

