/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-119">[CALCITE-119]
 * Comparing a Java type long with a SQL type INTEGER gives wrong
 * answer</a>.
 */
@Test
void testCompareJavaAndSqlTypes() {
    final CalciteAssert.AssertThat with = CalciteAssert.that().withSchema("s", CATCHALL);
    // With CALCITE-119, returned 0 rows. The problem was that when comparing
    // a Java type (long) and a SQL type (INTEGER), the SQL type was deemed
    // "less restrictive". So, the long value got truncated to an int value.
    with.query("select \"primitiveLong\" as c from \"s\".\"everyTypes\"\n" + "where \"primitiveLong\" > 0").returns("C=9223372036854775807\n");
    // count(nullif(b, false)) counts how many times b is true
    with.query("select count(\"primitiveBoolean\") as p,\n" + "  count(\"wrapperBoolean\") as w,\n" + "  count(nullif(\"primitiveShort\" >= 0, false)) as sp,\n" + "  count(nullif(\"wrapperShort\" >= 0, false)) as sw,\n" + "  count(nullif(\"primitiveInt\" >= 0, false)) as ip,\n" + "  count(nullif(\"wrapperInteger\" >= 0, false)) as iw,\n" + "  count(nullif(\"primitiveLong\" >= 0, false)) as lp,\n" + "  count(nullif(\"wrapperLong\" >= 0, false)) as lw\n" + "from \"s\".\"everyTypes\"").returns("P=2; W=1; SP=2; SW=1; IP=2; IW=1; LP=2; LW=1\n");
}

