/**
 * Tests scanning a table function whose row type is determined by parsing a
 * JSON argument. The arguments must therefore be available at prepare
 * time.
 */
@Test
void testTableFunctionScanDynamicType() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM TABLE("dynamicRowType"('{nullable:true,fields:[...]}', 3))
    final RelBuilder builder = RelBuilder.create(config().build());
    final Method m = Smalls.DYNAMIC_ROW_TYPE_TABLE_METHOD;
    final TableFunction tableFunction = TableFunctionImpl.create(m.getDeclaringClass(), m.getName());
    final SqlOperator operator = new SqlUserDefinedTableFunction(new SqlIdentifier("dynamicRowType", SqlParserPos.ZERO), SqlKind.OTHER_FUNCTION, ReturnTypes.CURSOR, InferTypes.ANY_NULLABLE, Arg.metadata(Arg.of("count", f -> f.createSqlType(SqlTypeName.INTEGER), SqlTypeFamily.INTEGER, false), Arg.of("typeJson", f -> f.createSqlType(SqlTypeName.VARCHAR), SqlTypeFamily.STRING, false)), tableFunction);
    final String jsonRowType = "{\"nullable\":false,\"fields\":[" + "  {\"name\":\"i\",\"type\":\"INTEGER\",\"nullable\":false}," + "  {\"name\":\"d\",\"type\":\"DATE\",\"nullable\":true}" + "]}";
    final int rowCount = 3;
    RelNode root = builder.functionScan(operator, 0, builder.literal(jsonRowType), builder.literal(rowCount)).build();
    final String expected = "LogicalTableFunctionScan(" + "invocation=[dynamicRowType('{\"nullable\":false,\"fields\":[" + "  {\"name\":\"i\",\"type\":\"INTEGER\",\"nullable\":false}," + "  {\"name\":\"d\",\"type\":\"DATE\",\"nullable\":true}]}', 3)], " + "rowType=[RecordType(INTEGER i, DATE d)])\n";
    assertThat(root, hasTree(expected));
    // Make sure that the builder's stack is empty.
    try {
        RelNode node = builder.build();
        fail("expected error, got " + node);
    } catch (NoSuchElementException e) {
        assertNull(e.getMessage());
    }
}

