/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-2730">[CALCITE-2730]
 * RelBuilder incorrectly simplifies a filter with duplicate conjunction to
 * empty</a>.
 */
@Test
void testScanFilterDuplicateAnd() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp
    //   WHERE deptno > 20 AND deptno > 20 AND deptno > 20
    final RelBuilder builder = RelBuilder.create(config().build());
    builder.scan("EMP");
    final RexNode condition = builder.greaterThan(builder.field("DEPTNO"), builder.literal(20));
    final RexNode condition2 = builder.lessThan(builder.field("DEPTNO"), builder.literal(30));
    final RelNode root = builder.filter(condition, condition, condition).build();
    final String expected = "LogicalFilter(condition=[>($7, 20)])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expected));
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp
    //   WHERE deptno > 20 AND deptno < 30 AND deptno > 20
    final RelNode root2 = builder.scan("EMP").filter(condition, condition2, condition, condition).build();
    final String expected2 = "" + "LogicalFilter(condition=[SEARCH($7, Sarg[(20..30)])])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root2, hasTree(expected2));
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4325">[CALCITE-4325]
 * RexSimplify incorrectly simplifies complex expressions with Sarg and
 * NULL</a>.
 */
@Test
void testFilterAndOrWithNull() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp
    //   WHERE (deptno <> 20 OR deptno IS NULL) AND deptno = 10
    // Should be simplified to:
    //   SELECT *
    //   FROM emp
    //   WHERE deptno = 10
    // With [CALCITE-4325], is incorrectly simplified to:
    //   SELECT *
    //   FROM emp
    //   WHERE deptno = 10 OR deptno IS NULL
    final Function<RelBuilder, RelNode> f = b -> b.scan("EMP").filter(b.and(b.or(b.notEquals(b.field("DEPTNO"), b.literal(20)), b.isNull(b.field("DEPTNO"))), b.equals(b.field("DEPTNO"), b.literal(10)))).build();
    final String expected = "LogicalFilter(condition=[=($7, 10)])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
}

