@Test
void testProjectBloat() {
    final Function<RelBuilder, RelNode> f = b -> b.scan("EMP").project(b.alias(caseCall(b, b.field("DEPTNO"), b.literal(0), b.literal("zero"), b.literal(1), b.literal("one"), b.literal(2), b.literal("two"), b.literal("other")), "v")).project(b.call(SqlStdOperatorTable.PLUS, b.field("v"), b.field("v"))).build();
    // Complexity of bottom is 14; top is 3; merged is 29; difference is -12.
    // So, we merge if bloat is 20 or 100 (the default),
    // but not if it is -1, 0 or 10.
    final String expected = "LogicalProject($f0=[+" + "(CASE(=($7, 0), 'zero', =($7, 1), 'one', =($7, 2), 'two', 'other')," + " CASE(=($7, 0), 'zero', =($7, 1), 'one', =($7, 2), 'two', 'other'))])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    final String expectedNeg = "LogicalProject($f0=[+($0, $0)])\n" + "  LogicalProject(v=[CASE(=($7, 0), 'zero', =($7, 1), " + "'one', =($7, 2), 'two', 'other')])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
    assertThat(f.apply(createBuilder(c -> c.withBloat(0))), hasTree(expectedNeg));
    assertThat(f.apply(createBuilder(c -> c.withBloat(-1))), hasTree(expectedNeg));
    assertThat(f.apply(createBuilder(c -> c.withBloat(10))), hasTree(expectedNeg));
    assertThat(f.apply(createBuilder(c -> c.withBloat(20))), hasTree(expected));
}

@Test
void testProjectBloat2() {
    final Function<RelBuilder, RelNode> f = b -> b.scan("EMP").project(b.field("DEPTNO"), b.field("SAL"), b.alias(b.call(SqlStdOperatorTable.PLUS, b.field("DEPTNO"), b.field("EMPNO")), "PLUS")).project(b.call(SqlStdOperatorTable.MULTIPLY, b.field("SAL"), b.field("PLUS")), b.field("SAL")).build();
    // Complexity of bottom is 5; top is 4; merged is 6; difference is 3.
    // So, we merge except when bloat is -1.
    final String expected = "LogicalProject($f0=[*($5, +($7, $0))], SAL=[$5])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    final String expectedNeg = "LogicalProject($f0=[*($1, $2)], SAL=[$1])\n" + "  LogicalProject(DEPTNO=[$7], SAL=[$5], PLUS=[+($7, $0)])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
    assertThat(f.apply(createBuilder(c -> c.withBloat(0))), hasTree(expected));
    assertThat(f.apply(createBuilder(c -> c.withBloat(-1))), hasTree(expectedNeg));
    assertThat(f.apply(createBuilder(c -> c.withBloat(10))), hasTree(expected));
    assertThat(f.apply(createBuilder(c -> c.withBloat(20))), hasTree(expected));
}

/**
 * Creates a {@link Project} that contains a windowed aggregate function.
 * Repeats the using {@link RelBuilder.AggCall#over} and
 * {@link RexBuilder#makeOver}.
 */
@Test
void testProjectOver() {
    final Function<RelBuilder, RelNode> f = b -> {
        final RelDataType intType = b.getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        return b.scan("EMP").project(b.field("DEPTNO"), b.alias(b.getRexBuilder().makeOver(intType, SqlStdOperatorTable.ROW_NUMBER, ImmutableList.of(), ImmutableList.of(), ImmutableList.of(new RexFieldCollation(b.field("EMPNO"), ImmutableSet.of())), RexWindowBounds.UNBOUNDED_PRECEDING, RexWindowBounds.UNBOUNDED_FOLLOWING, true, true, false, false, false), "x")).build();
    };
    final Function<RelBuilder, RelNode> f2 = b -> b.scan("EMP").project(b.field("DEPTNO"), b.aggregateCall(SqlStdOperatorTable.ROW_NUMBER).over().partitionBy().orderBy(b.field("EMPNO")).rowsUnbounded().allowPartial(true).nullWhenCountZero(false).as("x")).build();
    final String expected = "" + "LogicalProject(DEPTNO=[$7], x=[ROW_NUMBER() OVER (ORDER BY $0)])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
    assertThat(f2.apply(createBuilder()), hasTree(expected));
}

