@Test
void testAggregateFilterNullable() {
    // Equivalent SQL:
    //   SELECT deptno, SUM(sal) FILTER (WHERE comm < 100) AS c
    //   FROM emp
    //   GROUP BY deptno
    final Function<RelBuilder, RelNode> f = builder -> builder.scan("EMP").aggregate(builder.groupKey(builder.field("DEPTNO")), builder.sum(builder.field("SAL")).filter(builder.lessThan(builder.field("COMM"), builder.literal(100))).as("C")).build();
    final String expected = "" + "LogicalAggregate(group=[{1}], C=[SUM($0) FILTER $2])\n" + "  LogicalProject(SAL=[$5], DEPTNO=[$7], $f8=[IS TRUE(<($6, 100))])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
    // now without pruning
    final String expected2 = "" + "LogicalAggregate(group=[{7}], C=[SUM($5) FILTER $8])\n" + "  LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], HIREDATE=[$4], SAL=[$5], COMM=[$6], DEPTNO=[$7], $f8=[IS TRUE(<($6, 100))])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder(c -> c.withPruneInputOfAggregate(false))), hasTree(expected2));
}

