/**
 * Tests that {@link RelBuilder#aggregate} on top of a {@link Project} prunes
 * away expressions that are not used.
 *
 * @see RelBuilder.Config#pruneInputOfAggregate
 */
@Test
void testAggregateProjectPrune() {
    // SELECT deptno, SUM(sal) FILTER (WHERE b)
    // FROM (
    //   SELECT deptno, empno + 10, sal, job = 'CLERK' AS b
    //   FROM emp)
    // GROUP BY deptno
    //   -->
    // SELECT deptno, SUM(sal) FILTER (WHERE b)
    // FROM (
    //   SELECT deptno, sal, job = 'CLERK' AS b
    //   FROM emp)
    // GROUP BY deptno
    final Function<RelBuilder, RelNode> f = builder -> builder.scan("EMP").project(builder.field("DEPTNO"), builder.call(SqlStdOperatorTable.PLUS, builder.field("EMPNO"), builder.literal(10)), builder.field("SAL"), builder.field("JOB")).aggregate(builder.groupKey(builder.field("DEPTNO")), builder.sum(builder.field("SAL")).filter(builder.equals(builder.field("JOB"), builder.literal("CLERK")))).build();
    final String expected = "" + "LogicalAggregate(group=[{0}], agg#0=[SUM($1) FILTER $2])\n" + "  LogicalProject(DEPTNO=[$7], SAL=[$5], $f4=[IS TRUE(=($2, 'CLERK'))])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
    // now with pruning disabled
    final String expected2 = "" + "LogicalAggregate(group=[{0}], agg#0=[SUM($2) FILTER $4])\n" + "  LogicalProject(DEPTNO=[$7], $f1=[+($0, 10)], SAL=[$5], JOB=[$2], " + "$f4=[IS TRUE(=($2, 'CLERK'))])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder(c -> c.withPruneInputOfAggregate(false))), hasTree(expected2));
}

/**
 * Tests that (a) if the input is a project and no fields are used
 * we remove the project (rather than projecting zero fields, which
 * would be wrong), and (b) if the same aggregate function is used
 * twice, we add a project on top.
 */
@Test
void testAggregateProjectPruneEmpty() {
    // SELECT COUNT(*) AS C, COUNT(*) AS C2 FROM (
    //  SELECT deptno, empno + 10, sal, job = 'CLERK' AS b
    //  FROM emp)
    //   -->
    // SELECT C, C AS C2 FROM (
    //   SELECT COUNT(*) AS c
    //   FROM emp)
    final Function<RelBuilder, RelNode> f = builder -> builder.scan("EMP").project(builder.field("DEPTNO"), builder.call(SqlStdOperatorTable.PLUS, builder.field("EMPNO"), builder.literal(10)), builder.field("SAL"), builder.field("JOB")).aggregate(builder.groupKey(), builder.countStar("C"), builder.countStar("C2")).build();
    final String expected = "" + "LogicalProject(C=[$0], C2=[$0])\n" + "  LogicalAggregate(group=[{}], C=[COUNT()])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
    // now with pruning disabled
    final String expected2 = "" + "LogicalProject(C=[$0], C2=[$0])\n" + "  LogicalAggregate(group=[{}], C=[COUNT()])\n" + "    LogicalProject(DEPTNO=[$7], $f1=[+($0, 10)], SAL=[$5], JOB=[$2])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder(c -> c.withPruneInputOfAggregate(false))), hasTree(expected2));
}

