@Test
void testAggregateGroupingSetsGroupId() {
    final String plan = "" + "LogicalProject(JOB=[$0], DEPTNO=[$1], $f2=[0:BIGINT])\n" + "  LogicalAggregate(group=[{2, 7}], groups=[[{2, 7}, {2}, {7}]])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
