@Test
void testDistinctEmpty() {
    // Is a relation with zero columns distinct?
    // What about if we know there are zero rows?
    // It is a matter of definition: there are no duplicate rows,
    // but applying "select ... group by ()" to it would change the result.
    // In theory, we could omit the distinct if we know there is precisely one
    // row, but we don't currently.
    final Function<RelBuilder, RelNode> f = builder -> builder.scan("EMP").filter(builder.call(SqlStdOperatorTable.IS_NULL, builder.field("COMM"))).project().distinct().build();
    final String expected = "" + "LogicalValues(tuples=[[{ true }]])\n";
    final RelNode r = f.apply(createBuilder());
    assertThat(r, hasTree(expected));
    // Now without adding extra fields
    final String expected2 = "" + "LogicalValues(tuples=[[{  }]])\n";
    final RelNode r2 = f.apply(createBuilder(c -> c.withPreventEmptyFieldList(false)));
    assertThat(r2, hasTree(expected2));
    // Now without pruning
    // (The empty LogicalProject is dubious, but it's what we've always done)
    final String expected3 = "" + "LogicalAggregate(group=[{}])\n" + "  LogicalProject\n" + "    LogicalFilter(condition=[IS NULL($6)])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n";
    final RelNode r3 = f.apply(createBuilder(c -> c.withPruneInputOfAggregate(false).withPreventEmptyFieldList(false)));
    assertThat(r3, hasTree(expected3));
}

