@Test
void testRepeatUnion1() {
    // Generates the sequence 1,2,3,...10 using a repeat union. Equivalent SQL:
    //   WITH RECURSIVE delta(n) AS (
    //     VALUES (1)
    //     UNION ALL
    //     SELECT n+1 FROM delta WHERE n < 10
    //   )
    //   SELECT * FROM delta
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.values(new String[] { "i" }, 1).transientScan("DELTA_TABLE").filter(builder.call(SqlStdOperatorTable.LESS_THAN, builder.field(0), builder.literal(10))).project(builder.call(SqlStdOperatorTable.PLUS, builder.field(0), builder.literal(1))).repeatUnion("DELTA_TABLE", true).build();
    final String expected = "LogicalRepeatUnion(all=[true])\n" + "  LogicalTableSpool(readType=[LAZY], writeType=[LAZY], table=[[DELTA_TABLE]])\n" + "    LogicalValues(tuples=[[{ 1 }]])\n" + "  LogicalTableSpool(readType=[LAZY], writeType=[LAZY], table=[[DELTA_TABLE]])\n" + "    LogicalProject($f0=[+($0, 1)])\n" + "      LogicalFilter(condition=[<($0, 10)])\n" + "        LogicalTableScan(table=[[DELTA_TABLE]])\n";
    assertThat(root, hasTree(expected));
}

@Test
void testRepeatUnion2() {
    // Generates the factorial function from 0 to 7. Equivalent SQL:
    //   WITH RECURSIVE delta (n, fact) AS (
    //     VALUES (0, 1)
    //     UNION ALL
    //     SELECT n+1, (n+1)*fact FROM delta WHERE n < 7
    //   )
    //   SELECT * FROM delta
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.values(new String[] { "n", "fact" }, 0, 1).transientScan("AUX").filter(builder.call(SqlStdOperatorTable.LESS_THAN, builder.field("n"), builder.literal(7))).project(Arrays.asList(builder.call(SqlStdOperatorTable.PLUS, builder.field("n"), builder.literal(1)), builder.call(SqlStdOperatorTable.MULTIPLY, builder.call(SqlStdOperatorTable.PLUS, builder.field("n"), builder.literal(1)), builder.field("fact"))), Arrays.asList("n", "fact")).repeatUnion("AUX", true).build();
    final String expected = "LogicalRepeatUnion(all=[true])\n" + "  LogicalTableSpool(readType=[LAZY], writeType=[LAZY], table=[[AUX]])\n" + "    LogicalValues(tuples=[[{ 0, 1 }]])\n" + "  LogicalTableSpool(readType=[LAZY], writeType=[LAZY], table=[[AUX]])\n" + "    LogicalProject(n=[+($0, 1)], fact=[*(+($0, 1), $1)])\n" + "      LogicalFilter(condition=[<($0, 7)])\n" + "        LogicalTableScan(table=[[AUX]])\n";
    assertThat(root, hasTree(expected));
}

