    // Equivalent SQL:
    //   SELECT empno FROM emp
    //   WHERE deptno = 20
    //   MINUS
    //   SELECT deptno FROM dept
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.scan("DEPT").project(builder.field("DEPTNO")).scan("EMP").filter(builder.equals(builder.field("DEPTNO"), builder.literal(20))).project(builder.field("EMPNO")).minus(false).build();
    final String expected = "" + "LogicalMinus(all=[false])\n" + "  LogicalProject(DEPTNO=[$0])\n" + "    LogicalTableScan(table=[[scott, DEPT]])\n" + "  LogicalProject(EMPNO=[$0])\n" + "    LogicalFilter(condition=[=($7, 20)])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expected));
}

/**
 * Tests building a simple join. Also checks {@link RelBuilder#size()}
 * at every step.
 */
@Test
void testJoin() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM (SELECT * FROM emp WHERE comm IS NULL)
    //   JOIN dept ON emp.deptno = dept.deptno
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.let(b -> assertSize(b, is(0))).scan("EMP").let(b -> assertSize(b, is(1))).filter(builder.call(SqlStdOperatorTable.IS_NULL, builder.field("COMM"))).let(b -> assertSize(b, is(1))).scan("DEPT").let(b -> assertSize(b, is(2))).join(JoinRelType.INNER, builder.equals(builder.field(2, 0, "DEPTNO"), builder.field(2, 1, "DEPTNO"))).let(b -> assertSize(b, is(1))).build();
    assertThat(builder, isRelBuilderWithSize(is(0)));
    final String expected = "" + "LogicalJoin(condition=[=($7, $8)], joinType=[inner])\n" + "  LogicalFilter(condition=[IS NULL($6)])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n" + "  LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(root, hasTree(expected));
}

