/**
 * Tests that {@code Union(Project(Values), ... Project(Values))} is
 * simplified to {@code Values}. It occurs commonly: people write
 * {@code SELECT 1 UNION SELECT 2}.
 */
@Test
void testUnionProjectValues() {
    // Equivalent SQL:
    //   SELECT 'a', 1
    //   UNION ALL
    //   SELECT 'b', 2
    final BiFunction<RelBuilder, Boolean, RelNode> f = (b, all) -> b.values(new String[] { "zero" }, 0).project(b.literal("a"), b.literal(1)).values(new String[] { "zero" }, 0).project(b.literal("b"), b.literal(2)).union(all, 2).build();
    final String expected = "LogicalValues(tuples=[[{ 'a', 1 }, { 'b', 2 }]])\n";
    // Same effect with and without ALL because tuples are distinct
    assertThat(f.apply(createBuilder(), true), hasTree(expected));
    assertThat(f.apply(createBuilder(), false), hasTree(expected));
}

@Test
void testUnionProjectValues2() {
    // Equivalent SQL:
    //   SELECT 'a', 1 FROM (VALUES (0), (0))
    //   UNION ALL
    //   SELECT 'b', 2
    final BiFunction<RelBuilder, Boolean, RelNode> f = (b, all) -> b.values(new String[] { "zero" }, 0).project(b.literal("a"), b.literal(1)).values(new String[] { "zero" }, 0, 0).project(b.literal("b"), b.literal(2)).union(all, 2).build();
    // Different effect with and without ALL because tuples are not distinct.
    final String expectedAll = "LogicalValues(tuples=[[{ 'a', 1 }, { 'b', 2 }, { 'b', 2 }]])\n";
    final String expectedDistinct = "LogicalValues(tuples=[[{ 'a', 1 }, { 'b', 2 }]])\n";
    assertThat(f.apply(createBuilder(), true), hasTree(expectedAll));
    assertThat(f.apply(createBuilder(), false), hasTree(expectedDistinct));
}

