@Test
void testPivot() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM (SELECT mgr, deptno, job, sal FROM emp)
    //   PIVOT (SUM(sal) AS ss, COUNT(*) AS c
    //       FOR (job, deptno)
    //       IN (('CLERK', 10) AS c10, ('MANAGER', 20) AS m20))
    //
    // translates to
    //   SELECT mgr,
    //     SUM(sal) FILTER (WHERE job = 'CLERK' AND deptno = 10) AS c10_ss,
    //     COUNT(*) FILTER (WHERE job = 'CLERK' AND deptno = 10) AS c10_c,
    //     SUM(sal) FILTER (WHERE job = 'MANAGER' AND deptno = 20) AS m20_ss,
    //     COUNT(*) FILTER (WHERE job = 'MANAGER' AND deptno = 20) AS m20_c
    //   FROM emp
    //   GROUP BY mgr
    //
    final Function<RelBuilder, RelNode> f = b -> b.scan("EMP").pivot(b.groupKey("MGR"), Arrays.asList(b.sum(b.field("SAL")).as("SS"), b.count().as("C")), b.fields(Arrays.asList("JOB", "DEPTNO")), ImmutableMap.<String, List<RexNode>>builder().put("C10", Arrays.asList(b.literal("CLERK"), b.literal(10))).put("M20", Arrays.asList(b.literal("MANAGER"), b.literal(20))).build().entrySet()).build();
    final String expected = "" + "LogicalAggregate(group=[{0}], C10_SS=[SUM($1) FILTER $2], " + "C10_C=[COUNT() FILTER $2], M20_SS=[SUM($1) FILTER $3], " + "M20_C=[COUNT() FILTER $3])\n" + "  LogicalProject(MGR=[$3], SAL=[$5], " + "$f8=[IS TRUE(AND(=($2, 'CLERK'), =($7, 10)))], " + "$f9=[IS TRUE(AND(=($2, 'MANAGER'), =($7, 20)))])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(f.apply(createBuilder()), hasTree(expected));
}

@Test
void testUnpivot() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM (SELECT deptno, job, sal, comm FROM emp)
    //   UNPIVOT INCLUDE NULLS (remuneration
    //     FOR remuneration_type IN (comm AS 'commission',
    //                               sal AS 'salary'))
    //
    // translates to
    //   SELECT e.deptno, e.job,
    //     CASE t.remuneration_type
    //     WHEN 'commission' THEN comm
    //     ELSE sal
    //     END AS remuneration
    //   FROM emp
    //   CROSS JOIN VALUES ('commission', 'salary') AS t (remuneration_type)
    //
    final BiFunction<RelBuilder, Boolean, RelNode> f = (b, includeNulls) -> b.scan("EMP").unpivot(includeNulls, ImmutableList.of("REMUNERATION"), ImmutableList.of("REMUNERATION_TYPE"), Pair.zip(Arrays.asList(ImmutableList.of(b.literal("commission")), ImmutableList.of(b.literal("salary"))), Arrays.asList(ImmutableList.of(b.field("COMM")), ImmutableList.of(b.field("SAL"))))).build();
    final String expectedIncludeNulls = "" + "LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], " + "HIREDATE=[$4], DEPTNO=[$7], REMUNERATION_TYPE=[$8], " + "REMUNERATION=[CASE(=($8, 'commission'), $6, =($8, 'salary'), $5, " + "null:NULL)])\n" + "  LogicalJoin(condition=[true], joinType=[inner])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n" + "    LogicalValues(tuples=[[{ 'commission' }, { 'salary' }]])\n";
    final String expectedExcludeNulls = "" + "LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], " + "HIREDATE=[$4], DEPTNO=[$5], REMUNERATION_TYPE=[$6], " + "REMUNERATION=[CAST($7):DECIMAL(7, 2) NOT NULL])\n" + "  LogicalFilter(condition=[IS NOT NULL($7)])\n" + "    " + expectedIncludeNulls.replace("\n  ", "\n      ");
    assertThat(f.apply(createBuilder(), true), hasTree(expectedIncludeNulls));
    assertThat(f.apply(createBuilder(), false), hasTree(expectedExcludeNulls));
}

