@Test
void testDynamicParameterInLimitOffset() {
    final RelBuilder relBuilder = RelBuilder.create(config().build());
    final RelDataType intType = relBuilder.getTypeFactory().createSqlType(SqlTypeName.INTEGER);
    final RexBuilder rexBuilder = relBuilder.getRexBuilder();
    RelNode planBefore = relBuilder.scan("DEPT").sortLimit(rexBuilder.makeDynamicParam(intType, 1), rexBuilder.makeDynamicParam(intType, 0), ImmutableList.of()).build();
    String expectedLogicalPlan = "LogicalSort(offset=[?1], fetch=[?0])\n" + "  LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(planBefore, hasTree(expectedLogicalPlan));
    RuleSet prepareRules = RuleSets.ofList(EnumerableRules.ENUMERABLE_FILTER_RULE, EnumerableRules.ENUMERABLE_SORT_RULE, EnumerableRules.ENUMERABLE_LIMIT_RULE, EnumerableRules.ENUMERABLE_TABLE_SCAN_RULE);
    RelTraitSet desiredTraits = planBefore.getTraitSet().replace(EnumerableConvention.INSTANCE);
    Program program = Programs.of(prepareRules);
    RelNode planAfter = program.run(planBefore.getCluster().getPlanner(), planBefore, desiredTraits, ImmutableList.of(), ImmutableList.of());
    String expectedEnumerablePlan = "EnumerableLimit(offset=[?1], fetch=[?0])\n" + "  EnumerableTableScan(table=[[scott, DEPT]])\n";
    assertThat(planAfter, hasTree(expectedEnumerablePlan));
    RelMetadataQuery mq = planAfter.getCluster().getMetadataQuery();
    assertThat(mq.getMinRowCount(planAfter), is(0D));
    assertThat(mq.getMaxRowCount(planAfter), is(Double.POSITIVE_INFINITY));
}

