@Test
void testHints() {
    final RelHint indexHint = RelHint.builder("INDEX").hintOption("_idx1").hintOption("_idx2").build();
    final RelHint propsHint = RelHint.builder("PROPERTIES").inheritPath(0).hintOption("parallelism", "3").hintOption("mem", "20Mb").build();
    final RelHint noHashJoinHint = RelHint.builder("NO_HASH_JOIN").inheritPath(0).build();
    final RelHint hashJoinHint = RelHint.builder("USE_HASH_JOIN").hintOption("orders").hintOption("products_temporal").build();
    final RelBuilder builder = RelBuilder.create(config().build());
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp /*+ INDEX(_idx1, _idx2) */
    final RelNode root = builder.scan("EMP").hints(indexHint).build();
    assertThat(root, hasHints("[[INDEX inheritPath:[] options:[_idx1, _idx2]]]"));
    // Equivalent SQL:
    //   SELECT /*+  PROPERTIES(parallelism='3', mem='20Mb') */
    //   *
    //   FROM emp /*+ INDEX(_idx1, _idx2) */
    final RelNode root1 = builder.scan("EMP").hints(indexHint, propsHint).build();
    assertThat(root1, hasHints("[[INDEX inheritPath:[] options:[_idx1, _idx2]], " + "[PROPERTIES inheritPath:[0] options:{parallelism=3, mem=20Mb}]]"));
    // Equivalent SQL:
    //   SELECT /*+ NO_HASH_JOIN */
    //   *
    //   FROM emp
    //     join dept
    //     on emp.deptno = dept.deptno
    final RelNode root2 = builder.scan("EMP").scan("DEPT").join(JoinRelType.INNER, builder.equals(builder.field(2, 0, "DEPTNO"), builder.field(2, 1, "DEPTNO"))).hints(noHashJoinHint).build();
    assertThat(root2, hasHints("[[NO_HASH_JOIN inheritPath:[0]]]"));
    // Equivalent SQL:
    //   SELECT *
    //   FROM orders
    //   JOIN products_temporal FOR SYSTEM_TIME AS OF orders.rowtime
    //   ON orders.product = products_temporal.id
    RelNode left = builder.scan("orders").build();
    RelNode right = builder.scan("products_temporal").build();
    RexNode period = builder.getRexBuilder().makeFieldAccess(builder.getRexBuilder().makeCorrel(left.getRowType(), new CorrelationId(0)), 0);
    RelNode root3 = builder.push(left).push(right).snapshot(period).correlate(JoinRelType.INNER, new CorrelationId(0), builder.field(2, 0, "ROWTIME"), builder.field(2, 0, "ID"), builder.field(2, 0, "PRODUCT")).hints(hashJoinHint).build();
    assertThat(root3, hasHints("[[USE_HASH_JOIN inheritPath:[] options:[orders, products_temporal]]]"));
}

