@Test
void testHintsOnNonHintable() {
    final RelHint indexHint = RelHint.builder("INDEX").hintOption("_idx1").hintOption("_idx2").build();
    // Attach hints on non hintable.
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp
    //   MATCH_RECOGNIZE (
    //     PARTITION BY deptno
    //     ORDER BY empno asc
    //     MEASURES
    //       STRT.mgr as start_nw,
    //       LAST(DOWN.mgr) as bottom_nw,
    //     PATTERN (STRT DOWN+ UP+) WITHIN INTERVAL '5' SECOND
    //     DEFINE
    //       DOWN as DOWN.mgr < PREV(DOWN.mgr),
    //       UP as UP.mgr > PREV(UP.mgr)
    //   )
    final RelBuilder builder = RelBuilder.create(config().build()).scan("EMP");
    final RelDataTypeFactory typeFactory = builder.getTypeFactory();
    final RelDataType intType = typeFactory.createSqlType(SqlTypeName.INTEGER);
    RexNode pattern = builder.patternConcat(builder.literal("STRT"), builder.patternQuantify(builder.literal("DOWN"), builder.literal(1), builder.literal(-1), builder.literal(false)), builder.patternQuantify(builder.literal("UP"), builder.literal(1), builder.literal(-1), builder.literal(false)));
    ImmutableMap.Builder<String, RexNode> pdBuilder = new ImmutableMap.Builder<>();
    RexNode downDefinition = builder.lessThan(builder.call(SqlStdOperatorTable.PREV, builder.patternField("DOWN", intType, 3), builder.literal(0)), builder.call(SqlStdOperatorTable.PREV, builder.patternField("DOWN", intType, 3), builder.literal(1)));
    pdBuilder.put("DOWN", downDefinition);
    RexNode upDefinition = builder.greaterThan(builder.call(SqlStdOperatorTable.PREV, builder.patternField("UP", intType, 3), builder.literal(0)), builder.call(SqlStdOperatorTable.PREV, builder.patternField("UP", intType, 3), builder.literal(1)));
    pdBuilder.put("UP", upDefinition);
    ImmutableList.Builder<RexNode> measuresBuilder = new ImmutableList.Builder<>();
    measuresBuilder.add(builder.alias(builder.patternField("STRT", intType, 3), "start_nw"));
    measuresBuilder.add(builder.alias(builder.call(SqlStdOperatorTable.LAST, builder.patternField("DOWN", intType, 3), builder.literal(0)), "bottom_nw"));
    RexNode after = builder.getRexBuilder().makeFlag(SqlMatchRecognize.AfterOption.SKIP_TO_NEXT_ROW);
    ImmutableList.Builder<RexNode> partitionKeysBuilder = new ImmutableList.Builder<>();
    partitionKeysBuilder.add(builder.field("DEPTNO"));
    ImmutableList.Builder<RexNode> orderKeysBuilder = new ImmutableList.Builder<>();
    orderKeysBuilder.add(builder.field("EMPNO"));
    RexNode interval = builder.literal("INTERVAL '5' SECOND");
    Executable executable = () -> {
        builder.match(pattern, false, false, pdBuilder.build(), measuresBuilder.build(), after, ImmutableMap.of(), false, partitionKeysBuilder.build(), orderKeysBuilder.build(), interval).hints(indexHint);
    };
    final AssertionError error1 = assertThrows(AssertionError.class, executable, "hints() should fail on non Hintable relational expression");
    assertThat(error1.getMessage(), containsString("The top relational expression is not a Hintable"));
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3747">[CALCITE-3747]
 * Constructing BETWEEN with RelBuilder throws class cast exception</a>.
 *
 * <p>BETWEEN is no longer allowed in RexCall. 'a BETWEEN b AND c' is expanded
 * 'a >= b AND a <= c', whether created via
 * {@link RelBuilder#call(SqlOperator, RexNode...)} or
 * {@link RelBuilder#between(RexNode, RexNode, RexNode)}.
 */
@Test
void testCallBetweenOperator() {
    final RelBuilder builder = RelBuilder.create(config().build()).scan("EMP");
    final String expected = "SEARCH($0, Sarg[[1..5]])";
    final RexNode call = builder.call(SqlStdOperatorTable.BETWEEN, builder.field("EMPNO"), builder.literal(1), builder.literal(5));
    assertThat(call, hasToString(expected));
    final RexNode call2 = builder.between(builder.field("EMPNO"), builder.literal(1), builder.literal(5));
    assertThat(call2, hasToString(expected));
    final RelNode root = builder.filter(call2).build();
    final String expectedRel = "" + "LogicalFilter(condition=[SEARCH($0, Sarg[[1..5]])])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expectedRel));
    // Consecutive filters are not merged. (For now, anyway.)
    builder.push(root).filter(builder.not(builder.equals(builder.field("EMPNO"), builder.literal(3))), builder.equals(builder.field("DEPTNO"), builder.literal(10)));
    final RelNode root2 = builder.build();
    final String expectedRel2 = "" + "LogicalFilter(condition=[AND(<>($0, 3), =($7, 10))])\n" + "  LogicalFilter(condition=[SEARCH($0, Sarg[[1..5]])])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root2, hasTree(expectedRel2));
    // The conditions in one filter are simplified.
    builder.scan("EMP").filter(builder.between(builder.field("EMPNO"), builder.literal(1), builder.literal(5)), builder.not(builder.equals(builder.field("EMPNO"), builder.literal(3))), builder.equals(builder.field("DEPTNO"), builder.literal(10)));
    final RelNode root3 = builder.build();
    final String expectedRel3 = "" + "LogicalFilter(condition=[AND(SEARCH($0, Sarg[[1..3), (3..5]]), =($7, 10))])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root3, hasTree(expectedRel3));
}

