/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4414">[CALCITE-4414]
 * RelMdSelectivity#getSelectivity for Calc can propagate a predicate with wrong reference</a>.
 */
@Test
void testCalcSelectivityWithPredicate() {
    final RelBuilder builder = RelBuilder.create(RelBuilderTest.config().build());
    final RelNode relNode = builder.scan("EMP").project(builder.field("DEPTNO")).scan("EMP").project(builder.field("DEPTNO")).union(true).projectPlus(builder.field("DEPTNO")).filter(builder.equals(builder.field(0), builder.literal(0))).build();
    // Program to convert Project + Filter into a single Calc
    final HepProgram program = new HepProgramBuilder().addRuleInstance(CoreRules.FILTER_TO_CALC).addRuleInstance(CoreRules.PROJECT_TO_CALC).addRuleInstance(CoreRules.CALC_MERGE).build();
    final HepPlanner hepPlanner = new HepPlanner(program);
    hepPlanner.setRoot(relNode);
    RelNode output = hepPlanner.findBestExp();
    // Add filter on the extra field generated by projectPlus (now a Calc after hepPlanner)
    output = builder.push(output).filter(builder.equals(builder.field(1), builder.literal(0))).build();
    // Should not fail
    output.estimateRowCount(output.getCluster().getMetadataQuery());
}

