/**
 * Unit test for
 * {@link org.apache.calcite.rel.metadata.RelMetadataQuery#areRowsUnique(RelNode)}.
 */
@Test
void testRowsUnique() {
    sql("select * from emp").assertRowsUnique(is(true), "table has primary key");
    sql("select deptno from emp").assertRowsUnique(is(false), "table has primary key");
    sql("select empno from emp").assertRowsUnique(is(true), "primary key is unique");
    sql("select empno from emp, dept").assertRowsUnique(is(false), "cartesian product destroys uniqueness");
    sql("select empno from emp join dept using (deptno)").assertRowsUnique(is(true), "many-to-one join does not destroy uniqueness");
    sql("select empno, job from emp join dept using (deptno) order by job desc").assertRowsUnique(is(true), "project and sort does not destroy uniqueness");
    sql("select deptno from emp limit 1").assertRowsUnique(is(true), "1 row table is always unique");
    sql("select distinct deptno from emp").assertRowsUnique(is(true), "distinct table is always unique");
    sql("select count(*) from emp").assertRowsUnique(is(true), "grand total is always unique");
    sql("select count(*) from emp group by deptno").assertRowsUnique(is(false), "several depts may have same count");
    sql("select deptno, count(*) from emp group by deptno").assertRowsUnique(is(true), "group by keys are unique");
    sql("select deptno, count(*) from emp group by grouping sets ((), (deptno))").assertRowsUnique(true, is(true), "group by keys are unique and not null");
    sql("select deptno, count(*) from emp group by grouping sets ((), (deptno))").assertRowsUnique(false, nullValue(Boolean.class), "is actually unique; TODO: deduce it");
    sql("select distinct deptno from emp join dept using (deptno)").assertRowsUnique(is(true), "distinct table is always unique");
    sql("select deptno from emp union select deptno from dept").assertRowsUnique(is(true), "set query is always unique");
    sql("select deptno from emp intersect select deptno from dept").assertRowsUnique(is(true), "set query is always unique");
    sql("select deptno from emp except select deptno from dept").assertRowsUnique(is(true), "set query is always unique");
}

