@Test
void testAllPredicatesAndTablesJoin() {
    final String sql = "select x.sal, y.deptno from
" + "(select a.deptno, c.sal from (select * from emp limit 7) as a
" + "cross join (select * from dept limit 1) as b
" + "inner join (select * from emp limit 2) as c
" + "on a.deptno = c.deptno) as x
" + "inner join
" + "(select a.deptno, c.sal from (select * from emp limit 7) as a
" + "cross join (select * from dept limit 1) as b
" + "inner join (select * from emp limit 2) as c
" + "on a.deptno = c.deptno) as y
" + "on x.deptno = y.deptno";
    final RelNode rel = sql(sql).toRel();
    final RelMetadataQuery mq = rel.getCluster().getMetadataQuery();
    final RelOptPredicateList inputSet = mq.getAllPredicates(rel);
    assertThat(inputSet.pulledUpPredicates, sortsAs("[=([CATALOG, SALES, EMP].#0.$7, [CATALOG, SALES, EMP].#1.$7), " + "=([CATALOG, SALES, EMP].#0.$7, [CATALOG, SALES, EMP].#2.$7), " + "=([CATALOG, SALES, EMP].#2.$7, [CATALOG, SALES, EMP].#3.$7), " + "true, " + "true]"));
    final Set<RelTableRef> tableReferences = Sets.newTreeSet(mq.getTableReferences(rel));
    assertThat(tableReferences, hasToString("[[CATALOG, SALES, DEPT].#0, [CATALOG, SALES, DEPT].#1, " + "[CATALOG, SALES, EMP].#0, [CATALOG, SALES, EMP].#1, " + "[CATALOG, SALES, EMP].#2, [CATALOG, SALES, EMP].#3]"));
}

