 * with a table that has its own implementation of {@link BuiltInMetadata.Size}.
 */
@Test
void testCustomizedAverageColumnSizes() {
    SqlTestFactory.CatalogReaderFactory factory = (typeFactory, caseSensitive) -> {
        CompositeKeysCatalogReader catalogReader = new CompositeKeysCatalogReader(typeFactory, false);
        catalogReader.init();
        return catalogReader;
    };
    final RelNode rel = sql("select key1, key2 from s.composite_keys_table").withCatalogReaderFactory(factory).toRel();
    final RelMetadataQuery mq = rel.getCluster().getMetadataQuery();
