/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-2865">[CALCITE-2865]
 * FilterProjectTransposeRule generates wrong traitSet when
 * copyFilter/copyProject is true</a>.
 */
@Test
void testFilterProjectTransposeRule() {
    List<RelOptRule> rules = Arrays.asList(// default: copyFilter=true, copyProject=true
    CoreRules.FILTER_PROJECT_TRANSPOSE, CoreRules.FILTER_PROJECT_TRANSPOSE.config.withOperandFor(Filter.class, filter -> !RexUtil.containsCorrelation(filter.getCondition()), Project.class, project -> true).withCopyFilter(false).withCopyProject(false).toRule());
    for (RelOptRule rule : rules) {
        RelBuilder b = RelBuilder.create(RelBuilderTest.config().build());
        RelNode in = b.scan("EMP").sort(// salary desc
        -4).project(// salary
        b.field(3)).filter(// salary = 11500
        b.equals(b.field(0), b.literal(11500))).build();
        HepProgram program = new HepProgramBuilder().addRuleInstance(rule).build();
        HepPlanner hepPlanner = new HepPlanner(program);
        hepPlanner.setRoot(in);
        RelNode result = hepPlanner.findBestExp();
        // Verify LogicalFilter traitSet (must be [3 DESC])
        RelNode filter = result.getInput(0);
        RelCollation collation = filter.getTraitSet().getTrait(RelCollationTraitDef.INSTANCE);
        assertNotNull(collation);
        List<RelFieldCollation> fieldCollations = collation.getFieldCollations();
        assertEquals(1, fieldCollations.size());
        RelFieldCollation fieldCollation = fieldCollations.get(0);
        assertEquals(3, fieldCollation.getFieldIndex());
        assertEquals(RelFieldCollation.Direction.DESCENDING, fieldCollation.getDirection());
    }
}

