/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3887">[CALCITE-3887]
 * Filter and Join conditions may not need to retain nullability during simplifications</a>.
 */
@Test
void testPushSemiJoinConditions() {
    final Function<RelBuilder, RelNode> relFn = b -> {
        RelNode left = b.scan("EMP").project(b.field("DEPTNO"), b.field("ENAME")).build();
        RelNode right = b.scan("DEPT").project(b.field("DEPTNO"), b.field("DNAME")).build();
        b.push(left).push(right);
        RexInputRef ref1 = b.field(2, 0, "DEPTNO");
        RexInputRef ref2 = b.field(2, 1, "DEPTNO");
        RexInputRef ref3 = b.field(2, 0, "ENAME");
        RexInputRef ref4 = b.field(2, 1, "DNAME");
        // ref1 IS NOT DISTINCT FROM ref2
        RexCall cond1 = (RexCall) b.call(SqlStdOperatorTable.OR, b.equals(ref1, ref2), b.call(SqlStdOperatorTable.AND, b.isNull(ref1), b.isNull(ref2)));
        // ref3 IS NOT DISTINCT FROM ref4
        RexCall cond2 = (RexCall) b.call(SqlStdOperatorTable.OR, b.equals(ref3, ref4), b.call(SqlStdOperatorTable.AND, b.isNull(ref3), b.isNull(ref4)));
        RexNode cond = b.and(cond1, cond2);
        return b.semiJoin(cond).project(b.field(0)).build();
    };
    relFn(relFn).withRule(CoreRules.JOIN_PUSH_EXPRESSIONS, CoreRules.SEMI_JOIN_PROJECT_TRANSPOSE, CoreRules.JOIN_REDUCE_EXPRESSIONS, CoreRules.FILTER_REDUCE_EXPRESSIONS).check();
}

