    final FilterJoinRule.FilterIntoJoinRule filterOnJoin = CoreRules.FILTER_INTO_JOIN.config.withSmart(true).withPredicate(predicate).as(FilterJoinRule.FilterIntoJoinRule.FilterIntoJoinRuleConfig.class).toRule();
    final HepProgram program = HepProgram.builder().addGroupBegin().addRuleInstance(CoreRules.FILTER_PROJECT_TRANSPOSE).addRuleInstance(join).addRuleInstance(filterOnJoin).addGroupEnd().build();
    final String sql = "select a.name\n" + "from dept a\n" + "left join dept b on b.deptno > 10\n" + "right join dept c on b.deptno > 10\n";
