@Test
void testPushFilterSemijoin() {
    final FilterJoinRule.Predicate predicate = (join, joinType, exp) -> joinType != JoinRelType.INNER;
    final FilterJoinRule.JoinConditionPushRule join = CoreRules.JOIN_CONDITION_PUSH.config.withPredicate(predicate).withDescription("FilterJoinRule:no-filter").as(FilterJoinRule.JoinConditionPushRule.JoinConditionPushRuleConfig.class).toRule();
    final Function<RelBuilder, RelNode> relFn = b -> {
        RelNode left = b.scan("DEPT").build();
