/**
 * Tests that an {@link EnumerableLimit} and {@link EnumerableSort} are
 * replaced by an {@link EnumerableLimitSort}, per
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3920">[CALCITE-3920]
 * Improve ORDER BY computation in Enumerable convention by exploiting
 * LIMIT</a>.
 */
@Test
void testLimitSort() {
    final String sql = "select mgr from sales.emp\n" + "union select mgr from sales.emp\n" + "order by mgr limit 10 offset 5";
    final RelOptFixture fixture = sql(sql).withVolcanoPlanner(false).withDecorrelate(true);
    RelNode rel = fixture.toRel();
    String planBefore = NL + RelOptUtil.toString(rel);
    final DiffRepository diffRepos = fixture.diffRepos;
    diffRepos.assertEquals("planBefore", "${planBefore}", planBefore);
    RuleSet ruleSet = RuleSets.ofList(EnumerableRules.ENUMERABLE_SORT_RULE, EnumerableRules.ENUMERABLE_LIMIT_RULE, EnumerableRules.ENUMERABLE_LIMIT_SORT_RULE, EnumerableRules.ENUMERABLE_PROJECT_RULE, EnumerableRules.ENUMERABLE_FILTER_RULE, EnumerableRules.ENUMERABLE_UNION_RULE, EnumerableRules.ENUMERABLE_TABLE_SCAN_RULE);
    Program program = Programs.of(ruleSet);
    RelTraitSet toTraits = rel.getCluster().traitSet().replace(0, EnumerableConvention.INSTANCE);
    RelNode relAfter = program.run(fixture.planner, rel, toTraits, Collections.emptyList(), Collections.emptyList());
    String planAfter = NL + RelOptUtil.toString(relAfter);
    diffRepos.assertEquals("planAfter", "${planAfter}", planAfter);
}

