/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4941">[CALCITE-4941]
 * SemiJoinRule loses hints</a>.
 */
@Test
void testSemiJoinRuleWithHint() {
    final RelHint noHashJoinHint = RelHint.builder("no_hash_join").build();
    final Function<RelBuilder, RelNode> relFn = b -> {
        b.getCluster().setHintStrategies(HintStrategyTable.builder().hintStrategy("no_hash_join", HintPredicates.JOIN).build());
        return b.scan("DEPT").scan("EMP").project(b.field("DEPTNO")).distinct().join(JoinRelType.INNER, b.equals(b.field(2, 0, "DEPTNO"), b.field(2, 1, "DEPTNO"))).hints(noHashJoinHint).project(b.field("DNAME")).build();
    };
    // verify plan
    relFn(relFn).withRule(CoreRules.PROJECT_TO_SEMI_JOIN).check();
    // verify hint
    final RelBuilder relBuilder = RelBuilder.create(RelBuilderTest.config().build());
    final RelNode input = relFn.apply(relBuilder);
    final HepProgram program = new HepProgramBuilder().addRuleInstance(CoreRules.PROJECT_TO_SEMI_JOIN).build();
    final HepPlanner hepPlanner = new HepPlanner(program);
    hepPlanner.setRoot(input);
    final RelNode output = hepPlanner.findBestExp();
    final Join join = (Join) output.getInput(0);
    assertTrue(join.getHints().contains(noHashJoinHint));
}

