/**
 * Similar to {@link #testJoinConditionPushdown1()} but semi join
 * from which more equality conditions can be inferred.
 */
@Test
void testJoinConditionPushdown4() {
    final Function<RelBuilder, RelNode> relFn = b -> {
        RelNode left = b.scan("EMP").project(b.field("DEPTNO"), b.field("ENAME")).build();
        RelNode right = b.scan("DEPT").project(b.field("DEPTNO"), b.field("DNAME")).build();
        b.push(left).push(right);
        RexInputRef ref1 = b.field(2, 0, "DEPTNO");
        RexInputRef ref2 = b.field(2, 1, "DEPTNO");
        RexInputRef ref3 = b.field(2, 1, "DNAME");
        RexCall cond1 = (RexCall) b.equals(ref1, ref2);
        RexCall cond2 = (RexCall) b.equals(ref1, ref3);
        RexNode cond = b.and(cond1, cond2);
        return b.semiJoin(cond).project(b.field(0)).build();
    };
    relFn(relFn).withRule(CoreRules.JOIN_PUSH_EXPRESSIONS, CoreRules.JOIN_CONDITION_PUSH, CoreRules.SEMI_JOIN_PROJECT_TRANSPOSE, CoreRules.JOIN_REDUCE_EXPRESSIONS, CoreRules.FILTER_REDUCE_EXPRESSIONS).check();
}

