@Test
void testReduceConstantsCalc() {
    // This reduction does not work using
    // ReduceExpressionsRule.PROJECT_INSTANCE or FILTER_INSTANCE,
    // only CALC_INSTANCE, because we need to pull the project expression
    //    upper('table')
    // into the condition
    //    upper('table') = 'TABLE'
    // and reduce it to TRUE. Only in the Calc are projects and conditions
    // combined.
    HepProgram program = new HepProgramBuilder().addRuleInstance(CoreRules.FILTER_PROJECT_TRANSPOSE).addRuleInstance(CoreRules.FILTER_SET_OP_TRANSPOSE).addRuleInstance(CoreRules.FILTER_TO_CALC).addRuleInstance(CoreRules.PROJECT_TO_CALC).addRuleInstance(CoreRules.CALC_MERGE).addRuleInstance(CoreRules.CALC_REDUCE_EXPRESSIONS).// the hard part is done... a few more rule calls to clean up
    addRuleInstance(PruneEmptyRules.UNION_INSTANCE).addRuleInstance(CoreRules.PROJECT_TO_CALC).addRuleInstance(CoreRules.CALC_MERGE).addRuleInstance(CoreRules.CALC_REDUCE_EXPRESSIONS).build();
    // Result should be same as typing
    //  SELECT * FROM (VALUES ('TABLE        ', 'T')) AS T(U, S)
    final String sql = "select * from (\n" + "  select upper(substring(x FROM 1 FOR 2) || substring(x FROM 3)) as u,\n" + "      substring(x FROM 1 FOR 1) as s\n" + "  from (\n" + "    select 'table' as x from (values (true))\n" + "    union\n" + "    select 'view' from (values (true))\n" + "    union\n" + "    select 'foreign table' from (values (true))\n" + "  )\n" + ") where u = 'TABLE'";
    sql(sql).withRelBuilderConfig(c -> c.withSimplifyValues(false)).withProgram(program).check();
}

