    //  SELECT sal, n
    //  FROM (SELECT sal, NDC() AS n FROM emp)
    //  WHERE n > 10
    final Function<RelBuilder, RelNode> relFn = b -> b.scan("EMP").project(b.field("SAL"), b.alias(b.call(nonDeterministicOp), "N")).filter(b.greaterThan(b.field("N"), b.literal(10))).build();
