@Test
void testReduceCaseWhenWithCast() {
    final Function<RelBuilder, RelNode> relFn = b -> {
        final RexBuilder rexBuilder = b.getRexBuilder();
        final RelDataType type = rexBuilder.getTypeFactory().createSqlType(SqlTypeName.BIGINT);
        RelNode left = b.values(new String[] { "x", "y" }, 1, 2).build();
        RexNode ref = rexBuilder.makeInputRef(left, 0);
        RexLiteral literal1 = rexBuilder.makeLiteral(1, type);
        RexLiteral literal2 = rexBuilder.makeLiteral(2, type);
        RexLiteral literal3 = rexBuilder.makeLiteral(3, type);
        // CASE WHEN x % 2 = 1 THEN x < 2
        //      WHEN x % 3 = 2 THEN x < 1
        //      ELSE x < 3
        final RexNode caseRexNode = rexBuilder.makeCall(SqlStdOperatorTable.CASE, rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, rexBuilder.makeCall(SqlStdOperatorTable.MOD, ref, literal2), literal1), rexBuilder.makeCall(SqlStdOperatorTable.LESS_THAN, ref, literal2), rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, rexBuilder.makeCall(SqlStdOperatorTable.MOD, ref, literal3), literal2), rexBuilder.makeCall(SqlStdOperatorTable.LESS_THAN, ref, literal1), rexBuilder.makeCall(SqlStdOperatorTable.LESS_THAN, ref, literal3));
        final RexNode castNode = rexBuilder.makeCast(rexBuilder.getTypeFactory().createTypeWithNullability(caseRexNode.getType(), true), caseRexNode);
        return b.push(left).project(castNode).build();
    };
    HepProgramBuilder builder = new HepProgramBuilder();
    builder.addRuleClass(ReduceExpressionsRule.class);
    HepPlanner hepPlanner = new HepPlanner(builder.build());
    hepPlanner.addRule(CoreRules.PROJECT_REDUCE_EXPRESSIONS);
    relFn(relFn).withPlanner(hepPlanner).checkUnchanged();
}

