    final AggregateExtractProjectRule rule = AggregateExtractProjectRule.SCAN.config.withOperandSupplier(b0 -> b0.operand(Aggregate.class).oneInput(b1 -> b1.operand(Project.class).predicate(new Predicate<Project>() {

