/**
 * Tests that ProjectAggregateMergeRule does nothing with non-numeric literals
 * and does not throw an exception.
 */
@Test
void testProjectAggregateMergeNonNumericLiteral() {
    // Requires a NULLABLE column to trigger
    final SqlTestFactory.CatalogReaderFactory catalogReaderFactory = (typeFactory, caseSensitive) -> new MockCatalogReader(typeFactory, caseSensitive) {

        @Override
        public MockCatalogReader init() {
            MockSchema schema = new MockSchema("SALES");
            registerSchema(schema);
            final boolean nullable = true;
            final RelDataType timestampType = typeFactory.createTypeWithNullability(typeFactory.createSqlType(SqlTypeName.TIMESTAMP), nullable);
            String tableName = "NULLABLE";
            MockTable table = MockTable.create(this, schema, tableName, false, 100);
            table.addColumn("HIREDATE", timestampType);
            registerTable(table);
            return this;
        }
    }.init();
    final String sql = "select hiredate, coalesce(hiredate, {ts '1969-12-31 00:00:00'}) as c1\n" + "from sales.nullable\n" + "group by hiredate";
    sql(sql).withCatalogReaderFactory(catalogReaderFactory).withRule(CoreRules.PROJECT_AGGREGATE_MERGE).checkUnchanged();
}

