/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3121">[CALCITE-3121]
 * VolcanoPlanner hangs due to sub-query with dynamic star</a>.
 */
@Test
void testSubQueryWithDynamicStarHang() {
    String sql = "select n.n_regionkey\n" + "from (select *\n" + "  from (select *\n" + "    from sales.customer) t) n\n" + "where n.n_nationkey > 1";
    PushProjector.ExprCondition exprCondition = expr -> {
        if (expr instanceof RexCall) {
            RexCall call = (RexCall) expr;
            return "item".equals(call.getOperator().getName().toLowerCase(Locale.ROOT));
        }
        return false;
    };
    RuleSet ruleSet = RuleSets.ofList(CoreRules.FILTER_PROJECT_TRANSPOSE, CoreRules.FILTER_MERGE, CoreRules.PROJECT_MERGE, ProjectFilterTransposeRule.Config.DEFAULT.withOperandFor(Project.class, Filter.class).withPreserveExprCondition(exprCondition).toRule(), EnumerableRules.ENUMERABLE_PROJECT_RULE, EnumerableRules.ENUMERABLE_FILTER_RULE, EnumerableRules.ENUMERABLE_SORT_RULE, EnumerableRules.ENUMERABLE_LIMIT_RULE, EnumerableRules.ENUMERABLE_TABLE_SCAN_RULE);
    Program program = Programs.of(ruleSet);
    sql(sql).withVolcanoPlanner(false).withDynamicTable().withDecorrelate(true).withAfter((fixture, r) -> {
        RelTraitSet toTraits = r.getCluster().traitSet().replace(0, EnumerableConvention.INSTANCE);
        return program.run(fixture.planner, r, toTraits, ImmutableList.of(), ImmutableList.of());
    }).check();
}

