@Test
void testIsNull() {
    final Fixture f = new Fixture();
    final RexNode sEqEn = f.eq(f.str, f.charLiteral("en"));
    final RexNode sIsNotNull = f.notNull(f.str);
    final RexNode sIsNull = f.isNull(f.str);
    final RexNode iEq5 = f.eq(f.i, f.literal(5));
    final RexNode iIsNull = f.isNull(f.i);
    final RexNode iIsNotNull = f.notNull(f.i);
    f.checkNotImplies(sIsNotNull, sIsNull);
    f.checkNotImplies(sIsNull, sIsNotNull);
    f.checkNotImplies(sEqEn, sIsNull);
    f.checkNotImplies(sIsNull, sEqEn);
    // "s = literal" implies "s is not null"
    f.checkImplies(sEqEn, sIsNotNull);
    // "s is not null" implies "s is not null"
    f.checkImplies(sIsNotNull, sIsNotNull);
    // "s is null" implies "s is null"
    f.checkImplies(sIsNull, sIsNull);
    // "s is not null and y = 5" implies "s is not null"
    f.checkImplies(f.and(sIsNotNull, iEq5), sIsNotNull);
    // "y = 5 and s is not null" implies "s is not null"
    f.checkImplies(f.and(iEq5, sIsNotNull), sIsNotNull);
    // "y is not null" does not imply "s is not null"
    f.checkNotImplies(iIsNull, sIsNotNull);
    // "s is not null or i = 5" does not imply "s is not null"
    f.checkNotImplies(f.or(sIsNotNull, iEq5), sIsNotNull);
    // "s is not null" implies "s is not null or i = 5"
    f.checkImplies(sIsNotNull, f.or(sIsNotNull, iEq5));
    // "s is not null" implies "i = 5 or s is not null"
    f.checkImplies(sIsNotNull, f.or(iEq5, sIsNotNull));
    // "i > 10" implies "x is not null"
    f.checkImplies(f.gt(f.i, f.literal(10)), iIsNotNull);
    // "-20 > i" implies "x is not null"
    f.checkImplies(f.gt(f.literal(-20), f.i), iIsNotNull);
    // "s is null and -20 > i" implies "x is not null"
    f.checkImplies(f.and(sIsNull, f.gt(f.literal(-20), f.i)), iIsNotNull);
    // "i > 10" does not imply "x is null"
    f.checkNotImplies(f.gt(f.i, f.literal(10)), iIsNull);
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-2041">[CALCITE-2041]
 * When simplifying a nullable expression, allow the result to change type to
 * NOT NULL</a> and match nullability.
 *
 * @see RexSimplify#simplifyPreservingType(RexNode, RexUnknownAs, boolean)
 */
@Test
void testSimplifyCastMatchNullability() {
    final Fixture f = new Fixture();
    // The cast is nullable, while the literal is not nullable. When we simplify
    // it, we end up with the literal. If defaultSimplifier is used, a CAST is
    // introduced on top of the expression, as nullability of the new expression
    // does not match the nullability of the original one. If
    // nonMatchingNullabilitySimplifier is used, the CAST is not added and the
    // simplified expression only consists of the literal.
    final RexNode e = f.cast(f.intRelDataType, f.literal(2014));
    assertThat(f.simplify.simplifyPreservingType(e, RexUnknownAs.UNKNOWN, true), hasToString("CAST(2014):JavaType(class java.lang.Integer)"));
    assertThat(f.simplify.simplifyPreservingType(e, RexUnknownAs.UNKNOWN, false), hasToString("2014"));
    // In this case, the cast is not nullable. Thus, in both cases, the
    // simplified expression only consists of the literal.
    RelDataType notNullIntRelDataType = f.typeFactory.createJavaType(int.class);
    final RexNode e2 = f.cast(notNullIntRelDataType, f.cast(notNullIntRelDataType, f.literal(2014)));
    assertThat(f.simplify.simplifyPreservingType(e2, RexUnknownAs.UNKNOWN, true), hasToString("2014"));
    assertThat(f.simplify.simplifyPreservingType(e2, RexUnknownAs.UNKNOWN, false), hasToString("2014"));
}

/**
 * Test case for simplifier of ceil/floor.
 */
@Test
void testSimplifyCeilFloor() {
    // We can add more time units here once they are supported in
    // RexInterpreter, e.g., TimeUnitRange.HOUR, TimeUnitRange.MINUTE,
    // TimeUnitRange.SECOND.
    final ImmutableList<TimeUnitRange> timeUnitRanges = ImmutableList.of(TimeUnitRange.YEAR, TimeUnitRange.MONTH);
    final Fixture f = new Fixture();
    final RexNode literalTs = f.timestampLiteral(new TimestampString("2010-10-10 00:00:00"));
    for (int i = 0; i < timeUnitRanges.size(); i++) {
        final RexNode innerFloorCall = f.rexBuilder.makeCall(SqlStdOperatorTable.FLOOR, literalTs, f.rexBuilder.makeFlag(timeUnitRanges.get(i)));
        final RexNode innerCeilCall = f.rexBuilder.makeCall(SqlStdOperatorTable.CEIL, literalTs, f.rexBuilder.makeFlag(timeUnitRanges.get(i)));
        for (int j = 0; j <= i; j++) {
            final RexNode outerFloorCall = f.rexBuilder.makeCall(SqlStdOperatorTable.FLOOR, innerFloorCall, f.rexBuilder.makeFlag(timeUnitRanges.get(j)));
            final RexNode outerCeilCall = f.rexBuilder.makeCall(SqlStdOperatorTable.CEIL, innerCeilCall, f.rexBuilder.makeFlag(timeUnitRanges.get(j)));
            final RexCall floorSimplifiedExpr = (RexCall) f.simplify.simplifyPreservingType(outerFloorCall, RexUnknownAs.UNKNOWN, true);
            assertThat(floorSimplifiedExpr.getKind(), is(SqlKind.FLOOR));
            assertThat(((RexLiteral) floorSimplifiedExpr.getOperands().get(1)).getValue(), hasToString(timeUnitRanges.get(j).toString()));
            assertThat(floorSimplifiedExpr.getOperands().get(0), hasToString(literalTs.toString()));
            final RexCall ceilSimplifiedExpr = (RexCall) f.simplify.simplifyPreservingType(outerCeilCall, RexUnknownAs.UNKNOWN, true);
            assertThat(ceilSimplifiedExpr.getKind(), is(SqlKind.CEIL));
            assertThat(((RexLiteral) ceilSimplifiedExpr.getOperands().get(1)).getValue(), hasToString(timeUnitRanges.get(j).toString()));
            assertThat(ceilSimplifiedExpr.getOperands().get(0), hasToString(literalTs.toString()));
        }
    }
    // Negative test
    for (int i = timeUnitRanges.size() - 1; i >= 0; i--) {
        final RexNode innerFloorCall = f.rexBuilder.makeCall(SqlStdOperatorTable.FLOOR, literalTs, f.rexBuilder.makeFlag(timeUnitRanges.get(i)));
        final RexNode innerCeilCall = f.rexBuilder.makeCall(SqlStdOperatorTable.CEIL, literalTs, f.rexBuilder.makeFlag(timeUnitRanges.get(i)));
        for (int j = timeUnitRanges.size() - 1; j > i; j--) {
            final RexNode outerFloorCall = f.rexBuilder.makeCall(SqlStdOperatorTable.FLOOR, innerFloorCall, f.rexBuilder.makeFlag(timeUnitRanges.get(j)));
            final RexNode outerCeilCall = f.rexBuilder.makeCall(SqlStdOperatorTable.CEIL, innerCeilCall, f.rexBuilder.makeFlag(timeUnitRanges.get(j)));
            final RexCall floorSimplifiedExpr = (RexCall) f.simplify.simplifyPreservingType(outerFloorCall, RexUnknownAs.UNKNOWN, true);
            assertThat(floorSimplifiedExpr, hasToString(outerFloorCall.toString()));
            final RexCall ceilSimplifiedExpr = (RexCall) f.simplify.simplifyPreservingType(outerCeilCall, RexUnknownAs.UNKNOWN, true);
            assertThat(ceilSimplifiedExpr, hasToString(outerCeilCall.toString()));
        }
    }
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3165">[CALCITE-3165]
 * Project#accept(RexShuttle shuttle) does not update rowType</a>.
 */
@Test
void testProjectUpdatesRowType() {
    final RelBuilder builder = RelBuilder.create(RelBuilderTest.config().build());
    // Equivalent SQL: SELECT deptno, sal FROM emp
    final RelNode root = builder.scan("EMP").project(builder.field("DEPTNO"), builder.field("SAL")).build();
    // Equivalent SQL: SELECT CAST(deptno AS VARCHAR), CAST(sal AS VARCHAR) FROM emp
    final RelNode rootWithCast = builder.scan("EMP").project(builder.cast(builder.field("DEPTNO"), SqlTypeName.VARCHAR), builder.cast(builder.field("SAL"), SqlTypeName.VARCHAR)).build();
    final RelDataType type = rootWithCast.getRowType();
    // Transform the first expression into the second one, by using a RexShuttle
    // that converts every RexInputRef into a 'CAST(RexInputRef AS VARCHAR)'
    final RelNode rootWithCastViaRexShuttle = root.accept(new RexShuttle() {

        @Override
        public RexNode visitInputRef(RexInputRef inputRef) {
            return builder.cast(inputRef, SqlTypeName.VARCHAR);
        }
    });
    final RelDataType type2 = rootWithCastViaRexShuttle.getRowType();
    assertThat(type, is(type2));
}

@Test
void testCalcUpdatesRowType() {
    final RelBuilder builder = RelBuilder.create(RelBuilderTest.config().build());
    // Equivalent SQL: SELECT deptno, sal, sal + 20 FROM emp
    final RelNode root = builder.scan("EMP").project(builder.field("DEPTNO"), builder.field("SAL"), builder.call(SqlStdOperatorTable.PLUS, builder.field("SAL"), builder.literal(20))).build();
    HepProgram program = new HepProgramBuilder().addRuleInstance(CoreRules.PROJECT_TO_CALC).build();
    HepPlanner planner = new HepPlanner(program);
    planner.setRoot(root);
    LogicalCalc calc = (LogicalCalc) planner.findBestExp();
    final RelNode calcWithCastViaRexShuttle = calc.accept(new RexShuttle() {

        @Override
        public RexNode visitCall(RexCall call) {
            return builder.cast(call, SqlTypeName.VARCHAR);
        }

        @Override
        public RexNode visitLocalRef(RexLocalRef localRef) {
            if (calc.getProgram().getExprList().get(localRef.getIndex()) instanceof RexCall) {
                return new RexLocalRef(localRef.getIndex(), builder.getTypeFactory().createSqlType(SqlTypeName.VARCHAR));
            } else {
                return localRef;
            }
        }
    });
    // Equivalent SQL: SELECT deptno, sal, CAST(sal + 20 AS VARCHAR) FROM emp
    final RelNode rootWithCast = builder.scan("EMP").project(builder.field("DEPTNO"), builder.field("SAL"), builder.cast(builder.call(SqlStdOperatorTable.PLUS, builder.field("SAL"), builder.literal(20)), SqlTypeName.VARCHAR)).build();
    assertThat(calcWithCastViaRexShuttle.getRowType(), is(rootWithCast.getRowType()));
}

