    assertThat(f.posixRegexSensitive("abc", "^a"), is(true));
    assertThat(f.posixRegexSensitive("abc", "(b|d)"), is(true));
    assertThat(f.posixRegexSensitive("abc", "^(b|c)"), is(false));
