void testConcatFunction() {
    // CONCAT is not in the library operator table
    final SqlValidatorFixture s = fixture().withOperatorTable(operatorTableFor(SqlLibrary.POSTGRESQL));
    s.withExpr("concat('a', 'b')").ok();
    s.withExpr("concat(x'12', x'34')").ok();
    s.withExpr("concat(_UTF16'a', _UTF16'b', _UTF16'c')").ok();
    s.withExpr("concat('aabbcc', 'ab', '+-')").columnType("VARCHAR(10) NOT NULL");
    s.withExpr("concat('aabbcc', CAST(NULL AS VARCHAR(20)), '+-')").columnType("VARCHAR(28) NOT NULL");
    s.withExpr("concat('aabbcc', 2)").withWhole(true).withTypeCoercion(false).fails("(?s)Cannot apply 'CONCAT' to arguments of type " + "'CONCAT\\(<CHAR\\(6\\)>, <INTEGER>\\)'\\. .*");
    s.withExpr("concat('aabbcc', 2)").ok();
    s.withExpr("concat('abc', 'ab', 123)").withWhole(true).withTypeCoercion(false).fails("(?s)Cannot apply 'CONCAT' to arguments of type " + "'CONCAT\\(<CHAR\\(3\\)>, <CHAR\\(2\\)>, <INTEGER>\\)'\\. .*");
    s.withExpr("concat('abc', 'ab', 123)").ok();
    s.withExpr("concat(true, false)").withWhole(true).withTypeCoercion(false).fails("(?s)Cannot apply 'CONCAT' to arguments of type " + "'CONCAT\\(<BOOLEAN>, <BOOLEAN>\\)'\\. .*");
    s.withExpr("concat(true, false)").ok();
    s.withExpr("concat(DATE '2020-04-17', TIMESTAMP '2020-04-17 14:17:51')").withWhole(true).withTypeCoercion(false).fails("(?s)Cannot apply 'CONCAT' to arguments of type " + "'CONCAT\\(<DATE>, <TIMESTAMP\\(0\\)>\\)'\\. .*");
    s.withExpr("concat(DATE '2020-04-17', TIMESTAMP '2020-04-17 14:17:51')").ok();
}

