@Test
void testRlike() {
    // RLIKE is supported for SPARK
    final SqlValidatorFixture s = fixture().withOperatorTable(operatorTableFor(SqlLibrary.SPARK));
    s.withExpr("'first_name' rlike '%Ted%'").columnType("BOOLEAN NOT NULL");
    s.withExpr("'first_name' rlike '^M+'").columnType("BOOLEAN NOT NULL");
    // RLIKE is only supported for Spark and Hive
    String noMatch = "(?s).*No match found for function signature RLIKE";
    expr("^'b' rlike '.+@.+\\\\..+'^").fails(noMatch).withOperatorTable(operatorTableFor(SqlLibrary.POSTGRESQL)).fails(noMatch).withOperatorTable(operatorTableFor(SqlLibrary.SPARK)).columnType("BOOLEAN NOT NULL").withOperatorTable(operatorTableFor(SqlLibrary.HIVE)).columnType("BOOLEAN NOT NULL");
}

