@Test
void testTimestampAddAndDiff() {
    List<String> tsi = ImmutableList.<String>builder().add("FRAC_SECOND").add("MICROSECOND").add("MINUTE").add("HOUR").add("DAY").add("WEEK").add("MONTH").add("QUARTER").add("YEAR").add("SQL_TSI_FRAC_SECOND").add("SQL_TSI_MICROSECOND").add("SQL_TSI_MINUTE").add("SQL_TSI_HOUR").add("SQL_TSI_DAY").add("SQL_TSI_WEEK").add("SQL_TSI_MONTH").add("SQL_TSI_QUARTER").add("SQL_TSI_YEAR").build();
    List<String> functions = ImmutableList.<String>builder().add("timestampadd(%s, 12, current_timestamp)").add("timestampdiff(%s, current_timestamp, current_timestamp)").build();
    for (String interval : tsi) {
        for (String function : functions) {
            expr(String.format(Locale.ROOT, function, interval)).ok();
        }
    }
    expr("timestampadd(SQL_TSI_WEEK, 2, current_timestamp)").columnType("TIMESTAMP(0) NOT NULL");
    expr("timestampadd(SQL_TSI_WEEK, 2, cast(null as timestamp))").columnType("TIMESTAMP(0)");
    expr("timestampdiff(SQL_TSI_WEEK, current_timestamp, current_timestamp)").columnType("INTEGER NOT NULL");
    expr("timestampdiff(SQL_TSI_WEEK, cast(null as timestamp), current_timestamp)").columnType("INTEGER");
    expr("timestampadd(^incorrect^, 1, current_timestamp)").fails("'INCORRECT' is not a valid time frame");
    expr("timestampdiff(^incorrect^, current_timestamp, current_timestamp)").fails("'INCORRECT' is not a valid time frame");
}

