/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-820">[CALCITE-820]
 * Validate that window functions have OVER clause</a>, and
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1340">[CALCITE-1340]
 * Window aggregates give invalid errors</a>.
 */
@Test
void testWindowFunctionsWithoutOver() {
    winSql("select sum(empno)\n" + "from emp\n" + "group by deptno\n" + "order by ^row_number()^").fails("OVER clause is necessary for window functions");
    winSql("select ^rank()^\n" + "from emp").fails("OVER clause is necessary for window functions");
    // With [CALCITE-1340], the validator would see RANK without OVER,
    // mistakenly think this is an aggregating query, and wrongly complain
    // about the PARTITION BY: "Expression 'DEPTNO' is not being grouped"
    winSql("select cume_dist() over w , ^rank()^\n" + "from emp\n" + "window w as (partition by deptno order by deptno)").fails("OVER clause is necessary for window functions");
    winSql("select ^nth_value(sal, 2)^\n" + "from emp").fails("OVER clause is necessary for window functions");
}

