void testOverInPartitionBy() {
    winSql("select sum(deptno) over ^(partition by sum(deptno)\n" + "over(order by deptno))^ from emp").fails("PARTITION BY expression should not contain OVER clause");
    winSql("select sum(deptno) over w\n" + "from emp\n" + "window w as ^(partition by sum(deptno) over(order by deptno))^").fails("PARTITION BY expression should not contain OVER clause");
}

@Test
void testOverInOrderBy() {
    winSql("select sum(deptno) over ^(order by sum(deptno)\n" + "over(order by deptno))^ from emp").fails("ORDER BY expression should not contain OVER clause");
    winSql("select sum(deptno) over w\n" + "from emp\n" + "window w as ^(order by sum(deptno) over(order by deptno))^").fails("ORDER BY expression should not contain OVER clause");
}

