@Test
void testWindowFunctions() {
    // SQL 03 Section 6.10
    // Window functions may only appear in the <select list> of a
    // <query specification> or <select statement: single row>,
    // or the <order by clause> of a simple table query.
    // See 4.15.3 for detail
    winSql("select *\n" + " from emp\n" + " where ^sum(sal) over (partition by deptno\n" + "    order by empno\n" + "    rows 3 preceding)^ > 10").fails("Windowed aggregate expression is illegal in WHERE clause");
    winSql("select *\n" + " from emp\n" + " group by ename, ^sum(sal) over (partition by deptno\n" + "    order by empno\n" + "    rows 3 preceding)^ + 10\n" + "order by deptno").fails("Windowed aggregate expression is illegal in GROUP BY clause");
    winSql("select *\n" + " from emp\n" + " join dept on emp.deptno = dept.deptno\n" + " and ^sum(sal) over (partition by emp.deptno\n" + "    order by empno\n" + "    rows 3 preceding)^ = dept.deptno + 40\n" + "order by deptno").fails("Windowed aggregate expression is illegal in ON clause");
    // rule 3, a)
    winSql("select sal from emp\n" + "order by sum(sal) over (partition by deptno order by deptno)").ok();
    // scope reference
    // rule 4,
    // valid window functions
    winExp("sum(sal)").ok();
}

@Test
void testWindowFunctions2() {
    List<String> defined = asList("CUME_DIST", "DENSE_RANK", "PERCENT_RANK", "RANK", "ROW_NUMBER");
    if (Bug.TODO_FIXED) {
        sql("select rank() over (order by deptno) from emp").columnType("INTEGER NOT NULL");
    }
    winSql("select rank() over w from emp\n" + "window w as ^(partition by sal)^, w2 as (w order by deptno)").fails(RANK_REQUIRES_ORDER_BY);
    winSql("select rank() over w2 from emp\n" + "window w as (partition by sal), w2 as (w order by deptno)").ok();
    // row_number function
    winExp("row_number() over (order by deptno)").ok();
    winExp("row_number() over (partition by deptno)").ok();
    winExp("row_number() over ()").ok();
    winExp("row_number() over (order by deptno ^rows^ 2 preceding)").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
    winExp("row_number() over (order by deptno ^range^ 2 preceding)").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
    // rank function type
    if (defined.contains("DENSE_RANK")) {
        winExp("^dense_rank()^").fails("OVER clause is necessary for window functions");
    } else {
        checkWinFuncExpWithWinClause("^dense_rank()^", "Function 'DENSE_RANK\\(\\)' is not defined");
    }
    winExp("rank() over (order by empno)").ok();
    winExp("percent_rank() over (order by empno)").ok();
    winExp("cume_dist() over (order by empno)").ok();
    winExp("nth_value(sal, 2) over (order by empno)").ok();
    // rule 6a
    // ORDER BY required with RANK & DENSE_RANK
    winSql("select rank() over ^(partition by deptno)^ from emp").fails(RANK_REQUIRES_ORDER_BY);
    winSql("select dense_rank() over ^(partition by deptno)^ from emp ").fails(RANK_REQUIRES_ORDER_BY);
    winSql("select rank() over w from emp window w as ^(partition by deptno)^").fails(RANK_REQUIRES_ORDER_BY);
    winSql("select dense_rank() over w from emp\n" + "window w as ^(partition by deptno)^").fails(RANK_REQUIRES_ORDER_BY);
    // rule 6b
    // Framing not allowed with RANK & DENSE_RANK functions
    // window framing defined in window clause
    winSql("select rank() over w from emp\n" + "window w as (order by empno ^rows^ 2 preceding )").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
    winSql("select dense_rank() over w from emp\n" + "window w as (order by empno ^rows^ 2 preceding)").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
    if (defined.contains("PERCENT_RANK")) {
        winSql("select percent_rank() over w from emp\n" + "window w as (order by empno)").ok();
        winSql("select percent_rank() over w from emp\n" + "window w as (order by empno ^rows^ 2 preceding)").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
        winSql("select percent_rank() over w from emp\n" + "window w as ^(partition by empno)^").fails(RANK_REQUIRES_ORDER_BY);
    } else {
        checkWinFuncExpWithWinClause("^percent_rank()^", "Function 'PERCENT_RANK\\(\\)' is not defined");
    }
    if (defined.contains("CUME_DIST")) {
        winSql("select cume_dist() over w from emp\n" + "window w as ^(rows 2 preceding)^").fails(RANK_REQUIRES_ORDER_BY);
        winSql("select cume_dist() over w from emp\n" + "window w as (order by empno ^rows^ 2 preceding)").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
        winSql("select cume_dist() over w from emp window w as (order by empno)").ok();
        winSql("select cume_dist() over (order by empno) from emp ").ok();
    } else {
        checkWinFuncExpWithWinClause("^cume_dist()^", "Function 'CUME_DIST\\(\\)' is not defined");
    }
    // window framing defined in in-line window
    winSql("select rank() over (order by empno ^range^ 2 preceding ) from emp ").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
    winSql("select dense_rank() over (order by empno ^rows^ 2 preceding ) from emp ").fails(ROW_RANGE_NOT_ALLOWED_WITH_RANK);
    if (defined.contains("PERCENT_RANK")) {
        winSql("select percent_rank() over (order by empno) from emp").ok();
    }
    // invalid column reference
    checkWinFuncExpWithWinClause("sum(^invalidColumn^)", "Column 'INVALIDCOLUMN' not found in any table");
    // invalid window functions
    checkWinFuncExpWithWinClause("^invalidFun(sal)^", "No match found for function signature INVALIDFUN\\(<NUMERIC>\\)");
    // 6.10 rule 10. no distinct allowed aggregate function
    // Fails in parser.
    // checkWinFuncExpWithWinClause(" sum(distinct sal) over w ", null);
    // 7.11 rule 10c
    winSql("select sum(sal) over (w partition by ^deptno^)\n" + " from emp window w as (order by empno rows 2 preceding )").fails("PARTITION BY not allowed with existing window reference");
    // 7.11 rule 10d
    winSql("select sum(sal) over (w order by ^empno^)\n" + " from emp window w as (order by empno rows 2 preceding )").fails("ORDER BY not allowed in both base and referenced windows");
    // 7.11 rule 10e
    winSql("select sum(sal) over (w)\n" + " from emp window w as (order by empno ^rows^ 2 preceding )").fails("Referenced window cannot have framing declarations");
    // Empty window is OK for functions that don't require ordering.
    winSql("select sum(sal) over () from emp").ok();
    winSql("select sum(sal) over w from emp window w as ()").ok();
    winSql("select count(*) over () from emp").ok();
    winSql("select count(*) over w from emp window w as ()").ok();
    winSql("select rank() over ^()^ from emp").fails(RANK_REQUIRES_ORDER_BY);
    winSql("select rank() over w from emp window w as ^()^").fails(RANK_REQUIRES_ORDER_BY);
}

