@Test
void testLeftOuterJoinWithAlias() {
    final String query = "select *\n" + "from (select row_number() over (order by sal) from emp) as emp1(r1)\n" + "left outer join\n" + "(select  dense_rank() over(order by sal) from emp) as emp2(r2)\n" + "on (emp1.r1 = emp2.r2)";
    // In this case, R2 is nullable in the join since we have a left outer join.
    final String type = "RecordType(BIGINT NOT NULL R1, BIGINT R2) NOT NULL";
    sql(query).type(type);
    // Similar query, without "AS t(c)"
    final String query2 = "select *\n" + "from (select row_number() over (order by sal) as r1 from emp) as emp1\n" + "left outer join\n" + "(select dense_rank() over(order by sal) as r2 from emp) as emp2\n" + "on (emp1.r1 = emp2.r2)";
    sql(query2).type(type);
    // Similar query, without "AS t"
    final String query3 = "select *\n" + "from (select row_number() over (order by sal) as r1 from emp)\n" + "left outer join\n" + "(select dense_rank() over(order by sal) as r2 from emp)\n" + "on r1 = r2";
