@Test
void testNameResolutionInValuesClause() {
    final String emps = "(select 1 as empno, 'x' as name, 10 as deptno, 'M' as gender, 'San Francisco' as city, 30 as empid, 25 as age from (values (1)))";
    final String depts = "(select 10 as deptno, 'Sales' as name from (values (1)))";
    sql("select * from " + emps + " join " + depts + "\n" + " on ^emps^.deptno = deptno").fails("Table 'EMPS' not found");
    // this is ok
    sql("select * from " + emps + " as e\n" + " join " + depts + " as d\n" + " on e.deptno = d.deptno").ok();
    // fail: ambiguous column in WHERE
    sql("select * from " + emps + " as emps,\n" + " " + depts + "\n" + "where ^deptno^ > 5").fails("Column 'DEPTNO' is ambiguous");
    // fail: ambiguous column reference in ON clause
    sql("select * from " + emps + " as e\n" + " join " + depts + " as d\n" + " on e.deptno = ^deptno^").fails("Column 'DEPTNO' is ambiguous");
    // ok: column 'age' is unambiguous
    sql("select * from " + emps + " as e\n" + " join " + depts + " as d\n" + " on e.deptno = age").ok();
    // ok: reference to derived column
    sql("select * from " + depts + "\n" + " join (select mod(age, 30) as agemod from " + emps + ")\n" + "on deptno = agemod").ok();
    // fail: deptno is ambiguous
    sql("select name from " + depts + "\n" + "join (select mod(age, 30) as agemod, deptno from " + emps + ")\n" + "on ^deptno^ = agemod").fails("Column 'DEPTNO' is ambiguous");
    // fail: lateral reference
    sql("select * from " + emps + " as e,\n" + " (select 1, ^e^.deptno from (values(true))) as d").fails("Table 'E' not found");
    // fail: deptno is ambiguous
    sql("select ^deptno^, name from " + depts + "as d\n" + "join " + emps + "as e\n" + "on d.deptno = e.deptno").fails("Column 'DEPTNO' is ambiguous");
}

