/**
 * Unit test for
 * {@link org.apache.calcite.sql.validate.SqlValidatorUtil#rollup}.
 */
@Test
void testRollupBitSets() {
    assertThat(rollup(ImmutableBitSet.of(1), ImmutableBitSet.of(3)), hasToString("[{1, 3}, {1}, {}]"));
    assertThat(rollup(ImmutableBitSet.of(1), ImmutableBitSet.of(3, 4)), hasToString("[{1, 3, 4}, {1}, {}]"));
    assertThat(rollup(ImmutableBitSet.of(1, 3), ImmutableBitSet.of(4)), hasToString("[{1, 3, 4}, {1, 3}, {}]"));
    assertThat(rollup(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3)), hasToString("[{1, 3, 4}, {1, 4}, {}]"));
    // non-disjoint bit sets
    assertThat(rollup(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3, 4)), hasToString("[{1, 3, 4}, {1, 4}, {}]"));
    // some bit sets are empty
    assertThat(rollup(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(), ImmutableBitSet.of(3, 4), ImmutableBitSet.of()), hasToString("[{1, 3, 4}, {1, 4}, {}]"));
    assertThat(rollup(ImmutableBitSet.of(1)), hasToString("[{1}, {}]"));
    // one empty bit set
    assertThat(rollup(ImmutableBitSet.of()), hasToString("[{}]"));
    // no bit sets
    assertThat(rollup(), hasToString("[{}]"));
}

/**
 * Unit test for
 * {@link org.apache.calcite.sql.validate.SqlValidatorUtil#cube}.
 */
@Test
void testCubeBitSets() {
    assertThat(cube(ImmutableBitSet.of(1), ImmutableBitSet.of(3)), hasToString("[{1, 3}, {1}, {3}, {}]"));
    assertThat(cube(ImmutableBitSet.of(1), ImmutableBitSet.of(3, 4)), hasToString("[{1, 3, 4}, {1}, {3, 4}, {}]"));
    assertThat(cube(ImmutableBitSet.of(1, 3), ImmutableBitSet.of(4)), hasToString("[{1, 3, 4}, {1, 3}, {4}, {}]"));
    assertThat(cube(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3)), hasToString("[{1, 3, 4}, {1, 4}, {3}, {}]"));
    // non-disjoint bit sets
    assertThat(cube(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3, 4)), hasToString("[{1, 3, 4}, {1, 4}, {3, 4}, {}]"));
    // some bit sets are empty, and there are duplicates
    assertThat(cube(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(), ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3, 4), ImmutableBitSet.of()), hasToString("[{1, 3, 4}, {1, 4}, {3, 4}, {}]"));
    assertThat(cube(ImmutableBitSet.of(1)), hasToString("[{1}, {}]"));
    assertThat(cube(ImmutableBitSet.of()), hasToString("[{}]"));
    assertThat(cube(), hasToString("[{}]"));
}

@Test
void testGrouping() {
    sql("select deptno, grouping(deptno) from emp group by deptno").ok();
    sql("select deptno, grouping(deptno, deptno) from emp group by deptno").ok();
    sql("select deptno / 2, grouping(deptno / 2),\n" + " ^grouping(deptno / 2, empno)^\n" + "from emp group by deptno / 2, empno").ok();
    sql("select deptno, grouping(^empno^) from emp group by deptno").fails("Argument to GROUPING operator must be a grouped expression");
    sql("select deptno, grouping(deptno, ^empno^) from emp group by deptno").fails("Argument to GROUPING operator must be a grouped expression");
    sql("select deptno, grouping(^empno^, deptno) from emp group by deptno").fails("Argument to GROUPING operator must be a grouped expression");
    sql("select deptno, grouping(^deptno + 1^) from emp group by deptno").fails("Argument to GROUPING operator must be a grouped expression");
    sql("select deptno, grouping(emp.^xxx^) from emp").fails("Column 'XXX' not found in table 'EMP'");
    sql("select deptno, ^grouping(deptno)^ from emp").fails("GROUPING operator may only occur in an aggregate query");
    sql("select deptno, sum(^grouping(deptno)^) over () from emp").fails("GROUPING operator may only occur in an aggregate query");
    sql("select deptno from emp group by deptno having grouping(deptno) < 5").ok();
    sql("select deptno from emp group by deptno order by grouping(deptno)").ok();
    sql("select deptno as xx from emp group by deptno order by grouping(xx)").ok();
    sql("select deptno as empno from emp\n" + "group by deptno order by grouping(empno)").ok();
    sql("select 1 as deptno from emp\n" + "group by deptno order by grouping(^deptno^)").fails("Argument to GROUPING operator must be a grouped expression");
    sql("select deptno from emp group by deptno order by grouping(emp.deptno)").ok();
    sql("select ^deptno^ from emp group by empno order by grouping(deptno)").fails("Expression 'DEPTNO' is not being grouped");
    sql("select deptno from emp order by ^grouping(deptno)^").fails("GROUPING operator may only occur in an aggregate query");
    sql("select deptno from emp where ^grouping(deptno)^ = 1").fails("GROUPING operator may only occur in an aggregate query");
    sql("select deptno from emp where ^grouping(deptno)^ = 1 group by deptno").fails("GROUPING operator may only occur in SELECT, HAVING or ORDER BY clause");
    sql("select deptno from emp group by deptno, ^grouping(deptno)^").fails("GROUPING operator may only occur in SELECT, HAVING or ORDER BY clause");
    sql("select deptno from emp\n" + "group by grouping sets(deptno, ^grouping(deptno)^)").fails("GROUPING operator may only occur in SELECT, HAVING or ORDER BY clause");
    sql("select deptno from emp\n" + "group by cube(empno, ^grouping(deptno)^)").fails("GROUPING operator may only occur in SELECT, HAVING or ORDER BY clause");
    sql("select deptno from emp\n" + "group by rollup(empno, ^grouping(deptno)^)").fails("GROUPING operator may only occur in SELECT, HAVING or ORDER BY clause");
}

