@Test
void testJoinUsing() {
    final String empDeptType = "RecordType(INTEGER NOT NULL DEPTNO," + " INTEGER NOT NULL EMPNO," + " VARCHAR(20) NOT NULL ENAME," + " VARCHAR(10) NOT NULL JOB," + " INTEGER MGR," + " TIMESTAMP(0) NOT NULL HIREDATE," + " INTEGER NOT NULL SAL," + " INTEGER NOT NULL COMM," + " BOOLEAN NOT NULL SLACKER," + " VARCHAR(10) NOT NULL NAME) NOT NULL";
    sql("select * from emp join dept using (deptno)").ok().type(empDeptType);
    // NATURAL has same effect as USING
    sql("select * from emp natural join dept").ok().type(empDeptType);
    // fail: comm exists on one side not the other
    // todo: The error message could be improved.
    sql("select * from emp join dept using (deptno, ^comm^)").fails("Column 'COMM' not found in any table");
    sql("select * from emp join dept using (^empno^)").fails("Column 'EMPNO' not found in any table");
