/**
 * Tests the {@code QUALIFY} clause.
 */
@Test
void testQualifyPositive() {
    final SqlValidatorFixture f = fixture().withConformance(SqlConformanceEnum.LENIENT);
    final String qualifyWithoutAlias = "SELECT
" + "empno, ename
" + "FROM emp
" + "QUALIFY ROW_NUMBER() over (partition by ename order by deptno) = 1";
    f.withSql(qualifyWithoutAlias).ok();
    final String qualifyWithAlias = "SELECT empno, ename, deptno,
" + "   ROW_NUMBER() over (partition by ename order by deptno) as row_num
" + "FROM emp
" + "QUALIFY row_num = 1";
    f.withSql(qualifyWithAlias).ok();
    final String qualifyWithWindowClause = "SELECT empno, ename,
" + " SUM(deptno) OVER myWindow as sumDeptNo
" + "FROM emp
" + "WINDOW myWindow AS (PARTITION BY ename ORDER BY empno)
" + "QUALIFY sumDeptNo = 1";
    f.withSql(qualifyWithWindowClause).ok();
    final String qualifyWithEverything = "SELECT DISTINCT empno, ename, deptno,
" + "    RANK() OVER (PARTITION BY ename ORDER BY deptno DESC) as rank_val
" + "FROM emp
" + "WHERE sal > 1000
" + "QUALIFY rank_val = (SELECT COUNT(*) FROM emp)
" + "ORDER BY deptno
" + "LIMIT 5";
    f.withSql(qualifyWithEverything).ok();
    final String qualifyReferencingCommonColumnInJoin = "SELECT * 
" + "FROM emp
" + "NATURAL JOIN dept
" + "QUALIFY ROW_NUMBER() over (partition by ename order by emp.deptno) = 1";
    f.withSql(qualifyReferencingCommonColumnInJoin).ok();
    final String qualifyOnMultipleWindowFunctions = "SELECT" + "   AVG(deptno) OVER (PARTITION BY ename) avgDeptNo," + "   RANK() OVER (PARTITION BY deptno ORDER BY ename) as myRank
" + "FROM emp
" + "QUALIFY avgDeptNo = 1 AND myRank = 1";
    f.withSql(qualifyOnMultipleWindowFunctions).ok();
}

/**
 * Negative tests for the {@code QUALIFY} clause.
 */
@Test
void testQualifyNegative() {
    final SqlValidatorFixture f = fixture().withConformance(SqlConformanceEnum.LENIENT);
    // The predicate in the QUALIFY clause expression must be a boolean, since
    // we use it as a filter.
    final String qualifyWithNonBooleanExpression = "SELECT\n" + "empno, ename\n" + "FROM emp\n" + "QUALIFY ^1 + 1^";
    f.withSql(qualifyWithNonBooleanExpression).fails("QUALIFY clause must be a condition");
    // We don't allow for using ordinal column references in QUALIFY.
    final String qualifyWithOrdinal = "SELECT\n" + "empno, ename, ROW_NUMBER() over (partition by ename order by deptno) = 1\n" + "FROM emp\n" + "QUALIFY ^3^";
    f.withSql(qualifyWithOrdinal).fails("QUALIFY clause must be a condition");
    // 'deptno' is a common column in both the emp and dept table.
    // We need to use emp.deptno or dept.deptno to make it unambiguous
    final String qualifyReferencingAmbiguousCommonColumnInJoin = "SELECT *\n" + "FROM emp\n" + "NATURAL JOIN dept\n" + "QUALIFY ROW_NUMBER() over (partition by ename order by ^deptno^) = 1";
    f.withSql(qualifyReferencingAmbiguousCommonColumnInJoin).fails("Column 'DEPTNO' is ambiguous");
    // Qualify must contain a window function. This matches the behavior where
    // HAVING needs to have an aggregate or reference a group column.
    final String qualifyOnNonWindowFunction = "SELECT * \n" + "FROM emp\n" + "QUALIFY ^SUM(deptno) = 1^";
    f.withSql(qualifyOnNonWindowFunction).fails("QUALIFY expression 'SUM\\(`EMP`\\.`DEPTNO`\\) = 1' " + "must contain a window function");
    final String qualifyOnAliasedNonWindowFunction = "" + "SELECT ^SUM(deptno) as sumDeptNo\n" + "FROM emp\n" + "QUALIFY sumDeptNo = 1^";
    f.withSql(qualifyOnAliasedNonWindowFunction).fails("QUALIFY expression 'SUM\\(`EMP`\\.`DEPTNO`\\) = 1' " + "must contain a window function");
    // This query fails, since it's a mix of regular aggregates and window
    // functions. This query needs to fail, since we assume that qualify filters
    // on the result of a window function in SqlToRelConverter and that the
    // input Rel is a LogicalProject and not a LogicalAggregate.
    final String mixedNonAggregateAndWindowAggregate = "SELECT\n" + "   SUM(deptno) as sumDeptNo, " + "   RANK() OVER (PARTITION BY ^ename^ ORDER BY deptno) myRank\n" + "FROM emp\n";
    f.withSql(mixedNonAggregateAndWindowAggregate).fails("Expression 'ENAME' is not being grouped");
}

/**
 * Tests the {@code WITH} clause, also called common table expressions.
 */
@Test
void testWith() {
    // simplest possible
    sql("with emp2 as (select * from emp)\n" + "select * from emp2").type(EMP_RECORD_TYPE);
    // degree of emp2 column list does not match its query
    sql("with emp2 ^(x, y)^ as (select * from emp)\n" + "select * from emp2").fails("Number of columns must match number of query columns");
    // duplicate names in column list
    sql("with emp2 (x, y, ^y^, x) as (select sal, deptno, ename, empno from emp)\n" + "select * from emp2").fails("Duplicate name 'Y' in column list");
    // column list required if aliases are not unique
    sql("with emp2 as (^select empno as e, sal, deptno as e from emp^)\n" + "select * from emp2").fails("Column has duplicate column name 'E' and no column list specified");
    // forward reference
    sql("with emp3 as (select * from ^emp2^),\n" + " emp2 as (select * from emp)\n" + "select * from emp3").fails("Object 'EMP2' not found");
    // forward reference in with-item not used; should still fail
    sql("with emp3 as (select * from ^emp2^),\n" + " emp2 as (select * from emp)\n" + "select * from emp2").fails("Object 'EMP2' not found");
    // table not used is ok
    sql("with emp2 as (select * from emp),\n" + " emp3 as (select * from emp2)\n" + "select * from emp2").type(EMP_RECORD_TYPE);
    // self-reference is not ok, even in table not used
    sql("with emp2 as (select * from emp),\n" + " emp3 as (select * from ^emp3^)\n" + "values (1)").fails("Object 'EMP3' not found");
    // self-reference not ok
    sql("with emp2 as (select * from ^emp2^)\n" + "select * from emp2 where false").fails("Object 'EMP2' not found");
    // refer to 2 previous tables, not just immediately preceding
    sql("with emp2 as (select * from emp),\n" + " dept2 as (select * from dept),\n" + " empDept as (select emp2.empno, dept2.deptno from dept2 join emp2 using (deptno))\n" + "select 1 as uno from empDept").type("RecordType(INTEGER NOT NULL UNO) NOT NULL");
}

