/**
 * Tests the {@code WITH} clause in sub-queries.
 */
@Test
void testWithSubQuery() {
    // nested WITH (parentheses required - and even with parentheses SQL
    // standard doesn't allow sub-query to have WITH)
    sql("with emp2 as (select * from emp)
" + "(
" + "  with dept2 as (select * from dept)
" + "  (
" + "    with empDept as (select emp2.empno, dept2.deptno from dept2 join emp2 using (deptno))
" + "    select 1 as uno from empDept))").type("RecordType(INTEGER NOT NULL UNO) NOT NULL");
    // WITH inside WHERE can see enclosing tables
    sql("select * from emp
" + "where exists (
" + "  with dept2 as (select * from dept where dept.deptno >= emp.deptno)
" + "  select 1 from dept2 where deptno <= emp.deptno)").type(EMP_RECORD_TYPE);
    // WITH inside FROM cannot see enclosing tables
    sql("select * from emp
" + "join (
" + "  with dept2 as (select * from dept where dept.deptno >= ^emp^.deptno)
" + "  select * from dept2) as d on true").fails("Table 'EMP' not found");
    // as above, using USING
    sql("select * from emp
" + "join (
" + "  with dept2 as (select * from dept where dept.deptno >= ^emp^.deptno)
" + "  select * from dept2) as d using (deptno)").fails("Table 'EMP' not found");
    // WITH inside FROM
    sql("select e.empno, d.* from emp as e
" + "join (
" + "  with dept2 as (select * from dept where dept.deptno > 10)
" + "  select deptno, 1 as uno from dept2) as d using (deptno)").type("RecordType(INTEGER NOT NULL EMPNO," + " INTEGER NOT NULL DEPTNO," + " INTEGER NOT NULL UNO) NOT NULL");
    sql("select ^e^.empno, d.* from emp
" + "join (
" + "  with dept2 as (select * from dept where dept.deptno > 10)
" + "  select deptno, 1 as uno from dept2) as d using (deptno)").fails("Table 'E' not found");
}

