    sql("select * from (values 1) where 1 ^!=^ any (2, 3)").withConformance(custom).ok().withConformance(SqlConformanceEnum.DEFAULT).fails("Bang equal '!=' is not allowed under the current SQL conformance level").withConformance(SqlConformanceEnum.ORACLE_10).ok();
}

@Test
void testOrder() {
    final SqlConformance conformance = fixture().conformance();
    sql("select empno as x from emp order by empno").ok();
    // invalid use of 'asc'
    sql("select empno, sal from emp order by ^asc^").fails("Column 'ASC' not found in any table");
    // In sql92, empno is obscured by the alias.
    // Otherwise valid.
    // Checked Oracle10G -- is it valid.
    sql("select empno as x from emp order by empno").failsIf(conformance.isSortByAliasObscures(), "unknown column empno");
    // valid in oracle and pre-99 sql,
    // invalid in sql:2003
    sql("select empno as x from emp order by ^x^").failsIf(!conformance.isSortByAlias(), "Column 'X' not found in any table");
    // invalid in oracle and pre-99;
    // valid from sql:99 onwards (but sorting by constant achieves
    // nothing!)
    sql("select empno as x from emp order by ^10^").failsIf(conformance.isSortByOrdinal(), "Ordinal out of range");
    // Has different meanings in different dialects (which makes it very
    // confusing!) but is always valid.
    sql("select empno + 1 as empno from emp order by empno").ok();
    // Always fails
    sql("select empno as x from emp, dept order by ^deptno^").fails("Column 'DEPTNO' is ambiguous");
    sql("select empno + 1 from emp order by deptno asc, empno + 1 desc").ok();
    // Alias 'deptno' is closer in scope than 'emp.deptno'
    // and 'dept.deptno', and is therefore not ambiguous.
    // Checked Oracle10G -- it is valid.
    // Ambiguous in SQL:2003
    sql("select empno as deptno from emp, dept order by deptno").failsIf(!conformance.isSortByAlias(), "col ambig");
    sql("select deptno from dept\n" + "union\n" + "select empno from emp\n" + "order by deptno").ok();
    sql("select deptno from dept\n" + "union\n" + "select empno from emp\n" + "order by ^empno^").fails("Column 'EMPNO' not found in any table");
    // invalid in oracle and pre-99
    sql("select deptno from dept\n" + "union\n" + "select empno from emp\n" + "order by ^10^").failsIf(conformance.isSortByOrdinal(), "Ordinal out of range");
    // Sort by scalar sub-query
    sql("select * from emp\n" + "order by (select name from dept where deptno = emp.deptno)").ok();
    sql("select * from emp\n" + "order by (select name from dept where deptno = emp.^foo^)").fails("Column 'FOO' not found in table 'EMP'");
    // REVIEW jvs 10-Apr-2008:  I disabled this because I don't
    // understand what it means; see
    // testAggregateInOrderByFails for the discrimination I added
    // (SELECT should be aggregating for this to make sense).
    /*
        // Sort by aggregate. Oracle allows this.
        check("select 1 from emp order by sum(sal)");
*/
    // ORDER BY and SELECT *
    sql("select * from emp order by empno").ok();
    sql("select * from emp order by ^nonExistent^, deptno").fails("Column 'NONEXISTENT' not found in any table");
    // Overriding expression has different type.
    sql("select 'foo' as empno from emp order by ^empno + 5^").withTypeCoercion(false).fails("(?s)Cannot apply '\\+' to arguments of type '<CHAR\\(3\\)> \\+ <INTEGER>'\\..*");
    sql("select 'foo' as empno from emp order by empno + 5").ok();
}

