/**
 * Tests validation of the ORDER BY clause when DISTINCT is present.
 */
@Test
void testOrderDistinct() {
    // Distinct on expressions with attempts to order on a column in
    // the underlying table
    sql("select distinct cast(empno as bigint) " + "from emp order by ^empno^").fails("Expression 'EMPNO' is not in the select clause");
    sql("select distinct cast(empno as bigint) " + "from emp order by ^emp.empno^").fails("Expression 'EMP\\.EMPNO' is not in the select clause");
    sql("select distinct cast(empno as bigint) as empno " + "from emp order by ^emp.empno^").fails("Expression 'EMP\\.EMPNO' is not in the select clause");
    sql("select distinct cast(empno as bigint) as empno " + "from emp as e order by ^e.empno^").fails("Expression 'E\\.EMPNO' is not in the select clause");
    // These tests are primarily intended to test cases where sorting by
    // an alias is allowed.  But for instances that don't support sorting
    // by alias, the tests also verify that a proper exception is thrown.
    final SqlConformance conformance = fixture().conformance();
    sql("select distinct cast(empno as bigint) as empno " + "from emp order by ^empno^").failsIf(!conformance.isSortByAlias(), "Expression 'EMPNO' is not in the select clause");
    sql("select distinct cast(empno as bigint) as eno " + "from emp order by ^eno^").failsIf(!conformance.isSortByAlias(), "Column 'ENO' not found in any table");
    sql("select distinct cast(empno as bigint) as empno " + "from emp e order by ^empno^").failsIf(!conformance.isSortByAlias(), "Expression 'EMPNO' is not in the select clause");
    // Distinct on expressions, sorting using ordinals.
    if (conformance.isSortByOrdinal()) {
        sql("select distinct cast(empno as bigint) from emp order by 1").ok();
        sql("select distinct cast(empno as bigint) as empno " + "from emp order by 1").ok();
        sql("select distinct cast(empno as bigint) as empno " + "from emp as e order by 1").ok();
    }
    // Distinct on expressions with ordering on expressions as well
    sql("select distinct cast(empno as varchar(10)) from emp " + "order by cast(empno as varchar(10))").ok();
    sql("select distinct cast(empno as varchar(10)) as eno from emp " + " order by upper(^eno^)").failsIf(!conformance.isSortByAlias(), "Column 'ENO' not found in any table");
    // Test case for [CALCITE-5653], order by on aggregate will fail when there is an implicit cast
    // and IdentifierExpansion is off
    sql("select distinct sum(deptno + '1') from dept order by 1").withValidatorIdentifierExpansion(false).ok();
}

/**
 * Tests validation of the ORDER BY clause when DISTINCT and GROUP BY are
 * present.
 *
 * <p>Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-634">[CALCITE-634]
 * Allow ORDER BY aggregate function in SELECT DISTINCT, provided that it
 * occurs in SELECT clause</a>.
 */
@Test
void testOrderGroupDistinct() {
    // Order by an aggregate function,
    // which exists in select-clause with distinct being present
    sql("select distinct count(empno) AS countEMPNO from emp\n" + "group by empno\n" + "order by 1").ok();
    sql("select distinct count(empno) from emp\n" + "group by empno\n" + "order by 1").ok();
    sql("select distinct count(empno) AS countEMPNO from emp\n" + "group by empno\n" + "order by count(empno)").ok();
    sql("select distinct count(empno) from emp\n" + "group by empno\n" + "order by count(empno)").ok();
    sql("select distinct count(empno) from emp\n" + "group by empno\n" + "order by count(empno) desc").ok();
    sql("SELECT DISTINCT deptno from emp\n" + "ORDER BY deptno, ^sum(empno)^").fails("Aggregate expression is illegal in ORDER BY clause of non-aggregating SELECT");
    sql("SELECT DISTINCT deptno from emp\n" + "GROUP BY deptno ORDER BY deptno, ^sum(empno)^").fails("Expression 'SUM\\(`EMPNO`\\)' is not in the select clause");
    sql("SELECT DISTINCT deptno, min(empno) from emp\n" + "GROUP BY deptno ORDER BY deptno, ^sum(empno)^").fails("Expression 'SUM\\(`EMPNO`\\)' is not in the select clause");
    sql("SELECT DISTINCT deptno, sum(empno) from emp\n" + "GROUP BY deptno ORDER BY deptno, sum(empno)").ok();
}

@Test
void testGroup() {
    sql("select empno from emp where ^sum(sal)^ > 50").fails("Aggregate expression is illegal in WHERE clause");
    sql("select ^empno^ from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select ^*^ from emp group by deptno").fails("Expression 'EMP\\.EMPNO' is not being grouped");
    // If we're grouping on ALL columns, 'select *' is ok.
    // Checked on Oracle10G.
    sql("select * from (select empno,deptno from emp) group by deptno,empno").ok();
    // This query tries to reference an agg expression from within a
    // sub-query as a correlating expression, but the SQL syntax rules say
    // that the agg function SUM always applies to the current scope.
    // As it happens, the query is valid.
    sql("select deptno\n" + "from emp\n" + "group by deptno\n" + "having exists (select sum(emp.sal) > 10 from (values(true)))").ok();
    // if you reference a column from a sub-query, it must be a group col
    sql("select deptno " + "from emp " + "group by deptno " + "having exists (select 1 from (values(true)) where emp.deptno = 10)").ok();
    // Needs proper error message text and error markers in query
    if (TODO) {
        sql("select deptno " + "from emp " + "group by deptno " + "having exists (select 1 from (values(true)) where emp.empno = 10)").fails("xx");
    }
    // constant expressions
    sql("select cast(1 as integer) + 2 from emp group by deptno").ok();
    sql("select localtime, deptno + 3 from emp group by deptno").ok();
}

