@Test
void testRollup() {
    // DEPTNO is not null in database, but rollup introduces nulls
    sql("select deptno, count(*) as c, sum(sal) as s\n" + "from emp\n" + "group by rollup(deptno)").ok().type("RecordType(INTEGER DEPTNO, BIGINT NOT NULL C, INTEGER NOT NULL S) NOT NULL");
    // EMPNO stays NOT NULL because it is not rolled up
    sql("select deptno, empno\n" + "from emp\n" + "group by empno, rollup(deptno)").ok().type("RecordType(INTEGER DEPTNO, INTEGER NOT NULL EMPNO) NOT NULL");
    // DEPTNO stays NOT NULL because it is not rolled up
    sql("select deptno, empno\n" + "from emp\n" + "group by rollup(empno), deptno").ok().type("RecordType(INTEGER NOT NULL DEPTNO, INTEGER EMPNO) NOT NULL");
    // empno becomes NULL because it is rolled up, and so does empno + 1.
    sql("select empno, empno + 1 as e1\n" + "from emp\n" + "group by rollup(empno)").ok().type("RecordType(INTEGER EMPNO, INTEGER E1) NOT NULL");
}

