@Test
void testNestedAggFails() {
    // simple case
    sql("select ^sum(max(empno))^ from emp").fails(ERR_NESTED_AGG);
    // should still fail with intermediate expression
    sql("select ^sum(2*max(empno))^ from emp").fails(ERR_NESTED_AGG);
    // make sure it fails with GROUP BY too
    sql("select ^sum(max(empno))^ from emp group by deptno").fails(ERR_NESTED_AGG);
    // make sure it fails in HAVING too
    sql("select count(*) from emp group by deptno " + "having ^sum(max(empno))^=3").fails(ERR_NESTED_AGG);
    // double-nesting should fail too; bottom-up validation currently
    // causes us to flag the intermediate level
    sql("select sum(^max(min(empno))^) from emp").fails(ERR_NESTED_AGG);
}

@Test
void testNestedAggOver() {
    sql("select sum(max(empno))
" + " OVER (order by ^deptno^ ROWS 2 PRECEDING)
" + " from emp").fails("Expression 'DEPTNO' is not being grouped");
    sql("select sum(max(empno)) OVER w
" + " from emp
" + " window w as (order by ^deptno^ ROWS 2 PRECEDING)").fails("Expression 'DEPTNO' is not being grouped");
    sql("select sum(max(empno)) OVER w2, sum(deptno) OVER w1
" + " from emp group by deptno
" + " window w1 as (partition by ^empno^ ROWS 2 PRECEDING),
" + " w2 as (order by deptno ROWS 2 PRECEDING)").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(count(empno)) over w
" + "from emp group by deptno
" + "window w as (partition by deptno order by ^empno^)").fails("Expression 'EMPNO' is not being grouped");
    // in OVER clause with more than one level of nesting
    sql("select ^avg(sum(min(sal)))^ OVER (partition by deptno)
" + "from emp group by deptno").fails(ERR_NESTED_AGG);
    // OVER clause columns not appearing in GROUP BY clause NOT OK
    sql("select avg(^sal^) OVER (), avg(count(empno)) OVER (partition by 1)
" + " from emp").fails("Expression 'SAL' is not being grouped");
    sql("select avg(^sal^) OVER (), avg(count(empno)) OVER (partition by deptno)
" + " from emp group by deptno").fails("Expression 'SAL' is not being grouped");
    sql("select avg(deptno) OVER (partition by ^empno^),
" + " avg(count(empno)) OVER (partition by deptno)
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(deptno) OVER (order by ^empno^),
" + " avg(count(empno)) OVER (partition by deptno)
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + " from emp").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + " from emp").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by deptno order by ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(^sal^) OVER (),
" + " avg(count(empno)) OVER (partition by min(deptno))
" + " from emp").fails("Expression 'SAL' is not being grouped");
    sql("select avg(deptno) OVER (),
" + " avg(count(empno)) OVER (partition by deptno)" + " from emp group by deptno").ok();
    // COUNT(*), PARTITION BY(CONST) with GROUP BY is OK
    sql("select avg(count(*)) OVER ()
" + " from emp group by deptno").ok();
    sql("select count(*) OVER ()
" + " from emp group by deptno").ok();
    sql("select count(deptno) OVER ()
" + " from emp group by deptno").ok();
    sql("select count(deptno, deptno + 1) OVER ()
" + " from emp group by deptno").ok();
    sql("select count(deptno, deptno + 1, ^empno^) OVER ()
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select count(emp.^*^)
" + "from emp group by deptno").fails("Unknown field '\*'");
    sql("select count(emp.^*^) OVER ()
" + "from emp group by deptno").fails("Unknown field '\*'");
    sql("select avg(count(*)) OVER (partition by 1)
" + " from emp group by deptno").ok();
    sql("select avg(sum(sal)) OVER (partition by 1)
" + " from emp").ok();
    sql("select avg(sal), avg(count(empno)) OVER (partition by 1)
" + " from emp").ok();
    // expression is OK
    sql("select avg(sum(sal)) OVER (partition by 10 - deptno
" + "   order by deptno / 2 desc)
" + "from emp group by deptno").ok();
    sql("select avg(sal),
" + " avg(count(empno)) OVER (partition by min(deptno))
" + " from emp").ok();
    sql("select avg(min(sal)) OVER (),
" + " avg(count(empno)) OVER (partition by min(deptno))
" + " from emp").ok();
    // expression involving non-GROUP column is not OK
    sql("select avg(2+^sal^) OVER (partition by deptno)
" + "from emp group by deptno").fails("Expression 'SAL' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by deptno + ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by empno + deptno)
" + "from emp group by empno + deptno").ok();
    sql("select avg(sum(sal)) OVER (partition by empno + deptno + 1)
" + "from emp group by empno + deptno").ok();
    sql("select avg(sum(sal)) OVER (partition by ^deptno^ + 1)
" + "from emp group by empno + deptno").fails("Expression 'DEPTNO' is not being grouped");
    sql("select avg(empno + deptno) OVER (partition by empno + deptno + 1),
" + " count(empno + deptno) OVER (partition by empno + deptno + 1)
" + " from emp group by empno + deptno").ok();
    // expression is NOT OK (AS clause)
    sql("select sum(max(empno))
" + " OVER (order by ^deptno^ ROWS 2 PRECEDING) AS sumEmpNo
" + " from emp").fails("Expression 'DEPTNO' is not being grouped");
    sql("select sum(max(empno)) OVER w AS sumEmpNo
" + " from emp
" + " window w AS (order by ^deptno^ ROWS 2 PRECEDING)").fails("Expression 'DEPTNO' is not being grouped");
    sql("select avg(^sal^) OVER () AS avgSal," + " avg(count(empno)) OVER (partition by 1) AS avgEmpNo
" + " from emp").fails("Expression 'SAL' is not being grouped");
    sql("select count(deptno, deptno + 1, ^empno^) OVER () AS cntDeptEmp
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^deptno^ + 1) AS avgSal
" + "from emp group by empno + deptno").fails("Expression 'DEPTNO' is not being grouped");
    // OVER in clause
    sql("select ^sum(max(empno) OVER (order by deptno ROWS 2 PRECEDING))^ from emp").fails(ERR_NESTED_AGG);
}

