@Test
void testDateCompare() {
    // can convert character value to date, time, timestamp, interval
    // provided it is on one side of a comparison operator (=, <, >, BETWEEN)
    expr("date '2015-03-17' < '2015-03-18'").columnType("BOOLEAN NOT NULL");
    expr("date '2015-03-17' > '2015-03-18'").columnType("BOOLEAN NOT NULL");
    expr("date '2015-03-17' = '2015-03-18'").columnType("BOOLEAN NOT NULL");
    expr("'2015-03-17' < date '2015-03-18'").columnType("BOOLEAN NOT NULL");
    expr("date '2015-03-17' between '2015-03-16' and '2015-03-19'").columnType("BOOLEAN NOT NULL");
    expr("date '2015-03-17' between '2015-03-16' and '2015-03'||'-19'").columnType("BOOLEAN NOT NULL");
    expr("'2015-03-17' between date '2015-03-16' and date '2015-03-19'").columnType("BOOLEAN NOT NULL");
    expr("date '2015-03-17' between date '2015-03-16' and '2015-03-19'").columnType("BOOLEAN NOT NULL");
    expr("date '2015-03-17' between '2015-03-16' and date '2015-03-19'").columnType("BOOLEAN NOT NULL");
    expr("time '12:34:56' < '12:34:57'").columnType("BOOLEAN NOT NULL");
    expr("timestamp '2015-03-17 12:34:56' < '2015-03-17 12:34:57'").columnType("BOOLEAN NOT NULL");
    expr("interval '2' hour < '2:30'").columnType("BOOLEAN NOT NULL");
    // can convert to exact and approximate numeric
    expr("123 > '72'").columnType("BOOLEAN NOT NULL");
    expr("12.3 > '7.2'").columnType("BOOLEAN NOT NULL");
    // can convert to boolean
    expr("true = 'true'").columnType("BOOLEAN NOT NULL");
    expr("^true and 'true'^").fails("Cannot apply 'AND' to arguments of type '<BOOLEAN> AND <CHAR\\(4\\)>'\\..*");
}

@Test
void testOverlaps() {
    expr("(date '1-2-3', date '1-2-3')\n" + " overlaps (date '1-2-3', date '1-2-3')").columnType("BOOLEAN NOT NULL");
    expr("period (date '1-2-3', date '1-2-3')\n" + " overlaps period (date '1-2-3', date '1-2-3')").columnType("BOOLEAN NOT NULL");
    expr("(date '1-2-3', date '1-2-3') overlaps (date '1-2-3', interval '1' " + "year)").ok();
    expr("(time '1:2:3', interval '1' second) overlaps (time '23:59:59', time" + " '1:2:3')").ok();
    expr("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6' ) overlaps " + "(timestamp '1-2-3 4:5:6', interval '1 2:3:4.5' day to second)").ok();
    wholeExpr("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6' )\n" + " overlaps (time '4:5:6', interval '1 2:3:4.5' day to second)").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    wholeExpr("(time '4:5:6', timestamp '1-2-3 4:5:6' )\n" + " overlaps (time '4:5:6', interval '1 2:3:4.5' day to second)").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    wholeExpr("(time '4:5:6', time '4:5:6' )\n" + " overlaps (time '4:5:6', date '1-2-3')").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    wholeExpr("1 overlaps 2").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type " + "'<INTEGER> OVERLAPS <INTEGER>'\\. Supported form.*");
    expr("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "   overlaps (date '1-2-3', date '1-2-3')\n" + "or false").columnType("BOOLEAN NOT NULL");
    // row with 3 arguments as left argument to overlaps
    expr("true\n" + "or ^(date '1-2-3', date '1-2-3', date '1-2-3')\n" + "   overlaps (date '1-2-3', date '1-2-3')^\n" + "or false").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    // row with 3 arguments as right argument to overlaps
    expr("true\n" + "or ^(date '1-2-3', date '1-2-3')\n" + "  overlaps (date '1-2-3', date '1-2-3', date '1-2-3')^\n" + "or false").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    expr("^period (date '1-2-3', date '1-2-3')\n" + "   overlaps (date '1-2-3', date '1-2-3', date '1-2-3')^").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    expr("true\n" + "or ^(1, 2) overlaps (2, 3)^\n" + "or false").fails("(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    // Other operators with similar syntax
    String[] ops = { "overlaps", "contains", "equals", "precedes", "succeeds", "immediately precedes", "immediately succeeds" };
    for (String op : ops) {
        expr("period (date '1-2-3', date '1-2-3')\n" + " " + op + " period (date '1-2-3', date '1-2-3')").columnType("BOOLEAN NOT NULL");
        expr("(date '1-2-3', date '1-2-3')\n" + " " + op + " (date '1-2-3', date '1-2-3')").columnType("BOOLEAN NOT NULL");
    }
}

@Test
void testContains() {
    final String cannotApply = "(?s).*Cannot apply 'CONTAINS' to arguments of type .*";
    expr("(date '1-2-3', date '1-2-3')\n" + " contains (date '1-2-3', date '1-2-3')").columnType("BOOLEAN NOT NULL");
    expr("period (date '1-2-3', date '1-2-3')\n" + " contains period (date '1-2-3', date '1-2-3')").columnType("BOOLEAN NOT NULL");
    expr("(date '1-2-3', date '1-2-3')\n" + "  contains (date '1-2-3', interval '1' year)").ok();
    expr("(time '1:2:3', interval '1' second)\n" + " contains (time '23:59:59', time '1:2:3')").ok();
    expr("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6')\n" + " contains (timestamp '1-2-3 4:5:6', interval '1 2:3:4.5' day to " + "second)").ok();
    // period contains point
    expr("(date '1-2-3', date '1-2-3')\n" + "  contains date '1-2-3'").ok();
    // same, with "period" keyword
    expr("period (date '1-2-3', date '1-2-3')\n" + "  contains date '1-2-3'").ok();
    // point contains period
    wholeExpr("date '1-2-3'\n" + "  contains (date '1-2-3', date '1-2-3')").fails(cannotApply);
    // same, with "period" keyword
    wholeExpr("date '1-2-3'\n" + "  contains period (date '1-2-3', date '1-2-3')").fails(cannotApply);
    // point contains point
    wholeExpr("date '1-2-3' contains date '1-2-3'").fails(cannotApply);
    wholeExpr("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6' )\n" + " contains (time '4:5:6', interval '1 2:3:4.5' day to second)").fails(cannotApply);
    wholeExpr("(time '4:5:6', timestamp '1-2-3 4:5:6' )\n" + " contains (time '4:5:6', interval '1 2:3:4.5' day to second)").fails(cannotApply);
    wholeExpr("(time '4:5:6', time '4:5:6' )\n" + "  contains (time '4:5:6', date '1-2-3')").fails(cannotApply);
    wholeExpr("1 contains 2").fails(cannotApply);
    // row with 3 arguments
    expr("true\n" + "or ^(date '1-2-3', date '1-2-3', date '1-2-3')\n" + "  contains (date '1-2-3', date '1-2-3')^\n" + "or false").fails(cannotApply);
    expr("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "  contains (date '1-2-3', date '1-2-3')\n" + "or false").columnType("BOOLEAN NOT NULL");
    // second argument is a point
    expr("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "  contains date '1-2-3'\n" + "or false").columnType("BOOLEAN NOT NULL");
    // first argument may be null, so result may be null
    expr("true\n" + "or (date '1-2-3',\n" + "     case 1 when 2 then date '1-2-3' else null end)\n" + "  contains date '1-2-3'\n" + "or false").columnType("BOOLEAN");
    // second argument may be null, so result may be null
    expr("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "  contains case 1 when 1 then date '1-2-3' else null end\n" + "or false").columnType("BOOLEAN");
    expr("true\n" + "or ^period (date '1-2-3', date '1-2-3')\n" + "  contains period (date '1-2-3', time '4:5:6')^\n" + "or false").fails(cannotApply);
    expr("true\n" + "or ^(1, 2) contains (2, 3)^\n" + "or false").fails(cannotApply);
}

