@Test
void testUnnest() {
    sql("select*from unnest(multiset[1])").columnType("INTEGER NOT NULL");
    sql("select*from unnest(multiset[1, 2])").columnType("INTEGER NOT NULL");
    sql("select*from unnest(multiset[321.3, 2.33])").columnType("DECIMAL(5, 2) NOT NULL");
    sql("select*from unnest(multiset[321.3, 4.23e0])").columnType("DOUBLE NOT NULL");
    sql("select*from unnest(multiset[43.2e1, cast(null as decimal(4,2))])").columnType("DOUBLE");
    sql("select*from unnest(multiset[1, 2.3, 1])").columnType("DECIMAL(11, 1) NOT NULL");
    sql("select*from unnest(multiset['1','22','333'])").columnType("CHAR(3) NOT NULL");
    sql("select*from unnest(multiset['1','22','333','22'])").columnType("CHAR(3) NOT NULL");
    sql("select*from ^unnest(1)^").fails("(?s).*Cannot apply 'UNNEST' to arguments of type 'UNNEST.<INTEGER>.'.*");
    sql("select*from unnest(multiset(select*from dept))").ok();
    sql("select c from unnest(multiset(select deptno from dept)) as t(c)").ok();
    sql("select c from unnest(multiset(select * from dept)) as t(^c^)").fails("List of column aliases must have same degree as table; " + "table has 2 columns \\('DEPTNO', 'NAME'\\), " + "whereas alias list has 1 columns");
    sql("select ^c1^ from unnest(multiset(select name from dept)) as t(c)").fails("Column 'C1' not found in any table");
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-3789">[CALCITE-3789]
 * Support validation of UNNEST multiple array columns like Presto</a>.
 */
@Test
void testAliasUnnestMultipleArrays() {
    // for accessing a field in STRUCT type unnested from array
    sql("select e.ENAME\n" + "from dept_nested_expanded as d CROSS JOIN\n" + " UNNEST(d.employees) as t(e)").withConformance(SqlConformanceEnum.PRESTO).columnType("VARCHAR(10) NOT NULL");
    // for unnesting multiple arrays at the same time
    sql("select d.deptno, e, k.empno, l.\"unit\", l.\"X\" * l.\"Y\"\n" + "from dept_nested_expanded as d CROSS JOIN\n" + " UNNEST(d.admins, d.employees, d.offices) as t(e, k, l)").withConformance(SqlConformanceEnum.PRESTO).ok();
    // Make sure validation fails properly given illegal select items
    sql("select d.deptno, ^e^.some_column, k.empno\n" + "from dept_nested_expanded as d CROSS JOIN\n" + " UNNEST(d.admins, d.employees) as t(e, k)").withConformance(SqlConformanceEnum.PRESTO).fails("Table 'E' not found");
    sql("select d.deptno, e.detail, ^unknown^.detail\n" + "from dept_nested_expanded as d CROSS JOIN\n" + " UNNEST(d.employees) as t(e)").withConformance(SqlConformanceEnum.PRESTO).fails("Incompatible types");
    // Make sure validation fails without PRESTO conformance
    sql("select e.ENAME\n" + "from dept_nested_expanded as d CROSS JOIN\n" + " UNNEST(d.employees) as t(^e^)").fails("List of column aliases must have same degree as table; table has 3 columns " + "\\('EMPNO', 'ENAME', 'DETAIL'\\), whereas alias list has 1 columns");
}

