    s.withSql("select ^PATH^ from (select 1 as path from (values (true)))").fails("Column 'PATH' not found in any table; did you mean 'path'\\?");
    s.withSql("select t.^PATH^ from (select 1 as path from (values (true))) as t").fails("Column 'PATH' not found in table 't'; did you mean 'path'\\?");
    s.withSql("select t.x, t.^PATH^ from (values (true, 1)) as t(path, x)").fails("Column 'PATH' not found in table 't'; did you mean 'path'\\?");
    // Built-in functions can be written in any case, even those with no args,
    // and regardless of spaces between function name and open parenthesis.
    s.withSql("values (current_timestamp, floor(2.5), ceil (3.5))").ok();
    s.withSql("values (CURRENT_TIMESTAMP, FLOOR(2.5), CEIL (3.5))").ok();
    s.withSql("values (CURRENT_TIMESTAMP, CEIL (3.5))").type("RecordType(TIMESTAMP(0) NOT NULL CURRENT_TIMESTAMP, " + "DECIMAL(2, 0) NOT NULL EXPR$1) NOT NULL");
}

