@Test
void testCaseInsensitiveTableAlias() {
    final SqlValidatorFixture s = fixture().withCaseSensitive(false).withQuoting(Quoting.BRACKET);
    final SqlValidatorFixture sensitive = fixture().withQuoting(Quoting.BRACKET);
    // Table aliases should follow case-sensitivity preference.
    //
    // In MySQL, table aliases are case-insensitive:
    // mysql> select `D`.day from DAYS as `d`, DAYS as `D`;
    // ERROR 1066 (42000): Not unique table/alias: 'D'
