/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1549">[CALCITE-1549]
 * Improve error message when table or column not found</a>.
 */
@Test
void testTableNotFoundDidYouMean() {
    // No table in default schema
    sql("select * from ^unknownTable^").fails("Object 'UNKNOWNTABLE' not found");
    // Similar table exists in default schema
    sql("select * from ^\"Emp\"^").fails("Object 'Emp' not found within 'SALES'; did you mean 'EMP'\\?");
    // Schema correct, but no table in specified schema
    sql("select * from ^sales.unknownTable^").fails("Object 'UNKNOWNTABLE' not found within 'SALES'");
    // Similar table exists in specified schema
    sql("select * from ^sales.\"Emp\"^").fails("Object 'Emp' not found within 'SALES'; did you mean 'EMP'\\?");
    // No schema found
    sql("select * from ^unknownSchema.unknownTable^").fails("Object 'UNKNOWNSCHEMA' not found");
    // Similar schema found
    sql("select * from ^\"sales\".emp^").fails("Object 'sales' not found; did you mean 'SALES'\\?");
    sql("select * from ^\"saLes\".\"eMp\"^").fails("Object 'saLes' not found; did you mean 'SALES'\\?");
    // Spurious after table
    sql("select * from ^emp.foo^").fails("Object 'FOO' not found within 'SALES\\.EMP'");
    sql("select * from ^sales.emp.foo^").fails("Object 'FOO' not found within 'SALES\\.EMP'");
    // Alias not found
    sql("select ^aliAs^.\"name\"\n" + "from sales.emp as \"Alias\"").fails("Table 'ALIAS' not found; did you mean 'Alias'\\?");
    // Alias not found, fully-qualified
    sql("select ^sales.\"emp\"^.\"name\" from sales.emp").fails("Table 'SALES\\.emp' not found; did you mean 'EMP'\\?");
}

@Test
void testColumnNotFoundDidYouMean() {
    // Column not found
    sql("select ^\"unknownColumn\"^ from emp").fails("Column 'unknownColumn' not found in any table");
    // Similar column in table, unqualified table name
    sql("select ^\"empNo\"^ from emp").fails("Column 'empNo' not found in any table; did you mean 'EMPNO'\\?");
    // Similar column in table, table name qualified with schema
    sql("select ^\"empNo\"^ from sales.emp").fails("Column 'empNo' not found in any table; did you mean 'EMPNO'\\?");
    // Similar column in table, table name qualified with catalog and schema
    sql("select ^\"empNo\"^ from catalog.sales.emp").fails("Column 'empNo' not found in any table; did you mean 'EMPNO'\\?");
    // With table alias
    sql("select e.^\"empNo\"^ from catalog.sales.emp as e").fails("Column 'empNo' not found in table 'E'; did you mean 'EMPNO'\\?");
    // With fully-qualified table alias
    sql("select catalog.sales.emp.^\"empNo\"^\n" + "from catalog.sales.emp").fails("Column 'empNo' not found in table 'CATALOG\\.SALES\\.EMP'; " + "did you mean 'EMPNO'\\?");
    // Similar column in table; multiple tables
    sql("select ^\"name\"^ from emp, dept").fails("Column 'name' not found in any table; did you mean 'NAME'\\?");
    // Similar column in table; table and a query
    sql("select ^\"name\"^ from emp,\n" + "  (select * from dept) as d").fails("Column 'name' not found in any table; did you mean 'NAME'\\?");
    // Similar column in table; table and an un-aliased query
    sql("select ^\"name\"^ from emp, (select * from dept)").fails("Column 'name' not found in any table; did you mean 'NAME'\\?");
    // Similar column in table, multiple tables
    sql("select ^\"deptno\"^ from emp,\n" + "  (select deptno as \"deptNo\" from dept)").fails("Column 'deptno' not found in any table; " + "did you mean 'DEPTNO', 'deptNo'\\?");
    sql("select ^\"deptno\"^ from emp,\n" + "  (select * from dept) as t(\"deptNo\", name)").fails("Column 'deptno' not found in any table; " + "did you mean 'DEPTNO', 'deptNo'\\?");
}

/**
 * Tests matching of built-in operator names.
 */
@Test
void testUnquotedBuiltInFunctionNames() {
    final SqlValidatorFixture mysql = fixture().withUnquotedCasing(Casing.UNCHANGED).withQuoting(Quoting.BACK_TICK).withCaseSensitive(false);
    final SqlValidatorFixture oracle = fixture().withUnquotedCasing(Casing.TO_UPPER).withCaseSensitive(true);
    // Built-in functions are always case-insensitive.
    oracle.withSql("select count(*), sum(deptno), floor(2.5) from dept").ok();
    oracle.withSql("select COUNT(*), FLOOR(2.5) from dept").ok();
    oracle.withSql("select cOuNt(*), FlOOr(2.5) from dept").ok();
    oracle.withSql("select cOuNt (*), FlOOr (2.5) from dept").ok();
    oracle.withSql("select current_time from dept").ok();
    oracle.withSql("select Current_Time from dept").ok();
    oracle.withSql("select CURRENT_TIME from dept").ok();
    mysql.withSql("select sum(deptno), floor(2.5) from dept").ok();
    mysql.withSql("select count(*), sum(deptno), floor(2.5) from dept").ok();
    mysql.withSql("select COUNT(*), FLOOR(2.5) from dept").ok();
    mysql.withSql("select cOuNt(*), FlOOr(2.5) from dept").ok();
    mysql.withSql("select cOuNt (*), FlOOr (2.5) from dept").ok();
    mysql.withSql("select current_time from dept").ok();
    mysql.withSql("select Current_Time from dept").ok();
    mysql.withSql("select CURRENT_TIME from dept").ok();
    // MySQL assumes that a quoted function name is not a built-in.
    //
    // mysql> select `sum`(`day`) from days;
    // ERROR 1630 (42000): FUNCTION foodmart.sum does not exist. Check the
    //   'Function Name Parsing and Resolution' section in the Reference Manual
    // mysql> select `SUM`(`day`) from days;
    // ERROR 1630 (42000): FUNCTION foodmart.SUM does not exist. Check the
    //   'Function Name Parsing and Resolution' section in the Reference Manual
    // mysql> select SUM(`day`) from days;
    // +------------+
    // | SUM(`day`) |
    // +------------+
    // |         28 |
    // +------------+
    // 1 row in set (0.00 sec)
    //
    // We do not follow MySQL in this regard. `count` is preserved in
    // lower-case, and is matched case-insensitively because it is a built-in.
    // So, the query succeeds.
    oracle.withSql("select \"count\"(*) from dept").ok();
    mysql.withSql("select `count`(*) from dept").ok();
}

