    sql("insert into empnullables (ename, empno) select ?, ? from (values (1))").ok().assertBindType(is("RecordType(VARCHAR(20) ?0, INTEGER ?1)"));
    // WITH
    final String sql3 = "insert into empnullables (ename, empno)\n" + "with v as (values ('a'))\n" + "select ?, ? from (values (1))";
