    // VALUES with expression
    s.withSql("insert into empnullables values (? + 1, ?)").ok().assertBindType(is("RecordType(INTEGER ?0, VARCHAR(20) ?1)"));
    // SELECT
    s.withSql("insert into empnullables select ?, ? from (values (1))").ok().assertBindType(is("RecordType(INTEGER ?0, VARCHAR(20) ?1)"));
    // WITH
    final String sql3 = "insert into empnullables\n" + "with v as (values ('a'))\n" + "select ?, ? from (values (1))";
    s.withSql(sql3).ok().assertBindType(is("RecordType(INTEGER ?0, VARCHAR(20) ?1)"));
    // UNION
    final String sql2 = "insert into empnullables\n" + "select ?, ? from (values (1))\n" + "union all\n" + "select ?, ? from (values (time '1:2:3'))";
    final String expected2 = "RecordType(INTEGER ?0, VARCHAR(20) ?1," + " INTEGER ?2, VARCHAR(20) ?3)";
    s.withSql(sql2).ok().assertBindType(is(expected2));
}

