/**
 * Tests that various expressions are monotonic.
 */
@Test
void testMonotonic() {
    sql("select stream floor(rowtime to hour) from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream ceil(rowtime to minute) from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream extract(minute from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.NOT_MONOTONIC));
    sql("select stream (rowtime - timestamp '1970-01-01 00:00:00') hour from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream\n" + "cast((rowtime - timestamp '1970-01-01 00:00:00') hour as integer)\n" + "from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream\n" + "cast((rowtime - timestamp '1970-01-01 00:00:00') hour as integer) / 15\n" + "from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream\n" + "mod(cast((rowtime - timestamp '1970-01-01 00:00:00') hour as integer), 15)\n" + "from orders").assertMonotonicity(is(SqlMonotonicity.NOT_MONOTONIC));
    // constant
    sql("select stream 1 - 2 from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    sql("select stream 1 + 2 from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    // extract(YEAR) is monotonic, extract(other time unit) is not
    sql("select stream extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream extract(month from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.NOT_MONOTONIC));
    // <monotonic> - constant
    sql("select stream extract(year from rowtime) - 3 from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream extract(year from rowtime) * 5 from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream extract(year from rowtime) * -5 from orders").assertMonotonicity(is(SqlMonotonicity.DECREASING));
    // <monotonic> / constant
    sql("select stream extract(year from rowtime) / -5 from orders").assertMonotonicity(is(SqlMonotonicity.DECREASING));
    sql("select stream extract(year from rowtime) / 5 from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream extract(year from rowtime) / 0 from orders").assertMonotonicity(// +inf is constant!
    is(SqlMonotonicity.CONSTANT));
    sql("select stream extract(year from rowtime) / null from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    sql("select stream null / extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    sql("select stream extract(year from rowtime) / cast(null as integer) from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    sql("select stream cast(null as integer) / extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    // constant / <monotonic> is not monotonic (we don't know whether sign of
    // expression ever changes)
    sql("select stream 5 / extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.NOT_MONOTONIC));
    // <monotonic> * constant
    sql("select stream extract(year from rowtime) * -5 from orders").assertMonotonicity(is(SqlMonotonicity.DECREASING));
    sql("select stream extract(year from rowtime) * 5 from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream extract(year from rowtime) * 0 from orders").assertMonotonicity(// 0 is constant!
    is(SqlMonotonicity.CONSTANT));
    // constant * <monotonic>
    sql("select stream -5 * extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.DECREASING));
    sql("select stream 5 * extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
    sql("select stream 0 * extract(year from rowtime) from orders").assertMonotonicity(is(SqlMonotonicity.CONSTANT));
    // <monotonic> - <monotonic>
    sql("select stream\n" + "extract(year from rowtime) - extract(year from rowtime)\n" + "from orders").assertMonotonicity(is(SqlMonotonicity.NOT_MONOTONIC));
    // <monotonic> + <monotonic>
    sql("select stream\n" + "extract(year from rowtime) + extract(year from rowtime)\n" + "from orders").assertMonotonicity(is(SqlMonotonicity.INCREASING));
}

