    final String selectError = "Rolled up column 'SLACKINGMIN' is not allowed in SELECT";
    sql("select * from (select deptno, ^slackingmin^ from emp_r)\n" + " join dept using (deptno)").fails(selectError);
    sql("select * from dept as a\n" + "join (select deptno, ^slackingmin^ from emp_r) using (deptno)").fails(selectError);
    sql("select * from emp_r as a\n" + "join dept_r as b using (deptno, ^slackingmin^)").fails(usingError);
