@Test
void testRegexpReplace() {
    final SqlOperatorTable opTable = operatorTableFor(SqlLibrary.ORACLE);
    expr("REGEXP_REPLACE('a b c', 'a', 'X')").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
    expr("REGEXP_REPLACE('abc def ghi', '[a-z]+', 'X', 2)").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
    expr("REGEXP_REPLACE('abc def ghi', '[a-z]+', 'X', 1, 3)").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
    expr("REGEXP_REPLACE('abc def GHI', '[a-z]+', 'X', 1, 3, 'c')").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
    // Implicit type coercion.
    expr("REGEXP_REPLACE(null, '(-)', '###')").withOperatorTable(opTable).columnType("VARCHAR");
    expr("REGEXP_REPLACE('100-200', null, '###')").withOperatorTable(opTable).columnType("VARCHAR");
    expr("REGEXP_REPLACE('100-200', '(-)', null)").withOperatorTable(opTable).columnType("VARCHAR");
    expr("REGEXP_REPLACE('abc def ghi', '[a-z]+', 'X', '2')").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
    expr("REGEXP_REPLACE('abc def ghi', '[a-z]+', 'X', '1', '3')").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
    // The last argument to REGEXP_REPLACE should be specific character, but with
    // implicit type coercion, the validation still passes.
    expr("REGEXP_REPLACE('abc def ghi', '[a-z]+', 'X', '1', '3', '1')").withOperatorTable(opTable).columnType("VARCHAR NOT NULL");
}

