        final String expected = "F0=5; N=4; C=abcd\n" + "F0=5; N=4; C=abcd\n" + "F0=5; N=4; C=abcd\n" + "F0=5; N=4; C=abcd\n";
        assertThat(CalciteAssert.toString(resultSet), equalTo(expected));
    }
}

