    f.checkWiderType(f.arrayType(f.smallintType), f.arrayType(f.doubleType), f.arrayType(f.doubleType), true, true);
    f.checkWiderType(f.arrayType(f.timestampType), f.arrayType(f.varcharType), f.arrayType(f.varcharType), true, true);
