    // (values(1) union all select * from (values(3)) where false)
    // union all values(2)
    // Non-trivial filter is important for the test to fail
    RelNode relNode = relBuilder.values(new String[] { "x" }, "1").values(new String[] { "x" }, "3").filter(relBuilder.equals(relBuilder.field("x"), relBuilder.literal("30"))).union(true).values(new String[] { "x" }, "2").union(true).build();
