 * VolcanoPlanner CannotPlanException: best rel is null even though there is
 * an option with non-infinite cost</a>.
 */
@Test
void testCorrelatedJoinWithIdenticalInputs() {
    final RelBuilder builder = RelBuilder.create(RelBuilderTest.config().build());
    final RuleSet ruleSet = RuleSets.ofList(CoreRules.JOIN_TO_CORRELATE, EnumerableRules.ENUMERABLE_CORRELATE_RULE, EnumerableRules.ENUMERABLE_PROJECT_RULE, EnumerableRules.ENUMERABLE_FILTER_RULE, EnumerableRules.ENUMERABLE_SORT_RULE, EnumerableRules.ENUMERABLE_UNION_RULE, EnumerableRules.ENUMERABLE_TABLE_SCAN_RULE);
    builder.scan("EMP").scan("EMP").union(true).scan("EMP").scan("EMP").union(true).join(JoinRelType.INNER, builder.equals(builder.field(2, 0, "DEPTNO"), builder.field(2, 1, "EMPNO")));
    final RelNode relNode = builder.build();
    final RelOptPlanner planner = relNode.getCluster().getPlanner();
    final Program program = Programs.of(ruleSet);
    final RelTraitSet toTraits = relNode.getTraitSet().replace(EnumerableConvention.INSTANCE);
    final RelNode output = program.run(planner, relNode, toTraits, ImmutableList.of(), ImmutableList.of());
    final String plan = toString(output);
    assertThat(plan, equalTo("EnumerableCorrelate(correlation=[$cor0], joinType=[inner], " + "requiredColumns=[{7}])\n" + "  EnumerableUnion(all=[true])\n" + "    EnumerableTableScan(table=[[scott, EMP]])\n" + "    EnumerableTableScan(table=[[scott, EMP]])\n" + "  EnumerableFilter(condition=[=($cor0.DEPTNO, $0)])\n" + "    EnumerableUnion(all=[true])\n" + "      EnumerableTableScan(table=[[scott, EMP]])\n" + "      EnumerableTableScan(table=[[scott, EMP]])\n"));
}

