/**
 * Tests the method {@link BitSets#closure(java.util.SortedMap)}.
 */
@Test
void testClosure() {
    final SortedMap<Integer, BitSet> empty = new TreeMap<>();
    assertThat(BitSets.closure(empty), equalTo(empty));
    // Map with an an entry for each position.
    final SortedMap<Integer, BitSet> map = new TreeMap<>();
    map.put(0, BitSets.of(3));
    map.put(1, BitSets.of());
    map.put(2, BitSets.of(7));
    map.put(3, BitSets.of(4, 12));
    map.put(4, BitSets.of());
    map.put(5, BitSets.of());
    map.put(6, BitSets.of());
    map.put(7, BitSets.of());
    map.put(8, BitSets.of());
    map.put(9, BitSets.of());
    map.put(10, BitSets.of());
    map.put(11, BitSets.of());
    map.put(12, BitSets.of());
    final String original = map.toString();
    final String expected = "{0={3, 4, 12}, 1={}, 2={7}, 3={3, 4, 12}, 4={4, 12}, 5={}, 6={}, 7={7}, 8={}, 9={}, 10={}, 11={}, 12={4, 12}}";
    assertThat(BitSets.closure(map), hasToString(expected));
    assertThat("argument modified", map, hasToString(original));
    // Now a similar map with missing entries. Same result.
    final SortedMap<Integer, BitSet> map2 = new TreeMap<>();
    map2.put(0, BitSets.of(3));
    map2.put(2, BitSets.of(7));
    map2.put(3, BitSets.of(4, 12));
    map2.put(9, BitSets.of());
    final String original2 = map2.toString();
    assertThat(BitSets.closure(map2), hasToString(expected));
    assertThat("argument modified", map2, hasToString(original2));
}

/**
 * Unit test for {@link ChunkList}.
 */
@Test
void testChunkList() {
    final ChunkList<Integer> list = new ChunkList<>();
    final ChunkList<Integer> list0 = new ChunkList<>(list);
    final ChunkList<Integer> list1 = new ChunkList<>(list);
    list1.add(123);
    assertEquals(0, list.size());
    assertEquals(0, list0.size());
    assertEquals(1, list1.size());
    assertTrue(list.isEmpty());
    assertEquals("[]", list.toString());
    try {
        list.remove(0);
        fail("expected exception");
    } catch (IndexOutOfBoundsException e) {
        // ok
    }
    try {
        list.get(-1);
        fail("expected exception");
    } catch (IndexOutOfBoundsException e) {
        // ok
    }
    try {
        list.get(0);
        fail("expected exception");
    } catch (IndexOutOfBoundsException e) {
        // ok
    }
    list.add(7);
    assertEquals(1, list.size());
    assertEquals(7, (int) list.get(0));
    assertFalse(list.isEmpty());
    assertEquals("[7]", list.toString());
    list.add(9);
    list.add(null);
    list.add(11);
    assertEquals(4, list.size());
    assertEquals(7, (int) list.get(0));
    assertEquals(9, (int) list.get(1));
    assertNull(list.get(2));
    assertEquals(11, (int) list.get(3));
    assertFalse(list.isEmpty());
    assertEquals("[7, 9, null, 11]", list.toString());
    assertTrue(list.contains(9));
    assertFalse(list.contains(8));
    list.addAll(Collections.nCopies(70, 1));
    assertEquals(74, list.size());
    assertEquals(1, (int) list.get(40));
    assertEquals(1, (int) list.get(70));
    int n = 0;
    for (Integer integer : list) {
        Util.discard(integer);
        ++n;
    }
    assertEquals(n, list.size());
    int i = list.indexOf(null);
    assertEquals(2, i);
    // can't sort if null is present
    list.set(2, 123);
    i = list.indexOf(null);
    assertEquals(-1, i);
    // sort an empty list
    Collections.sort(list0);
    assertThat(list0.isEmpty(), is(true));
    // sort a list with 1 element
    Collections.sort(list1);
    assertThat(list1, hasSize(1));
    Collections.sort(list);
    assertEquals(74, list.size());
    list.remove((Integer) 7);
    Collections.sort(list);
    assertEquals(1, (int) list.get(3));
    // remove all instances of a value that exists
    boolean b = list.removeAll(Collections.singletonList(9));
    assertTrue(b);
    // remove all instances of a non-existent value
    b = list.removeAll(Collections.singletonList(99));
    assertFalse(b);
    // remove all instances of a value that occurs in the last chunk
    list.add(12345);
    b = list.removeAll(Collections.singletonList(12345));
    assertTrue(b);
    // remove all instances of a value that occurs in the last chunk but
    // not as the last value
    list.add(12345);
    list.add(123);
    b = list.removeAll(Collections.singletonList(12345));
    assertTrue(b);
    assertThat(new ChunkList<>(Collections.nCopies(1000, 77)).size(), is(1000));
    // add to an empty list via iterator
    //noinspection MismatchedQueryAndUpdateOfCollection
    final ChunkList<String> list2 = new ChunkList<>();
    list2.listIterator(0).add("x");
    assertEquals("[x]", list2.toString());
    // add at start
    list2.add(0, "y");
    assertEquals("[y, x]", list2.toString());
    list2.remove(0);
    assertEquals("[x]", list2.toString());
    // clear a list of length 5, one element at a time, using an iterator
    list2.clear();
    list2.addAll(ImmutableList.of("a", "b", "c", "d", "e"));
    assertThat(list2, hasSize(5));
    final ListIterator<String> listIterator = list2.listIterator(0);
    assertThat(listIterator.next(), is("a"));
    listIterator.remove();
    assertThat(listIterator.next(), is("b"));
    listIterator.remove();
    assertThat(listIterator.next(), is("c"));
    listIterator.remove();
    assertThat(listIterator.next(), is("d"));
    listIterator.remove();
    assertThat(list2, hasSize(1));
    assertThat(listIterator.next(), is("e"));
    listIterator.remove();
    assertThat(list2, hasSize(0));
}

