/**
 * Tests {@link RangeSets#map} and {@link RangeSets#forEach}.
 */
@Test
void testRangeMap() {
    final StringBuilder sb = new StringBuilder();
    final RangeSets.Handler<Integer, StringBuilder> h = new RangeSets.Handler<Integer, StringBuilder>() {

        @Override
        public StringBuilder all() {
            return sb.append("all()");
        }

        @Override
        public StringBuilder atLeast(Integer lower) {
            return sb.append("atLeast(").append(lower).append(")");
        }

        @Override
        public StringBuilder atMost(Integer upper) {
            return sb.append("atMost(").append(upper).append(")");
        }

        @Override
        public StringBuilder greaterThan(Integer lower) {
            return sb.append("greaterThan(").append(lower).append(")");
        }

        @Override
        public StringBuilder lessThan(Integer upper) {
            return sb.append("lessThan(").append(upper).append(")");
        }

        @Override
        public StringBuilder singleton(Integer value) {
            return sb.append("singleton(").append(value).append(")");
        }

        @Override
        public StringBuilder closed(Integer lower, Integer upper) {
            return sb.append("closed(").append(lower).append(", ").append(upper).append(")");
        }

        @Override
        public StringBuilder closedOpen(Integer lower, Integer upper) {
            return sb.append("closedOpen(").append(lower).append(", ").append(upper).append(")");
        }

        @Override
        public StringBuilder openClosed(Integer lower, Integer upper) {
            return sb.append("openClosed(").append(lower).append(", ").append(upper).append(")");
        }

        @Override
        public StringBuilder open(Integer lower, Integer upper) {
            return sb.append("open(").append(lower).append(", ").append(upper).append(")");
        }
    };
    final RangeSets.Consumer<Integer> c = new RangeSets.Consumer<Integer>() {

        @Override
        public void all() {
            sb.append("all()");
        }

        @Override
        public void atLeast(Integer lower) {
            sb.append("atLeast(").append(lower).append(")");
        }

        @Override
        public void atMost(Integer upper) {
            sb.append("atMost(").append(upper).append(")");
        }

        @Override
        public void greaterThan(Integer lower) {
            sb.append("greaterThan(").append(lower).append(")");
        }

        @Override
        public void lessThan(Integer upper) {
            sb.append("lessThan(").append(upper).append(")");
        }

        @Override
        public void singleton(Integer value) {
            sb.append("singleton(").append(value).append(")");
        }

        @Override
        public void closed(Integer lower, Integer upper) {
            sb.append("closed(").append(lower).append(", ").append(upper).append(")");
        }

        @Override
        public void closedOpen(Integer lower, Integer upper) {
            sb.append("closedOpen(").append(lower).append(", ").append(upper).append(")");
        }

        @Override
        public void openClosed(Integer lower, Integer upper) {
            sb.append("openClosed(").append(lower).append(", ").append(upper).append(")");
        }

        @Override
        public void open(Integer lower, Integer upper) {
            sb.append("open(").append(lower).append(", ").append(upper).append(")");
        }
    };
    final Fixture f = new Fixture();
    for (Range<Integer> range : f.ranges) {
        RangeSets.map(range, h);
    }
    assertThat(sb, hasToString(f.rangesString));
    sb.setLength(0);
    for (Range<Integer> range : f.ranges) {
        RangeSets.forEach(range, c);
    }
    assertThat(sb, hasToString(f.rangesString));
    // Use a smaller set of ranges that does not overlap
    sb.setLength(0);
    for (Range<Integer> range : f.disjointRanges) {
        RangeSets.forEach(range, c);
    }
    assertThat(sb, hasToString(f.disjointRangesString));
    // For a RangeSet consisting of disjointRanges the effect is the same,
    // but the ranges are sorted.
    sb.setLength(0);
    RangeSets.forEach(f.rangeSet, c);
    assertThat(sb, hasToString(f.disjointRangesSortedString));
}

