    assertThat(SqlLibrary.parse("oracle,CALCITE,oracle"), is(ImmutableList.of(o, c, o)));
    assertThat(SqlLibrary.parse(""), is(ImmutableList.of()));
    assertThrows(IllegalArgumentException.class, () -> SqlLibrary.parse("oracle,calcite,foo,oracle"));
    assertThrows(IllegalArgumentException.class, () -> SqlLibrary.parse("oracle,calcite,,oracle"));
    assertThat(SqlLibrary.expand(ImmutableList.of(a)), hasToString("[ALL, BIG_QUERY, CALCITE, HIVE, MSSQL, MYSQL, ORACLE, " + "POSTGRESQL, SPARK]"));
    assertThat(SqlLibrary.expand(ImmutableList.of(a, c)), hasToString("[ALL, BIG_QUERY, CALCITE, HIVE, MSSQL, MYSQL, ORACLE, " + "POSTGRESQL, SPARK]"));
    assertThat(SqlLibrary.expand(ImmutableList.of(c, a)), hasToString("[CALCITE, ALL, BIG_QUERY, HIVE, MSSQL, MYSQL, ORACLE, " + "POSTGRESQL, SPARK]"));
    assertThat(SqlLibrary.expand(ImmutableList.of(c, o, a)), hasToString("[CALCITE, ORACLE, ALL, BIG_QUERY, HIVE, MSSQL, MYSQL, " + "POSTGRESQL, SPARK]"));
    assertThat(SqlLibrary.expand(ImmutableList.of(o, c, o)), hasToString("[ORACLE, CALCITE]"));
    assertThat("all + spatial + standard covers everything", ImmutableSet.copyOf(SqlLibrary.expand(ImmutableList.of(a, sp, st))), is(ImmutableSet.copyOf(SqlLibrary.values())));
    assertThat(SqlLibrary.expandUp(ImmutableList.of(c)), hasToString("[ALL, CALCITE]"));
    assertThat(SqlLibrary.expandUp(ImmutableList.of(c, o)), hasToString("[ALL, CALCITE, ORACLE]"));
    assertThat(SqlLibrary.expandUp(ImmutableList.of(st, c, o)), hasToString("[STANDARD, ALL, CALCITE, ORACLE]"));
    assertThat(SqlLibrary.expandUp(ImmutableList.of(st, sp)), hasToString("[STANDARD, SPATIAL]"));
    assertThat(SqlLibrary.expandUp(ImmutableList.of(st, a, sp)), hasToString("[STANDARD, ALL, SPATIAL]"));
    assertThat(SqlLibrary.expandUp(ImmutableList.of(a)), hasToString("[ALL]"));
}

