@Test
void testPushCastNumeric() {
    String druidQuery = "'filter':{'type':'bound','dimension':'product_id'," + "'upper':'10','upperStrict':true,'ordering':'numeric'}";
    fixture().withRel(b -> {
        // select product_id
        // from foodmart.foodmart
        // where product_id < cast(10 as varchar)
        final RelDataType intType = b.getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        return b.scan("foodmart", "foodmart").filter(b.call(SqlStdOperatorTable.LESS_THAN, b.getRexBuilder().makeCall(intType, SqlStdOperatorTable.CAST, ImmutableList.of(b.field("product_id"))), b.getRexBuilder().makeCall(intType, SqlStdOperatorTable.CAST, ImmutableList.of(b.literal("10"))))).project(b.field("product_id")).build();
    }).queryContains(new DruidChecker(druidQuery));
}

