    // Logically Equivalent to
    // select sum("store_sales"), sum("store_cost")
    // from "foodmart" where "brand_name" = 'Super' and "store_state" = 'CA'
    String sql = "select " + "sum(\"store_sales\") filter (where \"store_state\" = 'CA'), " + "sum(\"store_cost\") filter (where \"store_state\" = 'CA') " + "from \"foodmart\" " + "where \"brand_name\" = 'Super'";
    // Aggregates should lose reference to any filter clause
    String expectedAggregateExplain = "aggs=[[SUM($0), SUM($2)]]";
    String expectedQuery = "{'queryType':'timeseries','dataSource':'foodmart','descending':false," + "'granularity':'all','filter':{'type':'and','fields':[{'type':'selector','dimension':" + "'store_state','value':'CA'},{'type':'selector','dimension':'brand_name','value':" + "'Super'}]},'aggregations':[{'type':'doubleSum','name':'EXPR$0','fieldName':" + "'store_sales'},{'type':'doubleSum','name':'EXPR$1','fieldName':'store_cost'}]," + "'intervals':['1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z']," + "'context':{'skipEmptyBuckets':false}}";
    sql(sql).queryContains(new DruidChecker(expectedQuery)).explainContains(expectedAggregateExplain).returnsUnordered("EXPR$0=2600.01; EXPR$1=1013.162");
}

/**
 * Tests that when the resulting filter from factoring filter clauses out is always false,
 * that they are still pushed to Druid to handle.
 */
@Test
void testOuterFilterFalseAfterFactorSimplification() {
    // Normally we would factor out "the_year" > 1997 into the outer filter to prune the data
    // before aggregation and simplify the expression, but in this case that would produce:
    // "the_year" > 1997 AND "the_year" <= 1997 -> false (after simplification)
    // Since Druid cannot handle a "false" filter, we revert back to the
    // pre-simplified version. i.e the filter should be "the_year" > 1997 and "the_year" <= 1997
    // and let Druid handle an unsatisfiable expression
    String sql = "select sum(\"store_sales\") filter (where \"the_year\" > 1997) " + "from \"foodmart\" where \"the_year\" <= 1997";
    String expectedFilter = "filter':{'type':'and','fields':[{'type':'bound','dimension':'the_year'" + ",'lower':'1997','lowerStrict':true,'ordering':'numeric'},{'type':'bound'," + "'dimension':'the_year','upper':'1997','upperStrict':false,'ordering':'numeric'}]}";
    sql(sql).queryContains(new DruidChecker(expectedFilter));
}

