@Test
void testTopNMonthGranularity() {
    final String sql = "select sum(\"unit_sales\") as s,\n" + "max(\"unit_sales\") as m,\n" + "\"state_province\" as p\n" + "from \"foodmart\"\n" + "group by \"state_province\", floor(\"timestamp\" to MONTH)\n" + "order by s desc limit 3";
    // Cannot use a Druid "topN" query, granularity != "all";
    // have to use "groupBy" query followed by external Sort and fetch.
    final String explain = "PLAN=" + "EnumerableCalc(expr#0..3=[{inputs}], S=[$t2], M=[$t3], P=[$t0])\n" + "  EnumerableInterpreter\n" + "    DruidQuery(table=[[foodmart, foodmart]], " + "intervals=[[1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z]], projects=[[$30, FLOOR" + "($0, FLAG(MONTH)), $89]], groups=[{0, 1}], aggs=[[SUM($2), MAX($2)]], sort0=[2], " + "dir0=[DESC], fetch=[3])";
    final String druidQueryPart1 = "{'queryType':'groupBy','dataSource':'foodmart'," + "'granularity':'all','dimensions':[{'type':'default'," + "'dimension':'state_province',\"outputName\":\"state_province\",\"outputType\":\"STRING\"}," + "{'type':'extraction','dimension':'__time'," + "'outputName':'floor_month','extractionFn':{'type':'timeFormat','format'";
    final String druidQueryPart2 = "'limitSpec':{'type':'default','limit':3," + "'columns':[{'dimension':'S','direction':'descending'," + "'dimensionOrder':'numeric'}]},'aggregations':[{'type':'longSum'," + "'name':'S','fieldName':'unit_sales'},{'type':'longMax','name':'M'," + "'fieldName':'unit_sales'}]," + "'intervals':['1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z']}";
    sql(sql).returnsUnordered("S=12399; M=6; P=WA", "S=12297; M=7; P=WA", "S=10640; M=6; P=WA").explainContains(explain).queryContains(new DruidChecker(druidQueryPart1, druidQueryPart2));
}

