/**
 * Tests that conditions applied to time units extracted via the EXTRACT
 * function become ranges on the timestamp column
 *
 * <p>Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1334">[CALCITE-1334]
 * Convert predicates on EXTRACT function calls into date ranges</a>.
 */
@Test
void testFilterTimestamp() {
    String sql = "select count(*) as c\n" + "from \"foodmart\"\n" + "where extract(year from \"timestamp\") = 1997\n" + "and extract(month from \"timestamp\") in (4, 6)\n";
    final String explain = "PLAN=EnumerableInterpreter\n" + "  DruidQuery(table=[[foodmart, foodmart]], intervals=[[1997-04-01T00:00:00.000Z/" + "1997-05-01T00:00:00.000Z, 1997-06-01T00:00:00.000Z/1997-07-01T00:00:00.000Z]]," + " projects=[[0]], groups=[{}], aggs=[[COUNT()]])";
    CalciteAssert.AssertQuery q = sql(sql).returnsUnordered("C=13500");
    Assumptions.assumeTrue(Bug.CALCITE_4213_FIXED, "CALCITE-4213");
    q.explainContains(explain);
}

