@Test
void testCountColumn() {
    final String sql = "SELECT count(\"countryName\") FROM (SELECT \"countryName\" FROM " + "\"wikipedia\" WHERE \"countryName\"  IS NOT NULL) as a";
    sql(sql, WIKI_AUTO2).returnsUnordered("EXPR$0=3799");
    final String sql2 = "SELECT count(\"countryName\") FROM (SELECT \"countryName\" FROM " + "\"wikipedia\") as a";
    final String plan2 = "PLAN=EnumerableInterpreter\n" + "  DruidQuery(table=[[wiki, wikipedia]], " + "intervals=[[1900-01-01T00:00:00.000Z/3000-01-01T00:00:00.000Z]], projects=[[$6]], " + "groups=[{}], aggs=[[COUNT($0)]])";
    sql(sql2, WIKI_AUTO2).returnsUnordered("EXPR$0=3799").explainContains(plan2);
    final String sql3 = "SELECT count(*), count(\"countryName\") FROM \"wikipedia\"";
    final String plan3 = "PLAN=EnumerableInterpreter\n" + "  DruidQuery(table=[[wiki, wikipedia]], " + "intervals=[[1900-01-01T00:00:00.000Z/3000-01-01T00:00:00.000Z]], projects=[[$6]], " + "groups=[{}], aggs=[[COUNT(), COUNT($0)]])";
    sql(sql3, WIKI_AUTO2).explainContains(plan3);
}

