/**
 * Tests post-aggregation support with +, -, /, * operators.
 */
@Test
void testPostAggregationWithComplexColumns() {
    foodmartApprox("select " + "(count(distinct \"customer_id\") * 2) + " + "count(distinct \"customer_id\") - " + "(3 * count(distinct \"customer_id\")) " + "from \"foodmart\"").queryContains(new DruidChecker("\"postAggregations\":[{\"type\":\"expression\"," + "\"name\":\"EXPR$0\",\"expression\":\"(((\\\"$f0\\\" * 2) + \\\"$f0\\\")" + " - (3 * \\\"$f0\\\"))\"}]")).returnsUnordered("EXPR$0=0");
    foodmartApprox("select " + "\"the_month\" as \"month\", " + "sum(\"store_sales\") / count(distinct \"customer_id\") as \"avg$\" " + "from \"foodmart\" group by \"the_month\"").queryContains(new DruidChecker("'postAggregations':[{'type':'expression'," + "'name':'avg$','expression':'(\\'$f1\\' / \\'$f2\\')'}]")).returnsUnordered("month=January; avg$=32.62155444126063", "month=February; avg$=33.102021036814484", "month=March; avg$=33.84970906630567", "month=April; avg$=32.557517084282296", "month=May; avg$=32.42617797228287", "month=June; avg$=33.93093562874239", "month=July; avg$=34.36859097127213", "month=August; avg$=32.81181818181806", "month=September; avg$=33.327733840304155", "month=October; avg$=32.74730858468674", "month=November; avg$=34.51727684346705", "month=December; avg$=33.62788665879565");
    final String druid = "'postAggregations':[{'type':'expression','name':'EXPR$0'," + "'expression':'((\\'$f0\\' + 100) - (\\'$f0\\' * 2))'}]";
    final String sql = "select (count(distinct \"user_id\") + 100) - " + "(count(distinct \"user_id\") * 2) from \"wiki\"";
    wikiApprox(sql).queryContains(new DruidChecker(druid)).returnsUnordered("EXPR$0=-10590");
    // Change COUNT(DISTINCT ...) to APPROX_COUNT_DISTINCT(...) and get
    // same result even if approximation is off by default.
    final String sql2 = "select (approx_count_distinct(\"user_id\") + 100) - " + "(approx_count_distinct(\"user_id\") * 2) from \"wiki\"";
    sql(sql2, WIKI).queryContains(new DruidChecker(druid)).returnsUnordered("EXPR$0=-10590");
}

