/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1738">[CALCITE-1738]
 * Push CAST of literals to Druid</a>.
 */
@Test
void testFilterWithCast() {
    final Fixture2 f = new Fixture2();
    final Calendar c = Util.calendar();
    c.clear();
    c.set(2010, Calendar.JANUARY, 1);
    final TimestampString from = TimestampString.fromCalendarFields(c);
    c.clear();
    c.set(2011, Calendar.JANUARY, 1);
    final TimestampString to = TimestampString.fromCalendarFields(c);
    // d >= 2010-01-01 AND d < 2011-01-01
    checkDateRangeNoSimplify(f, f.and(f.ge(f.d, f.cast(f.timestampDataType, f.timestampLiteral(from))), f.lt(f.d, f.cast(f.timestampDataType, f.timestampLiteral(to)))), is("[2010-01-01T00:00:00.000Z/2011-01-01T00:00:00.000Z]"));
}

/**
 * Currently the patterns like below will be converted to Search in range
 * which is not supported in elastic search adapter.
 * (val1 >= 10 and val1 <= 20)
 * (val1 <= 10 or val1 >=20)
 * (val1 <= 10) or (val1 > 15 and val1 <= 20)
 * So disable this test case until the translation from Search in range
 * to rang Query in ES is implemented.
 */
@Test
void searchInRange() {
    Assumptions.assumeTrue(Bug.CALCITE_4645_FIXED, "CALCITE-4645");
    CalciteAssert.that().with(AggregationTest::createConnection).query("select count(*) from view where val1 >= 10 and val1 <=20").returns("EXPR$0=1\n");
    CalciteAssert.that().with(AggregationTest::createConnection).query("select count(*) from view where val1 <= 10 or val1 >=20").returns("EXPR$0=2\n");
    CalciteAssert.that().with(AggregationTest::createConnection).query("select count(*) from view where val1 <= 10 or (val1 > 15 and val1 <= 20)").returns("EXPR$0=2\n");
}

