/**
 * Sorting (and aggregating) directly on items without a view.
 *
 * <p>Queries of type:
 * {@code select _MAP['a'] from elastic order by _MAP['b']}
 */
@Test
void testSortNoSchema() {
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select * from elastic.zips order by _MAP['city']").returnsCount(ZIPS_SIZE);
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select * from elastic.zips where _MAP['state'] = 'NY' order by _MAP['city']").queryContains(ElasticsearchChecker.elasticsearchChecker("query:{'constant_score':{filter:{term:{state:'NY'}}}}", "sort:[{city:'asc'}]", String.format(Locale.ROOT, "size:%s", ElasticsearchTransport.DEFAULT_FETCH_SIZE))).returnsOrdered("_MAP={id=11226, city=BROOKLYN, loc=[-73.956985, 40.646694], pop=111396, state=NY}", "_MAP={id=11373, city=JACKSON HEIGHTS, loc=[-73.878551, 40.740388], pop=88241, state=NY}", "_MAP={id=10021, city=NEW YORK, loc=[-73.958805, 40.768476], pop=106564, state=NY}");
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select _MAP['state'] from elastic.zips order by _MAP['city']").returnsCount(ZIPS_SIZE);
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select * from elastic.zips where _MAP['state'] = 'NY' or " + "_MAP['city'] = 'BROOKLYN'" + " order by _MAP['city']").queryContains(ElasticsearchChecker.elasticsearchChecker("query:{'dis_max':{'queries':[{'bool':{'should':" + "[{'term':{'state':'NY'}},{'term':" + "{'city':'BROOKLYN'}}]}}]}},'sort':[{'city':'asc'}]", String.format(Locale.ROOT, "size:%s", ElasticsearchTransport.DEFAULT_FETCH_SIZE)));
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select _MAP['city'] from elastic.zips where _MAP['state'] = 'NY' " + "order by _MAP['city']").returnsOrdered("EXPR$0=BROOKLYN", "EXPR$0=JACKSON HEIGHTS", "EXPR$0=NEW YORK");
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select _MAP['city'] as city, _MAP['state'] from elastic.zips " + "order by _MAP['city'] asc").returns(sortedResultSetChecker("city", RelFieldCollation.Direction.ASCENDING)).returnsCount(ZIPS_SIZE);
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select _MAP['city'] as city, _MAP['state'] from elastic.zips " + "order by _MAP['city'] desc").returns(sortedResultSetChecker("city", RelFieldCollation.Direction.DESCENDING)).returnsCount(ZIPS_SIZE);
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select max(_MAP['pop']), min(_MAP['pop']), _MAP['state'] from elastic.zips " + "group by _MAP['state'] order by _MAP['state'] limit 3").returnsOrdered("EXPR$0=32383.0; EXPR$1=23238.0; EXPR$2=AK", "EXPR$0=44165.0; EXPR$1=42124.0; EXPR$2=AL", "EXPR$0=53532.0; EXPR$1=37428.0; EXPR$2=AR");
    CalciteAssert.that().with(ElasticSearchAdapterTest::createConnection).query("select max(_MAP['pop']), min(_MAP['pop']), _MAP['state'] from elastic.zips " + "where _MAP['state'] = 'NY' group by _MAP['state'] order by _MAP['state'] limit 3").returns("EXPR$0=111396.0; EXPR$1=88241.0; EXPR$2=NY\n");
}

