/**
 * Tests the ElasticSearch match query. The match query is translated from
 * CONTAINS query which is build using RelBuilder, RexBuilder because the
 * normal SQL query assumes CONTAINS query is for date/period range.
 *
 * <p>Equivalent SQL query:
 *
 * <blockquote>
 * <code>select * from zips where city contains 'waltham'</code>
 * </blockquote>
 *
 * <p>ElasticSearch query for it:
 *
 * <blockquote><code>
 * {"query":{"constant_score":{"filter":{"match":{"city":"waltham"}}}}}
 * </code></blockquote>
 */
@Test
void testMatchQuery() throws Exception {
    CalciteConnection con = createConnection();
    SchemaPlus postSchema = con.getRootSchema().getSubSchema("elastic");
    FrameworkConfig postConfig = Frameworks.newConfigBuilder().parserConfig(SqlParser.Config.DEFAULT).defaultSchema(postSchema).build();
    final RelBuilder builder = RelBuilder.create(postConfig);
    builder.scan(ZIPS);
    final RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    final RexBuilder rexBuilder = new RexBuilder(typeFactory);
    RexNode nameRexNode = rexBuilder.makeCall(SqlStdOperatorTable.ITEM, rexBuilder.makeInputRef(typeFactory.createSqlType(SqlTypeName.ANY), 0), rexBuilder.makeCharLiteral(new NlsString("city", typeFactory.getDefaultCharset().name(), SqlCollation.COERCIBLE)));
    RelDataType mapType = typeFactory.createMapType(typeFactory.createSqlType(SqlTypeName.VARCHAR), typeFactory.createTypeWithNullability(typeFactory.createSqlType(SqlTypeName.ANY), true));
    List<RexNode> namedList = ImmutableList.of(rexBuilder.makeInputRef(mapType, 0), nameRexNode);
    // Add fields in builder stack so it is accessible while filter preparation
    builder.projectNamed(namedList, Arrays.asList("_MAP", "city"), true);
    RexNode filterRexNode = builder.call(SqlStdOperatorTable.CONTAINS, builder.field("city"), builder.literal("waltham"));
    builder.filter(filterRexNode);
    String builderExpected = "" + "LogicalFilter(condition=[CONTAINS($1, 'waltham')])\n" + "  LogicalProject(_MAP=[$0], city=[ITEM($0, 'city')])\n" + "    ElasticsearchTableScan(table=[[elastic, " + ZIPS + "]])\n";
    RelNode root = builder.build();
    RelRunner ru = (RelRunner) con.unwrap(Class.forName("org.apache.calcite.tools.RelRunner"));
    try (PreparedStatement preparedStatement = ru.prepareStatement(root)) {
        String s = CalciteAssert.toString(preparedStatement.executeQuery());
        final String result = "" + "_MAP={id=02154, city=NORTH WALTHAM, loc=[-71.236497, 42.382492], " + "pop=57871, state=MA}; city=NORTH WALTHAM\n";
        // Validate query prepared
        assertThat(root, hasTree(builderExpected));
        // Validate result returned from ES
        assertThat(s, is(result));
    }
}

