@ParameterizedTest
@MethodSource("explainFormats")
void testPushDownProjectAggregate(String format) throws SQLException {
    String expected = null;
    String extra = null;
    switch(format) {
        case "dot":
            expected = "PLAN=digraph {\n" + "\"CsvTableScan\\ntable = [SALES, EMPS\\n]\\nfields = [3]\\n\" -> " + "\"EnumerableAggregate\\ngroup = {0}\\nEXPR$1 = COUNT()\\n\" [label=\"0\"]\n" + "}\n";
