/**
 * Unit test for {@link Functions#filter}.
 */
@Test
void testFilter() {
    final List<String> abc = Arrays.asList("A", "B", "C", "D");
    // a miss, then a hit
    assertEquals("[A, C, D]", Functions.filter(abc, v1 -> !v1.equals("B")).toString());
    // a hit, then all misses
    assertEquals("[A]", Functions.filter(abc, v1 -> v1.equals("A")).toString());
    // two hits, then a miss
    assertEquals("[A, B, D]", Functions.filter(abc, v1 -> !v1.equals("C")).toString());
    assertSame(Collections.emptyList(), Functions.filter(abc, Functions.falsePredicate1()));
    assertSame(abc, Functions.filter(abc, Functions.truePredicate1()));
}

