            return a0 == 0 ? "0" : "x" + apply(a0 - 1);
        }
    };
    assertEquals("[]", Functions.generate(0, xx).toString());
    assertEquals("[0]", Functions.generate(1, xx).toString());
    assertEquals("[0, x0, xx0]", Functions.generate(3, xx).toString());
    try {
        final List<String> generate = Functions.generate(-2, xx);
