@Test
void testType() {
    // Type of ternary operator is the gcd of its arguments.
    assertEquals(long.class, Expressions.condition(Expressions.constant(true), Expressions.constant(5), Expressions.constant(6L)).getType());
    assertEquals(long.class, Expressions.condition(Expressions.constant(true), Expressions.constant(5L), Expressions.constant(6)).getType());
    // If one of the arguments is null constant, it is implicitly coerced.
    assertEquals(String.class, Expressions.condition(Expressions.constant(true), Expressions.constant("xxx"), Expressions.constant(null)).getType());
    assertEquals(Integer.class, Expressions.condition(Expressions.constant(true), Expressions.constant(0), Expressions.constant(null)).getType());
    // In Java, "-" applied to short and byte yield int.
    assertEquals(double.class, Expressions.negate(Expressions.constant((double) 1)).getType());
    assertEquals(float.class, Expressions.negate(Expressions.constant((float) 1)).getType());
    assertEquals(long.class, Expressions.negate(Expressions.constant((long) 1)).getType());
    assertEquals(int.class, Expressions.negate(Expressions.constant(1)).getType());
    assertEquals(int.class, Expressions.negate(Expressions.constant((short) 1)).getType());
    assertEquals(int.class, Expressions.negate(Expressions.constant((byte) 1)).getType());
}

