    assertNotEquals(comparer.hashCode(emps[0]), comparer.hashCode(null));
    assertFalse(comparer.equal(null, emps[1]));
    assertTrue(comparer.equal(null, null));
    assertEquals(comparer.hashCode(null), comparer.hashCode(null));
}

