@Test
void cartesianProductWithReset() {
    Enumerator<List<Integer>> product = Linq4j.product(Arrays.asList(Linq4j.enumerator(Arrays.asList(1, 2)), Linq4j.enumerator(Arrays.asList(3, 4))));
    assertThat("cartesian product", contentsOf(product), hasToString("[[1, 3], [1, 4], [2, 3], [2, 4]]"));
    product.reset();
    assertThat("cartesian product after .reset()", contentsOf(product), hasToString("[[1, 3], [1, 4], [2, 3], [2, 4]]"));
    product.moveNext();
    product.reset();
    assertThat("cartesian product after .moveNext(); .reset()", contentsOf(product), hasToString("[[1, 3], [1, 4], [2, 3], [2, 4]]"));
}

