        // ok
    }
    try {
        EnumerableDefaults.sequenceEqual(enumerable1, null);
        fail();
    } catch (NullPointerException ignored) {
        // ok
    }
    assertFalse(// Keep as collection
    Linq4j.asEnumerable(enumerable1.skip(1).toList()).sequenceEqual(enumerable2));
    assertFalse(enumerable1.sequenceEqual(// Keep as collection
    Linq4j.asEnumerable(enumerable2.skip(1).toList())));
}

