@Test
void testOptimizeTernaryNullCasting2() {
    ParameterExpression o = Expressions.parameter(Boolean.class, "o");
    ParameterExpression v = Expressions.parameter(Boolean.class, "v");
    BlockStatement bl = Expressions.block(Expressions.declare(0, v, new ConstantExpression(Boolean.class, false)), Expressions.declare(0, o, Expressions.condition(v, new ConstantExpression(Object.class, null), new ConstantExpression(Boolean.class, true))));
    assertEquals("{\n  Boolean v = Boolean.valueOf(false);\n" + "  Boolean o = v ? null : Boolean.valueOf(true);\n}\n", optimize(bl));
    bl = Expressions.block(Expressions.declare(0, o, Expressions.orElse(new ConstantExpression(Boolean.class, true), new ConstantExpression(Boolean.class, null))));
    assertEquals("{\n  Boolean o = Boolean.valueOf(true) || (Boolean) null;\n}\n", optimize(bl));
    bl = Expressions.block(Expressions.declare(0, o, Expressions.orElse(new ConstantExpression(Boolean.class, null), new ConstantExpression(Boolean.class, true))));
    assertEquals("{\n  Boolean o = (Boolean) null || Boolean.valueOf(true);\n}\n", optimize(bl));
}

@Test
void testOptimizeBinaryNullCasting1() {
    ParameterExpression x = Expressions.variable(String.class, "x");
    ConstantExpression one = new ConstantExpression(String.class, "one");
    ConstantExpression second = new ConstantExpression(String.class, null);
    ConstantExpression innerExp = new ConstantExpression(Long.class, 2L);
    ParameterExpression y = Expressions.parameter(Long.class, "y");
    BinaryExpression exp0 = Expressions.greaterThan(y, innerExp);
    ConditionalStatement finalExp = Expressions.ifThenElse(exp0, Expressions.assign(x, one), Expressions.assign(x, second));
    assertEquals("{\n  if (y > Long.valueOf(2L)) {\n" + "    return x = \"one\";\n" + "  } else {\n" + "    return x = null;\n" + "  }\n}\n", optimize(finalExp));
}

