    assertModel(MODEL).query("select state, city from zips where state > 'WI' order by state, city").limit(3).returnsOrdered("STATE=WV; CITY=BECKLEY", "STATE=WV; CITY=ELM GROVE", "STATE=WV; CITY=STAR CITY");
}

/**
 * MongoDB's predicates are handed (they can only accept literals on the
