@Test
void testGroup() {
    // Syntax:
    //   alias = GROUP alias { ALL | BY expression}
    //     [, alias ALL | BY expression ...] [USING 'collected' | 'merge']
    //     [PARTITION BY partitioner] [PARALLEL n];
    // Equivalent to Pig Latin:
    //   r = GROUP e BY (deptno, job);
    final Function<PigRelBuilder, RelNode> f = builder -> builder.scan("EMP").group(null, null, -1, builder.groupKey("DEPTNO", "JOB").alias("e")).build();
    final String plan = "" + "LogicalAggregate(group=[{0, 1}], EMP=[COLLECT($2)])\n" + "  LogicalProject(JOB=[$2], DEPTNO=[$7], " + "$f8=[ROW($0, $1, $2, $3, $4, $5, $6, $7)])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(str(f.apply(createBuilder(b -> b))), is(plan));
    // now without pruning
    final String plan2 = "" + "LogicalAggregate(group=[{2, 7}], EMP=[COLLECT($8)])\n" + "  LogicalProject(EMPNO=[$0], ENAME=[$1], JOB=[$2], MGR=[$3], " + "HIREDATE=[$4], SAL=[$5], COMM=[$6], DEPTNO=[$7], $f8=[ROW($0, $1, $2, $3, $4, $5, $6, $7)])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(str(f.apply(createBuilder(b -> b.withPruneInputOfAggregate(false)))), is(plan2));
}

