@Test
void testGroupby() {
    final String baseScript = "A = LOAD 'scott.DEPT' as (DEPTNO:int, DNAME:chararray, LOC:CHARARRAY);
";
    final String basePlan = "      LogicalTableScan(table=[[scott, DEPT]])
";
    final String script = baseScript + "B = GROUP A BY DEPTNO;
";
    final String plan = "" + "LogicalProject(group=[$0], A=[$1])
" + "  LogicalAggregate(group=[{0}], A=[COLLECT($1)])
" + "    LogicalProject(DEPTNO=[$0], $f1=[ROW($0, $1, $2)])
" + basePlan;
    final String result = "" + "(20,{(20,RESEARCH,DALLAS)})
" + "(40,{(40,OPERATIONS,BOSTON)})
" + "(10,{(10,ACCOUNTING,NEW YORK)})
" + "(30,{(30,SALES,CHICAGO)})
";
    final String sql = "" + "SELECT DEPTNO, COLLECT(ROW(DEPTNO, DNAME, LOC)) AS A
" + "FROM scott.DEPT
" + "GROUP BY DEPTNO";
    pig(script).assertRel(hasTree(plan)).assertResult(is(result)).assertSql(is(sql));
    final String script1 = baseScript + "B = GROUP A ALL;
";
    final String plan1 = "" + "LogicalProject(group=[$0], A=[$1])
" + "  LogicalAggregate(group=[{0}], A=[COLLECT($1)])
" + "    LogicalProject($f0=['all'], $f1=[ROW($0, $1, $2)])
" + basePlan;
    final String result1 = "" + "(all,{(10,ACCOUNTING,NEW YORK),(20,RESEARCH,DALLAS)," + "(30,SALES,CHICAGO),(40,OPERATIONS,BOSTON)})
";
    pig(script1).assertResult(is(result1)).assertRel(hasTree(plan1));
}

