/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-6022">[CALCITE-6022]
 * Support "CREATE TABLE ... LIKE" DDL in server module</a>.
 */
@Test
void testCreateTableLikeWithStoredGeneratedColumn() throws Exception {
    try (Connection c = connect();
        Statement s = c.createStatement()) {
        s.execute("create table t (\n" + " h int not null,\n" + " i int,\n" + " j int as (i + 1) stored,\n" + " k int default -1)\n");
        s.execute("create table t2 like t including defaults including generated");
        int x = s.executeUpdate("insert into t2 (h, i) values (3, 4)");
        assertThat(x, is(1));
        final String sql1 = "explain plan for\n" + "insert into t2 (h, i) values (3, 4)";
        try (ResultSet r = s.executeQuery(sql1)) {
            assertThat(r.next(), is(true));
            final String plan = "" + "EnumerableTableModify(table=[[T2]], operation=[INSERT], flattened=[false])\n" + "  EnumerableCalc(expr#0..1=[{inputs}], expr#2=[1], expr#3=[+($t1, $t2)], expr#4=[-1], proj#0..1=[{exprs}], J=[$t3], K=[$t4])\n" + "    EnumerableValues(tuples=[[{ 3, 4 }]])\n";
            assertThat(r.getString(1), isLinux(plan));
            assertThat(r.next(), is(false));
        }
        try (ResultSet r = s.executeQuery("select * from t2")) {
            assertThat(r.next(), is(true));
            assertThat(r.getInt("H"), is(3));
            assertThat(r.wasNull(), is(false));
            assertThat(r.getInt("I"), is(4));
            // j = i + 1
            assertThat(r.getInt("J"), is(5));
            // k = -1 (default)
            assertThat(r.getInt("K"), is(-1));
            assertThat(r.next(), is(false));
        }
        SQLException e = assertThrows(SQLException.class, () -> s.executeUpdate("insert into t2 values (3, 4, 5, 6)"));
        assertThat(e.getMessage(), containsString("Cannot INSERT into generated column 'J'"));
    }
}

