@Test
void testHyphenatedTableName() {
    sql("select * from bigquery^-^foo-bar.baz").fails("(?s)Encountered "-" at .*").withDialect(BIG_QUERY).ok("SELECT *
" + "FROM `bigquery-foo-bar`.baz");
    // Like BigQuery, MySQL allows back-ticks.
    sql("select `baz`.`buzz` from foo.`baz`").withDialect(BIG_QUERY).ok("SELECT baz.buzz
" + "FROM foo.baz").withDialect(MYSQL).ok("SELECT `baz`.`buzz`
" + "FROM `foo`.`baz`");
    // Unlike BigQuery, MySQL does not allow hyphenated identifiers.
    sql("select `baz`.`buzz` from foo^-^bar.`baz`").withDialect(BIG_QUERY).ok("SELECT baz.buzz
" + "FROM `foo-bar`.baz").withDialect(MYSQL).fails("(?s)Encountered "-" at .*");
    // No hyphenated identifiers as table aliases.
    sql("select * from foo.baz as hyphenated^-^alias-not-allowed").withDialect(BIG_QUERY).fails("(?s)Encountered "-" at .*");
    sql("select * from foo.baz as `hyphenated-alias-allowed-if-quoted`").withDialect(BIG_QUERY).ok("SELECT *
" + "FROM foo.baz AS `hyphenated-alias-allowed-if-quoted`");
    // No hyphenated identifiers as column names.
    sql("select * from foo-bar.baz cross join (select alpha-omega from t) as t").withDialect(BIG_QUERY).ok("SELECT *
" + "FROM `foo-bar`.baz
" + "CROSS JOIN (SELECT (alpha - omega)
" + "FROM t) AS t");
    sql("select * from bigquery-foo-bar.baz as hyphenated^-^alias-not-allowed").withDialect(BIG_QUERY).fails("(?s)Encountered "-" at .*");
    sql("insert into bigquery^-^public-data.foo values (1)").fails("Non-query expression encountered in illegal context").withDialect(BIG_QUERY).ok("INSERT INTO `bigquery-public-data`.foo
" + "VALUES (1)");
    sql("update bigquery^-^public-data.foo set a = b").fails("(?s)Encountered "-" at .*").withDialect(BIG_QUERY).ok("UPDATE `bigquery-public-data`.foo SET a = b");
    sql("delete from bigquery^-^public-data.foo where a = 5").fails("(?s)Encountered "-" at .*").withDialect(BIG_QUERY).ok("DELETE FROM `bigquery-public-data`.foo
" + "WHERE (a = 5)");
    final String mergeSql = "merge into bigquery^-^public-data.emps e
" + "using (
" + "  select *
" + "  from bigquery-public-data.tempemps
" + "  where deptno is null) t
" + "on e.empno = t.empno
" + "when matched then
" + "  update set name = t.name, deptno = t.deptno,
" + "    salary = t.salary * .1
" + "when not matched then
" + "    insert (name, dept, salary)
" + "    values(t.name, 10, t.salary * .15)";
    final String mergeExpected = "MERGE INTO `bigquery-public-data`.emps AS e
" + "USING (SELECT *
" + "FROM `bigquery-public-data`.tempemps
" + "WHERE (deptno IS NULL)) AS t
" + "ON (e.empno = t.empno)
" + "WHEN MATCHED THEN" + " UPDATE SET name = t.name, deptno = t.deptno," + " salary = (t.salary * 0.1)
" + "WHEN NOT MATCHED THEN" + " INSERT (name, dept, salary)" + " VALUES (t.name, 10, (t.salary * 0.15))";
    sql(mergeSql).fails("(?s)Encountered "-" at .*").withDialect(BIG_QUERY).ok(mergeExpected);
    // Hyphenated identifiers may not contain spaces, even in BigQuery.
    sql("select * from bigquery ^-^ foo - bar as t where x < y").fails("(?s)Encountered "-" at .*").withDialect(BIG_QUERY).fails("(?s)Encountered "-" at .*");
}

