@Test
void testBetween() {
    sql("select * from t where price between 1 and 2").ok("SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` BETWEEN ASYMMETRIC 1 AND 2)");
    sql("select * from t where price between symmetric 1 and 2").ok("SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` BETWEEN SYMMETRIC 1 AND 2)");
    sql("select * from t where price not between symmetric 1 and 2").ok("SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` NOT BETWEEN SYMMETRIC 1 AND 2)");
    sql("select * from t where price between ASYMMETRIC 1 and 2+2*2").ok("SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` BETWEEN ASYMMETRIC 1 AND (2 + (2 * 2)))");
    final String sql0 = "select * from t\n" + " where price > 5\n" + " and price not between 1 + 2 and 3 * 4 AnD price is null";
    final String expected0 = "SELECT *\n" + "FROM `T`\n" + "WHERE (((`PRICE` > 5) " + "AND (`PRICE` NOT BETWEEN ASYMMETRIC (1 + 2) AND (3 * 4))) " + "AND (`PRICE` IS NULL))";
    sql(sql0).ok(expected0);
    final String sql1 = "select * from t\n" + "where price > 5\n" + "and price between 1 + 2 and 3 * 4 + price is null";
    final String expected1 = "SELECT *\n" + "FROM `T`\n" + "WHERE ((`PRICE` > 5) " + "AND ((`PRICE` BETWEEN ASYMMETRIC (1 + 2) AND ((3 * 4) + `PRICE`)) " + "IS NULL))";
    sql(sql1).ok(expected1);
    final String sql2 = "select * from t\n" + "where price > 5\n" + "and price between 1 + 2 and 3 * 4 or price is null";
    final String expected2 = "SELECT *\n" + "FROM `T`\n" + "WHERE (((`PRICE` > 5) " + "AND (`PRICE` BETWEEN ASYMMETRIC (1 + 2) AND (3 * 4))) " + "OR (`PRICE` IS NULL))";
    sql(sql2).ok(expected2);
    final String sql3 = "values a between c and d and e and f between g and h";
    final String expected3 = "VALUES (" + "ROW((((`A` BETWEEN ASYMMETRIC `C` AND `D`) AND `E`)" + " AND (`F` BETWEEN ASYMMETRIC `G` AND `H`))))";
    sql(sql3).ok(expected3);
    sql("values a between b or c^").fails(".*BETWEEN operator has no terminating AND");
    sql("values a ^between^").fails("(?s).*Encountered \"between <EOF>\" at line 1, column 10.*");
    sql("values a between symmetric 1^").fails(".*BETWEEN operator has no terminating AND");
    // precedence of BETWEEN is higher than AND and OR, but lower than '+'
    sql("values a between b and c + 2 or d and e").ok("VALUES (ROW(((`A` BETWEEN ASYMMETRIC `B` AND (`C` + 2)) OR (`D` AND `E`))))");
    // '=' has slightly lower precedence than BETWEEN; both are left-assoc
    sql("values x = a between b and c = d = e").ok("VALUES (ROW((((`X` = (`A` BETWEEN ASYMMETRIC `B` AND `C`)) = `D`) = `E`)))");
    // AND doesn't match BETWEEN if it's between parentheses!
    sql("values a between b or (c and d) or e and f").ok("VALUES (ROW((`A` BETWEEN ASYMMETRIC ((`B` OR (`C` AND `D`)) OR `E`) AND `F`)))");
}

