@Test
void testRow() {
    sql("select t.r.\"EXPR$1\", t.r.\"EXPR$0\" from (select (1,2) r from sales.depts) t").ok("SELECT `T`.`R`.`EXPR$1`, `T`.`R`.`EXPR$0`\n" + "FROM (SELECT (ROW(1, 2)) AS `R`\n" + "FROM `SALES`.`DEPTS`) AS `T`");
    sql("select t.r.\"EXPR$1\".\"EXPR$2\" " + "from (select ((1,2),(3,4,5)) r from sales.depts) t").ok("SELECT `T`.`R`.`EXPR$1`.`EXPR$2`\n" + "FROM (SELECT (ROW((ROW(1, 2)), (ROW(3, 4, 5)))) AS `R`\n" + "FROM `SALES`.`DEPTS`) AS `T`");
    sql("select t.r.\"EXPR$1\".\"EXPR$2\" " + "from (select ((1,2),(3,4,5,6)) r from sales.depts) t").ok("SELECT `T`.`R`.`EXPR$1`.`EXPR$2`\n" + "FROM (SELECT (ROW((ROW(1, 2)), (ROW(3, 4, 5, 6)))) AS `R`\n" + "FROM `SALES`.`DEPTS`) AS `T`");
    // Conformance DEFAULT and LENIENT support explicit row value constructor
    final String selectRow = "select ^row(t1a, t2a)^ from t1";
    final String expected = "SELECT (ROW(`T1A`, `T2A`))\n" + "FROM `T1`";
    sql(selectRow).withConformance(SqlConformanceEnum.DEFAULT).ok(expected);
    sql(selectRow).withConformance(SqlConformanceEnum.LENIENT).ok(expected);
    final String pattern = "ROW expression encountered in illegal context";
    sql(selectRow).withConformance(SqlConformanceEnum.MYSQL_5).fails(pattern);
    sql(selectRow).withConformance(SqlConformanceEnum.ORACLE_12).fails(pattern);
    sql(selectRow).withConformance(SqlConformanceEnum.STRICT_2003).fails(pattern);
    sql(selectRow).withConformance(SqlConformanceEnum.SQL_SERVER_2008).fails(pattern);
    final String whereRow = "select 1 from t2 where ^row (x, y)^ < row (a, b)";
    final String whereExpected = "SELECT 1\n" + "FROM `T2`\n" + "WHERE ((ROW(`X`, `Y`)) < (ROW(`A`, `B`)))";
    sql(whereRow).withConformance(SqlConformanceEnum.DEFAULT).ok(whereExpected);
    sql(whereRow).withConformance(SqlConformanceEnum.SQL_SERVER_2008).fails(pattern);
    final String whereRow2 = "select 1 from t2 where ^(x, y)^ < (a, b)";
    sql(whereRow2).withConformance(SqlConformanceEnum.DEFAULT).ok(whereExpected);
    // After this point, SqlUnparserTest has problems.
    // We generate ROW in a dialect that does not allow ROW in all contexts.
    // So bail out.
    assumeFalse(fixture().tester.isUnparserTest());
    sql(whereRow2).withConformance(SqlConformanceEnum.SQL_SERVER_2008).ok(whereExpected);
}

