@Test
void testLikeAndSimilar() {
    sql("select * from t where x like '%abc%'").ok("SELECT *\n" + "FROM `T`\n" + "WHERE (`X` LIKE '%abc%')");
    sql("select * from t where x+1 not siMilaR to '%abc%' ESCAPE 'e'").ok("SELECT *\n" + "FROM `T`\n" + "WHERE ((`X` + 1) NOT SIMILAR TO '%abc%' ESCAPE 'e')");
    // LIKE has higher precedence than AND
    sql("select * from t where price > 5 and x+2*2 like y*3+2 escape (select*from t)").ok("SELECT *\n" + "FROM `T`\n" + "WHERE ((`PRICE` > 5) AND ((`X` + (2 * 2)) LIKE ((`Y` * 3) + 2) ESCAPE (SELECT *\n" + "FROM `T`)))");
    sql("values a and b like c").ok("VALUES (ROW((`A` AND (`B` LIKE `C`))))");
    // LIKE has higher precedence than AND
    sql("values a and b like c escape d and e").ok("VALUES (ROW(((`A` AND (`B` LIKE `C` ESCAPE `D`)) AND `E`)))");
    // LIKE has same precedence as '='; LIKE is right-assoc, '=' is left
    sql("values a = b like c = d").ok("VALUES (ROW(((`A` = (`B` LIKE `C`)) = `D`)))");
    // Nested LIKE
    sql("values a like b like c escape d").ok("VALUES (ROW((`A` LIKE (`B` LIKE `C` ESCAPE `D`))))");
    sql("values a like b like c escape d and false").ok("VALUES (ROW(((`A` LIKE (`B` LIKE `C` ESCAPE `D`)) AND FALSE)))");
    sql("values a like b like c like d escape e escape f").ok("VALUES (ROW((`A` LIKE (`B` LIKE (`C` LIKE `D` ESCAPE `E`) ESCAPE `F`))))");
    // Mixed LIKE and SIMILAR TO
    sql("values a similar to b like c similar to d escape e escape f").ok("VALUES (ROW((`A` SIMILAR TO (`B` LIKE (`C` SIMILAR TO `D` ESCAPE `E`) ESCAPE `F`))))");
    if (isReserved("ESCAPE")) {
        sql("select * from t where ^escape^ 'e'").fails("(?s).*Encountered \"escape\" at .*");
    }
    // LIKE with +
    sql("values a like b + c escape d").ok("VALUES (ROW((`A` LIKE (`B` + `C`) ESCAPE `D`)))");
    // LIKE with ||
    sql("values a like b || c escape d").ok("VALUES (ROW((`A` LIKE (`B` || `C`) ESCAPE `D`)))");
    // ESCAPE with no expression
    if (isReserved("ESCAPE")) {
        sql("values a ^like^ escape d").fails("(?s).*Encountered \"like escape\" at .*");
    }
    // ESCAPE with no expression
    if (isReserved("ESCAPE")) {
        sql("values a like b || c ^escape^ and false").fails("(?s).*Encountered \"escape and\" at line 1, column 22.*");
    }
    // basic SIMILAR TO
    sql("select * from t where x similar to '%abc%'").ok("SELECT *\n" + "FROM `T`\n" + "WHERE (`X` SIMILAR TO '%abc%')");
    sql("select * from t where x+1 not siMilaR to '%abc%' ESCAPE 'e'").ok("SELECT *\n" + "FROM `T`\n" + "WHERE ((`X` + 1) NOT SIMILAR TO '%abc%' ESCAPE 'e')");
    // SIMILAR TO has higher precedence than AND
    sql("select * from t where price > 5 and x+2*2 SIMILAR TO y*3+2 escape (select*from t)").ok("SELECT *\n" + "FROM `T`\n" + "WHERE ((`PRICE` > 5) AND ((`X` + (2 * 2)) SIMILAR TO ((`Y` * 3) + 2) ESCAPE (SELECT *\n" + "FROM `T`)))");
    // Mixed LIKE and SIMILAR TO
    sql("values a similar to b like c similar to d escape e escape f").ok("VALUES (ROW((`A` SIMILAR TO (`B` LIKE (`C` SIMILAR TO `D` ESCAPE `E`) ESCAPE `F`))))");
    // SIMILAR TO with sub-query
    sql("values a similar to (select * from t where a like b escape c) escape d").ok("VALUES (ROW((`A` SIMILAR TO (SELECT *\n" + "FROM `T`\n" + "WHERE (`A` LIKE `B` ESCAPE `C`)) ESCAPE `D`)))");
}

@Test
void testIlike() {
    // The ILIKE operator is only valid when the PostgreSQL function library is
    // enabled ('fun=postgresql'). But the parser can always parse it.
    final String expected = "SELECT *\n" + "FROM `T`\n" + "WHERE (`X` NOT ILIKE '%abc%')";
    final String sql = "select * from t where x not ilike '%abc%'";
    sql(sql).ok(expected);
    final String sql1 = "select * from t where x ilike '%abc%'";
    final String expected1 = "SELECT *\n" + "FROM `T`\n" + "WHERE (`X` ILIKE '%abc%')";
    sql(sql1).ok(expected1);
}

@Test
void testRlike() {
    // The RLIKE operator is valid when the HIVE or SPARK function library is
    // enabled ('fun=spark' or 'fun=hive'). But the parser can always parse it.
    final String expected = "SELECT `COLA`\n" + "FROM `T`\n" + "WHERE (MAX(`EMAIL`) RLIKE '.+@.+\\\\..+')";
    final String sql = "select cola from t where max(email) rlike '.+@.+\\\\..+'";
    sql(sql).ok(expected);
    final String expected1 = "SELECT `COLA`\n" + "FROM `T`\n" + "WHERE (MAX(`EMAIL`) NOT RLIKE '.+@.+\\\\..+')";
    final String sql1 = "select cola from t where max(email) not rlike '.+@.+\\\\..+'";
    sql(sql1).ok(expected1);
}

