    expr("E'\141'").ok("_UTF16'a'");
    expr("E'\141\141\141'").ok("_UTF16'aaa'");
    expr("E'\1411'").ok("_UTF16'a1'");
    expr("E'\\x61'").ok("_UTF16'a'");
    expr("E'\\x61\\x61\\x61'").ok("_UTF16'aaa'");
    expr("E'\\x61\\x61\\x61'").ok("_UTF16'aaa'");
    expr("E'\\xDg0000'").ok("_UTF16'\rg0000'");
    expr("E'\\u0061'").ok("_UTF16'a'");
    expr("E'\\u0061\\u0061\\u0061'").ok("_UTF16'aaa'");
    expr("E'\\U00000061'").ok("_UTF16'a'");
    expr("E'\\U00000061\\U00000061\\U00000061'").ok("_UTF16'aaa'");
    expr("E'\\0'").ok("_UTF16'\u0000'");
    expr("E'\\07'").ok("_UTF16'\u0007'");
    expr("E'\\07'").ok("_UTF16'\u0007'");
    expr("E'a\\'a\\'a\\''").ok("_UTF16'a''a''a'''");
    expr("E'a''a''a'''").ok("_UTF16'a''a''a'''");
    expr("E^'\\'^").fails("(?s).*Encountered .*");
    expr("E^'a\\'^").fails("(?s).*Encountered.*");
    expr("E'a\\''^a^'").fails("(?s).*Encountered.*");
    expr("^E'A\\U0061'^").fails(RESOURCE.unicodeEscapeMalformed(1).str());
    expr("^E'AB\\U0000006G'^").fails(RESOURCE.unicodeEscapeMalformed(2).str());
}

