@Test
void testIdentifier() {
    expr("ab").ok("`AB`");
    expr("     \"a  \"\" b!c\"").ok("`a  \" b!c`");
    expr("     ^`^a  \" b!c`").fails("(?s).*Encountered.*");
    expr("\"x`y`z\"").ok("`x``y``z`");
    expr("^`^x`y`z`").fails("(?s).*Encountered.*");
    expr("myMap[field] + myArray[1 + 2]").ok("(`MYMAP`[`FIELD`] + `MYARRAY`[(1 + 2)])");
    sql("VALUES a").node(isQuoted(0, false));
    sql("VALUES \"a\"").node(isQuoted(0, true));
    sql("VALUES \"a\".\"b\"").node(isQuoted(1, true));
    sql("VALUES \"a\".b").node(isQuoted(1, false));
}

@Test
void testBackTickIdentifier() {
    SqlParserFixture f = fixture().withConfig(c -> c.withQuoting(Quoting.BACK_TICK)).expression();
    f.sql("ab").ok("`AB`");
    f.sql("     `a  \" b!c`").ok("`a  \" b!c`");
    f.sql("     ^\"^a  \"\" b!c\"").fails("(?s).*Encountered.*");
    f.sql("^\"^x`y`z\"").fails("(?s).*Encountered.*");
    f.sql("`x``y``z`").same();
    f.sql("`x\\`^y^\\`z`").fails("(?s).*Encountered.*");
    f.sql("myMap[field] + myArray[1 + 2]").ok("(`MYMAP`[`FIELD`] + `MYARRAY`[(1 + 2)])");
    f = f.expression(false);
    f.sql("VALUES a").node(isQuoted(0, false));
    f.sql("VALUES `a`").node(isQuoted(0, true));
    f.sql("VALUES `a``b`").node(isQuoted(0, true));
}

@Test
void testBackTickBackslashIdentifier() {
    SqlParserFixture f = fixture().withConfig(c -> c.withQuoting(Quoting.BACK_TICK_BACKSLASH)).expression();
    f.sql("ab").ok("`AB`");
    f.sql("     `a  \" b!c`").ok("`a  \" b!c`");
    f.sql("     \"a  \"^\" b!c\"^").fails("(?s).*Encountered.*");
    // BACK_TICK_BACKSLASH identifiers implies
    // BigQuery dialect, which implies double-quoted character literals.
    f.sql("^\"^x`y`z\"").ok("'x`y`z'");
    f.sql("`x`^`y`^`z`").fails("(?s).*Encountered.*");
    f.sql("`x\\`y\\`z`").ok("`x``y``z`");
    f.sql("myMap[field] + myArray[1 + 2]").ok("(`MYMAP`[`FIELD`] + `MYARRAY`[(1 + 2)])");
    f = f.expression(false);
    f.sql("VALUES a").node(isQuoted(0, false));
    f.sql("VALUES `a`").node(isQuoted(0, true));
    f.sql("VALUES `a\\`b`").node(isQuoted(0, true));
}

@Test
void testBracketIdentifier() {
    SqlParserFixture f = fixture().withConfig(c -> c.withQuoting(Quoting.BRACKET)).expression();
    f.sql("ab").ok("`AB`");
    f.sql("     [a  \" b!c]").ok("`a  \" b!c`");
    f.sql("     ^`^a  \" b!c`").fails("(?s).*Encountered.*");
    f.sql("     ^\"^a  \"\" b!c\"").fails("(?s).*Encountered.*");
    f.sql("[x`y`z]").ok("`x``y``z`");
    f.sql("^\"^x`y`z\"").fails("(?s).*Encountered.*");
    f.sql("^`^x``y``z`").fails("(?s).*Encountered.*");
    f.sql("[anything [even brackets]] is].[ok]").ok("`anything [even brackets] is`.`ok`");
    // What would be a call to the 'item' function in DOUBLE_QUOTE and BACK_TICK
    // is a table alias.
    f = f.expression(false);
    f.sql("select * from myMap[field], myArray[1 + 2]").ok("SELECT *\n" + "FROM `MYMAP` AS `field`,\n" + "`MYARRAY` AS `1 + 2`");
    f.sql("select * from myMap [field], myArray [1 + 2]").ok("SELECT *\n" + "FROM `MYMAP` AS `field`,\n" + "`MYARRAY` AS `1 + 2`");
    f.sql("VALUES a").node(isQuoted(0, false));
    f.sql("VALUES [a]").node(isQuoted(0, true));
}

