/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4080">[CALCITE-4080]
 * Allow character literals as column aliases, if
 * SqlConformance.allowCharLiteralAlias()</a>.
 */
@Test
void testSingleQuotedAlias() {
    final String expectingAlias = "Expecting alias, found character literal";
    final String sql1 = "select 1 as ^'a b'^ from t";
    sql(sql1).withConformance(SqlConformanceEnum.DEFAULT).fails(expectingAlias);
    final String sql1b = "SELECT 1 AS `a b`\n" + "FROM `T`";
    sql(sql1).withConformance(SqlConformanceEnum.MYSQL_5).ok(sql1b);
    sql(sql1).withConformance(SqlConformanceEnum.BIG_QUERY).ok(sql1b);
    sql(sql1).withConformance(SqlConformanceEnum.SQL_SERVER_2008).ok(sql1b);
    // valid on MSSQL (alias contains a single quote)
    final String sql2 = "with t as (select 1 as ^'x''y'^)\n" + "select [x'y] from t as [u]";
    final SqlParserFixture f2 = sql(sql2).withConfig(c -> c.withQuoting(Quoting.BRACKET).withConformance(SqlConformanceEnum.DEFAULT));
    f2.fails(expectingAlias);
    final String sql2b = "WITH `T` AS (SELECT 1 AS `x'y`) SELECT `x'y`\n" + "FROM `T` AS `u`";
    f2.withConformance(SqlConformanceEnum.MYSQL_5).ok(sql2b);
    f2.withConformance(SqlConformanceEnum.BIG_QUERY).ok(sql2b);
    f2.withConformance(SqlConformanceEnum.SQL_SERVER_2008).ok(sql2b);
    // also valid on MSSQL
    final String sql3 = "with [t] as (select 1 as [x]) select [x] from [t]";
    final String sql3b = "WITH `t` AS (SELECT 1 AS `x`) SELECT `x`\n" + "FROM `t`";
    final SqlParserFixture f3 = sql(sql3).withConfig(c -> c.withQuoting(Quoting.BRACKET).withConformance(SqlConformanceEnum.DEFAULT));
    f3.ok(sql3b);
    f3.withConformance(SqlConformanceEnum.MYSQL_5).ok(sql3b);
    f3.withConformance(SqlConformanceEnum.BIG_QUERY).ok(sql3b);
    f3.withConformance(SqlConformanceEnum.SQL_SERVER_2008).ok(sql3b);
    // char literal as table alias is invalid on MSSQL (and others)
    final String sql4 = "with t as (select 1 as x) select x from t as ^'u'^";
    final String sql4b = "(?s)Encountered \"\\\\'u\\\\'\" at .*";
    final SqlParserFixture f4 = sql(sql4).withConfig(c -> c.withQuoting(Quoting.BRACKET).withConformance(SqlConformanceEnum.DEFAULT));
    f4.fails(sql4b);
    f4.withConformance(SqlConformanceEnum.MYSQL_5).fails(sql4b);
    f4.withConformance(SqlConformanceEnum.BIG_QUERY).fails(sql4b);
    f4.withConformance(SqlConformanceEnum.SQL_SERVER_2008).fails(sql4b);
    // char literal as table alias (without AS) is invalid on MSSQL (and others)
    final String sql5 = "with t as (select 1 as x) select x from t ^'u'^";
    final String sql5b = "(?s)Encountered \"\\\\'u\\\\'\" at .*";
    final SqlParserFixture f5 = sql(sql5).withConfig(c -> c.withQuoting(Quoting.BRACKET).withConformance(SqlConformanceEnum.DEFAULT));
    f5.fails(sql5b);
    f5.withConformance(SqlConformanceEnum.MYSQL_5).fails(sql5b);
    f5.withConformance(SqlConformanceEnum.BIG_QUERY).fails(sql5b);
    f5.withConformance(SqlConformanceEnum.SQL_SERVER_2008).fails(sql5b);
}

