@Test
void testUnionOffset() {
    // Note that the second sub-query has parentheses, to ensure that ORDER BY,
    // OFFSET, FETCH are associated with just that sub-query, not the UNION.
    final String sql = "select a from t
" + "union all
" + "(select b from t order by b offset 3 fetch next 5 rows only)";
    final String expected = "SELECT `A`
" + "FROM `T`
" + "UNION ALL
" + "(SELECT `B`
" + "FROM `T`
" + "ORDER BY `B`
" + "OFFSET 3 ROWS
" + "FETCH NEXT 5 ROWS ONLY)";
    sql(sql).ok(expected);
    // as above, just ORDER BY
    final String sql2 = "select a from t
" + "union all
" + "(select b from t order by b)";
    final String expected2 = "SELECT `A`
" + "FROM `T`
" + "UNION ALL
" + "(SELECT `B`
" + "FROM `T`
" + "ORDER BY `B`)";
    sql(sql2).ok(expected2);
    // as above, just OFFSET
    final String sql3 = "select a from t
" + "union all
" + "(select b from t offset 3)";
    final String expected3 = "SELECT `A`
" + "FROM `T`
" + "UNION ALL
" + "(SELECT `B`
" + "FROM `T`
" + "OFFSET 3 ROWS)";
    sql(sql3).ok(expected3);
    // as above, just FETCH
    final String sql4 = "select a from t
" + "union all
" + "(select b from t fetch next 5 rows only)";
    final String expected4 = "SELECT `A`
" + "FROM `T`
" + "UNION ALL
" + "(SELECT `B`
" + "FROM `T`
" + "FETCH NEXT 5 ROWS ONLY)";
    sql(sql4).ok(expected4);
    // as above, just FETCH and OFFSET
    final String sql5 = "select a from t
" + "union all
" + "(select b from t offset 3 fetch next 5 rows only)";
    final String expected5 = "SELECT `A`
" + "FROM `T`
" + "UNION ALL
" + "(SELECT `B`
" + "FROM `T`
" + "OFFSET 3 ROWS
" + "FETCH NEXT 5 ROWS ONLY)";
    sql(sql5).ok(expected5);
    // as previous, INTERSECT
    final String sql6 = "select a from t
" + "intersect
" + "(select b from t offset 3 fetch next 5 rows only)";
    final String expected6 = "SELECT `A`
" + "FROM `T`
" + "INTERSECT
" + "(SELECT `B`
" + "FROM `T`
" + "OFFSET 3 ROWS
" + "FETCH NEXT 5 ROWS ONLY)";
    sql(sql6).ok(expected6);
}

