@Test
void testJoinAssociativity() {
    // joins are left-associative
    // 1. no parens needed
    String expected = "SELECT *\n" + "FROM `A`\n" + "NATURAL LEFT JOIN `B`\n" + "LEFT JOIN `C` ON (`B`.`C1` = `C`.`C1`)";
    sql("select * from (a natural left join b) left join c on b.c1 = c.c1").ok(expected);
    // 2. parens needed
    String expected2 = "SELECT *\n" + "FROM `A`\n" + "NATURAL LEFT JOIN (`B` LEFT JOIN `C` ON (`B`.`C1` = `C`.`C1`))";
    sql("select * from a natural left join (b left join c on b.c1 = c.c1)").ok(expected2);
    // 3. same as 1
    sql("select * from a natural left join b left join c on b.c1 = c.c1").ok(expected);
    // bushy
    String sql4 = "select *\n" + "from (a cross join b)\n" + "cross join (c cross join d)";
    String expected4 = "SELECT *\n" + "FROM `A`\n" + "CROSS JOIN `B`\n" + "CROSS JOIN (`C` CROSS JOIN `D`)";
    sql(sql4).ok(expected4);
}

