/**
 * Tests CROSS APPLY, which is equivalent to CROSS JOIN and LEFT JOIN but
 * only supported in some conformance levels (e.g. SQL Server).
 */
@Test
void testApply() {
    final String pattern = "APPLY operator is not allowed under the current SQL conformance level";
    final String sql = "select * from dept\n" + "cross apply table(ramp(deptno)) as t(a^)^";
    sql(sql).fails(pattern);
    final String expected = "SELECT *\n" + "FROM `DEPT`\n" + "CROSS JOIN LATERAL TABLE(`RAMP`(`DEPTNO`)) AS `T` (`A`)";
    sql(sql).withConformance(SqlConformanceEnum.SQL_SERVER_2008).ok(expected);
    // Supported in Oracle 12 but not Oracle 10
    sql(sql).withConformance(SqlConformanceEnum.ORACLE_10).fails(pattern);
    sql(sql).withConformance(SqlConformanceEnum.ORACLE_12).ok(expected);
}

