/**
 * Tests that ambiguity between extended string literals and character string
 * aliases is always resolved in favor of extended string literals.
 */
@Test
void testContinuedLiteralAlias() {
    final String expectingAlias = "Expecting alias, found character literal";
    // Not ambiguous, because of 'as'.
    final String sql0 = "select 1 an_alias,\n" + "  x'01'\n" + "  'ab' as x\n" + "from t";
    final String sql0b = "SELECT 1 AS `AN_ALIAS`, X'01'\n" + "'AB' AS `X`\n" + "FROM `T`";
    sql(sql0).withConformance(SqlConformanceEnum.DEFAULT).ok(sql0b);
    sql(sql0).withConformance(SqlConformanceEnum.MYSQL_5).ok(sql0b);
    sql(sql0).withConformance(SqlConformanceEnum.BIG_QUERY).ok(sql0b);
    // Is 'ab' an alias or is it part of the x'01' 'ab' continued binary string
    // literal? It's ambiguous, but we prefer the latter.
    final String sql1 = "select 1 ^'an alias'^,\n" + "  x'01'\n" + "  'ab'\n" + "from t";
    final String sql1b = "SELECT 1 AS `an alias`, X'01'\n" + "'AB'\n" + "FROM `T`";
    sql(sql1).withConformance(SqlConformanceEnum.DEFAULT).fails(expectingAlias);
    sql(sql1).withConformance(SqlConformanceEnum.MYSQL_5).ok(sql1b);
    sql(sql1).withConformance(SqlConformanceEnum.BIG_QUERY).ok(sql1b);
    // Parser prefers continued character and binary string literals over
    // character string aliases, regardless of whether the dialect allows
    // character string aliases.
    final String sql2 = "select 'continued'\n" + "  'char literal, not alias',\n" + "  x'01'\n" + "  'ab'\n" + "from t";
    final String sql2b = "SELECT 'continued'\n" + "'char literal, not alias', X'01'\n" + "'AB'\n" + "FROM `T`";
    sql(sql2).withConformance(SqlConformanceEnum.DEFAULT).ok(sql2b);
