@Test
void testOrderOffsetFetch() {
    sql("select a from foo order by b, c offset 1 row fetch first 2 row only").ok("SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 2 ROWS ONLY");
    // as above, but ROWS rather than ROW
    sql("select a from foo order by b, c offset 1 rows fetch first 2 rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 2 ROWS ONLY");
    // as above, but NEXT (means same as FIRST)
    sql("select a from foo order by b, c offset 1 rows fetch next 3 rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 3 ROWS ONLY");
    // as above, but omit the ROWS noise word after OFFSET. This is not
    // compatible with SQL:2008 but allows the Postgres syntax
    // "LIMIT ... OFFSET".
    sql("select a from foo order by b, c offset 1 fetch next 3 rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 3 ROWS ONLY");
    // as above, omit OFFSET
    sql("select a from foo order by b, c fetch next 3 rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "FETCH NEXT 3 ROWS ONLY");
    // FETCH, no ORDER BY or OFFSET
    sql("select a from foo fetch next 4 rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "FETCH NEXT 4 ROWS ONLY");
    // OFFSET, no ORDER BY or FETCH
    sql("select a from foo offset 1 row").ok("SELECT `A`
" + "FROM `FOO`
" + "OFFSET 1 ROWS");
    // OFFSET and FETCH, no ORDER BY
    sql("select a from foo offset 1 row fetch next 3 rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 3 ROWS ONLY");
    // OFFSET and FETCH, with dynamic parameters
    sql("select a from foo offset ? row fetch next ? rows only").ok("SELECT `A`
" + "FROM `FOO`
" + "OFFSET ? ROWS
" + "FETCH NEXT ? ROWS ONLY");
    // missing ROWS after FETCH
    sql("select a from foo offset 1 fetch next 3 ^only^").fails("(?s).*Encountered "only" at .*");
    // FETCH before OFFSET is illegal
    sql("select a from foo fetch next 3 rows only ^offset^ 1").fails("(?s).*Encountered "offset" at .*");
}

