@Test
void testLimitStartCount() {
    final String error = "'LIMIT start, count' is not allowed under the " + "current SQL conformance level";
    sql("select a from foo ^limit 1,2^").withConformance(SqlConformanceEnum.DEFAULT).fails(error);
    // "limit all" is equivalent to no limit
    final String expected0 = "SELECT `A`\n" + "FROM `FOO`";
    sql("select a from foo limit all").withConformance(SqlConformanceEnum.DEFAULT).ok(expected0);
    final String expected1 = "SELECT `A`\n" + "FROM `FOO`\n" + "ORDER BY `X`";
    sql("select a from foo order by x limit all").withConformance(SqlConformanceEnum.DEFAULT).ok(expected1);
    final String expected2 = "SELECT `A`\n" + "FROM `FOO`\n" + "OFFSET 2 ROWS\n" + "FETCH NEXT 3 ROWS ONLY";
    sql("select a from foo limit 2,3").withConformance(SqlConformanceEnum.LENIENT).ok(expected2);
    // "offset 4" overrides the earlier "2"
    final String expected3 = "SELECT `A`\n" + "FROM `FOO`\n" + "OFFSET 4 ROWS\n" + "FETCH NEXT 3 ROWS ONLY";
    sql("select a from foo limit 2,3 offset 4").withConformance(SqlConformanceEnum.LENIENT).ok(expected3);
    // "fetch next 4" is invalid after "limit 3"
    sql("select a from foo limit 2,3 ^fetch^ next 4 rows only").withConformance(SqlConformanceEnum.LENIENT).fails("(?s).*Encountered \"fetch\" at line 1.*");
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5086">[CALCITE-5086]
 * Calcite supports OFFSET start LIMIT count expression</a>.
 */
@Test
void testOffsetStartLimitCount() {
    final String error = "'OFFSET start LIMIT count' is not allowed under the " + "current SQL conformance level";
    sql("select a from foo order by b, c offset 1 limit 2").withConformance(SqlConformanceEnum.LENIENT).ok("SELECT `A`\n" + "FROM `FOO`\n" + "ORDER BY `B`, `C`\n" + "OFFSET 1 ROWS\n" + "FETCH NEXT 2 ROWS ONLY");
    sql("select a from foo order by b, c ^offset 1 limit 2^").withConformance(SqlConformanceEnum.DEFAULT).fails(error);
    // "limit 2" overrides the earlier "offset 4"
    final String expected3 = "SELECT `A`\n" + "FROM `FOO`\n" + "OFFSET 2 ROWS\n" + "FETCH NEXT 3 ROWS ONLY";
    sql("select a from foo offset 4 limit 2,3").withConformance(SqlConformanceEnum.LENIENT).ok(expected3);
    // "fetch next 4" is illegal following "limit 3"
    sql("select a from foo offset 2 limit 3 ^fetch^ next 4 rows only").withConformance(SqlConformanceEnum.LENIENT).fails("(?s).*Encountered \"fetch\" at line 1.*");
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-5184">[CALCITE-5184]
 * Support "LIMIT start, ALL" (in MySQL conformance)</a>.
 *
 * @see SqlConformance#isLimitStartCountAllowed()
 */
@Test
void testLimitStartAll() {
    String expected = "SELECT `A`\n" + "FROM `FOO`\n" + "OFFSET 2 ROWS";
    sql("select a from foo ^limit 2, all^").withConformance(SqlConformanceEnum.DEFAULT).fails("'LIMIT start, ALL' is not allowed under the " + "current SQL conformance level").withConformance(SqlConformanceEnum.MYSQL_5).ok(expected).withConformance(SqlConformanceEnum.LENIENT).ok(expected);
    // 'limit 2, all' will override 'offset 1' (if allowed by conformance)
    sql("select a from foo ^offset 1 limit 2, all^").withConformance(SqlConformanceEnum.DEFAULT).fails("'LIMIT start, ALL' is not allowed under the " + "current SQL conformance level").withConformance(SqlConformanceEnum.MYSQL_5).fails("'OFFSET start LIMIT count' is not allowed under the " + "current SQL conformance level").withConformance(SqlConformanceEnum.LENIENT).ok(expected);
    // 'offset 1' will override 'limit 2, all'
    String expected2 = "SELECT `A`\n" + "FROM `FOO`\n" + "OFFSET 1 ROWS";
    sql("select a from foo limit 2, all offset 1").withConformance(SqlConformanceEnum.LENIENT).ok(expected2);
}

