@Test
void testLateral() {
    // Bad: LATERAL table
    sql("select * from lateral ^emp^").fails("(?s)Encountered \"emp\" at .*");
    sql("select * from lateral table ^emp^ as e").fails("(?s)Encountered \"emp\" at .*");
    // Bad: LATERAL TABLE schema.table
    sql("select * from lateral table ^scott^.emp").fails("(?s)Encountered \"scott\" at .*");
    final String expected = "SELECT *\n" + "FROM LATERAL TABLE(`RAMP`(1))";
    // Good: LATERAL TABLE function(arg, arg)
    sql("select * from lateral table(ramp(1))").ok(expected);
    sql("select * from lateral table(ramp(1)) as t").ok(expected + " AS `T`");
    sql("select * from lateral table(ramp(1)) as t(x)").ok(expected + " AS `T` (`X`)");
    // Bad: Parentheses make it look like a sub-query
    sql("select * from lateral (^table (ramp(1))^)").fails("Expected query or join");
    // Good: LATERAL (subQuery)
    final String expected2 = "SELECT *\n" + "FROM LATERAL (SELECT *\n" + "FROM `EMP`)";
    sql("select * from lateral (select * from emp)").ok(expected2);
    sql("select * from lateral (select * from emp) as t").ok(expected2 + " AS `T`");
    sql("select * from lateral (select * from emp) as t(x)").ok(expected2 + " AS `T` (`X`)");
}

@Test
void testTemporalTable() {
    final String sql0 = "select stream * from orders, products\n" + "for system_time as of TIMESTAMP '2011-01-02 00:00:00'";
    final String expected0 = "SELECT STREAM *\n" + "FROM `ORDERS`,\n" + "`PRODUCTS` FOR SYSTEM_TIME AS OF TIMESTAMP '2011-01-02 00:00:00'";
    sql(sql0).ok(expected0);
    // Can not use explicit LATERAL keyword.
    final String sql1 = "select stream * from orders, LATERAL ^products_temporal^\n" + "for system_time as of TIMESTAMP '2011-01-02 00:00:00'";
    final String error = "(?s)Encountered \"products_temporal\" at line .*";
    sql(sql1).fails(error);
    // Inner join with a specific timestamp
    final String sql2 = "select stream * from orders join products_temporal\n" + "for system_time as of timestamp '2011-01-02 00:00:00'\n" + "on orders.productid = products_temporal.productid";
    final String expected2 = "SELECT STREAM *\n" + "FROM `ORDERS`\n" + "INNER JOIN `PRODUCTS_TEMPORAL` " + "FOR SYSTEM_TIME AS OF TIMESTAMP '2011-01-02 00:00:00' " + "ON (`ORDERS`.`PRODUCTID` = `PRODUCTS_TEMPORAL`.`PRODUCTID`)";
    sql(sql2).ok(expected2);
    // Left join with a timestamp field
    final String sql3 = "select stream * from orders left join products_temporal\n" + "for system_time as of orders.rowtime " + "on orders.productid = products_temporal.productid";
    final String expected3 = "SELECT STREAM *\n" + "FROM `ORDERS`\n" + "LEFT JOIN `PRODUCTS_TEMPORAL` " + "FOR SYSTEM_TIME AS OF `ORDERS`.`ROWTIME` " + "ON (`ORDERS`.`PRODUCTID` = `PRODUCTS_TEMPORAL`.`PRODUCTID`)";
    sql(sql3).ok(expected3);
    // Left join with a timestamp expression
    final String sql4 = "select stream * from orders left join products_temporal\n" + "for system_time as of orders.rowtime - INTERVAL '3' DAY " + "on orders.productid = products_temporal.productid";
    final String expected4 = "SELECT STREAM *\n" + "FROM `ORDERS`\n" + "LEFT JOIN `PRODUCTS_TEMPORAL` " + "FOR SYSTEM_TIME AS OF (`ORDERS`.`ROWTIME` - INTERVAL '3' DAY) " + "ON (`ORDERS`.`PRODUCTID` = `PRODUCTS_TEMPORAL`.`PRODUCTID`)";
    sql(sql4).ok(expected4);
}

