@Test
void testDescribeTable() {
    sql("describe emps").ok("DESCRIBE TABLE `EMPS`");
    sql("describe \"emps\"").ok("DESCRIBE TABLE `emps`");
    sql("describe s.emps").ok("DESCRIBE TABLE `S`.`EMPS`");
    sql("describe db.c.s.emps").ok("DESCRIBE TABLE `DB`.`C`.`S`.`EMPS`");
    sql("describe emps col1").ok("DESCRIBE TABLE `EMPS` `COL1`");
    // BigQuery allows hyphens in schema (project) names
    sql("describe foo-bar.baz").withDialect(BIG_QUERY).ok("DESCRIBE TABLE `foo-bar`.baz");
    sql("describe table foo-bar.baz").withDialect(BIG_QUERY).ok("DESCRIBE TABLE `foo-bar`.baz");
    // table keyword is OK
    sql("describe table emps col1").ok("DESCRIBE TABLE `EMPS` `COL1`");
    // character literal for column name not ok
    sql("describe emps ^'col_'^").fails("(?s).*Encountered \"\\\\'col_\\\\'\" at .*");
    // composite column name not ok
    sql("describe emps c1^.^c2").fails("(?s).*Encountered \"\\.\" at .*");
}

@Test
void testDescribeStatement() {
    // Currently DESCRIBE STATEMENT becomes EXPLAIN.
    // See [CALCITE-1221] Implement DESCRIBE DATABASE, CATALOG, STATEMENT
    final String expected0 = "" + "EXPLAIN PLAN INCLUDING ATTRIBUTES WITH IMPLEMENTATION FOR\n" + "SELECT *\n" + "FROM `EMPS`";
    sql("describe statement select * from emps").ok(expected0);
    final String expected1 = "" + "EXPLAIN PLAN INCLUDING ATTRIBUTES WITH IMPLEMENTATION FOR\n" + "(SELECT *\n" + "FROM `EMPS`\n" + "ORDER BY 2)";
    sql("describe statement select * from emps order by 2").ok(expected1);
    sql("describe select * from emps").ok(expected0);
    sql("describe (select * from emps)").ok(expected0);
    sql("describe statement (select * from emps)").ok(expected0);
    final String expected2 = "" + "EXPLAIN PLAN INCLUDING ATTRIBUTES WITH IMPLEMENTATION FOR\n" + "SELECT `DEPTNO`\n" + "FROM `EMPS`\n" + "UNION\n" + "SELECT `DEPTNO`\n" + "FROM `DEPTS`";
    sql("describe select deptno from emps union select deptno from depts").ok(expected2);
    final String expected3 = "" + "EXPLAIN PLAN INCLUDING ATTRIBUTES WITH IMPLEMENTATION FOR\n" + "INSERT INTO `EMPS`\n" + "VALUES (ROW(1, 'a'))";
    sql("describe insert into emps values (1, 'a')").ok(expected3);
    // only allow query or DML, not explain, inside describe
    sql("describe ^explain^ plan for select * from emps").fails("(?s).*Encountered \"explain\" at .*");
    sql("describe statement ^explain^ plan for select * from emps").fails("(?s).*Encountered \"explain\" at .*");
}

