@Test
void testStringLiteralDoubleQuoted() {
    sql("select `deptno` as d, ^\"^deptno\" as d2 from emp").withDialect(MYSQL).fails("(?s)Encountered \"\\\\\"\" at .*").withDialect(BIG_QUERY).ok("SELECT deptno AS d, 'deptno' AS d2\n" + "FROM emp");
    // MySQL uses single-quotes as escapes; BigQuery uses backslashes
    sql("select 'Let''s call the dog \"Elvis\"!'").withDialect(MYSQL).node(isCharLiteral("Let's call the dog \"Elvis\"!"));
    sql("select 'Let\\'\\'s call the dog \"Elvis\"!'").withDialect(BIG_QUERY).node(isCharLiteral("Let''s call the dog \"Elvis\"!"));
    sql("select 'Let\\'s ^call^ the dog \"Elvis\"!'").withDialect(MYSQL).fails("(?s)Encountered \"call\" at .*").withDialect(BIG_QUERY).node(isCharLiteral("Let's call the dog \"Elvis\"!"));
    // Oracle uses double-quotes as escapes in identifiers;
    // BigQuery uses backslashes as escapes in double-quoted character literals.
    sql("select \"Let's call the dog \\\"Elvis^\\^\"!\"").withDialect(ORACLE).fails("(?s)Lexical error at line 1, column 35\\.  " + "Encountered: \"\\\\\\\\\" \\(92\\), after : \"\".*").withDialect(BIG_QUERY).node(isCharLiteral("Let's call the dog \"Elvis\"!"));
}

@VisibleForTesting
@Test
public void testCaseExpression() {
    // implicit simple "ELSE NULL" case
    expr("case \t col1 when 1 then 'one' end").ok("(CASE WHEN (`COL1` = 1) THEN 'one' ELSE NULL END)");
    // implicit searched "ELSE NULL" case
    expr("case when nbr is false then 'one' end").ok("(CASE WHEN (`NBR` IS FALSE) THEN 'one' ELSE NULL END)");
    // multiple WHENs
    expr("case col1 when\n1.2 then 'one' when 2 then 'two' else 'three' end").ok("(CASE WHEN (`COL1` = 1.2) THEN 'one' WHEN (`COL1` = 2) THEN 'two' ELSE 'three' END)");
    // sub-queries as case expression operands
    expr("case (select * from emp) when 1 then 2 end").ok("(CASE WHEN ((SELECT *\n" + "FROM `EMP`) = 1) THEN 2 ELSE NULL END)");
    expr("case 1 when (select * from emp) then 2 end").ok("(CASE WHEN (1 = (SELECT *\n" + "FROM `EMP`)) THEN 2 ELSE NULL END)");
    expr("case 1 when 2 then (select * from emp) end").ok("(CASE WHEN (1 = 2) THEN (SELECT *\n" + "FROM `EMP`) ELSE NULL END)");
    expr("case 1 when 2 then 3 else (select * from emp) end").ok("(CASE WHEN (1 = 2) THEN 3 ELSE (SELECT *\n" + "FROM `EMP`) END)");
    expr("case x when 2, 4 then 3 else 4 end").ok("(CASE WHEN (`X` IN (2, 4)) THEN 3 ELSE 4 END)");
    // comma-list must not be empty
    sql("case x when 2, 4 then 3 when ^then^ 5 else 4 end").fails("(?s)Encountered \"then\" at .*");
    // commas not allowed in boolean case
    sql("case when b1, b2 ^when^ 2, 4 then 3 else 4 end").fails("(?s)Encountered \"when\" at .*");
}

