    sql(sql1).ok(expected1);
    final String sql2 = "select count(*) over w\n" + "from emp window w as (rows 2 preceding)";
    final String expected2 = "SELECT (COUNT(*) OVER `W`)\n" + "FROM `EMP`\n" + "WINDOW `W` AS (ROWS 2 PRECEDING)";
    sql(sql2).ok(expected2);
    // Chained string literals are valid syntax. They are unlikely to be
    // semantically valid, because intervals are usually numeric or
    // datetime.
    // Note: literal chain is not yet replaced with combined literal
    // since we are just parsing, and not validating the sql.
    final String sql3 = "select count(*) over w from emp window w as (\n" + "  rows 'foo' 'bar'\n" + "       'baz' preceding)";
    final String expected3 = "SELECT (COUNT(*) OVER `W`)\n" + "FROM `EMP`\n" + "WINDOW `W` AS (ROWS 'foo'\n'bar'\n'baz' PRECEDING)";
    sql(sql3).ok(expected3);
    // Partition clause out of place. Found after ORDER BY
    final String sql4 = "select count(z) over w as foo\n" + "from Bids\n" + "window w as (partition by y order by x ^partition^ by y)";
    sql(sql4).fails("(?s).*Encountered \"partition\".*");
    final String sql5 = "select count(z) over w as foo\n" + "from Bids window w as (order by x ^partition^ by y)";
    sql(sql5).fails("(?s).*Encountered \"partition\".*");
    // Cannot partition by sub-query
    sql("select sum(a) over (partition by ^(^select 1 from t), x) from t2").fails("Query expression encountered in illegal context");
    // AND is required in BETWEEN clause of window frame
    final String sql7 = "select sum(x) over\n" + " (order by x range between unbounded preceding ^unbounded^ following)";
    sql(sql7).fails("(?s).*Encountered \"unbounded\".*");
    // WINDOW keyword is not permissible.
    sql("select sum(x) over ^window^ (order by x) from bids").fails("(?s).*Encountered \"window\".*");
    // ORDER BY must be before Frame spec
    sql("select sum(x) over (rows 2 preceding ^order^ by x) from emp").fails("(?s).*Encountered \"order\".*");
}

