    sql("select count(z) over w foo from Bids window w as (order by x)").ok("SELECT (COUNT(`Z`) OVER `W`) AS `FOO`\n" + "FROM `BIDS`\n" + "WINDOW `W` AS (ORDER BY `X`)");
