    final String expected = "SELECT `X`\n" + "FROM `T` AS `T1`";
    sql("select x from t as t1").ok(expected);
    sql("select x from t t1").ok(expected);
    // AS is required in WINDOW declaration
    sql("select sum(x) over w from bids window w ^(order by x)").fails("(?s).*Encountered \"\\(\".*");
