@Test
void testTimestampAdd() {
    final String sql = "select * from t\n" + "where timestampadd(month, 5, hiredate) < curdate";
    final String expected = "SELECT *\n" + "FROM `T`\n" + "WHERE (TIMESTAMPADD(MONTH, 5, `HIREDATE`) < `CURDATE`)";
    sql(sql).ok(expected);
    // SQL_TSI_MONTH is treated as a user-defined time frame, hence appears as
    // an identifier (with backticks) when unparsed. It will be resolved to
    // MICROSECOND during validation.
    final String sql2 = "select * from t\n" + "where timestampadd(sql_tsi_month, 5, hiredate) < curdate";
    final String expected2 = "SELECT *\n" + "FROM `T`\n" + "WHERE (TIMESTAMPADD(`SQL_TSI_MONTH`, 5, `HIREDATE`) < `CURDATE`)";
    sql(sql2).ok(expected2);
    // Previously a parse error, now an identifier that the validator will find
    // to be invalid.
    expr("timestampadd(incorrect, 1, current_timestamp)").ok("TIMESTAMPADD(`INCORRECT`, 1, CURRENT_TIMESTAMP)");
}

@Test
void testTimestampDiff() {
    final String sql = "select * from t\n" + "where timestampdiff(microsecond, 5, hiredate) < curdate";
    final String expected = "SELECT *\n" + "FROM `T`\n" + "WHERE (TIMESTAMPDIFF(MICROSECOND, 5, `HIREDATE`) < `CURDATE`)";
    sql(sql).ok(expected);
    // FRAC_SECOND is treated as a user-defined time frame, hence appears as
    // an identifier (with backticks) when unparsed. It will be resolved to
    // MICROSECOND during validation.
    final String sql2 = "select * from t\n" + "where timestampdiff(frac_second, 5, hiredate) < curdate";
    final String expected2 = "SELECT *\n" + "FROM `T`\n" + "WHERE (TIMESTAMPDIFF(`FRAC_SECOND`, 5, `HIREDATE`) < `CURDATE`)";
    sql(sql2).ok(expected2);
    // Previously a parse error, now an identifier that the validator will find
    // to be invalid.
    expr("timestampdiff(incorrect, current_timestamp, current_timestamp)").ok("TIMESTAMPDIFF(`INCORRECT`, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)");
}

@Test
void testTimeTrunc() {
    final String sql = "select time_trunc(TIME '15:30:00', hour) from t";
    final String expected = "SELECT TIME_TRUNC(TIME '15:30:00', HOUR)\n" + "FROM `T`";
    sql(sql).ok(expected);
    // Syntactically valid; validator will complain because WEEK is for DATE or
    // TIMESTAMP but not for TIME.
    final String sql2 = "select time_trunc(time '15:30:00', week) from t";
    final String expected2 = "SELECT TIME_TRUNC(TIME '15:30:00', WEEK)\n" + "FROM `T`";
    sql(sql2).ok(expected2);
    // note backticks
    final String sql3 = "select time_trunc(time '15:30:00', incorrect) from t";
    final String expected3 = "SELECT TIME_TRUNC(TIME '15:30:00', `INCORRECT`)\n" + "FROM `T`";
    sql(sql3).ok(expected3);
}

