}

@Test
void testParensInFrom() {
    // UNNEST may not occur within parentheses.
    // FIXME should fail at "unnest"
    sql("select *from (^unnest(x)^)").fails("Expected query or join");
    // <table-name> may not occur within parentheses.
    // TODO: Postgres gives "syntax error at ')'", which might be better
    sql("select * from (^emp^)").fails("(?s)Expected query or join.*");
    // <table-name> may not occur within parentheses.
    // TODO: Postgres gives "syntax error at ')'", which might be better
    sql("select * from (^emp as x^)").fails("Expected query or join");
    // <table-name> may not occur within parentheses.
    sql("select * from (^emp^) as x").fails("Expected query or join");
    // Parentheses around JOINs are OK, and sometimes necessary.
    String sql1 = "select *\n" + "from (emp join dept using (deptno))";
    String expected = "SELECT *\n" + "FROM `EMP`\n" + "INNER JOIN `DEPT` USING (`DEPTNO`)";
    sql(sql1).ok(expected);
    String sql2 = "select *\n" + "from (emp join dept using (deptno))\n" + "join foo using (x)";
    String expected2 = "SELECT *\n" + "FROM `EMP`\n" + "INNER JOIN `DEPT` USING (`DEPTNO`)\n" + "INNER JOIN `FOO` USING (`X`)";
    sql(sql2).ok(expected2);
    // In Postgres and Standard SQL, you can alias a join:
    //   "select x.i from (t cross join u) as x"
    // is syntactically and semantically valid; but
    //   "select t.i from (t cross join u) as x"
    // is semantically invalid.
    // TODO: Support this in Calcite.
    sql("select * from (t cross ^join^ u) as x").fails("Join expression encountered in illegal context");
    sql("select *\n" + "from (t cross ^join^ u)\n" + "  tablesample substitute('medium')").fails("Join expression encountered in illegal context");
    sql("select *\n" + "from (t cross ^join^ u)\n" + "PIVOT (sum(sal) AS sal FOR job in ('CLERK' AS c))").fails("Join expression encountered in illegal context");
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-35">[CALCITE-35]
 * Support parenthesized sub-clause in JOIN</a>.
 */
@Test
void testParenthesizedJoins() {
    final String sql = "SELECT * FROM " + "(((S.C c INNER JOIN S.N n ON n.id = c.id) " + "INNER JOIN S.A a ON (NOT a.isactive)) " + "INNER JOIN S.T t ON t.id = a.id)";
    final String expected = "SELECT *\n" + "FROM `S`.`C` AS `C`\n" + "INNER JOIN `S`.`N` AS `N` ON (`N`.`ID` = `C`.`ID`)\n" + "INNER JOIN `S`.`A` AS `A` ON (NOT `A`.`ISACTIVE`)\n" + "INNER JOIN `S`.`T` AS `T` ON (`T`.`ID` = `A`.`ID`)";
    sql(sql).ok(expected);
    final String sql2 = "select *\n" + "from a\n" + " join (b join c on b.x = c.x)\n" + " on a.y = c.y";
    final String expected2 = "SELECT *\n" + "FROM `A`\n" + "INNER JOIN (`B` INNER JOIN `C` ON (`B`.`X` = `C`.`X`))" + " ON (`A`.`Y` = `C`.`Y`)";
    sql(sql2).ok(expected2);
}

