/**
 * Tests parsing parenthesized queries.
 */
@Test
void testParenthesizedQueries() {
    final String expected = "SELECT *\n" + "FROM (SELECT *\n" + "FROM `TAB`) AS `X`";
    final String sql1 = "SELECT *\n" + "FROM (((SELECT * FROM tab))) X";
    final String sql2 = "SELECT *\n" + "FROM ((((((((((((SELECT * FROM tab)))))))))))) X";
    sql(sql1).ok(expected);
    sql(sql2).ok(expected);
    final String sql3 = "SELECT *\n" + "FROM ((((((((((((SELECT * FROM t)))\n" + "  cross join ((table t2)))))))))))";
    final String expected3 = "SELECT *\n" + "FROM (SELECT *\n" + "FROM `T`)\n" + "CROSS JOIN (TABLE `T2`)";
    sql(sql3).ok(expected3);
    // Adding an alias to the previous query makes it invalid
    // (The error message and location could be improved)
    final String sql4 = "SELECT *\n" + "FROM ((((((((((((SELECT * FROM t)))\n" + "  cross ^join^ ((table t2))))))))))) X";
    final String sql5 = "SELECT *\n" + "FROM ((((((((((((SELECT * FROM t)))\n" + "  cross ^join^ ((table t2))))))))))) as X";
    final String sql6 = "SELECT *\n" + "FROM ((((((((((((SELECT * FROM t)))\n" + "  cross ^join^ ((table t2))))))))))) as X (a, b, c)";
    final String message = "Join expression encountered in illegal context";
    sql(sql4).fails(message);
    sql(sql5).fails(message);
    sql(sql6).fails(message);
}

