@Test
void testLongIdentifiers() {
    StringBuilder ident128Builder = new StringBuilder();
    for (int i = 0; i < 128; i++) {
        ident128Builder.append((char) ('a' + (i % 26)));
    }
    String ident128 = ident128Builder.toString();
    String ident128Upper = ident128.toUpperCase(Locale.US);
    String ident129 = "x" + ident128;
    String ident129Upper = ident129.toUpperCase(Locale.US);
    sql("select * from " + ident128).ok("SELECT *\n" + "FROM `" + ident128Upper + "`");
    sql("select * from ^" + ident129 + "^").fails("Length of identifier '" + ident129Upper + "' must be less than or equal to 128 characters");
    sql("select " + ident128 + " from mytable").ok("SELECT `" + ident128Upper + "`\n" + "FROM `MYTABLE`");
    sql("select ^" + ident129 + "^ from mytable").fails("Length of identifier '" + ident129Upper + "' must be less than or equal to 128 characters");
}

