@Test
void testUnicodeLiteral() {
    // Note that here we are constructing a SQL statement which directly
    // contains Unicode characters (not SQL Unicode escape sequences).  The
    // escaping here is Java-only, so by the time it gets to the SQL
    // parser, the literal already contains Unicode characters.
    String in1 = "values _UTF16'" + ConversionUtil.TEST_UNICODE_STRING + "'";
    String out1 = "VALUES (ROW(_UTF16'" + ConversionUtil.TEST_UNICODE_STRING + "'))";
    sql(in1).ok(out1);
    // Without the U& prefix, escapes are left unprocessed
    String in2 = "values '" + ConversionUtil.TEST_UNICODE_SQL_ESCAPED_LITERAL + "'";
    String out2 = "VALUES (ROW('" + ConversionUtil.TEST_UNICODE_SQL_ESCAPED_LITERAL + "'))";
    sql(in2).ok(out2);
    // Likewise, even with the U& prefix, if some other escape
    // character is specified, then the backslash-escape
    // sequences are not interpreted
    String in3 = "values U&'" + ConversionUtil.TEST_UNICODE_SQL_ESCAPED_LITERAL + "' UESCAPE '!'";
    String out3 = "VALUES (ROW(_UTF16'" + ConversionUtil.TEST_UNICODE_SQL_ESCAPED_LITERAL + "'))";
    sql(in3).ok(out3);
}

@Test
void testUnicodeEscapedLiteral() {
    // Note that here we are constructing a SQL statement which
    // contains SQL-escaped Unicode characters to be handled
    // by the SQL parser.
    String in = "values U&'" + ConversionUtil.TEST_UNICODE_SQL_ESCAPED_LITERAL + "'";
    String out = "VALUES (ROW(_UTF16'" + ConversionUtil.TEST_UNICODE_STRING + "'))";
    sql(in).ok(out);
    // Verify that we can override with an explicit escape character
    sql(in.replace("\\", "!") + "UESCAPE '!'").ok(out);
}

@Test
void testIllegalUnicodeEscape() {
    expr("U&'abc' UESCAPE '!!'").fails(".*must be exactly one character.*");
    expr("U&'abc' UESCAPE ''").fails(".*must be exactly one character.*");
    expr("U&'abc' UESCAPE '0'").fails(".*hex digit.*");
    expr("U&'abc' UESCAPE 'a'").fails(".*hex digit.*");
    expr("U&'abc' UESCAPE 'F'").fails(".*hex digit.*");
    expr("U&'abc' UESCAPE ' '").fails(".*whitespace.*");
    expr("U&'abc' UESCAPE '+'").fails(".*plus sign.*");
    expr("U&'abc' UESCAPE '\"'").fails(".*double quote.*");
    expr("'abc' UESCAPE ^'!'^").fails(".*without Unicode literal introducer.*");
    expr("^U&'\\0A'^").fails(".*is not exactly four hex digits.*");
    expr("^U&'\\wxyz'^").fails(".*is not exactly four hex digits.*");
}

@Test
void testSqlOptions() {
    SqlNode node = sql("alter system set schema = true").node();
    SqlSetOption opt = (SqlSetOption) node;
    assertThat(opt.getScope(), equalTo("SYSTEM"));
    SqlPrettyWriter writer = new SqlPrettyWriter();
    assertThat(writer.format(opt.getName()), equalTo("\"SCHEMA\""));
    writer = new SqlPrettyWriter();
    assertThat(writer.format(opt.getValue()), equalTo("TRUE"));
    writer = new SqlPrettyWriter();
    assertThat(writer.format(opt), equalTo("ALTER SYSTEM SET \"SCHEMA\" = TRUE"));
    sql("alter system set \"a number\" = 1").ok("ALTER SYSTEM SET `a number` = 1").node(isDdl());
    sql("alter system set flag = false").ok("ALTER SYSTEM SET `FLAG` = FALSE");
    sql("alter system set approx = -12.3450").ok("ALTER SYSTEM SET `APPROX` = -12.3450");
    sql("alter system set onOff = on").ok("ALTER SYSTEM SET `ONOFF` = `ON`");
    sql("alter system set onOff = off").ok("ALTER SYSTEM SET `ONOFF` = `OFF`");
    sql("alter system set baz = foo").ok("ALTER SYSTEM SET `BAZ` = `FOO`");
    sql("alter system set \"a\".\"number\" = 1").ok("ALTER SYSTEM SET `a`.`number` = 1");
    sql("set approx = -12.3450").ok("SET `APPROX` = -12.3450").node(isDdl());
    node = sql("reset schema").node();
    opt = (SqlSetOption) node;
    assertThat(opt.getScope(), equalTo(null));
    writer = new SqlPrettyWriter();
    assertThat(writer.format(opt.getName()), equalTo("\"SCHEMA\""));
    assertThat(opt.getValue(), equalTo(null));
    writer = new SqlPrettyWriter();
    assertThat(writer.format(opt), equalTo("RESET \"SCHEMA\""));
    sql("alter system RESET flag").ok("ALTER SYSTEM RESET `FLAG`");
    sql("reset onOff").ok("RESET `ONOFF`").node(isDdl());
    sql("reset \"this\".\"is\".\"sparta\"").ok("RESET `this`.`is`.`sparta`");
    sql("alter system reset all").ok("ALTER SYSTEM RESET `ALL`");
    sql("reset all").ok("RESET `ALL`");
    // expressions not allowed
    sql("alter system set aString = 'abc' ^||^ 'def' ").fails("(?s)Encountered \"\\|\\|\" at line 1, column 34\\..*");
    // multiple assignments not allowed
    sql("alter system set x = 1^,^ y = 2").fails("(?s)Encountered \",\" at line 1, column 23\\..*");
}

