@Test
void testConfigureFromDialect() {
    // Calcite's default converts unquoted identifiers to upper case
    sql("select unquotedColumn from \"double\"\"QuotedTable\"").withDialect(CALCITE).ok("SELECT \"UNQUOTEDCOLUMN\"\n" + "FROM \"double\"\"QuotedTable\"");
    // MySQL leaves unquoted identifiers unchanged
    sql("select unquotedColumn from `double``QuotedTable`").withDialect(MYSQL).ok("SELECT `unquotedColumn`\n" + "FROM `double``QuotedTable`");
    // Oracle converts unquoted identifiers to upper case
    sql("select unquotedColumn from \"double\"\"QuotedTable\"").withDialect(ORACLE).ok("SELECT \"UNQUOTEDCOLUMN\"\n" + "FROM \"double\"\"QuotedTable\"");
    // PostgreSQL converts unquoted identifiers to lower case
    sql("select unquotedColumn from \"double\"\"QuotedTable\"").withDialect(POSTGRESQL).ok("SELECT \"unquotedcolumn\"\n" + "FROM \"double\"\"QuotedTable\"");
    // Redshift converts all identifiers to lower case
    sql("select unquotedColumn from \"double\"\"QuotedTable\"").withDialect(REDSHIFT).ok("SELECT \"unquotedcolumn\"\n" + "FROM \"double\"\"quotedtable\"");
    // BigQuery leaves quoted and unquoted identifiers unchanged
    sql("select unquotedColumn from `double\\`QuotedTable`").withDialect(BIG_QUERY).ok("SELECT unquotedColumn\n" + "FROM `double\\`QuotedTable`");
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-4230">[CALCITE-4230]
 * In Babel for BigQuery, split quoted table names that contain dots</a>.
 */
@Test
void testSplitIdentifier() {
    final String sql = "select *\n" + "from `bigquery-public-data.samples.natality`";
    final String sql2 = "select *\n" + "from `bigquery-public-data`.`samples`.`natality`";
    final String expectedSplit = "SELECT *\n" + "FROM `bigquery-public-data`.samples.natality";
    final String expectedNoSplit = "SELECT *\n" + "FROM `bigquery-public-data.samples.natality`";
    final String expectedSplitMysql = "SELECT *\n" + "FROM `bigquery-public-data`.`samples`.`natality`";
    // In BigQuery, an identifier containing dots is split into sub-identifiers.
    sql(sql).withDialect(BIG_QUERY).ok(expectedSplit);
    // In MySQL, identifiers are not split.
    sql(sql).withDialect(MYSQL).ok(expectedNoSplit);
    // Query with split identifiers produces split AST. No surprise there.
    sql(sql2).withDialect(BIG_QUERY).ok(expectedSplit);
    // Similar to previous; we just quote simple identifiers on unparse.
    sql(sql2).withDialect(MYSQL).ok(expectedSplitMysql);
}

