@Test
void testSqlOperatorOverloading() {
    final SqlStdOperatorTable operatorTable = SqlStdOperatorTable.instance();
    for (SqlOperator sqlOperator : operatorTable.getOperatorList()) {
        String operatorName = sqlOperator.getName();
        List<SqlOperator> routines = new ArrayList<>();
        final SqlIdentifier id = new SqlIdentifier(operatorName, SqlParserPos.ZERO);
        operatorTable.lookupOperatorOverloads(id, null, sqlOperator.getSyntax(), routines, SqlNameMatchers.withCaseSensitive(true));
        routines.removeIf(operator -> !sqlOperator.getClass().isInstance(operator));
        assertThat(routines, hasSize(1));
        assertThat(sqlOperator, equalTo(routines.get(0)));
    }
}

