@ParameterizedTest
@MethodSource("safeParameters")
void testCastApproxNumericLimits(CastType castType, SqlOperatorFixture f) {
    f.setFor(SqlStdOperatorTable.CAST, VmName.EXPAND);
    // Test casting for min, max, out of range for approx numeric types
    Numeric.forEach(numeric -> {
        String type = numeric.typeName;
        boolean isFloat;
        switch(numeric) {
            case DOUBLE:
            case FLOAT:
                isFloat = false;
                break;
            case REAL:
                isFloat = true;
                break;
            default:
                // Skip non-approx types
                return;
        }
        if (!f.brokenTestsEnabled()) {
            return;
        }
        // Convert from literal to type
        f.checkCastToApproxOkay(numeric.maxNumericString, type, isFloat ? isWithin(numeric.maxNumericAsDouble(), 1E32) : isExactly(numeric.maxNumericAsDouble()), castType);
        f.checkCastToApproxOkay(numeric.minNumericString, type, isExactly(numeric.minNumericString), castType);
        if (isFloat) {
            f.checkCastFails(numeric.maxOverflowNumericString, type, OUT_OF_RANGE_MESSAGE, true, castType);
        } else {
            // Double: Literal out of range
            f.checkCastFails(numeric.maxOverflowNumericString, type, LITERAL_OUT_OF_RANGE_MESSAGE, false, castType);
        }
        // Underflow: goes to 0
        f.checkCastToApproxOkay(numeric.minOverflowNumericString, type, isExactly(0), castType);
        // Convert from string to type
        f.checkCastToApproxOkay("'" + numeric.maxNumericString + "'", type, isFloat ? isWithin(numeric.maxNumericAsDouble(), 1E32) : isExactly(numeric.maxNumericAsDouble()), castType);
        f.checkCastToApproxOkay("'" + numeric.minNumericString + "'", type, isExactly(numeric.minNumericAsDouble()), castType);
        f.checkCastFails("'" + numeric.maxOverflowNumericString + "'", type, OUT_OF_RANGE_MESSAGE, true, castType);
        // Underflow: goes to 0
        f.checkCastToApproxOkay("'" + numeric.minOverflowNumericString + "'", type, isExactly(0), castType);
        // Convert from type to string
        // Treated as DOUBLE
        f.checkCastToString(numeric.maxNumericString, null, isFloat ? null : "1.79769313486231E308", castType);
        // TODO: The following tests are slightly different depending on
        // whether the java or fennel calc are used.
        // Try to make them the same
        if (false) /* fennel calc*/
        {
            // Treated as FLOAT or DOUBLE
            f.checkCastToString(numeric.maxNumericString, type, // Treated as DOUBLE
            isFloat ? "3.402824E38" : "1.797693134862316E308", castType);
            f.checkCastToString(numeric.minNumericString, null, // Treated as FLOAT or DOUBLE
            isFloat ? null : "4.940656458412465E-324", castType);
            f.checkCastToString(numeric.minNumericString, type, isFloat ? "1.401299E-45" : "4.940656458412465E-324", castType);
        } else if (false) /* JavaCalc */
        {
            // Treated as FLOAT or DOUBLE
            f.checkCastToString(numeric.maxNumericString, type, // Treated as DOUBLE
            isFloat ? "3.402823E38" : "1.797693134862316E308", castType);
            f.checkCastToString(numeric.minNumericString, null, isFloat ? null : null, // Treated as FLOAT or DOUBLE
            castType);
            f.checkCastToString(numeric.minNumericString, type, isFloat ? "1.401298E-45" : null, castType);
        }
        f.checkCastFails("'notnumeric'", type, INVALID_CHAR_MESSAGE, true, castType);
    });
}

