    f.checkScalar("cast('12:54:78' as TIME)", "12:55:18", "TIME(0) NOT NULL");
    f.checkScalar("cast('12:34:5' as TIME)", "12:34:05", "TIME(0) NOT NULL");
    f.checkScalar("cast('12:3:45' as TIME)", "12:03:45", "TIME(0) NOT NULL");
    f.checkScalar("cast('1:23:45' as TIME)", "01:23:45", "TIME(0) NOT NULL");
    // timestamp <-> string
    f.checkCastToString("TIMESTAMP '1945-02-24 12:42:25'", null, "1945-02-24 12:42:25", castType);
    if (TODO) {
        // TODO: casting allows one to discard precision without error
        f.checkCastToString("TIMESTAMP '1945-02-24 12:42:25.34'", null, "1945-02-24 12:42:25.34", castType);
    }
    f.checkScalar("cast('1945-02-24 12:42:25' as TIMESTAMP)", "1945-02-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    f.checkScalar("cast('  1945-02-24 12:42:25  ' as TIMESTAMP)", "1945-02-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    f.checkScalar("cast('1945-02-24 12:42:25.34' as TIMESTAMP)", "1945-02-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    f.checkScalar("cast('1945-12-31' as TIMESTAMP)", "1945-12-31 00:00:00", "TIMESTAMP(0) NOT NULL");
    f.checkScalar("cast('2004-02-29' as TIMESTAMP)", "2004-02-29 00:00:00", "TIMESTAMP(0) NOT NULL");
    if (Bug.FRG282_FIXED) {
        f.checkScalar("cast('1945-02-24 12:42:25.34' as TIMESTAMP(2))", "1945-02-24 12:42:25.34", "TIMESTAMP(2) NOT NULL");
    }
    // Remove the if condition and the else block once CALCITE-6053 is fixed
    if (TestUtil.AVATICA_VERSION.startsWith("1.0.0-dev-main")) {
        if (castType == CastType.CAST) {
            f.checkFails("cast('1945-2-2 12:2:5' as TIMESTAMP)", "Invalid DATE value, '1945-2-2 12:2:5'", true);
            f.checkFails("cast('1241241' as TIMESTAMP)", "Invalid DATE value, '1241241'", true);
            f.checkFails("cast('1945-20-24 12:42:25.34' as TIMESTAMP)", "Invalid DATE value, '1945-20-24 12:42:25.34'", true);
            f.checkFails("cast('1945-01-24 25:42:25.34' as TIMESTAMP)", "Value of HOUR field is out of range in '1945-01-24 25:42:25.34'", true);
            f.checkFails("cast('1945-1-24 12:23:34.454' as TIMESTAMP)", "Invalid DATE value, '1945-1-24 12:23:34.454'", true);
        } else {
            // test cases for 'SAFE_CAST' and 'TRY_CAST'
            f.checkNull("cast('1945-2-2 12:2:5' as TIMESTAMP)");
            f.checkNull("cast('1241241' as TIMESTAMP)");
            f.checkNull("cast('1945-20-24 12:42:25.34' as TIMESTAMP)");
            f.checkNull("cast('1945-01-24 25:42:25.34' as TIMESTAMP)");
            f.checkNull("cast('1945-1-24 12:23:34.454' as TIMESTAMP)");
        }
    } else {
        f.checkScalar("cast('1945-2-2 12:2:5' as TIMESTAMP)", "1945-02-02 12:02:05", "TIMESTAMP(0) NOT NULL");
        f.checkScalar("cast('1241241' as TIMESTAMP)", "1241-01-01 00:00:00", "TIMESTAMP(0) NOT NULL");
        f.checkScalar("cast('1945-20-24 12:42:25.34' as TIMESTAMP)", "1946-08-26 12:42:25", "TIMESTAMP(0) NOT NULL");
        f.checkScalar("cast('1945-01-24 25:42:25.34' as TIMESTAMP)", "1945-01-25 01:42:25", "TIMESTAMP(0) NOT NULL");
        f.checkScalar("cast('1945-1-24 12:23:34.454' as TIMESTAMP)", "1945-01-24 12:23:34", "TIMESTAMP(0) NOT NULL");
    }
    if (castType == CastType.CAST) {
        f.checkFails("cast('nottime' as TIMESTAMP)", BAD_DATETIME_MESSAGE, true);
    } else {
        f.checkNull("cast('nottime' as TIMESTAMP)");
    }
    // date <-> string
    f.checkCastToString("DATE '1945-02-24'", null, "1945-02-24", castType);
    f.checkCastToString("DATE '1945-2-24'", null, "1945-02-24", castType);
    f.checkScalar("cast('1945-02-24' as DATE)", "1945-02-24", "DATE NOT NULL");
    f.checkScalar("cast(' 1945-2-4 ' as DATE)", "1945-02-04", "DATE NOT NULL");
    f.checkScalar("cast('  1945-02-24  ' as DATE)", "1945-02-24", "DATE NOT NULL");
    if (castType == CastType.CAST) {
        f.checkFails("cast('notdate' as DATE)", BAD_DATETIME_MESSAGE, true);
    } else {
        f.checkNull("cast('notdate' as DATE)");
    }
    f.checkScalar("cast('52534253' as DATE)", "7368-10-13", "DATE NOT NULL");
    f.checkScalar("cast('1945-30-24' as DATE)", "1947-06-26", "DATE NOT NULL");
    // cast null
    f.checkNull("cast(null as date)");
    f.checkNull("cast(null as timestamp)");
    f.checkNull("cast(null as time)");
    f.checkNull("cast(cast(null as varchar(10)) as time)");
    f.checkNull("cast(cast(null as varchar(10)) as date)");
    f.checkNull("cast(cast(null as varchar(10)) as timestamp)");
    f.checkNull("cast(cast(null as date) as timestamp)");
    f.checkNull("cast(cast(null as time) as timestamp)");
    f.checkNull("cast(cast(null as timestamp) as date)");
    f.checkNull("cast(cast(null as timestamp) as time)");
}

