    f.checkScalar("timestamp '2003-08-02 12:54:01' " + "- interval '0.01' second(1, 3)", isExactDateTime(LocalDateTime.of(2003, 8, 2, 12, 54, 0, 990_000_000)), "TIMESTAMP(3) NOT NULL");
    f.checkScalar("timestamp '2003-08-02 12:54:01.000' " + "- interval '1' second", isExactDateTime(LocalDateTime.of(2003, 8, 2, 12, 54, 0, 0)), "TIMESTAMP(3) NOT NULL");
    f.checkScalar("timestamp '2003-08-02 12:54:01.123' " + "- interval '1' hour", isExactDateTime(LocalDateTime.of(2003, 8, 2, 11, 54, 1, 123_000_000)), "TIMESTAMP(3) NOT NULL");
    f.checkScalar("timestamp with local time zone '2003-08-02 12:54:01' " + "- interval '0.456' second(1, 3)", isExactDateTime(LocalDateTime.of(2003, 8, 2, 12, 54, 0, 544_000_000)), "TIMESTAMP_WITH_LOCAL_TIME_ZONE(3) NOT NULL");
    f.checkScalar("time '23:54:01' " + "- interval '0.01' second(1, 3)", isExactTime(LocalTime.of(23, 54, 0, 990_000_000)), "TIME(3) NOT NULL");
    f.checkScalar("time '23:54:01.123' " + "- interval '1' minute", isExactTime(LocalTime.of(23, 53, 1, 123_000_000)), "TIME(3) NOT NULL");
    f.checkScalar("date '2003-08-02' " + "- interval '1.123' second(1, 3)", "2003-08-02", "DATE NOT NULL");
    // Datetime minus year-month interval
    f.checkScalar("timestamp '2003-08-02 12:54:01' - interval '12' year", "1991-08-02 12:54:01", "TIMESTAMP(0) NOT NULL");
    f.checkScalar("date '2003-08-02' - interval '12' year", "1991-08-02", "DATE NOT NULL");
    f.checkScalar("date '2003-08-02' - interval '12-3' year to month", "1991-05-02", "DATE NOT NULL");
}

