@ParameterizedTest
@MethodSource("bitGetParameters")
void testBitGetFunc(SqlOperatorFixture f, String functionName) {
    f.checkFails("^" + functionName + "(cast(11 as bigint), 1)^", "No match found for function signature " + functionName + "\\(<NUMERIC>, <NUMERIC>\\)", false);
    final SqlOperatorFixture f1 = f.withLibrary(SqlLibrary.SPARK);
    // test for bigint value
    f1.checkScalarExact(functionName + "(cast(11 as bigint), 3)", "TINYINT NOT NULL", "1");
    f1.checkScalarExact(functionName + "(cast(-1 as bigint), 0)", "TINYINT NOT NULL", "1");
    f1.checkScalarExact(functionName + "(cast(11 as bigint), 63)", "TINYINT NOT NULL", "0");
    f1.checkScalarExact(functionName + "(cast(-1 as bigint), 63)", "TINYINT NOT NULL", "1");
    f1.checkFails(functionName + "(cast(11 as bigint), 64)", "BIT_GET/GETBIT error: position 64 exceeds the bit upper limit 63", true);
    f1.checkFails(functionName + "(cast(11 as bigint), -1)", "BIT_GET/GETBIT error: negative position -1 not allowed", true);
    f1.checkNull(functionName + "(cast(null as bigint), 1)");
    f1.checkNull(functionName + "(cast(11 as bigint), cast(null as integer))");
    // test for integer value
    f1.checkScalarExact(functionName + "(cast(11 as integer), 3)", "TINYINT NOT NULL", "1");
    f1.checkScalarExact(functionName + "(cast(-1 as integer), 0)", "TINYINT NOT NULL", "1");
    f1.checkScalarExact(functionName + "(cast(11 as integer), 31)", "TINYINT NOT NULL", "0");
    f1.checkScalarExact(functionName + "(cast(-1 as integer), 31)", "TINYINT NOT NULL", "1");
    f1.checkFails(functionName + "(cast(11 as integer), 32)", "BIT_GET/GETBIT error: position 32 exceeds the bit upper limit 31", true);
    // test for smallint value
    f1.checkScalarExact(functionName + "(cast(11 as smallint), 3)", "TINYINT NOT NULL", "1");
