@Test
void testXmlTransform() {
    SqlOperatorFixture f = fixture().withLibrary(SqlLibrary.ORACLE);
    f.checkNull("XMLTRANSFORM('', NULL)");
    f.checkNull("XMLTRANSFORM(NULL,'')");
    f.checkFails("XMLTRANSFORM('', '<')", "Illegal xslt specified : '.*", true);
    final String sql = "XMLTRANSFORM('<', '<?xml version=\"1.0\"?>\n" + "<xsl:stylesheet version=\"1.0\" xmlns:xsl=\"http://www.w3.org/1999/XSL/Transform\">" + "</xsl:stylesheet>')";
    f.checkFails(sql, "Invalid input for XMLTRANSFORM xml: '.*", true);
    final String sql2 = "XMLTRANSFORM(" + "'<?xml version=\"1.0\"?>\n" + "<Article>\n" + "  <Title>My Article</Title>\n" + "  <Authors>\n" + "    <Author>Mr. Foo</Author>\n" + "    <Author>Mr. Bar</Author>\n" + "  </Authors>\n" + "  <Body>This is my article text.</Body>\n" + "</Article>'" + "," + "'<?xml version=\"1.0\"?>\n" + "<xsl:stylesheet version=\"1.0\" xmlns:xsl=\"http://www.w3" + ".org/1999/XSL/Transform\">" + "  <xsl:output method=\"text\"/>" + "  <xsl:template match=\"/\">" + "    Article - <xsl:value-of select=\"/Article/Title\"/>" + "    Authors: <xsl:apply-templates select=\"/Article/Authors/Author\"/>" + "  </xsl:template>" + "  <xsl:template match=\"Author\">" + "    - <xsl:value-of select=\".\" />" + "  </xsl:template>" + "</xsl:stylesheet>')";
    f.checkString(sql2, "    Article - My Article    Authors:     - Mr. Foo    - Mr. Bar", "VARCHAR");
    // Test case for <a href="https://issues.apache.org/jira/browse/CALCITE-5813">[CALCITE-5813]
    // Type inference for REPEAT sql function is incorrect</a>. This test shows that the
    // output of the XML_TRANSFORM function can exceed 2000 characters. */
    StringBuilder sql3 = new StringBuilder();
    StringBuilder expected = new StringBuilder();
    sql3.append("XMLTRANSFORM(" + "'<?xml version=\"1.0\"?>\n" + "<Article>\n" + "  <Title>My Article</Title>\n" + "  <Authors>\n" + "    <Author>Mr. Foo</Author>\n" + "    <Author>Mr. Bar</Author>\n");
    expected.append("    Article - My Article    Authors:     - Mr. Foo    - Mr. Bar");
    for (int i = 0; i < 40; i++) {
        final String row = "Mr. Bar                                                        " + i;
        sql3.append("    <Author>").append(row).append("</Author>\n");
        expected.append("    - ").append(row);
    }
    sql3.append("  </Authors>\n" + "  <Body>This is my article text.</Body>\n" + "</Article>'" + "," + "'<?xml version=\"1.0\"?>\n" + "<xsl:stylesheet version=\"1.0\" xmlns:xsl=\"http://www.w3" + ".org/1999/XSL/Transform\">" + "  <xsl:output method=\"text\"/>" + "  <xsl:template match=\"/\">" + "    Article - <xsl:value-of select=\"/Article/Title\"/>" + "    Authors: <xsl:apply-templates select=\"/Article/Authors/Author\"/>" + "  </xsl:template>" + "  <xsl:template match=\"Author\">" + "    - <xsl:value-of select=\".\" />" + "  </xsl:template>" + "</xsl:stylesheet>')");
    f.checkString(sql3.toString(), expected.toString(), "VARCHAR");
}

@Test
void testExtractXml() {
    SqlOperatorFixture f = fixture().withLibrary(SqlLibrary.ORACLE);
    f.checkFails("\"EXTRACT\"('', '<','a')", "Invalid input for EXTRACT xpath: '.*", true);
    f.checkFails("\"EXTRACT\"('', '<')", "Invalid input for EXTRACT xpath: '.*", true);
    f.checkNull("\"EXTRACT\"('', NULL)");
    f.checkNull("\"EXTRACT\"(NULL,'')");
    f.checkString("\"EXTRACT\"(" + "'<Article>" + "<Title>Article1</Title>" + "<Authors>" + "<Author>Foo</Author>" + "<Author>Bar</Author>" + "</Authors>" + "<Body>article text.</Body>" + "</Article>', '/Article/Title')", "<Title>Article1</Title>", "VARCHAR");
    f.checkString("\"EXTRACT\"('" + "<Article>" + "<Title>Article1</Title>" + "<Title>Article2</Title>" + "<Authors><Author>Foo</Author><Author>Bar</Author></Authors>" + "<Body>article text.</Body>" + "</Article>', '/Article/Title')", "<Title>Article1</Title><Title>Article2</Title>", "VARCHAR");
    // Test case for <a href="https://issues.apache.org/jira/browse/CALCITE-5813">[CALCITE-5813]
    // Type inference for REPEAT sql function is incorrect</a>. This test shows that
    // the output of the 'XML_EXTRACT' function can exceed 2000 characters. */
    StringBuilder sql = new StringBuilder();
    StringBuilder expected = new StringBuilder();
    sql.append("\"EXTRACT\"('" + "<Article>" + "<Title>Article1</Title>" + "<Title>Article2");
    expected.append("<Title>Article1</Title><Title>Article2");
    final String spaces = "                                                                               ";
    for (int i = 0; i < 40; i++) {
        sql.append(spaces);
        expected.append(spaces);
    }
    sql.append("Long</Title>" + "<Authors><Author>Foo</Author><Author>Bar</Author></Authors>" + "<Body>article text.</Body>" + "</Article>', '/Article/Title')");
    expected.append("Long</Title>");
    f.checkString(sql.toString(), expected.toString(), "VARCHAR");
    f.checkString("\"EXTRACT\"(\n" + "'<books xmlns=\"http://www.contoso.com/books\">" + "<book><title>Title</title>" + "<author>Author Name</author>" + "<price>5.50</price>" + "</book>" + "</books>', " + "'/books:books/books:book', " + "'books=\"http://www.contoso.com/books\"')", "<book xmlns=\"http://www.contoso.com/books\"><title>Title</title><author>Author " + "Name</author><price>5.50</price></book>", "VARCHAR");
}

