    f.checkScalar("safe_add(cast(1.2345 as decimal(5,4)), cast(20 as bigint))", "21.2345", "DECIMAL(19, 4)");
    f.checkScalar("safe_add(cast(1.2345 as decimal(5,4)), cast(2.0 as decimal(2, 1)))", "3.2345", "DECIMAL(6, 4)");
    f.checkScalar("safe_add(cast(3 as double), cast(3 as bigint))", "6.0", "DOUBLE");
    f.checkScalar("safe_add(cast(3 as bigint), cast(3 as double))", "6.0", "DOUBLE");
    f.checkScalar("safe_add(cast(3 as double), cast(1.2345 as decimal(5, 4)))", "4.2345", "DOUBLE");
    f.checkScalar("safe_add(cast(1.2345 as decimal(5, 4)), cast(3 as double))", "4.2345", "DOUBLE");
    f.checkScalar("safe_add(cast(3 as double), cast(3 as double))", "6.0", "DOUBLE");
