    f.checkScalar("safe_add(cast('-Infinity' as double), cast(3 as double))", "-Infinity", "DOUBLE");
    f.checkScalar("safe_add(cast('-Infinity' as double), " + "cast('Infinity' as double))", "NaN", "DOUBLE");
    // Tests for NaN
    f.checkScalar("safe_add(cast('NaN' as double), cast(3 as bigint))", "NaN", "DOUBLE");
    f.checkScalar("safe_add(cast('NaN' as double), cast(1.23 as decimal(3, 2)))", "NaN", "DOUBLE");
