    // Overflow test for each pairing
    f.checkNull("safe_add(cast(20 as bigint), " + "cast(9223372036854775807 as bigint))");
    f.checkNull("safe_add(cast(-20 as bigint), " + "cast(-9223372036854775807 as bigint))");
