    f.checkNull("safe_add(cast(-9.9e7 as decimal(76, 0)), " + "cast(-1.7976931348623157e308 as double))");
    f.checkNull("safe_add(cast(1.7976931348623157e308 as double), cast(3 as bigint))");
    f.checkNull("safe_add(cast(-1.7976931348623157e308 as double), " + "cast(-3 as bigint))");
