    YEAR_VARIANTS.forEach(s -> f.checkScalar("timestampadd(" + s + ", 10, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL"));
    // TIMESTAMPADD with time; returns a time value .The interval is negative.
