    DAY_VARIANTS.forEach(s -> f.checkScalar("timestampadd(" + s + ", -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL"));
    WEEK_VARIANTS.forEach(s -> f.checkScalar("timestampadd(" + s + ", -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL"));
